INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'IM Anfang schuf Gott den Himmel und die Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Die Erde war aber wüst und öde, und Finsternis lag auf der Urflut, und der Geist Gottes schwebte über den Wassern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Und Gott sprach: Es werde Licht! Und es ward Licht. (a) Jes 45:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah, daß das Licht gut war, und Gott schied das Licht von der Finsternis.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Und Gott nannte das Licht Tag, und die Finsternis nannte er Nacht. Und es ward Abend und ward Morgen: ein erster Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: Es werde eine Feste inmitten der Wasser, und sie scheide die Wasser voneinander! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Gott machte die Feste und schied die Wasser unter der Feste von den Wassern über der Feste.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Feste Himmel. Und es ward Abend und ward Morgen: ein zweiter Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: Das Wasser unter dem Himmel sammle sich an einen Ort, daß das Trockene sichtbar werde! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Land, und die Ansammlung der Wasser nannte er Meer. Und Gott sah, daß es gut war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: Die Erde lasse sprossen junges Grün: Kraut, das Samen trägt, und Fruchtbäume, die nach ihrer Art Früchte tragen auf der Erde, in denen ihr Same ist! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Die Erde ließ sprossen junges Grün: Kraut, das Samen trägt nach seiner Art, und Bäume, die Früchte tragen, in denen ihr Same ist, je nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es ward Abend und ward Morgen: ein dritter Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: Es sollen Lichter werden an der Feste des Himmels, Tag und Nacht zu scheiden, und sie sollen als Zeichen dienen und zur Bestimmung von Zeiten, Tagen und Jahren,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und sie seien Lichter an der Feste des Himmels, daß sie auf die Erde leuchten! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Gott machte die zwei großen Lichter: das größere Licht, daß es den Tag beherrsche, und das kleinere Licht, daß es die Nacht beherrsche, dazu auch die Sterne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott setzte sie an die Feste des Himmels, daß sie auf die Erde leuchten');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und Tag und Nacht beherrschen und Licht und Finsternis scheiden. Und Gott sah, daß es gut war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es ward Abend und ward Morgen: ein vierter Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: Es wimmle das Wasser von lebenden Wesen, und Vögel sollen fliegen über der Erde an der Feste des Himmels! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Gott schuf die großen Seetiere und alles, was da lebt und webt, wovon das Wasser wimmelt, und alle geflügelten Tiere, ein jegliches nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet die Wasser des Meeres, und die Vögel sollen sich mehren auf der Erde!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es ward Abend und ward Morgen: ein fünfter Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach: Die Erde bringe hervor lebende Wesen: Vieh, kriechende Tiere und Wild des Feldes, ein jegliches nach seiner Art! Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Gott machte alle die verschiedenen Arten des Wildes und des Viehs und alles dessen, was auf dem Erdboden kriecht. Und Gott sah, daß es gut war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach: Lasset uns Menschen machen nach unserm Bilde, uns ähnlich; die sollen herrschen über die Fische im Meer und die Vögel des Himmels, über das Vieh und alles Wild des Feldes und über alles Kriechende, das auf der Erde sich regt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen nach seinem Bilde, nach dem Bilde Gottes schuf er ihn; als Mann und Weib schuf er sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan, und herrschet über die Fische im Meer und die Vögel des Himmels, über das Vieh und alle Tiere, die auf der Erde sich regen! (a) 1Mo 9:1; Ps 8:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Siehe, ich gebe euch alles Kraut, das Samen trägt, auf der ganzen Erde, und alle Bäume, an denen samenhaltige Früchte sind; das soll eure Speise sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Aber allen Tieren der Erde und allen Vögeln des Himmels und allem, was sich regt auf der Erde, was Lebensodem in sich hat, gebe ich alles Gras und Kraut zur Nahrung. Und es geschah also.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah alles an, was er gemacht hatte, und siehe, es war sehr gut. Und es ward Abend und ward Morgen: der sechste Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Also wurden vollendet der Himmel und die Erde mit ihrem ganzen Heer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Und Gott vollendete am siebenten Tage sein Werk, das er gemacht hatte, und er ruhte am siebenten Tage von all seinem Werke, das er gemacht hatte. (a) 2Mo 20:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebenten Tag und heiligte ihn; denn an ihm hat Gott geruht von all seinem Werke, das er geschaffen und vollbracht hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dies ist die Entstehung des Himmels und der Erde, als sie geschaffen wurden. ZUR Zeit, da Gott der Herr Erde und Himmel machte -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'noch gab es aber kein Gesträuch des Feldes auf Erden und noch wuchs kein Kraut auf dem Felde; denn Gott der Herr hatte noch nicht regnen lassen auf die Erde, und es war kein Mensch da, den Boden zu bebauen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'ein Wasserschwall aber brach hervor aus der Erde und tränkte alles Land -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'da bildete Gott der Herr den Menschen aus Erde vom Ackerboden und hauchte ihm Lebensodem in die Nase; so ward der Mensch ein lebendes Wesen. (a) Hio 33:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Dann pflanzte Gott der Herr einen Garten in Eden gegen Osten und setzte den Menschen darein, den er gebildet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Gott der Herr ließ allerlei Bäume aus der Erde wachsen, lieblich anzusehen und gut zu essen, und den Baum des Lebens mitten im Garten, und den Baum der Erkenntnis des Guten und des Bösen. (a) 1Mo 3:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Es entspringt aber ein Strom in Eden, den Garten zu bewässern; von da aus teilt er sich in vier Arme:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'der erste heißt Pison; das ist der, welcher das ganze Land Hawila umfließt, wo das Gold ist;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'und das Gold jenes Landes ist köstlich. Da findet man auch das Bdellionharz und den Edelstein Soham.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Der zweite Fluß heißt Gihon; das ist der, welcher das ganze Land Kusch umfließt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Der dritte Fluß heißt Hiddekel; das ist der, welcher östlich von Assur fließt. Der vierte Fluß ist der Euphrat. (1) d.i: Tigris.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Und Gott der Herr nahm den Menschen und setzte ihn in den Garten Eden, daß er ihn bebaue und bewahre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Gott der Herr gebot dem Menschen und sprach: Von allen Bäumen im Garten darfst du essen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'nur von dem Baume der Erkenntnis des Guten und des Bösen, von dem darfst du nicht essen; denn sobald du davon issest, mußt du sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Gott der Herr sprach: Es ist nicht gut, daß der Mensch allein sei. Ich will ihm eine Hilfe schaffen, die zu ihm paßt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Da bildete Gott der Herr aus Erde alle Tiere des Feldes und alle Vögel des Himmels und brachte sie zum Menschen, um zu sehen, wie er sie nennen würde; und ganz wie der Mensch sie nennen würde, so sollten sie heißen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Und der Mensch gab allem Vieh und allen Vögeln des Himmels und allen Tieren des Feldes Namen; aber für den Menschen fand er keine Hilfe, die zu ihm paßte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da ließ Gott der Herr einen Tiefschlaf auf den Menschen fallen, sodaß er einschlief. Und er nahm eine von seinen Rippen heraus und schloß die Stelle zu mit Fleisch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Und Gott der Herr baute ein Weib aus der Rippe, die er vom Menschen genommen hatte, und führte sie dem Menschen zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sprach der Mensch: \"Diese ist nun endlich Gebein von meinem Gebein und Fleisch von meinem Fleische. Die soll Männin heißen; denn vom Mann ist sie genommen.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum verläßt der Mann Vater und Mutter und hängt seinem Weibe an, und sie werden ein Leib.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und die beiden, der Mensch und sein Weib, waren nackt und schämten sich nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'DIE Schlange aber war listiger als alle Tiere des Feldes, die Gott der Herr gemacht hatte, und sie sprach zum Weibe: Gott hat wohl gar gesagt: \"Ihr dürft von keinem Baume des Gartens essen!\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da sprach das Weib zur Schlange: Wir dürfen essen von den Früchten der Bäume im Garten;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'nur von den Früchten des Baumes mitten im Garten hat Gott gesagt: \"Esset nicht davon; rühret sie auch nicht an, daß ihr nicht sterbet!\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da sprach die Schlange zum Weibe: Mitnichten werdet ihr sterben;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'sondern Gott weiß, daß, sobald ihr davon esset, euch die Augen aufgehen werden und ihr wie Gott sein und wissen werdet, was gut und böse ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Und das Weib sah, daß von dem Baume gut zu essen wäre und daß er lieblich anzusehen sei und begehrenswert, weil er klug machte, und sie nahm von seiner Frucht und aß und gab auch ihrem Manne neben ihr, und er aß.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da gingen den beiden die Augen auf, und sie wurden gewahr, daß sie nackt waren; und sie hefteten Feigenblätter zusammen und machten sich Schurze.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Als sie nun hörten, wie Gott der Herr in der Abendkühle im Garten wandelte, verbarg sich der Mensch mit seinem Weibe vor dem Angesichte Gottes des Herrn unter den Bäumen im Garten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Und Gott der Herr rief dem Menschen und sprach zu ihm: Wo bist du?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Er sprach: Ich hörte dich im Garten; da fürchtete ich mich, weil ich nackt bin, und verbarg mich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Und er sprach: Wer hat dir gesagt, daß du nackt bist? Hast du etwa von dem Baume gegessen, von dem ich dir zu essen verboten habe?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Der Mensch sprach: Das Weib, das du mir zugesellt hast, das hat mir von dem Baume gegeben; da habe ich gegessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sprach Gott der Herr zum Weibe: Was hast du da getan? Das Weib antwortete: Die Schlange hat mich verführt; da habe ich gegessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sprach Gott der Herr zur Schlange: Weil du das getan, bist du verflucht vor allem Vieh und vor allen Tieren des Feldes. Auf deinem Bauche sollst du kriechen und Staub fressen dein Leben lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich will Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Nachwuchs und ihrem Nachwuchs: er wird dir nach dem Kopfe treten, und du wirst ihm nach der Ferse schnappen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Und zum Weibe sprach er: Ich will dir viel Beschwerden machen in deiner Schwangerschaft; mit Schmerzen sollst du Kinder gebären! Nach deinem Manne wirst du verlangen; er aber soll dein Herr sein! (a) 1Kor 11:3; Eph 5:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zum Menschen sprach er: Weil du auf deines Weibes Stimme gehört und von dem Baume gegessen hast, von dem ich dir gebot: du sollst nicht davon essen, so ist um deinetwillen der Erdboden verflucht. Mit Mühsal sollst du dich von ihm nähren dein Leben lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dornen und Disteln soll er dir tragen, und das Kraut des Feldes sollst du essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichtes sollst du dein Brot essen, bis du wieder zur Erde kehrst, von der du genommen bist; denn Erde bist du, und zur Erde mußt du zurück. (a) Pre 12:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und der Mensch nannte sein Weib Eva; denn sie wurde die Mutter aller Lebenden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Gott der Herr machte dem Menschen und seinem Weibe Röcke von Fell und legte sie ihnen um.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Gott der Herr sprach: Siehe, der Mensch ist geworden wie unsereiner, daß er weiß, was gut und böse ist. Nun aber, daß er nur nicht seine Hand ausstrecke und auch von dem Baume des Lebens breche und ewig lebe!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'So schickte ihn Gott der Herr fort aus dem Garten Eden, daß er den Erdboden bebaue, von dem er genommen war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Und er vertrieb den Menschen und ließ östlich vom Garten Eden die Cherube sich lagern und die Flamme des zuckenden Schwertes, den Weg zum Baume des Lebens zu bewachen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'DER Mensch aber wohnte seinem Weibe Eva bei, und sie ward schwanger und gebar den Kain. Da sprach sie: Ich habe einen Sohn bekommen mit des Herrn Hilfe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und weiter gebar sie den Abel, seinen Bruder. Abel ward ein Schäfer, Kain aber ward ein Ackerbauer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Es begab sich aber nach geraumer Zeit, daß Kain von den Früchten des Ackers dem Herrn ein Opfer brachte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Und auch Abel brachte von den Erstlingen seiner Schafe dar und von ihrem Fette. Und der Herr sah wohlgefällig auf Abel und sein Opfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'auf Kain aber und sein Opfer sah er nicht. Da ergrimmte Kain gar sehr und blickte finster.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Und der Herr sprach zu Kain: Warum ergrimmst du, und warum blickst du so finster?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ist\'s nicht also? Wenn du recht handelst, darfst du frei aufschauen; handelst du aber nicht recht, so lauert die Sünde vor der Tür, und nach dir steht ihre Begierde; du aber sollst Herr werden über sie! (a) Rö 6:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Darauf sprach Kain zu seinem Bruder Abel: Laß uns aufs Feld gehen! Und als sie auf dem Felde waren, erhob sich Kain wider seinen Bruder Abel und schlug ihn tot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sprach der Herr zu Kain: Wo ist dein Bruder Abel? Er sprach: Ich weiß nicht. Bin ich denn meines Bruders Hüter?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Er aber sprach: Was hast du getan! Horch, das Blut deines Bruders schreit zu mir empor vom Ackerland.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun - verflucht bist du, verbannt vom Ackerland, das seinen Mund aufgetan hat, aus deiner Hand das Blut deines Bruders zu empfangen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Acker bebauen wirst, soll er dir hinfort seinen Ertrag nicht mehr geben: unstet und flüchtig sollst du sein auf Erden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Da sprach Kain zu dem Herrn: Meine Strafe ist größer, als daß ich sie tragen könnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Siehe, du vertreibst mich heute vom Ackerland, und ich muß mich vor deinem Angesicht verbergen; unstet und flüchtig muß ich sein auf Erden. So wird mich denn totschlagen, wer mich antrifft.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Der Herr aber sprach zu ihm: Nicht also! Wer immer Kain totschlägt, an dem wird es siebenfältig gerächt. Und der Herr versah Kain mit einem Zeichen, daß keiner ihn erschlüge, der ihn anträfe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Also ging Kain hinweg vom Angesichte des Herrn und wohnte im Lande Nod, östlich von Eden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain wohnte seinem Weibe bei; da ward sie schwanger und gebar den Henoch. Und er ward Erbauer einer Stadt; die nannte er nach seines Sohnes Namen Henoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Dem Henoch wurde Irad geboren; Irad aber zeugte Mehujael, Mehujael zeugte Methusael, Methusael zeugte Lamech.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamech aber nahm zwei Frauen; die eine hieß Ada, die andre Zilla.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Ada gebar den Jabal; der wurde der Vater derer, die in Zelten und bei Herden wohnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Sein Bruder hieß Jubal; der wurde der Vater aller derer, die Zither und Schalmei handhaben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Aber auch Zilla gebar einen Sohn, den Thubal-Kain; der wurde der Vater aller derer, die Erz und Eisen schmieden. Und die Schwester Thubal-Kains war Naema.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Und Lamech sprach zu seinen Frauen: Ada und Zilla, hört meine Rede, / ihr Weiber Lamechs, vernehmt meinen Spruch! / Einen Mann erschlug ich für meine Wunde / und einen Jüngling für meine Strieme. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Denn wird Kain siebenmal gerächt, / so Lamech siebenundsiebzigmal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Und Adam wohnte seinem Weibe abermals bei, und sie gebar einen Sohn, den hieß sie Seth, denn Gott hat mir, (so sprach sie,) einen andern Sproß gegeben für Abel, weil Kain ihn erschlagen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und auch dem Seth ward ein Sohn geboren; den hieß er Enos. Damals fing man an, den Namen Jahwes anzurufen. (1) der bes. Name des Gottes Israels lautete ursprünglich [Jahwe]. In der Reformationszeit kam dafür irrtümlicherweise die Namensform Jehova in Gebrauch. Die meisten Üs. wählten statt dessen nach jüd. Vorgang die allgemeine Bez. \"der Herr\", die in der Regel auch in unsrer Zürcher Bibel beibehalten ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'DIES ist das Verzeichnis der Nachkommen Adams: Als Gott den Adam erschuf, machte er ihn Gott ähnlich; (a) 1Mo 1:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'als Mann und Weib schuf er sie. Und er segnete sie und gab ihnen den Namen Adam, damals als sie geschaffen wurden. (1) d.i. Mensch. (a) 1Mo 1:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Als Adam 130 Jahre alt war, zeugte er einen Sohn, ihm selbst ähnlich, nach seinem Bilde; den hieß er Seth.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Und nachdem Adam den Seth gezeugt, lebte er noch achthundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'So betrug Adams ganze Lebenszeit 930 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Als Seth 105 Jahre alt war, zeugte er den Enos.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Und nachdem Seth den Enos gezeugt, lebte er noch 807 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'So betrug Seths ganze Lebenszeit 912 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Als Enos neunzig Jahre alt war, zeugte er den Kenan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Und nachdem Enos den Kenan gezeugt, lebte er noch 815 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'So betrug Enos\' ganze Lebenszeit 905 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Als Kenan siebzig Jahre alt war, zeugte er den Mahalaleel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Und nachdem Kenan den Mahalaleel gezeugt, lebte er noch 840 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'So betrug Kenans ganze Lebenszeit 910 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Als Mahalaleel 65 Jahre alt war, zeugte er den Jared.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Und nachdem Mahalaleel den Jared gezeugt, lebte er noch 830 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'So betrug Mahalaleels ganze Lebenszeit 895 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Als Jared 162 Jahre alt war, zeugte er den Henoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Und nachdem Jared den Henoch gezeugt, lebte er noch achthundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'So betrug Jareds ganze Lebenszeit 962 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Als Henoch 65 Jahre alt war, zeugte er den Methusalah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Und Henoch wandelte mit Gott; und nachdem er den Methusalah gezeugt, lebte er noch dreihundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'So betrug Henochs ganze Lebenszeit 365 Jahre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henoch wandelte mit Gott, und auf einmal war er nicht mehr da; denn Gott hatte ihn hinweggenommen. (a) Heb 11:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Als Methusalah 187 Jahre alt war, zeugte er den Lamech.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Und nachdem Methusalah den Lamech gezeugt, lebte er noch 782 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'So betrug Methusalahs ganze Lebenszeit 969 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Als Lamech 182 Jahre alt war, zeugte er einen Sohn;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'den hieß er Noah, indem er sprach: Dieser wird uns Erquickung schaffen von unsrer Arbeit und der Mühsal unsrer Hände durch den Acker, den der Herr verflucht hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Und nachdem Lamech den Noah gezeugt, lebte er noch 595 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'So betrug Lamechs ganze Lebenszeit 777 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Als Noah fünfhundert Jahre alt war, zeugte er den Sem, den Ham und den Japhet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'ALS aber die Menschen anfingen, sich auf der Erde zu mehren, und ihnen Töchter geboren wurden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'sahen die Gottessöhne, daß die Töchter der Menschen schön waren, und sie nahmen sich zu Weibern, welche sie nur wollten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sprach der Herr: Mein Geist soll nicht auf immer im Menschen walten, dieweil auch er Fleisch ist, und seine Lebenszeit sei 120 Jahre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Zu jenen Zeiten - und auch nachmals noch -, als die Gottessöhne zu den Töchtern der Menschen sich gesellten und diese ihnen Kinder gebaren, waren die Riesen auf Erden. Das sind die Recken der Urzeit, die hochberühmten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Als aber der Herr sah, daß der Menschen Bosheit groß war auf Erden, und daß alles Dichten und Trachten ihres Herzens die ganze Zeit nur böse war, (a) 1Mo 8:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'da reute es den Herrn, daß er den Menschen geschaffen hatte auf Erden, und es bekümmerte ihn tief.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Und der Herr sprach: Ich will die Menschen, die ich geschaffen habe, vom Erdboden vertilgen, die Menschen sowohl als das Vieh, auch die kriechenden Tiere und die Vögel des Himmels; denn es reut mich, daß ich sie gemacht habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noah aber hatte Gnade gefunden vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist die Geschichte Noahs: Noah war ein frommer Mann, unsträflich unter seinen Zeitgenossen; mit Gott wandelte er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noah zeugte drei Söhne: Sem, Ham und Japhet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Aber die Erde ward verderbt vor Gott, und voll ward die Erde von Frevel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Da sah Gott auf die Erde, und siehe, sie war verderbt; denn alles Fleisch hatte seinen Wandel verderbt auf Erden. (a) Ps 14:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sprach Gott zu Noah: Das Ende alles Fleisches ist bei mir beschlossen; denn die Erde ist voller Frevel von den Menschen her. So will ich sie denn von der Erde vertilgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mache dir eine Arche von Tannenholz; aus lauter Zellen sollst du die Arche machen, und verpiche sie inwendig und auswendig mit Pech.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und so sollst du sie machen: dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'nach der Elle sollst du sie fertigstellen. Ein Dach aber sollst du oben an der Arche machen, und die Türe der Arche sollst du an der Seite anbringen. Ein unteres, ein zweites und ein drittes Stockwerk sollst du darin machen. (1) aÜs: eine \"Lichtöffnung\".');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ich aber lasse jetzt die Sintflut über die Erde kommen, um alles Fleisch, das Lebensodem in sich hat, unter dem Himmel zu vertilgen; alles, was auf Erden ist, soll hinsterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will ich einen Bund aufrichten: du sollst in die Arche gehen, du und deine Söhne und dein Weib und deine Schwiegertöchter mit dir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allen Tieren, von allem Fleisch, sollst du je ein Paar in die Arche führen, um sie bei dir am Leben zu erhalten; ein Männchen und ein Weibchen sollen es sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von jeder Art der Vögel und des Viehs und alles dessen, was auf Erden kriecht, von allem soll je ein Paar zu dir hineingehen, um am Leben zu bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Du aber nimm dir von jeglicher Speise, die man ißt, und lege dir einen Vorrat an, damit er dir und ihnen zur Nahrung diene.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noah tat es; ganz wie ihm Gott geboten hatte, so tat er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Und der Herr sprach zu Noah: Gehe in die Arche, du und dein ganzes Haus; denn dich habe ich gerecht vor mir erfunden unter diesem Geschlechte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Nimm dir von allen reinen Tieren je sieben, Männchen und Weibchen, von den unreinen Tieren aber je ein Paar, ein Männchen und ein Weibchen, (a) 3Mo 11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'auch von den Vögeln des Himmels je sieben, Männchen und Weibchen, damit auf der ganzen Erde Nachwuchs am Leben bleibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn nach sieben Tagen will ich regnen lassen auf die Erde, vierzig Tage und vierzig Nächte lang, und will alle Wesen, die ich gemacht habe, vom Erdboden vertilgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noah tat, ganz wie ihm der Herr geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noah aber war sechshundert Jahre alt, als die Sintflut über die Erde kam.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Und Noah ging mit seinen Söhnen und mit seinem Weibe und seinen Schwiegertöchtern vor den Wassern der Sintflut in die Arche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von den reinen und von den unreinen Tieren, von den Vögeln und von allem, was auf Erden kriecht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'ging je ein Paar, ein Männchen und ein Weibchen, zu Noah in die Arche, wie Gott dem Noah geboten hatte. (a) 1Mo 6:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und nach den sieben Tagen kamen die Wasser der Sintflut über die Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im sechshundertsten Lebensjahre Noahs, am siebzehnten Tage des zweiten Monats, an diesem Tage brachen alle Brunnen der großen Urflut auf, und die Fenster des Himmels öffneten sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Und der Regen strömte auf die Erde, vierzig Tage und vierzig Nächte lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An eben diesem Tage ging Noah mit seinen Söhnen Sem, Ham und Japhet, mit seinem Weibe und seinen drei Schwiegertöchtern in die Arche;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alle die verschiedenen Arten des Wildes und des Viehs und alles dessen, was auf Erden kriecht, und auch der Vögel, alles dessen, was fliegt, was Flügel hat:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'die gingen zu Noah in die Arche, je zwei von allem Fleische, das Lebensodem in sich hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Und die hineingingen, waren je ein Männchen und ein Weibchen von allem Fleische, wie ihm Gott geboten hatte. Und der Herr schloß hinter ihm zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da kam die Sintflut über die Erde, vierzig Tage lang, und die Wasser wuchsen und hoben die Arche, und sie schwamm hoch über der Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und die Wasser nahmen mächtig überhand und wuchsen gewaltig über der Erde, und die Arche fuhr auf den Wassern dahin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und die Wasser wurden immer mächtiger über der Erde, sodaß alle hohen Berge unter dem ganzen Himmel bedeckt wurden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen stiegen die Wasser darüber hinaus, sodaß die Berge bedeckt wurden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da starb alles Fleisch dahin, das sich auf Erden regte, an Vögeln, an Vieh, an Wild und allem, was auf Erden wimmelte, auch alle Menschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alles, was Lebensluft atmete, was auf dem Trockenen war, das starb.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'So vertilgte er alle Wesen, die auf dem Erdboden waren: die Menschen sowohl als das Vieh, das Kriechende und die Vögel des Himmels, die wurden vertilgt von der Erde; nur Noah blieb übrig und was mit ihm in der Arche war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und die Wasser nahmen zu auf der Erde, 150 Tage lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da gedachte Gott des Noah und all des Wildes und des Viehs, das bei ihm in der Arche war. Und Gott ließ einen Wind über die Erde wehen, und die Wasser sanken;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'und es schlossen sich die Brunnen der Urflut und die Fenster des Himmels. Dem Regen vom Himmel ward gewehrt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'und die Wasser verliefen sich nach und nach von der Erde. So nahmen die Wasser ab nach den 150 Tagen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'und am siebzehnten Tage des siebenten Monats ließ sich die Arche auf den Bergen von Ararat nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Die Wasser aber sanken noch weiter, bis zum zehnten Monat; am ersten Tage des zehnten Monats wurden die Spitzen der Berge sichtbar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Nach Verlauf von vierzig Tagen aber öffnete Noah das Fenster der Arche, das er gemacht hatte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'und ließ den Raben ausfliegen; der flog hin und her, bis die Wasser auf Erden vertrocknet waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Da wartete Noah sieben Tage; dann ließ er die Taube ausfliegen, um zu sehen, ob sich die Wasser vom Erdboden verlaufen hätten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Da aber die Taube keine Stätte fand, wo ihr Fuß ruhen konnte, kam sie wieder zu ihm in die Arche; denn noch war Wasser auf der ganzen Erde. Da streckte er seine Hand aus, faßte sie und nahm sie zu sich herein in die Arche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Hierauf wartete er noch weitere sieben Tage; dann ließ er die Taube abermals aus der Arche fliegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Die kam um die Abendzeit zu ihm zurück, und siehe da! sie trug ein frisches Ölblatt in ihrem Schnabel. Da merkte Noah, daß sich die Wasser von der Erde verlaufen hatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Dann wartete er noch weitere sieben Tage und ließ die Taube ausfliegen; sie kam aber nicht wieder zu ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Im 601. Lebensjahre Noahs, am ersten Tage des ersten Monats, waren die Wasser auf Erden versiegt. Da tat Noah das Dach von der Arche, und siehe da! der Erdboden war trocken geworden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Am 27. Tage des zweiten Monats war die Erde ganz trocken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da redete Gott mit Noah und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Geh aus der Arche, du und dein Weib und deine Söhne und deine Schwiegertöchter mit dir;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'und alle die Tiere, die bei dir sind, alle Geschöpfe: Vögel, Vieh und alles, was auf Erden kriecht, die laß heraus mit dir, daß sie sich tummeln auf der Erde und fruchtbar seien und sich mehren auf Erden. (a) 1Mo 1:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Da ging Noah hinaus mit seinen Söhnen, mit seinem Weibe und seinen Schwiegertöchtern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Auch alles Wild und alles Vieh, alle Vögel und alles, was auf Erden kriecht, die gingen hinaus aus der Arche, Art um Art.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noah aber baute dem Herrn einen Altar; dann nahm er von allen reinen Tieren und von allen reinen Vögeln und brachte Brandopfer auf dem Altar. (a) 3Mo 11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Und der Herr roch den lieblichen Duft und sprach bei sich selbst: Ich will hinfort nicht mehr die Erde um der Menschen willen verfluchen; ist doch das Trachten des menschlichen Herzens böse von Jugend auf. Und ich will hinfort nicht mehr schlagen, was da lebt, wie ich getan habe. (a) 1Mo 6:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Solange die Erde steht, soll nicht aufhören Saat und Ernte, Frost und Hitze, Sommer und Winter, Tag und Nacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'UND Gott segnete Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde! (a) 1Mo 1:28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Furcht und Schrecken vor euch komme über alle Tiere der Erde, über alle Vögel des Himmels, über alles, was auf Erden kriecht, und über alle Fische im Meer: in eure Hand sind sie gegeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich regt und lebt, das sei eure Speise; wie das Kraut, das grüne, gebe ich euch alles. (a) 1Mo 1:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur Fleisch, das seine Seele - sein Blut - noch in sich hat, dürft ihr nicht essen. (a) 3Mo 17:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Euer eignes (vergossenes) Blut aber will ich einfordern; von allen Tieren will ich es einfordern, und von den Menschen untereinander will ich das Leben des Menschen einfordern: (a) 2Mo 21:12 28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'wer Menschenblut vergießt, dessen Blut soll auch durch Menschen vergossen werden; denn Gott hat den Menschen nach seinem Bilde gemacht. (a) 1Mo 1:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr nun, seid fruchtbar und mehret euch, breitet euch aus auf der Erde und herrscht über sie!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Dann sprach Gott zu Noah und zu seinen Söhnen, die bei ihm waren:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Ich aber, siehe, ich richte einen Bund auf mit euch und euren Nachkommen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'und mit allen lebenden Wesen, die bei euch sind, Vögeln, Vieh und allem Wild des Feldes bei euch, mit allen, die aus der Arche gekommen sind.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ich will einen Bund mit euch aufrichten, daß niemals wieder alles Fleisch von den Wassern der Sintflut soll ausgerottet werden und niemals wieder eine Sintflut kommen soll, die Erde zu verderben. (a) 1Mo 8:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Dies ist das Zeichen des Bundes, den ich stifte zwischen mir und euch und allen Lebewesen, die bei euch sind, auf ewige Zeiten:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'meinen Bogen stelle ich in die Wolken; der soll ein Bundeszeichen sein zwischen mir und der Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Wenn ich nun Wolken häufe ob der Erde und sich der Bogen in den Wolken zeigt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'dann will ich des Bundes gedenken, der da besteht zwischen mir und euch und allen lebenden Wesen, und niemals wieder sollen die Wasser zu einer Sintflut werden, die alles Fleisch verderbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Und wenn der Bogen in den Wolken steht, will ich ihn ansehen, um des ewigen Bundes zu gedenken zwischen Gott und allen lebenden Wesen, die auf Erden sind.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noah: Dies ist das Zeichen des Bundes, den ich aufrichte zwischen mir und allem Fleische, das auf Erden ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Die Söhne Noahs, die aus der Arche gingen, waren Sem, Ham und Japhet. Ham aber ist der Vater Kanaans.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Diese drei sind die Söhne Noahs, und von ihnen aus hat sich die ganze Erde bevölkert.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noah aber, der Landmann, war der erste, der Weinreben pflanzte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Und da er von dem Weine trank, ward er berauscht und lag entblößt im Innern seines Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Als nun Ham, der Vater Kanaans, seines Vaters Blöße sah, sagte er es seinen beiden Brüdern draußen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahmen Sem und Japhet das Gewand, legten es auf ihre Schultern und gingen rückwärts hinzu und bedeckten ihres Vaters Blöße, indem ihr Angesicht rückwärts gewendet war, sodaß sie ihres Vaters Blöße nicht sahen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als aber Noah von seinem Rausch erwachte und erfuhr, was ihm sein jüngster Sohn getan,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'sprach er: Verflucht sei Kanaan! / Knecht der Knechte / sei er seinen Brüdern!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und weiter sprach er: Gepriesen sei der Herr, der Gott Sems, / Kanaan aber sei ihm Knecht! /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Raum schaffe Gott dem Japhet, / daß er wohne in den Zelten Sems, / Kanaan aber sei ihm Knecht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Noah lebte nach der Sintflut noch 350 Jahre,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'und Noahs ganze Lebenszeit betrug 950 Jahre; dann starb er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'DIES sind die Nachkommen der Söhne Noahs, Sem, Ham und Japhet; diesen wurden Söhne geboren nach der Sintflut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japhets sind: Gomer, Magog, Madai, Jawan, Thubal, Mesech und Thiras. (1) d.i. Meder. (2) d.i. Jonier, Griechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Die Söhne Gomers sind: Askenas, Riphath und Thogarma.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Die Söhne Jawans sind: Elisa, Tharsis, die Chittäer und die Rhodier. (1) in Spanien. (2) d.i. Cyprier.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von ihnen haben sich die Inselvölker abgezweigt. Das sind die Nachkommen Japhets nach ihren Ländern, ihren Sprachen, ihren Geschlechtern, ihren Völkerschaften.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Die Söhne Hams sind: Kusch, Mizraim, Put und Kanaan. (1) d.i. Ägypter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Die Söhne Kuschs sind: Seba, Hawila, Sabtha, Ragma und Sabthecha. Die Söhne Ragmas sind: Saba und Dedan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kusch aber zeugte den Nimrod; der war der erste Gewaltherrscher auf Erden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Dieser ward ein gewaltiger Jäger vor dem Herrn. Daher sagt man: ein gewaltiger Jäger vor dem Herrn wie Nimrod.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Und der Anfang seines Reiches war Babel, Erech, Akkad und Kalne im Lande Sinear. (1) d.i. Babylonien.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog er aus nach Assur und baute Ninive, Rehoboth-Ir und Kelah,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'und Resen zwischen Ninive und Kelah; dies ist die große Stadt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim aber zeugte die Luditer, die Anamiter, die Lehabiter, die Naphthuhiter,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'die Pathrusiter, die Kasluhiter und die Kaphthoriter, von denen die Philister ausgegangen sind. (1) d.i. Kreter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan aber zeugte Sidon, seinen Erstgebornen, und Heth,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'und die Jebusiter, die Amoriter, die Girgasiter,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'die Hewiter, die Arkiter, die Siniter,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'die Arwaditer, die Zamariter und die Hamathiter. Später zerstreuten sich die Geschlechter der Kanaaniter;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'so reichte das Gebiet der Kanaaniter von Sidon an gegen Gerar hin bis nach Gaza und gegen Sodom, Gomorrha, Adma und Zeboim hin bis nach Lesa.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Das sind die Nachkommen Hams nach ihren Geschlechtern, ihren Sprachen, ihren Ländern, ihren Völkerschaften.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Aber auch Sem, dem Vater aller Söhne Hebers, dem ältern Bruder Japhets, wurden Söhne geboren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Die Söhne Sems sind: Elam, Assur, Arpachsad, Lud und Aram. (1) d.i. Südwestpersien. (2) d.i. Syrien.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Die Söhne Arams aber sind: Uz, Hul, Gether und Mas.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpachsad aber zeugte Selah, und Selah zeugte Heber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Heber wurden zwei Söhne geboren; einer hieß Peleg, weil zu seiner Zeit die Menschheit sich zerteilte, und sein Bruder hieß Joktan. (1) d.i. Teilung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktan aber zeugte Almodad, Seleph, Hazarmawet, Jerah,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Saba,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hawila und Jobab. Diese alle sind die Söhne Joktans.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihre Wohnsitze reichten von Mesa an gegen Sephar hin bis an das Ostgebirge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Das sind die Nachkommen Sems nach ihren Geschlechtern, ihren Sprachen, ihren Ländern, ihren Völkerschaften.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Das sind die Geschlechter der Nachkommen Noahs nach ihrer Abstammung, nach ihren Völkerschaften; und von diesen aus verzweigten sich die Völker auf der Erde nach der Sintflut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'ES hatte aber alle Welt einerlei Sprache und einerlei Worte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Als sie nun im Osten aufbrachen, fanden sie eine Ebene im Lande Sinear, und sie liessen sich dort nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen untereinander: Wohlan, lasst uns Ziegel streichen und hart brennen! Und es diente ihnen der Ziegel als Stein, und der Asphalt diente ihnen als Mörtel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Und sie sprachen: Wohlan, lasst uns eine Stadt bauen und einen Turm, dessen Spitze bis in den Himmel reicht; so wollen wir uns ein Denkmal schaffen, damit wir uns nicht über die ganze Erde zerstreuen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da fuhr der Herr hernieder, um die Stadt zu besehen und den Turm, den die Menschenkinder gebaut hatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und der Herr sprach: Siehe, sie sind ein Volk und haben alle eine Sprache. Und dies ist erst der Anfang ihres Tuns; nunmehr wird ihnen nichts unmöglich sein, was immer sie sich vornehmen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlan, lasst uns hinabfahren und daselbst ihre Sprache verwirren, dass keiner mehr des andern Sprache verstehe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Also zerstreute sie der Herr von dort über die ganze Erde, und sie liessen ab, die Stadt zu bauen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Daher heisst ihr Name Babel, weil der Herr daselbst die Sprache aller Welt verwirrt und sie von dort über die ganze Erde zerstreut hat. (1) in dem Namen Babel hörte man einen Anklang an ein hebrW., das \"verwirren\" bedeutet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'DIES sind die Nachkommen Sems: Als Sem hundert Jahre alt war, zeugte er, zwei Jahre nach der Sintflut, den Arpachsad.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Und nachdem Sem den Arpachsad gezeugt, lebte er noch fünfhundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Als Arpachsad 35 Jahre alt war, zeugte er den Selah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Und nachdem Arpachsad den Selah gezeugt, lebte er noch 403 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Als Selah dreissig Jahre alt war, zeugte er den Heber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Und nachdem Selah den Heber gezeugt, lebte er noch 403 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Als Heber 34 Jahre alt war, zeugte er den Peleg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Und nachdem Heber den Peleg gezeugt, lebte er noch 430 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Als Peleg dreissig Jahre alt war, zeugte er den Regu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Und nachdem Peleg den Regu gezeugt, lebte er noch 209 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Als Regu 32 Jahre alt war, zeugte er den Serug.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Und nachdem Regu den Serug gezeugt, lebte er noch 207 Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Als Serug dreissig Jahre alt war, zeugte er den Nahor.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Und nachdem Serug den Nahor gezeugt, lebte er noch zweihundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Als Nahor 29 Jahre alt war, zeugte er den Tharah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Und nachdem Nahor den Tharah gezeugt, lebte er noch zweihundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Als Tharah siebzig Jahre alt war, zeugte er den Abram, den Nahor und den Haran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies sind die Nachkommen Tharahs: Tharah zeugte den Abram, den Nahor und den Haran; und Haran zeugte den Lot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Haran aber starb bei Lebzeiten seines Vaters Tharah in seiner Heimat, zu Ur in Chaldäa.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Da nahmen sich Abram und Nahor Frauen; Abrams Weib hiess Sarai, und Nahors Weib hiess Milka, die Tochter Harans, des Vaters der Milka und der Jiska.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai aber war unfruchtbar; sie hatte keine Kinder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Da nahm Tharah seinen Sohn Abram und seinen Enkel Lot, den Sohn Harans, und seine Schwiegertochter Sarai, das Weib seines Sohnes Abram, und führte sie hinweg aus Ur in Chaldäa, um ins Land Kanaan zu ziehen; und sie kamen bis Haran und liessen sich dort nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Und Tharahs Lebenszeit betrug 205 Jahre; dann starb Tharah in Haran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'UND der Herr sprach zu Abram: Ziehe hinweg aus deinem Vaterlande und aus deiner Verwandtschaft und aus deines Vaters Hause in das Land, das ich dir zeigen werde; (a) Jos 24:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'so will ich dich zu einem grossen Volke machen und dich segnen und deinen Namen berühmt machen, dass er zum Segensworte wird. (1) V. 2-3: vgl. 1Mo 48:20; Jer 29:32; Ps 72:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Segnen will ich, die dich segnen, und wer dir flucht, den will ich verfluchen; und mit deinem Namen werden sich Segen wünschen alle Geschlechter der Erde. (1) vgl. 1Mo 48:20; Jer 29:32; Ps 72:17 (a) 1Mo 22:18; 26:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Da zog Abram hin, wie ihm der Herr geboten hatte, und Lot zog mit ihm. Abram aber war 75 Jahre alt, als er aus Haran wegzog.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Und Abram nahm sein Weib Sarai und Lot, seines Bruders Sohn, und all ihre Habe, die sie gewonnen, und die Leute, die sie in Haran erworben hatten, und sie wanderten aus, um ins Land Kanaan zu ziehen. Und sie kamen ins Land Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Da zog Abram durch das Land bis zu der Stätte von Sichem, bis zur Orakel-Terebinthe. Damals aber waren die Kanaaniter im Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien der Herr dem Abram und sprach zu ihm: Deinen Nachkommen will ich dieses Land geben. Und er baute daselbst dem Herrn, der ihm erschienen war, einen Altar. (a) 1Mo 13:15; 15:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Darnach brach er von dannen auf nach dem Gebirge östlich von Bethel und schlug sein Zelt auf, Bethel im Westen und Ai im Osten; da baute er dem Herrn einen Altar und rief den Namen des Herrn an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Dann zog Abram immer weiter nach dem Südland.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'ES kam aber eine Hungersnot über das Land. Da zog Abram nach Ägypten hinab, um dort eine Weile zu verbleiben; denn die Hungersnot lastete schwer auf dem Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Und da er sich Ägypten nahte, sprach er zu seinem Weibe Sarai: Ich weiss recht wohl, dass du ein schönes Weib bist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Wenn dich nun die Ägypter sehen, so werden sie denken: \"Das ist sein Weib\", und sie werden mich erschlagen und dich am Leben lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'So sage doch, du seiest meine Schwester, auf dass es mir um deinetwillen wohl gehe und ich durch dich am Leben bleibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als nun Abram nach Ägypten kam, sahen die Ägypter, dass das Weib sehr schön war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und die Grossen des Pharao sahen sie und rühmten sie vor dem Pharao. Da wurde das Weib in den Palast des Pharao geholt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Dem Abram aber tat er Gutes um ihretwillen: er bekam Schafe, Rinder und Esel, Sklaven und Sklavinnen, Eselinnen und Kamele.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Doch der Herr schlug den Pharao und sein Haus mit schweren Plagen um Sarais, des Weibes Abrams, willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da liess der Pharao den Abram rufen und sprach: Was hast du mir da angetan! Warum hast du mich nicht wissen lassen, dass sie dein Weib ist?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du gesagt, sie sei deine Schwester, sodass ich sie mir zum Weibe genommen habe? Nun, da hast du dein Weib, nimm sie und ziehe hin!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und der Pharao entbot seinethalben Leute; die mussten ihn und sein Weib und alles, was er hatte, geleiten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'ALSO zog Abram mit seinem Weibe und mit all seiner Habe, mit ihm auch Lot, aus Ägypten in das Südland hinauf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram aber war sehr reich an Vieh, an Silber und an Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er wanderte weiter von Lagerplatz zu Lagerplatz, aus dem Südland bis nach Bethel, bis zu der Stätte, wo im Anfang sein Zelt gestanden hatte, zwischen Bethel und Ai, (a) 1Mo 12:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'an die Stätte des Altars, den er vordem daselbst gemacht hatte, und dort rief Abram den Namen des Herrn an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lot aber, der mit Abram zog, hatte auch Schafe, Rinder und Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Und das Land ertrug es nicht, dass sie beieinander blieben; denn ihre Habe war gross, und darum konnten sie nicht beieinander bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'So kam es zum Streite zwischen den Hirten über Abrams Vieh und den Hirten über Lots Vieh. Damals aber wohnten die Kanaaniter und Pheresiter im Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: Lass doch nicht Zank sein zwischen mir und dir, zwischen meinen Hirten und deinen Hirten; wir sind ja Brüder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Steht dir nicht das ganze Land offen? So trenne dich doch von mir. Willst du zur Linken, so gehe ich zur Rechten; oder willst du zur Rechten, so gehe ich zur Linken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da erhob Lot seine Augen und sah, dass die ganze Jordanaue ein wasserreiches Land war - ehe der Herr Sodom und Gomorrha zerstörte -, wie der Garten des Herrn, wie das Land Ägypten, bis nach Zoar hin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Da erwählte sich Lot die ganze Jordanaue und brach auf nach Osten. So trennten sie sich voneinander:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram blieb im Lande Kanaan, Lot aber liess sich nieder in den Städten der Aue und zog mit seinen Zelten bis gegen Sodom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Aber die Leute von Sodom waren arge Sünder und Frevler wider den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Als sich nun Lot von Abram getrennt hatte, sprach der Herr zu Abram: Hebe deine Augen auf und schaue von der Stätte, da du stehst, gegen Mitternacht und gegen Mittag, gegen Morgen und gegen Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn das ganze Land, das du siehst - dir will ich es geben und deinen Nachkommen für ewige Zeiten. (a) 1Mo 12:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und deine Nachkommen will ich mehren wie den Staub der Erde, sodass, wenn man den Staub der Erde zählen kann, man auch deine Nachkommen wird zählen können. (a) 1Mo 28:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Auf, durchziehe das Land in die Länge und in die Breite; denn dir will ich es geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Da brach Abram mit seinen Zelten auf, zog hin und liess sich nieder bei der Terebinthe Mamres zu Hebron und baute daselbst dem Herrn einen Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'UND es begab sich zur Zeit Amraphels, des Königs von Sinear, Arjochs, des Königs von Ellasar, Kedor-Laomers, des Königs von Elam, und Thideals, des Königs von Gojim,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'dass sie Krieg anfingen mit Bera, dem König von Sodom, Birsa, dem König von Gomorrha, Sineab, dem König von Adma, Semeber, dem König von Zeboim, und dem König von Bela - das ist Zoar;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'diese alle kamen zusammen im Tale von Siddim - das ist das Salzmeer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre waren sie Kedor-Laomer untertan gewesen, im dreizehnten Jahre waren sie abgefallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Im vierzehnten Jahre aber kamen Kedor-Laomer und die Könige, die mit ihm verbündet waren, und schlugen die Rephaiter in Astharoth-Karnaim, die Susiter in Ham, die Emiter in der Ebene von Kirjathaim');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Horiter auf dem Gebirge Seir bis nach El-Paran, das am Rand der Wüste liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Darnach kehrten sie um und kamen nach En-Mispat - das ist Kades - und schlugen das ganze Land der Amalekiter sowie die Amoriter, die in Hazazon-Thamar wohnten. (1) dieser Name bed. \"Rechtsquell\".');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Aber der König von Sodom, der König von Gomorrha, der König von Adma, der König von Zeboim und der König von Bela - das ist Zoar - zogen aus und stellten sich im Tale von Siddim auf, mit ihnen zu streiten:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'mit Kedor-Laomer, dem König von Elam, Thideal, dem König von Gojim, Amraphel, dem König von Sinear, und Arjoch, dem König von Ellasar - vier Könige mit den fünfen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Das Tal von Siddim aber war voll Asphaltgruben. Als nun die Könige von Sodom und Gomorrha flohen, fielen sie dort hinein, und was übrigblieb, floh ins Gebirge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Da nahmen sie alle Habe von Sodom und Gomorrha und alle Nahrungsmittel darin fort und zogen davon. (1) d.h. die Feinde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Sie nahmen auch Lot, den Neffen Abrams, und seine Habe mit und zogen davon; der wohnte nämlich in Sodom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Da kam einer, der entronnen war, und brachte dem Hebräer Abram Kunde; der weilte bei der Terebinthe des Amoriters Mamre, des Bruders Eskols und Aners. Diese waren Abrams Bundesgenossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als nun Abram hörte, dass sein Verwandter gefangen sei, bewaffnete er seine erprobten Leute, die in seinem Haus gebornen Sklaven, 318 Mann, und jagte (den Feinden) nach bis Dan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Und er teilte seine Leute, überfiel jene bei Nacht mit seinen Sklaven, schlug sie und jagte ihnen nach bis Hoba, das nördlich von Damaskus liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Er brachte alle Habe zurück; auch seinen Verwandten Lot und dessen Habe brachte er zurück, ebenso die Frauen und das Volk.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Als nun Abram von seinem Siege über Kedor-Laomer und die mit ihm verbündeten Könige zurückkam, ging der König von Sodom ihm entgegen in das Tal Sawe - das ist das Königstal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melchisedek aber, der König von Salem, brachte Brot und Wein heraus; er war ein Priester des höchsten Gottes. (a) Ps 110:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: Gesegnet ist Abram vom höchsten Gott, dem Schöpfer des Himmels und der Erde,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'und gepriesen der höchste Gott, der deine Feinde in deine Hand gegeben hat! Und Abram gab ihm den Zehnten von allem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Da sprach der König von Sodom zu Abram: Gib mir die Leute; die Habe behalte für dich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram aber sprach zum König von Sodom: Ich hebe meine Hand auf zu dem Herrn, dem höchsten Gott, dem Schöpfer des Himmels und der Erde:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Nicht einen Faden noch Schuhriemen, nichts von allem, was dein ist, will ich behalten, dass du nicht sagest, du habest Abram reich gemacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Nichts will ich! nur was die Leute gegessen haben, und den Anteil der Männer, die mit mir gezogen sind; Aner, Eskol und Mamre, die mögen ihren Anteil bekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'DARNACH erging an Abram in einem Gesichte das Wort des Herrn: Fürchte dich nicht, Abram, ich bin dein Schild; dein wartet reicher Lohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram aber sprach: O Herr, mein Gott, was wolltest du mir geben? Muss ich doch von hinnen gehen ohne Kinder, und Erbe meines Hauses wird Elieser von Damaskus!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach: Mir hast du ja keine Kinder gegeben; so wird mein Haussklave mich beerben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Aber siehe, es erging an ihn das Wort des Herrn: Nicht er soll dein Erbe sein, sondern dein eigner leiblicher Sohn, der soll dein Erbe sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er führte ihn hinaus und sprach: Schaue gen Himmel und zähle die Sterne - ob du sie zählen kannst? Und er verhiess ihm: So sollen deine Nachkommen sein. (a) 1Mo 22:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram glaubte dem Herrn, und das rechnete er ihm als Gerechtigkeit an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und Gott sprach zu ihm: Ich bin der Herr, der dich aus Ur in Chaldäa herausgeführt hat, dass ich dir dieses Land zu eigen gebe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Er aber sprach: O Herr, mein Gott, woran soll ich erkennen, dass ich es besitzen werde?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Da gebot er ihm: Bringe mir eine dreijährige Kuh, eine dreijährige Ziege, einen dreijährigen Widder, eine Turteltaube und eine junge Taube.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Und er brachte ihm die Tiere alle, schnitt sie mitten entzwei und legte je einen Teil dem andern gegenüber; die Vögel aber zerschnitt er nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Und die Raubvögel stiessen auf die Toten Tiere herab, doch Abram scheuchte sie weg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Als nun die Sonne sich zum Untergange neigte, fiel ein Tiefschlaf auf Abram, und siehe, grosser Schrecken überfiel ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da sprach Gott zu Abram: Du sollst wissen, dass dein Geschlecht als Fremdling weilen wird in einem Lande, das nicht sein ist; und sie werden daselbst Sklaven sein, und man wird sie drücken, vierhundert Jahre lang. (a) 2Mo 1:13; 12:40');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Doch will ich auch über das Volk, dem sie dienen müssen, Gericht halten. Darnach werden sie mit reicher Habe ausziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Du aber sollst in Frieden zu deinen Vätern eingehen und in hohem Alter begraben werden. (a) 1Mo 25:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Erst das vierte Geschlecht wird hierher zurückkehren; denn noch ist nicht voll die Schuld der Amoriter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Als nun die Sonne untergegangen und es ganz finster geworden war, siehe da! ein rauchender Ofen und eine Feuerfackel, das fuhr zwischen diesen Stücken hin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An jenem Tage schloss der Herr mit Abram einen Bund und sprach: Deinem Geschlechte gebe ich dieses Land, vom Bach Ägyptens bis an den grossen Strom, den Euphratstrom; (a) 1Kön 5:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'die Keniter, die Kenissiter und die Kadmoniter,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'die Hethiter, die Pheresiter und die Rephaiter,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'die Amoriter, die Kanaaniter, die Girgasiter und die Jebusiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'SARAI, Abrams Weib, hatte ihm kein Kind geboren. Nun hatte sie eine ägyptische Magd, die hiess Hagar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Und Sarai sprach zu Abram: Der Herr hat mir nun einmal Kinder versagt. So gehe denn zu meiner Magd; vielleicht, dass ich durch sie einen Sohn bekomme. Und Abram hörte auf Sarai.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Da nahm Sarai, Abrams Weib, die Ägypterin Hagar, ihre Magd, nachdem Abram zehn Jahre im Lande Kanaan gewohnt hatte, und gab sie ihrem Manne Abram zum Weibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er ging zu Hagar, und sie ward schwanger. Als sie nun merkte, dass sie schwanger war, sah sie auf ihre Herrin herab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sprach Sarai zu Abram: Das Unrecht, das mir geschieht, komme über dich! Ich selbst habe dir meine Magd in die Arme gelegt. Nun, da sie sich schwanger weiss, sieht sie auf mich herab. Der Herr sei Richter zwischen mir und dir!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram aber sprach zu Sarai: Nun, deine Magd ist ja in deiner Gewalt; mache mit ihr, was dir gefällt. Da nun Sarai sie hart behandelte, entfloh sie ihr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Da traf sie der Engel des Herrn am Wasserquell in der Wüste, am Quell auf dem Wege nach Sur,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'und sprach: Hagar, Magd Sarais, wo kommst du her und wo willst du hin? Sie antwortete: Vor meiner Herrin Sarai fliehe ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Aber der Engel des Herrn sprach zu ihr: Kehre zurück zu deiner Herrin und ertrage ihre Härte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und er gab ihr die Verheissung: Zahlreich machen will ich dein Geschlecht, dass man vor Menge es nicht zählen kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Weiter sprach der Engel des Herrn zu ihr: Siehe, du bist schwanger und wirst einen Sohn gebären, den sollst du Ismael nennen, weil der Herr gehört hat, wie du littest. (1) d.i. Gott hört.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Er wird ein Mensch sein wie ein Wildesel - seine Hand wider jedermann und jedermanns Hand wider ihn; und allen seinen Brüdern setzt er sich vors Gesicht. (a) 1Mo 21:20; 25:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Und sie nannte den Namen des Herrn, der mit ihr redete: Du bist der El-Roi. Denn, sprach sie, wahrlich, hier habe ich dem nachgeschaut, der mich erschaute. (1) d.i. Gott des Schauens.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Darum nennt man diesen Quell den Quell von Lahai-Roi; der liegt zwischen Kades und Bered.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Sohn, den Hagar ihm geboren hatte, Ismael.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram war 86 Jahre alt, als Hagar ihm den Ismael gebar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'ALS Abram 99 Jahre alt war, erschien ihm der Herr und sprach zu ihm: Ich bin der allmächtige Gott, wandle vor mir, dann wirst du unsträflich sein,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'und ich will einen Bund stiften zwischen mir und dir und will dich über alle Massen mehren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da warf sich Abram auf sein Angesicht, und Gott redete mit ihm und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Siehe, das ist mein Bund mit dir, dass du ein Vater vieler Völker werden sollst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Darum sollst du nicht mehr Abram heissen, sondern Abraham soll dein Name sein; denn ich mache dich zum Vater vieler Völker. (1) der Erzähler hörte aus dem Namen Abraham etwas wie \"Vater der Menge\" heraus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Ich will dich über alle Massen fruchtbar machen und dich zu Völkern werden lassen, und Könige sollen von dir abstammen. (a) 1Mo 35:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Ich richte meinen Bund auf zwischen mir und dir und deinen Nachkommen von Geschlecht zu Geschlecht als einen ewigen Bund, dass ich dein und deiner Nachkommen Gott sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und ich gebe dir und deinen Nachkommen das Land, wo du als Fremdling weilst, das ganze Land Kanaan, zu ewigem Besitz, und ich will ihnen Gott sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham: Du aber halte meinen Bund, du und deine Nachkommen, Geschlecht für Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das aber ist der Bund zwischen mir und euch und deinen Nachkommen, den ihr halten sollt: Alles, was männlich ist unter euch, das soll beschnitten werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'An der Vorhaut sollt ihr beschnitten werden. Das soll ein Zeichen sein des Bundes zwischen mir und euch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Im Alter von acht Tagen soll alles, was männlich ist unter euch, beschnitten werden, Geschlecht für Geschlecht. (Auch der Sklave,) der im Haus geborne wie der von irgendeinem Fremden um Geld gekaufte, der nicht deines Stammes ist: (a) 3Mo 12:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'beide sollen beschnitten werden, der in deinem Haus geborne wie der von dir um Geld gekaufte. Das soll mein Bund an eurem Leibe sein, ein ewiger Bund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Ein Unbeschnittener aber - nämlich was männlich ist und unbeschnitten bleibt an der Vorhaut -, dessen Seele soll aus seinen Volksgenossen ausgerottet werden: meinen Bund hat er gebrochen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach zu Abraham: Dein Weib Sarai sollst du nicht mehr Sarai nennen, sondern Sara soll ihr Name sein. (1) d.i. Fürstin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ich will sie segnen, und auch von ihr gebe ich dir einen Sohn; ich will sie segnen, und sie soll zu Völkern werden, und Könige von Nationen sollen von ihr kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da warf sich Abraham auf sein Angesicht und lachte und sprach bei sich selbst: Einem Hundertjährigen sollte noch (ein Sohn) geboren werden? und Sara sollte mit neunzig Jahren noch gebären?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Ach, möchte nur Ismael vor dir am Leben bleiben!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sprach Gott: Vielmehr, dein Weib Sara soll dir einen Sohn gebären, den sollst du Isaak nennen, und ich will meinen Bund mit ihm aufrichten als einen ewigen Bund, dass ich sein Gott und seiner Nachkommen Gott sei. (a) 1Mo 21:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Aber auch wegen Ismaels erhöre ich dich: Siehe, ich segne ihn und mache ihn fruchtbar und überaus zahlreich; zwölf Fürsten wird er zeugen, und ich will ihn zu einem grossen Volke machen. (a) 1Mo 25:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Meinen Bund aber will ich aufrichten mit Isaak, den dir Sara gebären wird um diese Zeit im nächsten Jahr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Als Gott mit Abraham zu Ende geredet hatte, fuhr er auf von ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Da nahm Abraham seinen Sohn Ismael und alle Sklaven, die in seinem Hause geboren, und alle, die von ihm um Geld gekauft waren, alles, was männlich war unter seinen Hausgenossen, und beschnitt ihre Vorhaut noch am selben Tage, wie ihm Gott geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham war 99 Jahre alt, als er an der Vorhaut beschnitten wurde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Sein Sohn Ismael aber war dreizehn Jahre alt, als er an der Vorhaut beschnitten wurde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Noch am selben Tage wurden Abraham und sein Sohn Ismael beschnitten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'und alles, was männlich war in seinem Hause, der im Haus geborne wie der von Fremden um Geld gekaufte (Sklave), wurde mit ihm beschnitten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'UND der Herr erschien ihm bei der Terebinthe Mamres, während er am Eingang seines Zeltes sass, als der Tag am heissesten war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Wie er nun seine Augen erhob und sich umschaute, siehe, da standen drei Männer vor ihm. Sobald er sie sah, eilte er ihnen vom Eingang seines Zeltes entgegen, verneigte sich zur Erde');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'und sprach: Mein Herr, habe ich Gnade gefunden vor deinen Augen, so gehe doch nicht an deinem Knechte vorüber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soll ein wenig Wasser bringen, dass ihr euch die Füsse waschet, dann lagert euch unter dem Baume,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'und ich will einen Bissen Brot holen, dass ihr euch erlabet; darnach mögt ihr weiterziehen. Ihr seid nun einmal bei eurem Knecht vorbeigekommen. Sie sprachen: Du magst tun, wie du gesagt hast.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Nun eilte Abraham ins Zelt zu Sara und sprach: Nimm schnell drei Scheffel Mehl! Knete es und backe Kuchen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Auch zu den Rindern lief Abraham, holte ein zartes, schönes Kalb und gab es dem Knechte; der rüstete es eilends zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Dann nahm er Sauermilch und frische Milch und das Kalb, das er gerüstet hatte, und setzte es ihnen vor; er selbst aber wartete ihnen auf unter dem Baume, und sie assen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sprachen sie zu ihm: Wo ist dein Weib Sara? Er antwortete: Da drinnen im Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sprach er: Ich werde wieder zu dir kommen übers Jahr um diese Zeit; dann hat dein Weib Sara einen Sohn. Sara aber hörte zu am Eingang des Zeltes hinter ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Nun waren Abraham und Sara alt und hochbetagt, sodass es Sara nicht mehr nach der Frauen Weise ging.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Darum lachte Sara bei sich selbst und dachte: Nun ich welk bin, soll mich noch Liebeslust ankommen? Und auch mein Herr ist alt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sprach der Herr zu Abraham: Warum lacht denn Sara und denkt: \"Sollte ich wirklich noch Mutter werden können, da ich doch alt bin?\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ist denn irgend etwas unmöglich für den Herrn? Übers Jahr um diese Zeit werde ich wieder zu dir kommen; dann hat Sara einen Sohn. (a) Lu 1:37');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Sara leugnete und sprach: Ich habe nicht gelacht. Denn sie fürchtete sich. Aber er sprach: Doch, du hast gelacht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Da erhoben sich die Männer und gingen von dannen. UND schon schauten sie hinab auf Sodom, während Abraham noch mit ihnen ging, um ihnen das Geleit zu geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Der Herr aber dachte: Soll ich vor Abraham geheimhalten, was ich tun will? (a) Am 3:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham soll doch ein grosses und starkes Volk werden, und alle Völker der Erde werden sich mit seinem Namen Segen wünschen. (1) vgl. Anm. zu 1Mo 12:2 3.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn ich habe ihn erkoren, dass er seinen Söhnen und seinem Hause nach ihm befehle, den Weg des Herrn zu beobachten und Gerechtigkeit und Recht zu üben, damit der Herr über Abraham kommen lasse, was er ihm verheissen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und der Herr sprach: Das Geschrei über Sodom und Gomorrha, das ist gross, und ihre Sünde, die ist gar schwer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Darum will ich hinab und sehen, ob sie wirklich ganz so gehandelt haben, wie das Geschrei über sie verlautet, das zu mir gedrungen ist, oder nicht; das will ich erfahren!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Und die Männer wandten sich von dannen und gingen Sodom zu; Abraham aber blieb noch vor dem Herrn stehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat herzu und sprach: Willst du mit dem Gottlosen auch den Gerechten wegraffen? (a) 4Mo 16:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht sind fünfzig Gerechte in der Stadt; willst du die auch wegraffen und nicht lieber dem Ort vergeben wegen der fünfzig Gerechten darin?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ferne sei es von dir, solches zu tun, den Gerechten mit dem Gottlosen zu töten, dass es dem Gerechten erginge wie dem Gottlosen! Das sei ferne von dir! Der aller Welt Richter ist, sollte der nicht Recht üben?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Der Herr sprach: Finde ich zu Sodom fünfzig Gerechte in der Stadt, so will ich um ihretwillen dem ganzen Ort vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham aber hob von neuem an und sprach: Ach, ich habe mich unterfangen, mit meinem Herrn zu reden, wiewohl ich Staub und Asche bin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht sind es fünf weniger als fünfzig Gerechte; willst du dann die ganze Stadt verderben um der fünfe willen? Er sprach: Finde ich fünfundvierzig darin, so will ich sie nicht verderben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Und abermals redete er mit ihm und sprach: Vielleicht sind nur vierzig darin zu finden. Er sprach: Ich will es nicht tun, um der vierzig willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Er sprach: Mein Herr zürne nicht, wenn ich nochmals rede. Vielleicht sind nur dreissig darin zu finden. Er sprach: Finde ich dreissig darin, so will ich es nicht tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Er sprach: Ach, ich habe mich unterfangen, mit meinem Herrn zu reden; vielleicht sind nur zwanzig darin zu finden. Er sprach: Ich will sie nicht verderben, um der zwanzig willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Er sprach: Mein Herr zürne nicht, wenn ich noch diesmal rede. Vielleicht sind nur zehn darin zu finden. Er sprach: Ich will sie nicht verderben, um der zehne willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Dann ging der Herr hinweg, als er mit Abraham zu Ende geredet hatte. Abraham aber kehrte zurück an seinen Ort.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'UND die zwei Engel kamen am Abend nach Sodom, als Lot gerade im Tore von Sodom sass. Sobald er sie sah, stand er auf, ging ihnen entgegen, verneigte sich mit dem Angesicht zur Erde');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'und sprach: Ach, ihr Herren, kehrt doch im Hause eures Knechtes ein und bleibt übernacht und waschet eure Füsse; morgen früh mögt ihr dann eures Weges ziehen. Sie aber sprachen: Nein, wir wollen da auf dem Platze übernacht bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Da er aber sehr in sie drang, kehrten sie bei ihm ein und kamen in sein Haus. Und er rüstete ihnen ein Mahl und buk ungesäuerte Kuchen, und sie assen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Doch ehe sie sich schlafen legten, hatten schon die Männer der Stadt, die Männer von Sodom, jung und alt, alle insgesamt, das Haus umzingelt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Und sie riefen Lot und sprachen zu ihm: Wo sind die Männer, die heute abend zu dir gekommen sind? Bringe sie zu uns heraus, dass wir ihnen beiwohnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da trat Lot zu ihnen hinaus vor die Türe und schloss hinter sich zu');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'und sprach: Ach, liebe Brüder, tut doch nichts Schlechtes!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Seht, ich habe zwei Töchter, die noch nichts vom Manne wissen, die will ich euch herausgeben; macht mit ihnen, was euch gefällt. Nur diesen Männern tut nichts; denn sie sind nun einmal unter den Schatten meines Daches getreten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Sie aber schrieen: Weg mit dir! und sagten: Kommt der da ganz allein als Fremdling her und will den Richter spielen! Nun, wir wollen dir Schlimmeres antun als ihnen. So drangen sie mit Gewalt auf den Mann, auf Lot, ein und machten sich daran, die Türe zu erbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Aber die Männer streckten die Hand aus und zogen Lot zu sich ins Haus herein, und die Türe schlossen sie zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Die Leute vor der Haustüre aber schlugen sie mit Blindheit, klein und gross, sodass sie sich umsonst abmühten, die Türe zu finden. (a) 2Kön 6:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Dann sprachen die Männer zu Lot: Hast du noch jemand hier? Deine Söhne und Töchter, und wer in der Stadt dir angehört, die führe hinweg aus diesem Orte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir werden diese Stadt verderben, weil lautes Geschrei über sie vor den Herrn gekommen ist; und so hat uns der Herr gesandt, sie zu verderben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot hinaus und redete mit seinen Tochtermännern, die seine Töchter heiraten wollten, und sprach: Auf, geht hinweg aus diesem Orte! Denn der Herr wird diese Stadt verderben. Aber seine Tochtermänner glaubten, er scherze.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Als nun die Morgenröte heraufkam, trieben die Engel Lot zur Eile an und sprachen: Auf, nimm dein Weib und deine beiden Töchter, die hier sind, dass du nicht weggerafft werdest durch die Schuld der Stadt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Da er aber noch zögerte, ergriffen die Männer ihn und sein Weib und seine beiden Töchter bei der Hand, weil der Herr ihn verschonen wollte, führten ihn hinaus und liessen ihn draussen vor der Stadt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und als sie dieselben hinausgeführt hatten, sprach er: Rette dich! es gilt dein Leben! Sieh nicht hinter dich und bleibe nirgends stehen im ganzen Umkreis! Ins Gebirge rette dich, dass du nicht weggerafft werdest!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Aber Lot sprach zu ihm: Ach nein, Herr!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Dein Knecht hat ja doch Gnade gefunden vor deinen Augen, und du hast mir grosse Barmherzigkeit erwiesen, dass du mich am Leben erhalten hast. Aber ins Gebirge kann ich mich nicht retten; es könnte das Verderben mich ereilen, dass ich sterben müsste.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, die Stadt da ist nahe, sodass ich dahin fliehen könnte; und sie ist ja klein. Ach, lass mich dahin fliehen! Ist die Stadt nicht klein? So könnte ich am Leben bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da sprach er zu ihm: Siehe, ich will dir auch in diesem Stück willfahren und die Stadt nicht zerstören, von der du geredet hast.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Schnell, rette dich dorthin; denn ich kann nichts tun, bis du dort hineingekommen bist. Daher heisst die Stadt Zoar. (1) d.i. Kleinheit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Und eben, als die Sonne über der Erde aufgegangen war, kam Lot nach Zoar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Der Herr aber liess Schwefel und Feuer auf Sodom und Gomorrha regnen, von dem Herrn vom Himmel herab, (a) 5Mo 29:23; Jes 13:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'und vernichtete so die Städte und den ganzen Umkreis und alle Bewohner der Städte und was auf dem Lande gewachsen war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Lots Weib aber sah sich hinter ihm um und ward zur Salzsäule.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Am andern Morgen in der Frühe machte sich Abraham auf an den Ort, wo er vor dem Herrn gestanden hatte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'und schaute hinab auf Sodom und Gomorrha und auf das ganze umliegende Land. Da sah er den Qualm aufsteigen von dem Lande, wie Qualm von einem Schmelzofen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Und als Gott die Städte in der Niederung vernichtete, da gedachte er Abrahams, und er geleitete Lot hinweg aus der Zerstörung, als er die Städte zerstörte, in denen Lot gewohnt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot aber zog von Zoar hinauf und liess sich mit seinen beiden Töchtern im Gebirge nieder; denn er fürchtete sich, in Zoar zu bleiben. Und er wohnte mit seinen Töchtern in einer Höhle.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sprach die ältere zur jüngern: Unser Vater ist alt, und es ist kein Mann mehr im Lande, der zu uns kommen könnte nach aller Welt Brauch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Komm, wir wollen unserm Vater Wein zu trinken geben und uns zu ihm legen, dass wir durch unsern Vater unsern Stamm erhalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Also gaben sie in jener Nacht ihrem Vater Wein zu trinken. Dann ging die ältere hinein und legte sich zu ihrem Vater, und er merkte nichts davon, weder wie sie sich hinlegte, noch wie sie aufstand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Am Morgen sprach die ältere zur jüngern: Sieh, ich habe gestern bei meinem Vater gelegen. Nun wollen wir ihm auch heute nacht Wein zu trinken geben; dann geh du hinein und lege dich zu ihm, dass wir durch unsern Vater unsern Stamm erhalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Also gaben sie ihrem Vater auch in jener Nacht Wein zu trinken. Dann stand die jüngere auf und legte sich zu ihm, und er merkte nichts davon, weder wie sie sich hinlegte, noch wie sie aufstand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'So wurden die beiden Töchter Lots schwanger von ihrem Vater.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die ältere gebar einen Sohn und nannte ihn Moab; der ist der Stammvater der Moabiter bis auf den heutigen Tag. (1) Meab = vom Vater.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Und auch die jüngere gebar einen Sohn und nannte ihn Ben-Ammi; der ist der Stammvater der Ammoniter bis auf den heutigen Tag. (1) d.i. Sohn meines Verwandten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'ABRAHAM aber zog von dort in das Gebiet des Südlands und blieb zwischen Kades und Sur. Als er nun in Gerar weilte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'sagte er von seinem Weibe Sara: Sie ist meine Schwester. Da sandte Abimelech, der König von Gerar, hin und liess Sara holen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Des Nachts aber kam Gott zu Abimelech im Traum und sprach zu ihm: Fürwahr, du bist des Todes um des Weibes willen, das du genommen hast; denn sie ist ein Eheweib.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech jedoch hatte sie noch nicht berührt, und so sprach er: Herr, willst du wirklich Unschuldige umbringen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er nicht selbst zu mir gesagt: \"Sie ist meine Schwester\"? Und auch sie hat gesagt: \"Er ist mein Bruder.\" In aller Unschuld und mit reinen Händen habe ich das getan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Da antwortete ihm Gott im Traum: Auch ich weiss wohl, dass du das in aller Unschuld getan hast, und ich selber habe dich davor behütet, dich an mir zu versündigen; darum habe ich dir nicht gestattet, sie zu berühren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'So gib nun dem Manne sein Weib zurück, denn er ist ein Prophet, und er wird dann für dich bitten, sodass du am Leben bleibst. Gibst du sie aber nicht zurück, so wisse, dass du mit all den Deinen sterben musst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Am andern Morgen rief Abimelech alsbald seine Knechte und erzählte ihnen alles, was sich zugetragen hatte; und die Leute fürchteten sich sehr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Dann liess Abimelech den Abraham rufen und sprach zu ihm: Was habe ich dir getan, und womit habe ich an dir gesündigt, dass du so grosse Sünde über mich und mein Reich gebracht hast? Du hast an mir gehandelt, wie man nicht handeln soll.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und weiter sprach Abimelech zu Abraham: Was hast du denn beabsichtigt, dass du das getan hast?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham antwortete: Ich dachte eben: es gibt sicher keine Gottesfurcht an diesem Orte, und so werden sie mich umbringen um meines Weibes willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Auch ist sie wirklich meine Schwester, die Tochter meines Vaters, nur nicht die Tochter meiner Mutter; so konnte sie mein Weib werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Als mich nun Gott aus meines Vaters Hause in die Ferne wandern hiess, sprach ich zu ihr: Das musst du mir zuliebe tun, dass du überall, wohin wir kommen, von mir sagst, ich sei dein Bruder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Schafe und Rinder, Sklaven und Sklavinnen und schenkte sie Abraham; und sein Weib Sara gab er ihm zurück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: Sieh, mein Land steht dir offen; bleibe, wo es dir gefällt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Zu Sara aber sprach er: Sieh, da schenke ich deinem Bruder tausend Lot Silber; das soll eine Ehrenrettung für dich sein vor allen, die bei dir sind, und so bist du vor jedermann gerechtfertigt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Nun betete Abraham zu Gott, und Gott heilte Abimelech, sein Weib und seine Mägde, dass sie Kinder bekamen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Der Herr hatte nämlich jeden Mutterschoss im Hause Abimelechs verschlossen, um Saras, des Weibes Abrahams, willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'DER Herr aber nahm sich Saras an, wie er verheissen hatte, und tat an ihr nach seinem Worte: (a) 1Mo 18:10 14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara ward schwanger und gebar dem Abraham in seinem Alter einen Sohn, um die Zeit, die Gott angekündigt hatte. (a) 1Mo 18:10 14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham nannte den Sohn, der ihm von Sara geboren worden war, Isaak.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Am achten Tage aber beschnitt Abraham seinen Sohn Isaak, wie ihm Gott geboten hatte. (a) 1Mo 17:11 12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham war hundert Jahre alt, als ihm sein Sohn Isaak geboren wurde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Da sprach Sara: Ein Lachen hat mir Gott bereitet! Wer davon hört, wird über mich lachen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: Wer hat je dem Abraham verkünden können, dass Sara Kinder stillt? Und doch habe ich ihm in seinem Alter einen Sohn geboren!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind wuchs und ward entwöhnt; und Abraham veranstaltete ein grosses Mahl an dem Tage, da Isaak entwöhnt ward.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Als nun Sara den Sohn der Ägypterin Hagar, den diese dem Abraham geboren hatte, mit ihrem Sohne Isaak spielen sah,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'sprach sie zu Abraham: Jage die Magd da mit ihrem Sohne fort; denn der Sohn dieser Magd soll nicht Erbe werden mit meinem Sohn, mit Isaak.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dieses Wort missfiel Abraham sehr um seines Sohnes willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Aber Gott sprach zu Abraham: Lass dir\'s nicht leid sein um den Knaben und um deine Magd. In allem, was Sara zu dir sagt, höre auf sie. Denn nur nach Isaak soll dein Geschlecht benannt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Doch auch den Sohn der Magd will ich zu einem Volke machen, weil er deines Stammes ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Am andern Morgen in der Frühe nahm Abraham Brot und einen Schlauch voll Wasser und gab es Hagar, den Knaben aber setzte er ihr auf die Schulter; so schickte er sie fort. Da ging sie hin und irrte in der Wüste von Beerseba umher.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Als nun das Wasser in dem Schlauche ausgegangen war, warf sie den Knaben unter einen Strauch,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ging hin und setzte sich gegenüber, etwa einen Bogenschuss weit. Denn sie sprach: Ich kann den Tod des Knaben nicht mitansehen. So sass sie ihm gegenüber; der Knabe aber begann laut zu weinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Da hörte Gott die Stimme des Knaben, und der Engel Gottes rief der Hagar vom Himmel zu und sprach zu ihr: Was hast du, Hagar? Fürchte dich nicht; denn Gott hat die Stimme des Knaben gehört, dort wo er liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Stehe auf, nimm den Knaben und halte ihn fest an der Hand; denn zu einem grossen Volke will ich ihn machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott öffnete ihr die Augen, dass sie einen Wasserquell sah. Da ging sie hin, füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben: er wuchs auf und wohnte in der Wüste und ward ein Bogenschütze.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'ZU derselben Zeit sprachen Abimelech und sein Feldhauptmann Pichol zu Abraham: Gott ist mit dir in allem, was du tust.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'So schwöre mir nun bei Gott, dass du weder an mir noch an meinen Kindern und Kindeskindern treulos handeln willst; sondern die Freundschaft, die ich dir erwiesen habe, sollst du auch mir erweisen und dem Lande, darin du als Fremdling weilst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sprach Abraham: Ich schwöre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham aber stellte den Abimelech zur Rede wegen des Wasserquells, den Abimelechs Knechte mit Gewalt genommen hatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelech entgegnete: Ich weiss nicht, wer das getan hat; du hast mir nichts davon gesagt, und ich habe auch bis heute nichts davon gehört.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und sie schlossen miteinander einen Bund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Als nun Abraham sieben Lämmer beiseite stellte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'fragte Abimelech den Abraham: Was sollen diese sieben Lämmer hier, die du beiseite gestellt hast?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Er antwortete: Die sieben Lämmer musst du von mir annehmen, damit sie mir als Zeugnis dienen, dass ich diesen Brunnen gegraben habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher nannte man den Ort \"Beer-Seba\", weil sie einander dort geschworen haben. (1) d.i. Schwurbrunnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'So schlossen sie einen Bund zu Beerseba. Dann machte sich Abimelech mit seinem Feldhauptmann Pichol auf, und sie kehrten ins Philisterland zurück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham aber pflanzte in Beerseba eine Tamariske und rief daselbst den Namen des Herrn an, des ewigen Gottes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und er weilte noch lange Zeit als Fremdling im Philisterland.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'NACH diesen Begebenheiten wollte Gott den Abraham prüfen. Er sprach zu ihm: Abraham! Er antwortete: Hier bin ich!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Er sprach: Nimm deinen Sohn, deinen einzigen, den du liebhast, den Isaak, und gehe hin ins Land Moria und opfere ihn daselbst als Brandopfer auf einem der Berge, den ich dir nennen werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da bepackte Abraham am andern Morgen in der Frühe seinen Esel und nahm seine beiden Knechte und seinen Sohn Isaak mit sich; und er spaltete das Holz zum Brandopfer, machte sich auf und ging an den Ort, den ihm Gott genannt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage, als Abraham seine Augen erhob, sah er die Stätte von ferne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sprach Abraham zu seinen Knechten: Bleibet ihr hier mit dem Esel, ich aber und der Knabe wollen dorthin gehen, und wenn wir angebetet haben, wollen wir zu euch zurückkommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Dann nahm Abraham das Holz zum Brandopfer und lud es seinem Sohne Isaak auf; er selbst nahm den Feuerbrand und das Messer, und so gingen die beiden miteinander.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sprach Isaak zu seinem Vater Abraham: Vater! Abraham antwortete: Was willst du, mein Sohn? Er sprach: Siehe, hier ist wohl der Feuerbrand und das Holz; wo ist aber das Lamm zum Opfer?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham antwortete: Gott wird sich das Lamm zum Opfer selbst ersehen, mein Sohn. So gingen die beiden miteinander.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Als sie nun an die Stätte kamen, die Gott ihm genannt hatte, baute Abraham daselbst den Altar und schichtete das Holz darauf; dann band er seinen Sohn Isaak und legte ihn auf den Altar, oben auf das Holz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Hierauf streckte Abraham seine Hand aus und ergriff das Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm vom Himmel her der Engel des Herrn zu: Abraham, Abraham! Er antwortete: Hier bin ich!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Er sprach: Lege deine Hand nicht an den Knaben und tue ihm nichts; denn nun weiss ich, dass du Gott fürchtest: du hast deinen Sohn, deinen einzigen, mir nicht vorenthalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Wie nun Abraham seine Augen erhob, sah er einen Widder, der sich mit seinen Hörnern im Gebüsch verfangen hatte. Da ging Abraham hin, nahm den Widder und opferte ihn als Brandopfer anstatt seines Sohnes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham nannte die Stätte \"Gottessicht\"; daher man noch heutigen Tages sagt: auf dem Berge \"Gottessicht\".');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und der Engel des Herrn rief Abraham abermals zu vom Himmel her:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Ich schwöre bei mir selbst, spricht der Herr: weil du das getan und deinen Sohn, deinen einzigen, mir nicht vorenthalten hast,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'darum will ich dich segnen und dein Geschlecht so zahlreich machen wie die Sterne des Himmels und wie den Sand am Gestade des Meeres, und dein Geschlecht wird das Tor seiner Feinde besitzen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'mit dem Namen deines Stammes werden sich Segen wünschen alle Völker der Erde, weil du mir gehorcht hast. (1) vgl. Anm. zu 1Mo 12:2 3.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Hierauf kehrte Abraham zu seinen Knechten zurück, und sie machten sich auf und zogen zusammen nach Beerseba, und Abraham blieb in Beerseba wohnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'NACH diesen Begebenheiten ward dem Abraham gemeldet: Auch Milka hat deinem Bruder Nahor Söhne geboren:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'seinen Erstgebornen Uz und dessen Bruder Bus, und Kemuel, den Vater Arams,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Chesed und Haso, Pildas, Jidlaph und Bethuel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bethuel aber hat die Rebekka gezeugt. Diese acht gebar Milka dem Nahor, dem Bruder Abrahams;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'und seine Nebenfrau, mit Namen Rehuma, gebar auch Kinder: Tebah und Gaham, Thahas und Maacha.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'SARA wurde 127 Jahre alt; so lange lebte sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Dann starb Sara in Kirjath-Arba - das ist Hebron - im Lande Kanaan. Da ging Abraham hinein, die Totenklage um Sara zu halten und sie zu beweinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Darnach stand Abraham auf von seiner Toten und sprach zu den Hethitern:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ich bin bei euch ein Fremdling und Beisasse; gebt mir eine Grabstätte bei euch zu eigen, dass ich meine Tote hinausbringe und begrabe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Die Hethiter antworteten dem Abraham:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Möchtest du uns doch anhören, Herr! Du bist ein Gottesfürst mitten unter uns; im besten unsrer Gräber magst du deine Tote begraben! Keiner von uns wird dir sein Grab verweigern, deine Tote darin zu begraben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da stand Abraham auf, verneigte sich tief vor den Leuten des Landes, den Hethitern,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'und sprach zu ihnen: Ist es denn euer Wille, dass ich meine Tote hinausbringe und begrabe, so höret mich an und tretet für mich ein bei Ephron, dem Sohne Zohars,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'dass er mir die Höhle Machpela gebe, die ihm gehört, am Ende seines Grundstücks; um gutes Geld gebe er sie mir unter euch als Grabstätte zu eigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ephron aber sass mitten unter den Hethitern. Da antwortete der Hethiter Ephron dem Abraham vor den Hethitern, vor allen, die im Tore seiner Stadt erschienen waren, und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Möchtest du mich doch anhören, Herr! Ich schenke dir das Grundstück; auch die Höhle daselbst schenke ich dir, vor meinen Volksgenossen schenke ich sie dir. Begrabe nur deine Tote.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da verneigte sich Abraham tief vor den Leuten des Landes');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und sprach zu Ephron, dass die Leute des Landes es hörten: Doch nur, wenn du - bitte, höre mich an: ich bezahle das Geld für das Grundstück, nimm es von mir an; dann will ich meine Tote dort begraben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron aber antwortete dem Abraham:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Möchtest du mich doch anhören, Herr! Ein Stück Land, vierhundert Lot Silber wert, was bedeutet das zwischen mir und dir? Begrabe nur deine Tote.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Und Abraham willfahrte dem Ephron, und Abraham wog Ephron die Summe dar, die er vor den Hethitern genannt hatte: vierhundert Lot Silber nach dem im Handel üblichen Gewicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'So wurde Ephrons Grundstück bei Machpela, gegenüber Mamre, das Grundstück samt der Höhle und allen Bäumen auf dem Grundstück in seinem ganzen Umfang, (a) 1Mo 25:9 10; 50:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abrahams Eigentum in Gegenwart der Hethiter, aller, die im Tore seiner Stadt erschienen waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Darnach begrub Abraham sein Weib Sara in der Höhle auf dem Grundstück Machpela gegenüber Mamre - das ist Hebron - im Lande Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'So ging das Grundstück samt der Höhle von den Hethitern als Grabstätte in Abrahams Besitz über.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'ABRAHAM aber war alt geworden und hochbetagt, und der Herr hatte ihn in allem gesegnet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Nun sprach Abraham zu dem ältesten Knechte seines Hauses, der Verwalter aller seiner Güter war: lege doch deine Hand unter meine Hüfte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'ich will dich schwören lassen bei dem Herrn, dem Gott des Himmels und dem Gott der Erde, dass du meinem Sohne kein Weib nehmest von den Töchtern der Kanaaniter, unter denen ich wohne, (a) 1Mo 28:1 2; 5Mo 7:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sondern in mein Vaterland und zu meiner Verwandtschaft sollst du ziehen, ein Weib für meinen Sohn Isaak zu holen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Da sprach der Knecht zu ihm: Wie? wenn mir das Weib in dieses Land nicht folgen will? Soll ich alsdann deinen Sohn in jenes Land zurückbringen, aus dem du weggezogen bist?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sprach zu ihm: Hüte dich wohl, meinen Sohn dorthin zurückzubringen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Der Herr, der Gott des Himmels, der mich aus meines Vaters Hause und aus dem Lande meiner Verwandtschaft genommen, der mit mir geredet und mir geschworen hat: \"Deinen Nachkommen will ich dieses Land geben\", - der wird seinen Engel vor dir her senden, dass du dort ein Weib für meinen Sohn bekommst. (a) 1Mo 12:1 7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Wenn aber das Weib nicht mit dir ziehen will, so bist du dieses Eides ledig; doch meinen Sohn darfst du nicht wieder dorthin bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Knecht seine Hand unter die Hüfte Abrahams, seines Herrn, und schwur, nach seinem Wort zu tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Dann nahm der Knecht zehn Kamele von den Kamelen seines Herrn und allerlei Kostbarkeiten seines Herrn mit sich, brach auf und zog nach Syrien am Euphrat, nach der Stadt Nahors.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Da liess er die Kamele sich lagern, draussen vor der Stadt am Wasserquell, abends um die Zeit, da die Frauen herauskommen, um zu schöpfen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Und er sprach: O Herr, du Gott meines Herrn Abraham, lass es mir doch heute glücken und erweise dich gütig gegen Abraham, meinen Herrn!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Ich stelle mich jetzt hier an den Wasserquell, wenn die Töchter der Stadtbewohner herauskommen, um Wasser zu schöpfen:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'das Mädchen nun, zu dem ich sage: \"Neige doch deinen Krug, dass ich trinke\", und das dann spricht: \"Trinke, und auch deine Kamele will ich tränken\" - die soll es sein, die du deinem Knechte Isaak bestimmt hast; daran will ich erkennen, dass du dich gegen meinen Herrn gütig erweisest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Und ehe er noch ausgeredet hatte, siehe, da kam auch schon Rebekka heraus, die Tochter Bethuels, des Sohnes der Milka, des Weibes Nahors, des Bruders Abrahams; die trug ihren Krug auf der Achsel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Das Mädchen war sehr schön von Ansehen, eine Jungfrau; noch kein Mann hatte sie berührt. Sie stieg zum Quell hinab, füllte ihren Krug und stieg wieder herauf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da lief ihr der Knecht entgegen und sprach: Lass mich doch ein wenig Wasser aus deinem Kruge trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Sie sprach: Trinke, Herr! Und schnell nahm sie ihren Krug herab auf die Hand und gab ihm zu trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und als sie ihm genug zu trinken gegeben, sprach sie: Auch deinen Kamelen will ich schöpfen, bis sie genug getrunken haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und eilends leerte sie den Krug in die Tränkrinne; dann lief sie abermals zum Brunnen, um zu schöpfen, und schöpfte für alle seine Kamele.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Der Mann aber schaute ihr verwundert zu und schwieg stille, um zu erkennen, ob der Herr seine Reise habe gelingen lassen oder nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Als nun die Kamele genug getrunken hatten, nahm der Mann einen goldenen Nasenring, ein halbes Lot schwer, und zwei Spangen für ihre Arme, zehn Lot Gold schwer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Und er sprach: Wessen Tochter bist du? Sage es mir doch! Finden wir in deines Vaters Hause wohl Platz zum Übernachten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie sprach zu ihm: Ich bin die Tochter Bethuels, des Sohnes der Milka, den sie dem Nahor geboren hat. (a) 1Mo 22:23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Dann sagte sie zu ihm: Wir haben Stroh und Futter in Fülle und auch Platz zum Übernachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da verneigte sich der Mann, fiel vor dem Herrn nieder');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'und sprach: Gelobt sei der Herr, der Gott meines Gebieters Abraham, der seine Huld und Treue meinem Gebieter nicht entzogen hat! Mich hat Gott wahrhaftig den Weg zum Hause des Bruders meines Herrn geführt!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Das Mädchen aber lief hin und erzählte alles im Hause ihrer Mutter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Nun hatte Rebekka einen Bruder, der hiess Laban.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Als der den Nasenring sah und die Spangen an den Armen seiner Schwester, und als er hörte, wie seine Schwester Rebekka erzählte: \"So und so hat der Mann zu mir geredet\", lief er zu dem Manne hinaus an den Brunnen; und wie er zu dem Manne kam, stand der noch immer bei den Kamelen am Brunnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Und Laban sprach zu ihm: Komm herein, du Gesegneter des Herrn! Warum bleibst du da draussen stehen? Ich habe schon das Haus aufgeräumt und auch für die Kamele Platz gemacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Da kam der Mann ins Haus, und Laban zäumte die Kamele ab und gab ihnen Stroh und Futter, ihm aber und seinen Leuten Wasser, um sich die Füsse zu waschen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'dann setzte er ihm zu essen vor. Er aber sprach: Ich esse nicht, bis ich meinen Auftrag ausgerichtet habe. Er erwiderte: So rede!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Da sprach er: Ich bin der Knecht Abrahams.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Der Herr hat meinen Gebieter reichlich gesegnet, sodass er reich geworden ist; er hat ihm Schafe und Rinder, Silber und Gold, Knechte und Mägde, Kamele und Esel gegeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Und Sara, das Weib meines Herrn, hat ihm noch in seinem Alter einen Sohn geboren; dem hat er all sein Gut übergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Nun hat mein Herr einen Eid von mir genommen und gesagt: Du sollst meinem Sohn kein Weib nehmen von den Töchtern der Kanaaniter, in deren Land ich wohne;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern zu meines Vaters Hause sollst du ziehen und zu meinem Geschlechte, für meinen Sohn ein Weib zu holen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ich aber sprach zu meinem Herrn: Wie? wenn sie nun nicht mit mir ziehen will?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sprach er zu mir: Der Herr, vor dessen Angesichte ich gewandelt bin, wird seinen Engel mit dir senden und deine Reise wohl gelingen lassen, dass du für meinen Sohn ein Weib bekommst aus meinem Geschlechte und aus meines Vaters Hause.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Dann sollst du deines Eides ledig sein: wenn du zu meinem Geschlechte kommst und man sie dir nicht gibt, so bist du deines Eides ledig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Als ich nun heute zum Quell kam, sprach ich: O Herr, du Gott meines Gebieters Abraham, wenn du wirklich meine Reise, auf der ich jetzt bin, wolltest gelingen lassen -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ich stelle mich jetzt hier an den Wasserquell: die Jungfrau nun, die herauskommt, um zu schöpfen, und zu der ich sage: \"Gib mir aus deinem Kruge ein wenig Wasser zu trinken\",');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und die dann zu mir spricht: \"Trinke du, und auch für deine Kamele will ich schöpfen\", die sei das Weib, das der Herr dem Sohne meines Gebieters bestimmt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Und ehe ich noch bei mir selber ausgeredet, siehe, da kommt auch schon Rebekka heraus, ihren Krug auf der Achsel, steigt zum Quell hinab und schöpft. Da sprach ich zu ihr: \"Gib mir zu trinken.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Und schnell nahm sie den Krug von der Achsel und sprach: \"Trinke, und auch deine Kamele will ich tränken.\" So trank ich, und sie tränkte auch die Kamele.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Und ich fragte sie: \"Wessen Tochter bist du?\" Sie antwortete: \"Die Tochter Bethuels, des Sohnes Nahors, den ihm Milka geboren hat.\" Da legte ich ihr den Ring an die Nase und die Spangen an die Arme,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'und ich verneigte mich, fiel vor dem Herrn nieder und pries den Herrn, den Gott meines Gebieters Abraham, der mich den rechten Weg geführt hatte, um die Tochter des Bruders meines Herrn für seinen Sohn zu bekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Und nun, wollt ihr meinem Herrn Huld und Treue beweisen, so sagt es mir; wo nicht, sagt es mir auch, dass ich mich zur Rechten oder zur Linken wende.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Bethuel: Das ist von dem Herrn gefügt! Wir können nichts dazu sagen, weder Gutes noch Schlimmes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Da hast du Rebekka! Nimm sie und ziehe hin, dass sie das Weib des Sohnes deines Gebieters werde, wie der Herr es bestimmt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Als Abrahams Knecht ihre Worte hörte, warf er sich vor dem Herrn zur Erde nieder;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'dann holte er silbernes und goldenes Geschmeide und Gewänder hervor und gab sie Rebekka, auch ihrem Bruder und ihrer Mutter gab er Kostbarkeiten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Darnach assen und tranken sie, er und die Männer, die bei ihm waren, und blieben daselbst übernacht. Am Morgen aber, als sie aufstanden, sprach er: Entlasst mich nun zu meinem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Aber ihr Bruder und ihre Mutter erwiderten: Lass doch das Mädchen noch eine Zeitlang bei uns bleiben, wenigstens zehn Tage; darnach magst du ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Da sprach er zu ihnen: Haltet mich nicht auf, da doch der Herr meine Reise hat gelingen lassen; entlasst mich, dass ich zu meinem Gebieter ziehe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Sie sprachen: Wir wollen das Mädchen rufen und sie selbst befragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'So riefen sie Rebekka und sprachen zu ihr: Willst du mit diesem Manne ziehen? Sie antwortete: Ja, ich will.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Also liessen sie ihre Schwester Rebekka samt ihrer Amme mit dem Knechte Abrahams und seinen Leuten ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekka und sprachen zu ihr: Du unsre Schwester, werde zu vieltausendmal Tausenden, und dein Geschlecht gewinne das Tor seiner Feinde!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Da machten sich Rebekka und ihre Mägde auf; sie setzten sich auf die Kamele und folgten dem Manne. Und der Knecht nahm Rebekka und zog von dannen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber war in die Steppe des Brunnens von Lahai-Roi gezogen, und er wohnte im Gebiet des Südlands. (a) 1Mo 16:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Einst ging nun Isaak um die Abendzeit aufs Feld hinaus, um nachzusinnen, und als er seine Augen erhob, sah er Kamele des Weges kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Und als Rebekka ihre Augen erhob und Isaak sah, liess sie sich vom Kamele herab');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und sprach zu dem Knechte: Wer ist der Mann dort, der uns auf dem Felde entgegenkommt? Der Knecht antwortete: Das ist mein Herr. Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Der Knecht aber erzählte Isaak alles, was er ausgerichtet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Da führte Isaak die Rebekka ins Zelt hinein, und er nahm sie sich zum Weibe und gewann sie lieb. So tröstete sich Isaak nach seiner Mutter Tod.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'ABRAHAM aber nahm nochmals ein Weib, die hiess Ketura.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Sie gebar ihm Simran und Joksan, Medan und Midian, Jisbak und Suah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jodsan aber zeugte Saba und Dedan; und die Söhne Dedans waren die Assuriter, Letusiter und Lehummiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Die Söhne Midians aber sind Epha, Epher, Hanoch, Abida und Eldaa; alle diese sind Nachkommen der Ketura.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Und Abraham gab all sein Gut dem Isaak.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Den Söhnen der Nebenfrauen aber, die Abraham hatte, gab er Geschenke und schickte sie noch zu seinen Lebzeiten von seinem Sohne Isaak hinweg gegen Osten hin, ins Ostland.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Dies ist die Zeit der Lebensjahre Abrahams, die er gelebt hat: 175 Jahre;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'dann verschied er. So starb Abraham in schönem Alter, alt und lebenssatt, und ward versammelt zu seinen Stammesgenossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und seine Söhne Isaak und Ismael begruben ihn in der Höhle Machpela auf dem Grundstück des Hethiters Ephron, des Sohnes Zohars, das gegenüber Mamre liegt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'auf dem Grundstück, das Abraham von den Hethitern gekauft hatte. Daselbst wurden Abraham und sein Weib Sara begraben. (a) 1Mo 23:17 18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Und nach dem Tode Abrahams segnete Gott seinen Sohn Isaak. Isaak aber wohnte bei dem Brunnen von Lahai-Roi. (a) 1Mo 24:62');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist das Geschlechtsregister Ismaels, des Sohnes Abrahams, den die Ägypterin Hagar, die Magd Saras, dem Abraham geboren hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Dies sind die Namen der Söhne Ismaels, nach ihren Namen und Geschlechtern: Nebajoth, der Erstgeborne Ismaels, dann Kedar, Adbeel und Mibsam,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma und Massa,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad und Thema, Jetur, Naphis und Kedma.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dies also sind die Söhne Ismaels, und dies sind ihre Namen nach ihren Gehöften und Zeltlagern: zwölf Fürsten nach ihren Stämmen. (a) 1Mo 17:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies ist die Lebenszeit Ismaels: 137 Jahre; dann verschied er und starb und ward versammelt zu seinen Stammesgenossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Sie wohnten von Hawila an bis nach Sur, das östlich von Ägypten liegt, gegen Assur hin. All seinen Brüdern setzte er sich vors Gesicht. (a) 1Mo 16:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'DIES ist die Geschichte Isaaks, des Sohnes Abrahams: Abraham zeugte den Isaak.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Und Isaak war vierzig Jahre alt, als er sich die Tochter des Syrers Bethuel aus Mesopotamien, die Schwester des Syrers Laban, zum Weibe nahm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak aber bat den Herrn für sein Weib, denn sie war unfruchtbar; und der Herr liess sich von ihm erbitten, und sein Weib Rebekka wurde schwanger.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Da sich aber die Kinder in ihrem Leibe stiessen, sprach sie: Wenn es so ist, warum lebe ich dann? Und sie ging hin, den Herrn zu befragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Und der Herr sprach zu ihr: Zwei Völker sind in deinem Leibe, / und zwei Stämme werden sich aus deinem Schosse scheiden; / ein Stamm wird dem andern überlegen sein, / und der ältere wird dem jüngern dienen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Als nun die Zeit kam, dass sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der erste, der herauskam, war rötlich, ganz und gar wie ein behaarter Mantel, und man nannte ihn Esau.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Darnach kam sein Bruder heraus, der hielt mit seiner Hand die Ferse Esaus, und man nannte ihn Jakob. Isaak aber war sechzig Jahre alt, da sie geboren wurden. (1) d.i. Fersenhalter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Und als die Knaben heranwuchsen, ward Esau ein tüchtiger Jäger, ein Mann des freien Feldes; Jakob aber war ein gesitteter Mann, der in Zelten wohnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaak hatte den Esau lieber, weil er gern Wildbret ass; Jakob aber war der Liebling Rebekkas.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Nun kochte Jakob einst ein Gericht. Da kam Esau müde vom Felde heim,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'und Esau sprach zu Jakob: Lass mich doch schnell von dem roten Ding essen, dem roten da; denn ich bin müde. Daher heisst er Edom. (1) d.i. Rot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Aber Jakob sprach: Verkaufe mir zuvor deine Erstgeburt!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau antwortete: Sieh, ich muss ja doch sterben; was soll mir da die Erstgeburt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob sprach: So schwöre mir zuvor! Und er schwur ihm und verkaufte also dem Jakob seine Erstgeburt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Da gab Jakob dem Esau Brot und das Linsengericht; der ass und trank, stand auf und ging davon. So achtete Esau die Erstgeburt gering.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'ES kam aber eine Hungersnot über das Land, ausser der früheren, die zu Abrahams Zeiten gewesen war. Darum zog Isaak nach Gerar zu Abimelech, dem König der Philister. (a) 1Mo 12:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da erschien ihm der Herr und sprach: Ziehe nicht hinab nach Ägypten; bleibe in dem Lande, das ich dir nennen werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Weile als Fremdling in diesem Lande, ich will mit dir sein und will dich segnen; denn dir und deinem Geschlechte will ich all diese Länder geben und so den Eid erfüllen, den ich deinem Vater Abraham geschworen habe:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'ich will dein Geschlecht so zahlreich machen wie die Sterne des Himmels und will deinem Geschlecht all diese Länder geben, und mit dem Namen deines Geschlechtes werden sich Segen wünschen alle Völker der Erde, (1) vgl. Anm. zu 1Mo 12:2 3. (a) 1Mo 12:7; 15:5; 22:17 18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'weil Abraham auf mein Wort gehört und alles gehalten hat, was er mir zu halten hatte: meine Gebote, Satzungen und Gesetze.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Also blieb Isaak in Gerar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Als nun die Leute des Ortes nach seinem Weibe fragten, sprach er: \"Sie ist meine Schwester.\" Denn er fürchtete sich zu sagen: \"Sie ist mein Weib\"(, weil er dachte): die Leute des Ortes könnten mich um Rebekkas willen töten, da sie so schön ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er aber schon längere Zeit dort wohnte, begab es sich, dass einst Abimelech, der König der Philister, zum Fenster hinausschaute; da sah er Isaak mit seinem Weibe Rebekka kosen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Nun liess Abimelech den Isaak rufen und sprach: Sie ist ja dein Weib! Wie konntest du denn sagen, sie sei deine Schwester? Isaak antwortete ihm: Ich dachte eben, ich müsste um ihretwillen vielleicht sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech aber sprach: Was hast du uns da angetan! Wie leicht hätte einer aus dem Volke deinem Weibe Gewalt antun können, und du hättest eine Schuld über uns gebracht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Darnach gebot Abimelech dem ganzen Volke: Wer diesen Mann oder sein Weib anrührt, ist des Todes!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Und Isaak säte in dem Lande, und er erntete in jenem Jahre hundertfältig; denn der Herr segnete ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'So wurde der Mann reich und immer reicher, bis er über die Massen reich war;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'er hatte Herden von Schafen und Herden von Rindern und ein grosses Gesinde. Darum beneideten ihn die Philister.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Alle Brunnen aber, welche die Knechte seines Vaters gegraben hatten in den Tagen seines Vaters Abraham, die hatten die Philister zugeschüttet und mit Erde gefüllt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Und Abimelech sprach zu Isaak: Ziehe von uns hinweg, denn du bist uns viel zu mächtig geworden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dannen. Und er lagerte sich im Tale von Gerar und blieb daselbst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Und Isaak liess die Wasserbrunnen, welche die Knechte seines Vaters Abraham gegraben und welche die Philister nach dem Tode Abrahams zugeschüttet hatten, wieder aufgraben und benannte sie mit denselben Namen, mit denen sein Vater sie benannt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Als nun Isaaks Knechte im Tale gruben, fanden sie daselbst einen Brunnen mit Quellwasser.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Aber die Hirten von Gerar zankten mit den Hirten Isaaks und sprachen: Uns gehört das Wasser! Da nannte er den Brunnen Esek, weil sie sich dort mit ihm gezankt hatten. (1) d.i. Zank.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Hernach gruben sie einen andern Brunnen, um den stritten sie auch; darum nannte er ihn Sitna. (1) d.i. Streit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Da brach er von dannen auf und grub abermals einen Brunnen, um den zankten sie nicht; darum nannte er ihn Rehobot und sprach: Nun hat uns der Herr weiten Raum geschafft, dass wir im Lande wachsen können. (1) d.i. weiter Raum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Von dort zog er hinauf nach Beerseba.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und der Herr erschien ihm in jener Nacht und sprach: Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht, denn ich bin mit dir; ich will dich segnen und dein Geschlecht mehren um meines Knechtes Abraham willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Da baute er an der Stelle einen Altar und rief den Namen des Herrn an. Und Isaak schlug dort sein Zelt auf, und seine Knechte gruben daselbst einen Brunnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Nun kam einst Abimelech zu ihm von Gerar mit seinem Freunde Ahussat und seinem Feldhauptmann Pichol.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Da sprach Isaak zu ihnen: Warum kommt ihr zu mir, da ihr mich doch hasset und mich von euch weggeschickt habt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie sprachen: Wir sehen nun in der Tat, dass der Herr mit dir ist; darum dachten wir: es soll ein Vertrag zwischen uns beschworen werden, zwischen uns und dir, und wir wollen einen Bund mit dir schliessen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'dass du uns nichts zuleide tuest, wie auch wir dich nicht angerührt und dir nur Gutes getan und dich in Frieden haben ziehen lassen. Du bist nun einmal der Gesegnete des Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da bereitete er ihnen ein Mahl, und sie assen und tranken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Und am andern Morgen in der Frühe schwuren sie einander den Eid. Dann entliess sie Isaak, und sie schieden von ihm in Frieden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'An demselben Tage kamen Isaaks Knechte und sagten ihm von dem Brunnen, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser gefunden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Da nannte er ihn Sebua. Daher heisst der Ort \"Beer-Seba\" bis auf den heutigen Tag. (1) d.i. Eid. (2) d.i. Eidbrunnen. (a) 1Mo 21:31');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Als Esau vierzig Jahre alt war, nahm er zum Weibe Judith, die Tochter des Hethiters Beeri, ferner Basmath, die Tochter des Hethiters Elon;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'die waren für Isaak und Rebekka ein schwerer Kummer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'UND es begab sich, als Isaak alt geworden war und seine Augen trübe wurden, sodass er nicht mehr sehen konnte, da rief er Esau, seinen ältern Sohn, und sprach zu ihm: Mein Sohn! Er antwortete ihm: Hier bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Da sprach er: Sieh, ich bin alt geworden und weiss nicht, wann ich sterben muss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'So nimm nun dein Jagdgerät, Köcher und Bogen, geh aufs Feld und jage mir ein Wildbret;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'dann bereite mir ein gutes Gericht, wie ich es gerne habe, und bring es mir herein zum Essen, auf dass dich meine Seele segne, ehe ich sterbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka aber hörte zu, wie Isaak mit seinem Sohne Esau redete. Als nun Esau aufs Feld ging, für seinen Vater ein Wildbret zu jagen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'sprach Rebekka zu ihrem Sohne Jakob: Sieh, ich habe gehört, wie dein Vater zu deinem Bruder Esau sagte:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\"Bringe mir ein Wildbret und bereite mir ein gutes Gericht, dass ich esse; dann will ich dich segnen vor dem Angesicht des Herrn, ehe ich sterbe.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'So höre nun, mein Sohn, auf mich und tue, was ich dich heisse:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gehe zu der Herde und hole mir von dort zwei schöne Ziegenböcklein; dann will ich deinem Vater ein gutes Gericht bereiten, wie er es gerne hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Das sollst du deinem Vater hineintragen, dass er esse und dich vor seinem Tode segne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob aber sprach zu seiner Mutter Rebekka: Sieh, mein Bruder Esau ist behaart, und ich bin glatt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht könnte mein Vater mich betasten; dann stünde ich vor ihm als einer, der seinen Spott mit ihm treibt, und ich brächte über mich einen Fluch und nicht einen Segen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sprach seine Mutter zu ihm: Der Fluch komme über mich, mein Sohn! Höre du nur auf mich, geh und hole mir\'s.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er hin, holte die Böcklein und brachte sie seiner Mutter. Und seine Mutter bereitete ein gutes Gericht, wie es sein Vater gerne hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Dann nahm Rebekka die Feierkleider Esaus, ihres ältern Sohnes, die sie bei sich im Hause hatte, und legte sie Jakob, ihrem jüngern Sohne, an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Die Felle von den Ziegenböcklein aber tat sie ihm um die Arme und um seinen glatten Hals.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Dann gab sie das gute Gericht, das sie bereitet hatte, und das Brot ihrem Sohne Jakob in die Hand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'So ging er zu seinem Vater hinein und sprach: Vater! Er antwortete: Hier bin ich; wer bist du, mein Sohn?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborner; ich habe getan, wie du mir befohlen hast. Setze dich auf und iss von meinem Wildbret, auf dass mich deine Seele segne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Isaak aber sprach zu seinem Sohne: Mein Sohn, wie hast du es so bald gefunden? Er antwortete: Der Herr, dein Gott, hat es mir begegnen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: Tritt herzu, mein Sohn, dass ich dich betaste, ob du wirklich mein Sohn Esau seiest oder nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Nun trat Jakob zu seinem Vater Isaak, und als er ihn betastet hatte, sprach er: Die Stimme ist Jakobs Stimme, aber die Arme sind Esaus Arme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er erkannte ihn nicht; denn seine Arme waren behaart, wie die Arme seines Bruders Esau. So segnete er ihn denn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Und er sprach zu ihm: Bist du wirklich mein Sohn Esau? Er antwortete: Ja, das bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: So trage mir auf, dass ich esse von dem Wildbret meines Sohnes, auf dass dich meine Seele segne. Da trug er ihm auf, und er ass; und er brachte ihm auch Wein, und er trank.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Dann sprach sein Vater Isaak zu ihm: Komm her, mein Sohn, und küsse mich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Und er trat herzu und küsste ihn. Da roch er den Geruch seiner Kleider, und er segnete ihn und sprach: Siehe, der Geruch meines Sohnes / ist wie der Geruch des Feldes, / das der Herr gesegnet hat. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Gott gebe dir vom Tau des Himmels / und vom Fett der Erde / und Korn und Wein die Fülle! /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Völker sollen dir dienen / und Nationen sich vor dir beugen! / Sei ein Herr über deine Brüder, / und deiner Mutter Söhne sollen sich vor dir beugen! / Verflucht ist, wer dir flucht, / und gesegnet, wer dich segnet! (a) 1Mo 25:23; 12:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Als nun Isaak den Segen über Jakob eben vollendet hatte und Jakob kaum von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von der Jagd heim;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'der bereitete auch ein gutes Gericht und trug es seinem Vater hinein. Und er sprach zu seinem Vater: Richte dich auf, Vater, und iss von dem Wildbret deines Sohnes, auf dass mich deine Seele segne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Sein Vater Isaak aber sprach zu ihm: Wer bist du? Er antwortete: Ich bin dein Sohn, dein Erstgeborner, Esau.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da entsetzte sich Isaak über alle Massen und sprach: Wer war denn der, der ein Wild gejagt und es mir hereingebracht hat? Nun habe ich eben schon gegessen, ehe du kamst, und habe ihn gesegnet; er wird auch gesegnet bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Als Esau die Worte seines Vaters hörte, schrie er gar laut und kläglich auf und sprach zu seinem Vater: Segne mich auch, Vater!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Er aber sprach: Dein Bruder ist gekommen mit Hinterlist und hat dir den Segen vorweggenommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: Mit Recht heisst er Jakob; denn er hat mich nun zweimal hintergangen. Die Erstgeburt hat er mir genommen, und nun nimmt er mir auch den Segen. Und er sprach: Hast du mir keinen Segen vorbehalten? (1) d.i. der Hinterlistige. (a) 1Mo 25:33');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaak antwortete und sprach zu Esau: Sieh, ich habe ihn zum Herrn über dich gesetzt und alle seine Brüder ihm zu Knechten gegeben; mit Korn und Wein habe ich ihn versehen. Was kann ich da für dich noch tun, mein Sohn?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esau sprach zu seinem Vater: Hast du denn nur den einen Segen, Vater? Segne mich auch, Vater! Und Esau hob laut zu weinen an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete sein Vater Isaak und sprach zu ihm: Sieh, fern vom Fett der Erde soll deine Wohnung sein / und fern vom Tau des Himmels droben. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Von deinem Schwerte musst du leben, / und deinem Bruder sollst du dienen. / Doch wird\'s geschehen: wenn du dich mühst, / wirst du sein Joch von deinem Halse reissen. (a) 2Kön 8:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Esau aber ward dem Jakob feind um des Segens willen, mit dem ihn sein Vater gesegnet hatte. Und Esau sprach bei sich selbst: Bald kommt die Zeit der Trauer um meinen Vater; dann will ich meinen Bruder Jakob töten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Als nun der Rebekka die Worte ihres ältern Sohnes Esau hinterbracht wurden, schickte sie hin und liess ihren jüngern Sohn Jakob rufen und sprach zu ihm: Sieh, dein Bruder Esau will an dir Rache nehmen und dich töten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'So höre nun auf mich, mein Sohn: mache dich auf und fliehe zu meinem Bruder Laban nach Haran, (a) 1Mo 24:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleibe eine Zeitlang bei ihm, bis deines Bruders Grimm sich legt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'bis sich der Zorn deines Bruders von dir wendet und er vergisst, was du ihm angetan hast; dann will ich nach dir schicken und dich von dort holen lassen. Warum sollte ich euch beide an einem Tag verlieren?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'UND Rebekka sprach zu Isaak: Mir ist das Leben verleidet ob der Hethiterinnen; wenn Jakob auch ein solches Weib nimmt, eine von den Töchtern der Hethiter, eine Einheimische, was soll mir da das Leben? (a) 1Mo 26:34 35');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da rief Isaak den Jakob und segnete ihn; und er gebot ihm und sprach: Du sollst dir kein Weib nehmen von den Töchtern Kanaans. (a) 1Mo 24:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf und ziehe nach Mesopotamien, zum Hause Bethuels, des Vaters deiner Mutter, und hole dir dort ein Weib von den Töchtern Labans, des Bruders deiner Mutter. (a) 1Mo 24:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Und der allmächtige Gott segne dich und mache dich fruchtbar und mehre dich, dass du zu einer Gemeinde von Völkern werdest;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'und er gebe dir den Segen Abrahams, dir samt deinem Geschlechte, dass das Land, in dem du als Fremdling weilst, das Gott dem Abraham gegeben hat, dein eigen werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'So entliess Isaak den Jakob, und er zog nach Mesopotamien zu Laban, dem Sohne Bethuels, des Syrers, dem Bruder der Rebekka, der Mutter Jakobs und Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Als nun Esau sah, dass Isaak den Jakob gesegnet und ihn nach Mesopotamien gesandt hatte, damit er sich dort ein Weib hole - indem er ihn segnete und ihm gebot: \"Du sollst dir kein Weib nehmen von den Töchtern Kanaans\" -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und dass Jakob seinem Vater und seiner Mutter gehorsam war und nach Mesopotamien zog,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'da merkte Esau, dass sein Vater Isaak die Töchter Kanaans nicht gerne sah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Daher ging Esau hin zu Ismael und nahm zu den Frauen, die er schon hatte, Mahalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zum Weibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'JAKOB aber zog aus von Beerseba und machte sich auf den Weg nach Haran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Da traf es sich, dass er an die (heilige) Stätte (von Bethel) kam, und er blieb daselbst übernacht; denn die Sonne war untergegangen. Und er nahm einen von den Steinen der Stätte, tat ihn unter sein Haupt und legte sich an dieser Stätte schlafen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Da träumte ihm, eine Leiter sei auf die Erde gestellt, die mit der Spitze an den Himmel rührte, und die Engel Gottes stiegen daran auf und nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und siehe, der Herr stand vor ihm und sprach: Ich bin der Herr, der Gott deines Vaters Abraham und der Gott Isaaks; das Land, auf dem du ruhst, will ich dir und deinen Nachkommen geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und deine Nachkommen sollen (zahlreich) werden wie der Staub der Erde; gegen Abend und Morgen, gegen Mitternacht und Mittag sollst du dich ausbreiten, und mit deinem und deines Geschlechtes Namen werden sich Segen wünschen alle Geschlechter der Erde. (1) vgl. Anm. zu 1Mo 12:2 3.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Siehe, ich bin mit dir und will dich behüten allenthalben, wo du hinziehst, und dich in dieses Land zurückbringen. Denn ich will dich nicht verlassen, bis dass ich getan, was ich dir verheissen habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Als Jakob von seinem Schlaf erwachte, sprach er: Fürwahr, der Herr ist an dieser Stätte, und ich wusste es nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und er fürchtete sich und sprach: Wie furchtbar ist diese Stätte! Hier ist nichts anderes als Gottes Haus, hier ist die Pforte des Himmels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Am andern Morgen aber in der Frühe nahm Jakob den Stein, den er unter sein Haupt gelegt hatte, richtete ihn auf als Malstein und goss Öl oben darauf;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'und er nannte die Stätte Bethel. Früher aber hiess die Stadt Lus. (1) d.i. Gotteshaus. (a) 1Mo 35:6 7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob tat ein Gelübde und sprach: Wenn Gott mit mir ist und mich behütet auf dem Wege, den ich jetzt ziehe, wenn er mir Brot zu essen gibt und Kleider anzuziehen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und ich wohlbehalten wieder zu meines Vaters Haus zurückkomme, so soll der Herr mein Gott sein,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich als Malstein aufgerichtet habe, soll ein Gotteshaus werden, und alles, was du mir geben wirst, will ich dir getreulich verzehnten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'DANN machte sich Jakob auf den Weg und wanderte nach dem Land im Osten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Und als er um sich schaute, sah er auf dem Felde einen Brunnen; an dem lagerten gerade drei Herden Schafe; denn aus dem Brunnen pflegte man die Herden zu tränken. Der Stein über der Öffnung des Brunnens aber war gross.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und wenn alle Herden dort beisammen waren, wälzte man den Stein von der Öffnung des Brunnens und tränkte die Schafe; dann brachte man den Stein wieder über die Öffnung des Brunnens an seine Stelle.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jakob sprach zu den Leuten: Meine Brüder, wo seid ihr her? Sie antworteten: Wir sind von Haran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Er sprach zu ihnen: Kennt ihr Laban, den Sohn Nahors? Sie antworteten: Gewiss, wir kennen ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Er sprach zu ihnen: Steht es wohl um ihn? Sie antworteten: Ja, es steht wohl um ihn; doch sieh, da kommt eben seine Tochter Rahel mit den Schafen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Er sprach: Es ist ja noch hoch am Tage und noch nicht Zeit, das Vieh einzutreiben; tränkt die Schafe und dann lasst sie wieder weiden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie antworteten: Das können wir nicht, bis alle Herden beisammen sind; dann wälzt man den Stein von der Öffnung des Brunnens, und wir tränken die Schafe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Während er noch mit ihnen redete, war Rahel mit den Schafen ihres Vaters herangekommen; denn sie pflegte sie zu hüten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Als Jakob aber Rahel, die Tochter seines Oheims Laban, und die Schafe seines Oheims Laban sah, trat er herzu, wälzte den Stein von der Öffnung des Brunnens und tränkte die Schafe seines Oheims Laban.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Und Jakob küsste Rahel und begann laut zu weinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Dann sagte Jakob der Rahel, dass er der Verwandte ihres Vaters, der Sohn Rebekkas, sei. Da lief sie hin und sagte es ihrem Vater.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Als nun Laban die Kunde von Jakob, dem Sohne seiner Schwester, hörte, lief er ihm entgegen, umarmte und küsste ihn und führte ihn in sein Haus. Und er erzählte dem Laban seine ganze Geschichte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Da sprach Laban zu ihm: Ja, du bist von meinem Fleisch und Bein. Und er blieb einen Monat bei ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Darnach sprach Laban zu Jakob: Du bist ja doch mein Verwandter; solltest du mir umsonst dienen? Sag an: was soll dein Lohn sein?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Nun hatte Laban zwei Töchter; die ältere hiess Lea und die jüngere Rahel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea hatte matte Augen, Rahel aber war schön von Gestalt und schön von Angesicht;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'und Jakob hatte Rahel lieb. So sprach er: Ich will dir sieben Jahre um Rahel, deine jüngere Tochter, dienen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban antwortete: Es ist besser, ich gebe sie dir, als dass ich sie einem fremden Manne gebe; bleibe bei mir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Also diente Jakob um Rahel sieben Jahre, und sie kamen ihm vor wie ein paar Tage, so lieb hatte er sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Dann sprach Jakob zu Laban: Gib mir nun mein Weib - denn meine Zeit ist um -, dass ich ihr beiwohne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Leute des Ortes ein und veranstaltete ein Festmahl.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Am Abend aber nahm er seine Tochter Lea und führte sie zu ihm hinein, und er wohnte ihr bei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab seine Magd Silpa seiner Tochter Lea zur Magd.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Am Morgen aber, siehe, da war es Lea! Da sprach Jakob zu Laban: Was hast du mir angetan! Habe ich dir nicht um Rahel gedient? Warum hast du mich betrogen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban antwortete: Es ist hierzuland nicht Sitte, dass man die jüngere vor der ältern weggebe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vollende mit dieser die Festwoche, dann wollen wir dir auch die andre geben um den Dienst, den du bei mir noch weitere sieben Jahre tun sollst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob tat es und vollendete die Woche. Dann gab ihm jener seine Tochter Rahel zum Weibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab seine Magd Bilha seiner Tochter Rahel zur Magd.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Da wohnte Jakob auch der Rahel bei; Rahel aber hatte er lieber als Lea. Und er diente bei ihm noch weitere sieben Jahre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'ALS aber der Herr sah, dass Lea zurückgesetzt war, machte er sie fruchtbar, während Rahel unfruchtbar blieb.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'So ward Lea schwanger und gebar einen Sohn; den nannte sie Ruben. Denn sie sprach: Der Herr hat mein Elend angesehen; nun wird mich mein Mann liebhaben. (1) aus den Namen der Söhne Jakobs hörte man Anklänge an die Wörter heraus, deren Üs. jeweilen -+kursiv- gedruckt ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Und sie ward abermals schwanger und gebar einen Sohn; und sie sprach: Der Herr hat gehört, dass ich zurückgesetzt bin; darum hat er mir auch diesen gegeben. Und sie nannte ihn Simeon.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Dann ward sie abermals schwanger und gebar einen Sohn; und sie sprach: Nun endlich wird mein Mann mir anhänglich sein; denn ich habe ihm drei Söhne geboren. Darum nannte sie ihn Levi.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Und noch einmal ward sie schwanger und gebar einen Sohn; und sie sprach: Nunmehr will ich den Herrn preisen! Darum nannte sie ihn Juda. Darnach hörte sie auf zu gebären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Als Rahel sah, dass sie dem Jakob keine Kinder gebar, da ward sie eifersüchtig auf ihre Schwester und sprach zu Jakob: Schaffe mir Kinder; wo nicht, so sterbe ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakob aber wurde zornig über Rahel und sprach: Bin ich denn an Gottes Statt, der dir Leibesfrucht versagt? (a) Ps 127:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Darauf sprach sie: Da hast du meine Magd Bilha; wohne ihr bei; damit sie auf meinem Schoss gebäre und durch sie auch ich zu Kindern komme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Also gab sie ihm ihre Magd Bilha zum Weibe, und Jakob wohnte ihr bei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Und Bilha ward schwanger und gebar dem Jakob einen Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sprach Rahel: Gott hat mir Recht geschafft, er hat mich auch erhört und mir einen Sohn gegeben. Darum nannte sie ihn Dan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Und Bilha, Rahels Magd, ward abermals schwanger und gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rahel: Einen Gotteskampf habe ich mit meiner Schwester gekämpft, habe auch obgesiegt. Darum nannte sie ihn Naphthali.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Als nun Lea sah, dass sie aufgehört hatte zu gebären, nahm sie ihre Magd Silpa und gab sie Jakob zum Weibe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Und Silpa, Leas Magd, gebar dem Jakob einen Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: \"Glück auf!\" und nannte ihn Gad.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Darnach gebar Silpa, Leas Magd, dem Jakob einen zweiten Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: \"Ich Glückliche! Die Töchter des Volkes werden mich glücklich preisen!\" und sie nannte ihn Asser.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Nun ging einst Ruben aufs Feld, zur Zeit der Weizenernte; dort fand er Liebesäpfel und brachte sie seiner Mutter Lea heim. Da sprach Rahel zu Lea: Gib mir von den Liebesäpfeln deines Sohnes!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sie aber antwortete ihr: Ist\'s nicht genug, dass du mir meinen Mann genommen hast? Nun willst du auch noch die Liebesäpfel meines Sohnes haben! Da sprach Rahel: Nun, so mag er heute nacht bei dir schlafen für die Liebesäpfel deines Sohnes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Als nun Jakob am Abend vom Felde kam, ging Lea ihm entgegen und sprach: Zu mir musst du kommen, denn ich habe dich erkauft um die Liebesäpfel meines Sohnes. Also schlief er jene Nacht bei ihr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott erhörte Lea, und sie ward schwanger und gebar dem Jakob einen fünften Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sprach Lea: \"Gott hat mir\'s gelohnt, dass ich meinem Manne meine Magd gegeben habe\", und sie nannte ihn Issaschar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Dann ward Lea abermals schwanger und gebar dem Jakob einen sechsten Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Da sprach Lea: Gott hat mir eine reiche Gabe gegeben; nun endlich wird mein Mann bei mir Wohnung nehmen, denn ich habe ihm sechs Söhne geboren. Und sie nannte ihn Sebulon.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Darnach gebar sie eine Tochter und nannte sie Dina.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Gott aber gedachte der Rahel: er erhörte ihr Gebet und machte sie fruchtbar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Da ward sie schwanger und gebar einen Sohn; und sie sprach: Gott hat meine Schmach von mir genommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und sie nannte ihn Joseph und sprach: Der Herr wolle mir noch einen Sohn dazu geben!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'ALS nun Rahel den Joseph geboren hatte, sprach Jakob zu Laban: Entlasse mich, ich möchte an meinen Ort und in mein Land ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Frauen, um die ich dir gedient habe, und meine Kinder, dass ich hinziehen kann; du weisst ja selber, wie ich dir gedient habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban sprach zu ihm: Wenn du mir doch einen Gefallen tun wolltest! Ich habe erkundet, dass mich Gott um deinetwillen gesegnet hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Dann sprach er: Bestimme den Lohn, den du von mir haben willst; ich will ihn dir geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Er erwiderte ihm: Du weisst ja selber, wie ich dir gedient habe und was aus deinen Herden unter mir geworden ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Nur wenig hattest du, ehe ich herkam; nun aber ist es gewaltig gewachsen, und der Herr hat dich gesegnet, seit ich hier bin. Und nun, wann soll auch ich für mein Haus sorgen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Er aber sprach: Was soll ich dir geben? Jakob antwortete: Du sollst mir gar nichts geben. Wenn du mir tun willst, was ich nun sage, so will ich wieder deine Schafe weiden und hüten:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'ich will heute durch deine ganze Herde gehen; daraus magst du alle schwarzen Tiere unter den Lämmern, und was unter den Ziegen gefleckt und gesprenkelt ist, absondern - die sollen mein Lohn sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Und darin wird meine Rechtschaffenheit an einem künftigen Tage für mich zeugen: wenn du kommst, meinen Lohn zu besehen, so soll alles, was unter den Ziegen nicht gesprenkelt oder gefleckt und unter den Lämmern nicht schwarz ist, als von mir gestohlen gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da sprach Laban: Gut, es sei, wie du gesagt hast.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und er sonderte am selben Tage die gestreiften und gefleckten Böcke und alle gesprenkelten und gefleckten Ziegen aus, alles, woran etwas Weisses war, und alles, was schwarz war unter den Lämmern, und übergab sie seinen Söhnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und er machte einen Zwischenraum von drei Tagereisen zwischen sich und Jakob; Jakob aber weidete die übrige Herde Labans.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Nun nahm Jakob frische Ruten von Weisspappeln, Mandelbäumen und Platanen und schälte daran weisse streifen aus, sodass das Weisse an den Ruten blossgelegt wurde;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'dann stellte er die Ruten, die er geschält hatte, in die Tröge, in die Tränkrinnen, wohin die Herden zum Trinken kamen, vor die Tiere hin, und die Tiere begatteten sich, wenn sie zur Tränke kamen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'So begatteten sich die Tiere vor den Ruten und warfen dann Gestreifte, Gesprenkelte und Gefleckte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Die Lämmer aber schied Jakob aus. Und er kehrte das Gesicht der Tiere gegen die gestreiften und schwarzen in der Herde Labans. So machte er sich eigne Herden; die tat er nicht zu den Tieren Labans.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Sooft die starken Tiere brünstig waren, stellte Jakob die Ruten in die Tränkrinnen vor die Augen der Tiere, sodass sie sich vor den Ruten begatteten;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'wenn aber die Tiere schwächlich waren, stellte er sie nicht hin. So fielen Laban die schwächlichen Tiere zu, Jakob aber die starken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Daher ward der Mann über die Massen reich, sodass er viel Vieh, Mägde und Knechte, Kamele und Esel hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'DA vernahm er, dass die Söhne Labans sagten: Jakob hat unsres Vaters ganzes Gut an sich gebracht, und von unsres Vaters Gut hat er all diesen Reichtum erworben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob sah an Labans Miene, dass er gegen ihn nicht mehr war wie ehedem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Der Herr aber sprach zu Jakob: Kehre zurück in das Land deiner Väter und zu deiner Verwandtschaft; ich will mit dir sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob hin und liess Rahel und Lea aufs Feld zu seiner Herde rufen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'und sprach zu ihnen: Ich sehe an der Miene eures Vaters, dass er gegen mich nicht mehr ist wie ehedem; aber der Gott meines Vaters ist mit mir gewesen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ihr selber wisst doch, dass ich eurem Vater aus allen meinen Kräften gedient habe,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'euer Vater aber hat mich betrogen und mir den Lohn zehnmal verändert; aber Gott hat ihm nicht gestattet, dass er mir Schaden tue.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Wenn er sprach: \"Die Gesprenkelten sollen dein Lohn sein\", so warf die ganze Herde Gesprenkelte. Und wenn er sprach: \"Die Gestreiften sollen dein Lohn sein\", so warf die ganze Herde Gestreifte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'So hat Gott eurem Vater die Habe genommen und sie mir gegeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Denn als die Brunstzeit der Schafe kam, erhob ich meine Augen und sah im Traume, wie die Böcke, welche die Schafe besprangen, gestreift, gesprenkelt und scheckig waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach zu mir im Traume: Jakob! Ich antwortete: Hier bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Er aber sprach: Erhebe deine Augen und sieh, wie alle Böcke, welche die Schafe bespringen, gestreift, gesprenkelt und scheckig sind. Denn ich habe alles gesehen, was dir Laban antut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott, der dir zu Bethel erschienen ist, wo du einen Malstein gesalbt und wo du mir ein Gelübde getan hast. Nun mache dich auf, ziehe hinweg aus diesem Lande und kehre in dein Heimatland zurück. (a) 1Mo 28:18 19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da antworteten Rahel und Lea und sprachen zu ihm: Haben wir noch Teil und Erbe in unsers Vaters Hause?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Gelten wir ihm nicht als Fremde? Er hat uns ja verkauft und längst das Geld dafür verbraucht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'So gehört denn all der Reichtum, den Gott unserm Vater weggenommen hat, uns und unsern Kindern. Und nun tue alles, was dir Gott gesagt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da machte sich Jakob auf, lud seine Kinder und Frauen auf die Kamele');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'und trieb all sein Vieh hinweg und seine ganze Habe, die er erworben, seinen Besitz an Vieh, den er in Mesopotamien erworben hatte, um zu seinem Vater Isaak ins Land Kanaan zu ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban aber war hingegangen, seine Schafe zu scheren. Da stahl Rahel den Theraphim ihres Vaters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'So überlistete Jakob den Syrer Laban, indem er ihn nicht merken liess, dass er fliehen wollte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Und er floh mit allem, was sein war, machte sich auf, setzte über den (Euphrat-)Strom und nahm die Richtung nach dem Gebirge Gilead.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Am dritten Tage erhielt Laban die Kunde, dass Jakob entflohen sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da nahm er seine Verwandten mit und jagte ihm nach, sieben Tagereisen weit, und er erreichte ihn auf dem Gebirge Gilead.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Aber Gott kam des Nachts im Traume zu dem Syrer Laban und sprach zu ihm: Hüte dich, Jakob mit irgendeinem Wort zur Rede zu stellen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Als nun Laban den Jakob einholte - Jakob aber hatte sein Zelt auf dem Berge aufgeschlagen, und Laban hatte sein Zelt auf dem Gebirge Gilead aufgeschlagen, (1) der Name dieses Berges scheint ausgefallen zu sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'da sprach Laban zu Jakob: Was hast du getan, dass du mich hintergangen und meine Töchter weggeführt hast wie Kriegsgefangene?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich entflohen und hast mich getäuscht und mir nichts gesagt, dass ich dich mit Jubel und Gesängen, mit Handpauken und Harfen hätte geleiten können,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'und hast mich meine Enkel und Töchter nicht küssen lassen? Da hast du töricht gehandelt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Ich hätte wohl die Macht, dir Übles zu tun, aber der Gott deines Vaters hat heute nacht zu mir gesprochen: Hüte dich, Jakob mit irgendeinem Wort zur Rede zu stellen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Nun, du bist eben weggezogen, weil dich so sehnlich nach deines Vaters Haus verlangte; aber warum hast du meinen Gott gestohlen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jakob antwortete und sprach zu Laban: Ich fürchtete mich; denn ich dachte, du würdest mir deine Töchter entreissen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Der aber, bei dem du deinen Gott findest, der soll nicht am Leben bleiben! Vor unsern Verwandten untersuche, was ich bei mir habe, und nimm ihn an dich. Jakob wusste nämlich nicht, dass Rahel ihn gestohlen hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da ging Laban in das Zelt Jakobs und in das Zelt Leas und in das Zelt der beiden Mägde, aber er fand ihn nicht. Dann ging er aus dem Zelte Leas in das Zelt Rahels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rahel aber hatte den Theraphim genommen, ihn in den Kamelsattel gelegt und sich darauf gesetzt. Und Laban durchsuchte das ganze Zelt und fand ihn nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Da sprach sie zu ihrem Vater: Mein Herr, zürne nicht, dass ich mich nicht vor dir erheben kann; denn es geht mir, wie es den Frauen geht. Also durchsuchte er alles, doch den Theraphim fand er nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jakob aber ward zornig und zankte mit Laban. Und Jakob hob an und sprach zu ihm: Was habe ich verbrochen, was habe ich gefehlt, dass du mich so hitzig verfolgt hast?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hast nun alle meine Sachen durchsucht; was hast du von all den Sachen deines Hauses gefunden? Lege es hier vor meine und deine Verwandten, dass sie zwischen uns beiden Recht sprechen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Seit zwanzig Jahren bin ich jetzt bei dir; deine Schafe und Ziegen haben nicht fehlgeworfen, und die Widder deiner Herde habe ich nicht gegessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Was von wilden Tieren zerrissen war, durfte ich dir nicht bringen; ich selber musste es ersetzen, von meiner Hand fordertest du es, ob es am Tage geraubt war oder in der Nacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Am Tage verzehrte mich die Hitze und des Nachts der Frost, und der Schlaf floh meine Augen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Zwanzig Jahre habe ich dir jetzt in deinem Hause gedient, vierzehn Jahre um deine beiden Töchter und sechs Jahre um deine Herde, und du hast mir den Lohn zehnmal verändert.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wenn nicht der Gott meines Vaters, der Gott Abrahams und der Gefürchtete Isaaks, für mich gewesen wäre, du hättest mich jetzt mit leeren Händen ziehen lassen; mein Elend und die Arbeit meiner Hände hat Gott gesehen, und er hat heute nacht Recht gesprochen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban antwortete und sprach zu Jakob: Die Töchter sind meine Töchter, die Kinder sind meine Kinder, und das Vieh ist mein Vieh, und alles, was du da siehst, ist mein; aber was kann ich heute für diese meine Töchter tun oder für ihre Kinder, die sie geboren haben?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'So komm nun, wir wollen einen Vertrag schliessen, ich und du; wir wollen einen Steinhaufen machen, der soll Zeuge sein zwischen mir und dir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Da nahm Jakob einen Stein und richtete ihn auf als Malstein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Und Laban sprach zu seinen Verwandten: Leset Steine zusammen. Und sie lasen Steine auf und machten einen Haufen und hielten daselbst das Mahl auf dem Haufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn (in seiner Sprache) Jegar-Sahadutha, Jakob aber nannte ihn Gal-Ed.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Da sprach Laban: Der Haufe hier ist heute Zeuge zwischen mir und dir. Daher nannte er ihn Gal-Ed (1) d.i. Steinhaufe des Zeugnisses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und Mizpa; denn er sprach: Der Herr möge wachen zwischen mir und dir, wenn wir einander nicht mehr sehen. (1) d.i. Hochwacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Solltest du je meine Töchter schlecht behandeln oder andre Frauen zu meinen Töchtern hinzunehmen - ob auch kein Mensch bei uns ist, siehe wohl zu: Gott ist Zeuge zwischen mir und dir!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Dann sprach Laban zu Jakob: Siehe, der Steinhaufe hier, und siehe, der Malstein hier, den ich errichtet haben zwischen mir und dir -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'dieser Haufe ist Zeuge, und dieser Malstein ist Zeuge: ich darf nicht über diesen Haufen hinaus zu dir hinüber, und du darfst nicht über diesen Haufen und diesen Malstein hinaus zu mir herüber in böser Absicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors sei Richter zwischen uns! Und Jakob schwur bei dem Gefürchteten Isaaks, seines Vaters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Darnach schlachtete er ein Opfer auf dem Berge und lud seine Verwandten ein, das Mahl zu halten. Und als sie gegessen hatten, blieben sie auf dem Berge übernacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Am andern Morgen aber in der Frühe küsste Laban seine Enkel und seine Töchter und segnete sie; dann zog Laban hin und kehrte zurück an seinen Ort. (1) die Lutherbibel hat für Kap. 31,55; 32,1-32 die Zählung 32,1-33.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'AUCH Jakob zog seines Weges; da begegneten ihm auf einmal die Engel Gottes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Als Jakob sie sah, sprach er: Dies ist das Heerlager Gottes. Darum nannte er jene Stätte Mahanaim. (1) d.i. Lager. (a) Ps 34:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Darnach schickte Jakob Boten vor sich her zu seinem Bruder Esau in das Land Seir, ins Gefilde Edoms.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Und er befahl ihnen: So sollt ihr zu meinem Herrn Esau sprechen: Dein Knecht Jakob lässt dir sagen: Ich bin bei Laban in der Fremde gewesen und habe mich bis jetzt dort aufgehalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Ich habe Rinder, Esel und Schafe, Knechte und Mägde erworben, und nun sende ich meinem Herrn Botschaft, dass ich Gnade finde vor deinen Augen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Die Boten kehrten zu Jakob zurück und sprachen: Wir sind zu deinem Bruder Esau gekommen; er zieht dir schon entgegen mit vierhundert Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Da fürchtete sich Jakob sehr, und es ward ihm bange. Darum teilte er die Leute, die bei ihm waren, und die Schafe, Rinder und Kamele in zwei Lager;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'denn er dachte: Wenn Esau auf das eine Lager trifft und schlägt es, so kann doch das andre Lager entrinnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Und Jakob sprach: O Gott meines Vaters Abraham und Gott meines Vaters Isaak, Herr, der du mir gesagt hast: \"Kehre zurück in dein Land und zu deiner Verwandtschaft, ich will dir Gutes tun!\" - (a) 1Mo 28:15; 31:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'ich bin zu gering aller Barmherzigkeit und aller Treue, die du an deinem Knechte getan hast. Denn nur mit meinem Stabe bin ich über den Jordan da gegangen, und nun bin ich zu zwei Heeren geworden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Errette mich doch aus der Hand meines Bruders, aus der Hand Esaus; denn ich fürchte, er möchte kommen und mich schlagen, die Mutter samt den Kindern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du hast doch gesagt: \"Ich will dir Gutes tun und dein Geschlecht zahlreich machen wie den Sand am Meer, den man nicht zählen kann vor Menge.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Und er blieb jene Nacht daselbst. Dann nahm er von dem, was er erworben hatte, ein Geschenk für seinen Bruder Esau:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'zweihundert Ziegen und zwanzig Böcke, zweihundert Schafe und zwanzig Widder,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'dreissig säugende Kamele mit ihren Füllen, vierzig Kühe und zehn Stiere, zwanzig Eselinnen mit zehn Füllen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Und er übergab sie seinen Knechten, jede Herde besonders, und sprach zu seinen Knechten: Ziehet vor mir her und lasset Raum zwischen den einzelnen Herden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Und dem ersten gebot er: Wenn dir mein Bruder Esau begegnet und dich fragt: \"Wem gehörst du, und wo willst du hin? und wem gehören diese (Tiere, die du) vor dir (hertreibst)?\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'so sollst du sagen: \"Deinem Knecht Jakob; es ist ein Geschenk, das er meinem Herrn Esau sendet. Siehe, er kommt selber hinter uns her.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Gleicherweise gebot er auch dem zweiten und dem dritten und allen, die hinter den Herden hergingen: So, wie ich euch gesagt habe, sollt ihr zu Esau sprechen, wenn ihr ihn antrefft.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ihr sollt sagen: \"Siehe, dein Knecht Jakob kommt selber hinter uns her.\" Denn er dachte: Ich will ihn mit dem Geschenk, das vor mir her zieht, versöhnen; dann erst will ich sein Angesicht sehen, vielleicht nimmt er mich gnädig auf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'So zog das Geschenk vor ihm her; er aber blieb jene Nacht im Lager.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Noch in der Nacht stand er dann auf, nahm seine beiden Frauen und seine beiden Mägde und seine elf Söhne und ging über die Furt des Jabbok.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Er nahm sie und führte sie über den Fluss; auch all seine Habe brachte er hinüber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jakob aber blieb allein zurück. Da rang ein Mann mit ihm, bis die Morgenröte anbrach. (a) Hos 12:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Als der sah, dass er ihn nicht zu überwältigen vermochte, schlug er ihn auf das Hüftgelenk. Und Jakobs Hüftgelenk wurde verrenkt, als er mit ihm rang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und er sprach: lass mich los; die Morgenröte bricht an. Aber er antwortete: Ich lasse dich nicht, du segnest mich denn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Er sprach zu ihm: Wie heissest du? Er antwortete: Jakob.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Da sprach er: Du sollst nicht mehr Jakob heissen, sondern Israel. Denn du hast mit Gott und mit Menschen gestritten und hast obgesiegt. (1) d.i. Gottesstreiter. (a) 1Mo 35:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Und Jakob fragte ihn: Sag an, wie heissest du? Er aber sprach: Warum fragst du, wie ich heisse? Und er segnete ihn daselbst. (a) Ri 13:17 18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Und Jakob nannte die Stätte Pniel; denn (sagte er) ich habe Gott von Angesicht zu Angesicht geschaut und bin am Leben geblieben. (1) d.i. Angesicht Gottes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Und als er an Pniel vorüber war, ging die Sonne auf; er hinkte aber an der Hüfte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Daher essen die Israeliten bis auf den heutigen Tag den Muskelstrang nicht, der auf dem Hüftgelenk liegt, weil er Jakob auf das Hüftgelenk schlug, auf den Muskelstrang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'ALS nun Jakob seine Augen erhob, sah er Esau herankommen und vierhundert Mann mit ihm. Da verteilte er die Kinder auf Lea und Rahel und die beiden Mägde,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'und er stellte die Mägde mit ihren Kindern voran, dahinter Lea mit ihren Kindern, Rahel aber mit Joseph zuletzt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er selbst ging vor ihnen her und verneigte sich siebenmal zur Erde, bis er zu seinem Bruder kam.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Esau aber eilte ihm entgegen und umarmte ihn, fiel ihm um den Hals und küsste ihn, und sie weinten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Als er nun seine Augen erhob und die Frauen mit den Kindern sah, sprach er: Wer sind diese da bei dir? Er antwortete: Es sind die Kinder, die Gott deinem Knechte aus Gnaden beschert hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Und die Mägde traten herzu mit ihren Kindern und verneigten sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Dann trat auch Lea herzu mit ihren Kindern, und sie verneigten sich. Darnach traten Joseph und Rahel herzu und verneigten sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Und er sprach: Was willst du denn mit diesem ganzen Heer, dem ich begegnet bin? Er antwortete: Dass ich Gnade finde vor meinem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esau sprach: Ich habe genug, mein Bruder; behalte, was du hast.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob antwortete: Nicht doch! Habe ich Gnade vor dir gefunden, so nimm das Geschenk von mir an; denn ich habe ja dein Angesicht schauen dürfen, wie man Gottes Angesicht schaut, und du hast mich gütig aufgenommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch die Gabe an, die ich dir gebracht habe; denn Gott hat es mir in Gnaden beschert, und ich habe vollauf. So drang er in ihn, bis er es annahm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Und Esau sprach: Lass uns nun aufbrechen und fortziehen; ich will vor dir her ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Er aber sprach zu ihm: Mein Herr sieht, dass die Kinder noch zart sind und dass ich für die säugenden Schafe und Rinder zu sorgen habe; übertriebe man sie auch nur einen Tag, so würde mir die ganze Herde sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Herr ziehe doch seinem Knechte voraus. Ich will gemächlich nachtreiben, wie eben das Vieh vor mir und die Kinder wandern können, bis ich zu meinem Herrn nach Seir komme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Esau sprach: So will ich doch von den Leuten, die ich bei mir habe, etliche bei dir lassen. Er antwortete: Wozu das? Möge ich nur Gnade finden vor meinem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Da zog Esau an jenem Tage wieder seines Weges nach Seir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob aber zog nach Sukkoth und baute sich ein Haus; für sein Vieh aber machte er Hütten. Daher nannte er die Stätte Sukkoth. (1) d.i. Hütten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Darnach kam Jakob wohlbehalten zu der Stadt Sichem im Lande Kanaan, als er aus Mesopotamien kam, und lagerte vor der Stadt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Und er kaufte das Grundstück, auf dem er sein Zelt aufgeschlagen hatte, von den Söhnen Hemors, des Vaters Sichems, um hundert Taler.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Dort richtete er einen Malstein auf und baute einen Altar und nannte ihn \"El, Gott Israels\".');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'DINA aber, die Tochter Jakobs, die Lea ihm geboren hatte, ging einst aus, um sich die Mädchen des Landes anzusehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Als nun Sichem, der Sohn des Hewiters Hemor, des Landesfürsten, sie sah, ergriff er sie und wohnte ihr bei und tat ihr so Gewalt an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Aber sein Herz hing an Dina, der Tochter Jakobs, und er hatte das Mädchen lieb und redete ihr freundlich zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Sichem sprach zu seinem Vater Hemor: Wirb für mich um dieses Mädchen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob aber erfuhr, dass er seine Tochter Dina geschändet habe; doch weil seine Söhne mit dem Vieh auf dem Felde waren, schwieg Jakob stille, bis sie heimkamen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Da ging Hemor, Sichems Vater, hinaus zu Jakob, um mit ihm zu reden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Als nun die Söhne Jakobs vom Felde heimkamen, hörten sie davon; da wurden die Männer aufgebracht und sehr zornig, dass er eine Schandtat in Israel begangen hatte, indem er Jakobs Tochter beiwohnte; dergleichen durfte nicht geschehen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hemor aber redete mit ihnen und sprach: Mein Sohn Sichem hängt mit ganzer Seele an eurer Tochter; gebt sie ihm doch zum Weibe!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Verschwägert euch mit uns: ihr mögt uns eure Töchter geben und euch unsre Töchter nehmen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'und bleibt bei uns wohnen; das Land soll euch offenstehen: bleibt, tut euch darin um und werdet hier ansässig!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Sichem sprach zu ihrem Vater und zu ihren Brüdern: Tut mir doch den Gefallen! Was ihr von mir verlangt, das will ich geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Ihr mögt von mir einen noch so grossen Brautpreis fordern und Geschenke, ich will sie geben, wie ihr sie von mir fordert; nur gebt mir das Mädchen zum Weibe! (a) 2Mo 22:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da antworteten Jakobs Söhne dem Sichem und seinem Vater Hemor mit hinterlistiger Rede, weil er ihre Schwester geschändet hatte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'sie sprachen zu ihnen: Es ist uns unmöglich, unsre Schwester einem unbeschnittenen Manne zu geben; denn das gilt uns für eine Schande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nur unter der Bedingung wollen wir euch zu Willen sein, wenn ihr uns gleich werdet, indem ihr alles, was unter euch männlich ist, beschneiden lasst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Dann wollen wir euch unsre Töchter geben und uns eure Töchter nehmen, wir wollen bei euch wohnen und ein Volk (mit euch) werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wenn ihr euch aber nicht, wie wir verlangen, wollt beschneiden lassen, so nehmen wir unsre Tochter und ziehen von dannen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Diese Worte gefielen Hemor und seinem Sohne Sichem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Und der junge Mann zögerte nicht, darnach zu tun; denn er hatte Gefallen gefunden an der Tochter Jakobs, und er war der Angesehenste in seines Vaters Hause.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'So gingen denn Hemor und sein Sohn Sichem unter das Tor ihrer Stadt und sprachen zu den Bürgern ihrer Stadt:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Leute sind friedlich gesinnt, so lasst sie bei uns im Lande wohnen und darin sich umtun; das Land hat ja nach allen Seiten Raum genug für sie. Wir wollen uns ihre Töchter zu Frauen nehmen und ihnen unsre Töchter geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Allein, nur dann willigen die Leute ein, bei uns zu wohnen und ein Volk (mit uns) zu werden, wenn wir alles, was unter uns männlich ist, beschneiden lassen, gleich wie sie beschnitten sind.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Uns gehören ja dann ihre Herden, ihre Habe und all ihr Vieh. Ja, lasst uns ihnen zu Willen sein, dass sie bei uns wohnen bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Da willfahrten sie Hemor und seinem Sohne Sichem, alle die im Tore seiner Stadt aus und ein gingen, und liessen sich beschneiden, alles, was männlich war, alle, die im Tore seiner Stadt aus und ein gingen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Am dritten Tage aber, als es sie schmerzte, nahmen zwei der Söhne Jakobs, Simeon und Levi, Dinas Brüder, ein jeder sein Schwert, drangen ungefährdet in die Stadt ein und töteten alles, was männlich war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Auch Hemor und seinen Sohn Sichem töteten sie mit der Schärfe des Schwertes, nahmen Dina aus dem Hause Sichems und gingen davon.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die Söhne Jakobs fielen über die Kranken her und plünderten die Stadt, weil sie ihre Schwester geschändet hatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihre Schafe, Rinder und Esel, was in der Stadt und was auf dem Felde war, nahmen sie weg,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'all ihre Habe, all ihre Kinder und Frauen führten sie fort und plünderten alles, was in den Häusern war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sprach Jakob zu Simeon und Levi: Ihr bringt mich ins Unglück, indem ihr mich bei den Bewohnern des Landes, den Kanaanitern und Pheresitern, verhasst macht, wo ich doch nur wenig Leute habe. Wenn sie sich nun wider mich zusammentun, so werden sie mich schlagen, und ich werde samt meinem Hause vertilgt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Aber sie antworteten: Soll er unsere Schwester wie eine Dirne behandeln dürfen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'UND Gott sprach zu Jakob: Mache dich auf, ziehe hinauf nach Bethel und bleibe daselbst, und baue dort einen Altar dem Gott, der dir erschienen ist, als du vor deinem Bruder Esau flohst. (a) 1Mo 28:11-22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sprach Jakob zu seinem Hause und zu allen, die bei ihm waren: Schafft die fremden Götter weg, die unter euch sind, und reinigt euch und wechselt eure Kleider. (a) 1Mo 31:19; Jos 24:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Dann wollen wir uns aufmachen und hinauf nach Bethel ziehen; dort will ich einen Altar bauen dem Gott, der mich zur Zeit meiner Drangsal erhört hat und mit mir gewesen ist auf dem Wege, den ich gezogen bin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da gaben sie Jakob alle fremden Götter, die sie bei sich hatten, und ihre Ohrringe, und er vergrub sie unter der Terebinthe, die bei Sichem steht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Darnach brachen sie auf; der Schrecken Gottes aber kam über die Städte ringsumher, sodass sie die Söhne Jakobs nicht verfolgten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'So kam Jakob nach Lus im Lande Kanaan - das ist Bethel -, er und alle Leute, die bei ihm waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Und er baute dort einen Altar und nannte die Stätte El-Bethel, weil sich Gott ihm dort geoffenbart hatte, als er vor seinem Bruder floh. (1) d.i. der Gott von Bethel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Da starb Debora, die Amme der Rebekka, und ward begraben unterhalb Bethel unter der Eiche; dieser gab er den Namen \"Klageeiche\". (a) 1Mo 24:59');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien dem Jakob abermals, als er aus Mesopotamien kam, und segnete ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: Du heissest Jakob; aber du sollst nicht mehr Jakob heissen, sondern Israel soll dein Name sein. Und er nannte ihn Israel. (a) 1Mo 32:28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Dann sprach Gott zu ihm: Ich bin der allmächtige Gott, sei fruchtbar und mehre dich; ein Volk, ja eine Gemeinde von Völkern soll von dir kommen, und Könige sollen aus deinen Lenden hervorgehen. (a) 1Mo 17:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, das ich Abraham und Isaak gegeben habe, dir will ich es geben, und auch deinen Nachkommen will ich das Land geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Dann fuhr Gott auf von ihm, an der Stätte, wo er mit ihm geredet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jakob aber errichtete ein Mal an der Stätte, wo er mit ihm geredet hatte, ein steinernes Mal, und er spendete ein Trankopfer darauf und goss Öl darüber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob nannte die Stätte, wo Gott mit ihm geredet hatte, Bethel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Darnach brachen sie von Bethel auf, und als sie nur noch ein Stück Weges bis Ephrath hatten, gebar Rahel, und die Geburt kam sie schwer an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Und da sie eine so schwere Geburt hatte, sprach die Hebamme zu ihr: Sei getrost, du hast wieder einen Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Als aber ihre Seele entfloh - denn sie musste sterben -, da nannte sie ihn Ben-Oni; sein Vater aber nannte ihn Ben-Jamin. (1) d.i. Sohn meines Schmerzes. (2) d.i. Sohn des Glücks.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'So starb Rahel und ward begraben am Wege nach Ephrath, das ist Bethlehem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob errichtete auf ihrem Grabe einen Malstein. Das ist der Malstein des Rahelgrabes bis auf den heutigen Tag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Dann zog Israel weiter und schlug sein Zelt auf jenseits von Migdal-Eder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'In der Zeit nun, da Israel dortzulande wohnte, ging Ruben hin und schlief bei Bilha, dem Nebenweibe seines Vaters. Israel aber erfuhr es und ward zornig darob. Jakob hatte zwölf Söhne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Söhne Leas waren: Ruben der Erstgeborne Jakobs, Simeon, Levi, Juda, Issaschar und Sebulon;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'die Söhne Rahels: Joseph und Benjamin;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'die Söhne Bilhas, der Magd Rahels: Dan und Naphthali;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'die Söhne Silpas, der Magd Leas: Gad und Asser. Dies sind die Söhne Jakobs, die ihm in Mesopotamien geboren wurden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob kam zu seinem Vater Isaak nach Mamre, nach Kirjath-Arba - das ist Hebron -, wo Abraham und Isaak Fremdlinge gewesen waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Isaak aber wurde 180 Jahre alt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Dann verschied Isaak und starb und ward versammelt zu seinen Stammesgenossen, alt und lebenssatt; und seine Söhne Esau und Jakob begruben ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'DIES ist die Nachkommenschaft Esaus - das ist Edom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau hatte seine Frauen aus den Töchtern Kanaans genommen: Ada, die Tochter des Hethiters Elon, und Oholibama, die Tochter Anas, des Sohnes Zibeons, des Horiters, (a) 1Mo 26:34; 28:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basmath, die Tochter Ismaels, die Schwester Nebajoths.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada gebar dem Esau den Eliphas, Basmath gebar den Reguel,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'und Oholibama gebar den Jehus, den Jaelam und den Korah. Dies sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Frauen, seine Söhne und Töchter und alle Seelen seines Hauses, auch seine Habe und all sein Vieh und allen Besitz, den er im Lande Kanaan erworben hatte, und zog von seinem Bruder Jakob weg ins Land Seir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihr Besitz war zu gross, als dass sie beieinander bleiben konnten; und das Land, wo sie als Fremdlinge weilten, vermochte sie nicht zu erhalten wegen ihrer Herden. (a) 1Mo 13:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'So liess sich Esau auf dem Gebirge Seir nieder - Esau, das ist Edom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Das ist die Nachkommenschaft Esaus, des Vaters der Edomiter auf dem Gebirge Seir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphas, der Sohn Adas, des Weibes Esaus; Reguel, der Sohn Basmaths, des Weibes Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Die Söhne des Eliphas aber waren Theman, Omar, Zepho, Gaetham und Kenas.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Thimna war ein Nebenweib des Eliphas, des Sohnes Esaus; sie gebar dem Eliphas den Amalek. Das sind die Söhne Adas, des Weibes Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Dies sind die Söhne Reguels: Nahath, Serah, Samma und Missa. Das waren die Söhne Basmaths, des Weibes Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und dies waren die Söhne Oholibamas, des Weibes Esaus, der Tochter Anas, des Sohnes Zibeons: sie gebar dem Esau den Jehus, den Jaelam und den Korah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies sind die Fürsten der Söhne Esaus: die Söhne des Eliphas, des Erstgebornen Esaus: der Fürst von Theman, der Fürst von Omar, der Fürst von Zepho, der Fürst von Kenas,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Fürst von Korah, der Fürst von Gaetham, der Fürst von Amalek. Das sind die Fürsten von Eliphas im Lande Edom; das sind die Söhne der Ada.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Dies sind die Söhne Reguels, des Sohnes Esaus: der Fürst von Nahath, der Fürst von Serah, der Fürst von Samma, der Fürst von Missa. Das sind die Fürsten von Reguel im Lande Edom; das sind die Söhne der Basmath, des Weibes Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Dies sind die Söhne Oholibamas, des Weibes Esaus: der Fürst von Jehus, der Fürst von Jaelam, der Fürst von Korah. Das sind die Fürsten von Oholibama, der Tochter Anas, dem Weibe Esaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Das sind die Söhne Esaus, und das sind ihre Fürsten - das ist Edom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dies sind die Söhne Seirs, des Horiters, die (Ur-)Einwohner des Landes: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer und Disan. Das sind die Fürsten der Horiter, die Söhne Seirs im Lande Edom.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Die Söhne Lotans waren Hori und Hemam; und Lotans Schwester war Thimna.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Dies sind die Söhne Sobals: Alwan, Manahath, Ebal, Sepho und Onam.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Dies sind die Söhne Zibeons: Aja und Ana. Das ist der Ana, der die heissen Quellen in der Wüste fand, als er die Esel seines Vaters Zibeon hütete.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Dies sind die Söhne Anas: Dison; und Oholibama ist die Tochter Anas.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Dies sind die Söhne Disons: Hemdan, Esban, Jithran und Cheran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dies sind die Söhne Ezers: Bilhan, Saewan und Akan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dies sind die Söhne Disans: Uz und Aran.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Fürsten der Horiter: der Fürst von Lotan, der Fürst von Sobal, der Fürst von Zibeon, der Fürst von Ana,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Fürst von Dison, der Fürst von Ezer, der Fürst von Disan. Das sind die Fürsten der Horiter nach ihren Fürstentümern im Lande Seir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Dies sind die Könige, die im Lande Edom regiert haben, ehe ein König regierte in Israel:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, der Sohn Beors, ward König über Edom; seine Stadt hiess Dinhaba.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Als Bela starb, ward Jobab, der Sohn Serahs aus Bozra, König an seiner Statt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Als Jobab starb, ward Husam aus dem Land der Themaniter König an seiner Statt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Als Husam starb, ward Hadad, der Sohn Bedads, König an seiner Statt; der schlug die Midianiter im Gefilde Moabs; seine Stadt hiess Awith.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Als Hadad starb, ward Samla aus Masreka König an seiner Statt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Als Samla starb, ward Saul aus Rehoboth am Flusse König an seiner Statt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Als Saul starb, ward Baal-Hanan, der Sohn Achbors, König an seiner Statt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Als Baal-Hanan, der Sohn Achbors, starb, ward Hadar König an seiner Statt; seine Stadt hiess Pahu, und sein Weib hiess Mehetabel, die Tochter der Matred, der Tochter Mesahabs.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Dies sind die Namen der Fürsten Esaus nach ihren Geschlechtern, ihren Orten, ihren Namen: der Fürst von Thimna, der Fürst von Alwa, der Fürst von Jetheth,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Fürst von Oholibama, der Fürst von Ela, der Fürst von Pinon,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Fürst von Kenas, der Fürst von Theman, der Fürst von Mibzar,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Fürst von Magdiel, der Fürst von Iram. Das sind die Fürsten von Edom nach ihren Wohnsitzen in dem Lande, das sie besetzt hatten - das ist von Esau, dem Vater der Edomiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber blieb in dem Lande, wo sein Vater als Fremdling geweilt hatte, im Lande Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'DIES ist die Geschichte Jakobs: Als Joseph siebzehn Jahre alt war, hütete er die Schafe mit seinen Brüdern - er war aber noch jung -, mit den Söhnen Bilhas und Silpas, der Frauen seines Vaters, und was man ihnen Schlimmes nachsagte, hinterbrachte Joseph ihrem Vater.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel aber hatte Joseph lieber als alle seine andern Söhne, weil er ihm erst im Alter geboren war, und er liess ihm einen Rock mit Ärmeln machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Als nun seine Brüder sahen, dass ihr Vater ihn lieber hatte als alle seine andern Söhne, wurden sie ihm feind und mochten ihm kein freundliches Wort mehr gönnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Einst hatte Joseph einen Traum und erzählte ihn seinen Brüdern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Und er sprach zu ihnen: Hört einmal, was mir geträumt hat!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Wir waren am Garbenbinden auf dem Felde; da richtete sich auf einmal meine Garbe auf und blieb stehen, eure Garben aber stellten sich ringsherum und verneigten sich vor meiner Garbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Brüder zu ihm: Du willst wohl gar unser König werden oder über uns herrschen? Und sie hassten ihn noch mehr um seiner Träume und um seiner Worte willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Darnach hatte er noch einen andern Traum; den erzählte er seinen Brüdern auch und sprach: Seht, ich habe noch einen Traum gehabt: die Sonne und der Mond und elf Sterne verneigten sich vor mir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Das erzählte er seinem Vater und seinen Brüdern. Da schalt ihn sein Vater und sprach zu ihm: Was ist das für ein Traum, den du da gehabt hast? Sollen etwa ich und deine Mutter und deine Brüder kommen und vor dir niederfallen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Und seine Brüder wurden neidisch auf ihn, sein Vater aber behielt die Sache im Sinn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Als nun seine Brüder hingingen, die Schafe ihres Vaters bei Sichem zu weiden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'sprach Israel zu Joseph: Du weisst, deine Brüder weiden bei Sichem. Komm, ich will dich zu ihnen senden. Er erwiderte: Hier bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Und er sprach zu ihm: Geh hin und schau, ob es wohlsteht um deine Brüder und ob es wohlsteht um die Herde, und bringe mir Bericht. So sandte er ihn hin aus dem Tal von Hebron, und er kam nach Sichem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Da traf ihn ein Mann, wie er auf dem Felde umherirrte. Der Mann fragte ihn: Was suchst du?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er antwortete: Ich suche meine Brüder; sage mir doch, wo sie hüten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Der Mann sprach: Sie sind von hier weggezogen; denn ich hörte, wie sie sagten: \"Lasst uns nach Dothan gehen.\" Da ging Joseph seinen Brüdern nach und fand sie bei Dothan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Als sie ihn nun von ferne sahen, machten sie, bevor er nahe zu ihnen herankam, einen Anschlag, ihn zu töten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'und sprachen zueinander: Seht, da kommt der Träumer her!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Wohlan, wir wollen ihn töten und in eine der Zisternen werfen und hernach sagen, ein wildes Tier habe ihn gefressen; dann werden wir ja sehen, was aus seinen Träumen wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Als Ruben das hörte, suchte er ihn aus ihrer Hand zu erretten und sprach: Ans Leben wollen wir ihm nicht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Dann sprach Ruben zu ihnen: Vergiesst kein Blut! Werft ihn in diese Zisterne da in der Wüste, doch legt nicht Hand an ihn! Er wollte ihn aber aus ihrer Hand erretten, um ihn zu seinem Vater zurückzubringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Als nun Joseph zu seinen Brüdern kam, zogen sie ihm seinen Rock aus, den Ärmelrock, den er anhatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Und sie ergriffen ihn und warfen ihn in die Zisterne; die Zisterne aber war leer, es war kein Wasser darin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Dann setzten sie sich nieder, um zu essen. Als sie nun ihre Augen erhoben, sahen sie eine Karawane von Ismaelitern daherkommen, aus Gilead, die ihre Kamele mit Gummi, Balsam und Harz beladen hatten und damit nach Ägypten hinab unterwegs waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brüdern: Was nützte es uns, wenn wir unsern Bruder erschlügen und sein Blut zudeckten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, wir wollen ihn an die Ismaeliter verkaufen, aber uns nicht an ihm vergreifen; er ist doch unser Bruder und unser Fleisch. Und seine Brüder hörten auf ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Es kamen aber midianitische Kaufleute vorüber, und sie zogen Joseph aus der Zisterne herauf. Und sie verkauften Joseph um zwanzig Lot Silber an die Ismaeliter; die brachten Joseph nach Ägypten. (a) Mt 26:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als nun Ruben wieder zu der Zisterne kam, siehe, da war Joseph nicht mehr darin. Und er zerriss seine Kleider,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'kehrte zu seinen Brüdern zurück und sprach: Der Knabe ist nicht mehr da! Wo soll ich nun hin?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Da nahmen sie den Rock Josephs, schlachteten einen Ziegenbock und tauchten den Rock in das Blut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Dann schickten sie den Ärmelrock hin, brachten ihn ihrem Vater und sagten: Das haben wir gefunden. Sieh es an, ob es deines Sohnes Rock ist oder nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Und als er ihn ansah, sprach er: Es ist meines Sohnes Rock. Ein wildes Tier hat ihn gefressen. Fürwahr, zerrissen ist Joseph.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriss seine Kleider und legte ein Trauergewand um seine Hüften; und er trug lange Zeit Leid um seinen Sohn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Da erhoben sich alle seine Söhne und Töchter, ihn zu trösten. Aber er wollte sich nicht trösten lassen und sprach: Nein, trauernd werde ich zu meinem Sohn ins Totenreich hinunterfahren. So beweinte ihn sein Vater.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Die Midianiter aber verkauften Joseph nach Ägypten an Potiphar, den Kämmerer des Pharao, den Obersten der Leibwache.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'UM jene Zeit begab es sich, dass Juda von seinen Brüdern wegzog und sich an einen Mann aus Adullam mit Namen Hira anschloss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Und Juda sah daselbst die Tochter eines Kanaaniters namens Sua, und er nahm sie zum Weibe und wohnte ihr bei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Da ward sie schwanger und gebar einen Sohn; den nannte sie Er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Dann ward sie abermals schwanger und gebar einen Sohn, den nannte sie Onan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sodann gebar sie noch einen Sohn, den nannte sie Sela; sie befand sich aber in Chesib, als sie ihn gebar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Und Juda freite seinem Erstgebornen Er ein Weib mit Namen Thamar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Aber Er, der Erstgeborne Judas, missfiel dem Herrn; darum liess der Herr ihn sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sprach Juda zu Onan: Gehe zu dem Weibe deines Bruders und vollziehe mit ihr die Pflichtehe, dass du deinem Bruder Nachkommen schaffest. (a) 5Mo 25:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Da aber Onan wusste, dass die Kinder nicht als die seinen gelten sollten, liess er es, wenn er zum Weibe seines Bruders ging, auf die Erde fallen und so verderben, um seinem Bruder nicht Nachkommen zu verschaffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Aber dem Herrn missfiel, was er tat, und er liess ihn auch sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sprach Juda zu seiner Schwiegertochter Thamar: Bleibe als Witwe im Hause deines Vaters, bis mein Sohn Sela gross wird. Denn er dachte: auch er könnte sterben wie seine Brüder. So ging Thamar hin und blieb im Hause ihres Vaters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Und die Jahre vergingen; da starb die Tochter Suas, das Weib Judas. Als nun die Trauerzeit um war, ging Juda einst mit seinem Freunde Hira von Adullam zu seinen Schafscherern hinauf nach Thimna.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Nun sagte man der Thamar: Siehe, dein Schwiegervater geht hinauf nach Thimna, seine Schafe zu scheren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Da legte sie ihre Witwenkleider ab, bedeckte sich mit dem Schleier und verhüllte sich; dann setzte sie sich an das Tor von Enaim, am Wege nach Thimna. Denn sie hatte gesehen, dass Sela herangewachsen war, und doch war sie ihm nicht zum Weibe gegeben worden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Als Juda sie sah, hielt er sie für eine Dirne; denn sie hatte ihr Angesicht verhüllt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und er bog zu ihr ab am Wege und sprach: Lass mich dir beiwohnen. Denn er wusste nicht, dass es seine Schwiegertochter war. Sie antwortete: Was gibst du mir, wenn du zu mir kommen darfst?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er sprach: Ich will dir ein Ziegenböcklein von der Herde schicken. Sie erwiderte: Wenn du mir ein Pfand gibst, bis du es schickst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Er sprach: Was willst du, dass ich dir zum Pfande gebe? Sie antwortete: Deinen Siegelring und deine Schnur und den Stab in deiner Hand. Da gab er es ihr und wohnte ihr bei, und sie ward von ihm schwanger.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Und sie stand auf und ging ihres Weges, legte ihren Schleier ab und zog ihre Witwenkleider wieder an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda aber sandte das Ziegenböcklein durch seinen Freund von Adullam, um das Pfand von dem Weibe wieder zu bekommen; der aber fand sie nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Da fragte er die Leute an dem Orte: Wo ist die geweihte Buhle, die bei Enaim am Wege sass? Sie antworteten: Es ist gar keine geweihte Buhle hier gewesen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Und er kam wieder zu Juda und sprach: Ich habe sie nicht gefunden; auch sagen die Leute an dem Orte, es sei gar keine geweihte Buhle dagewesen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Da sprach Juda: So mag sie es behalten, dass wir nicht ins Gerede kommen. Nun, ich habe das Böcklein geschickt, du hast sie aber nicht gefunden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Etwa drei Monate später aber wurde Juda hinterbracht: Deine Schwiegertochter Thamar hat Unzucht getrieben und ist davon nun auch schwanger geworden. Da sprach Juda: Führt sie hinaus, sie soll verbrannt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Schon wurde sie hinausgeführt, da schickte sie zu ihrem Schwiegervater und liess ihm sagen: Von dem Manne, dem dies hier gehört, bin ich schwanger. Und sie sprach: Sieh es an; wem gehören diese Dinge, der Siegelring und die Schnur und der Stab?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Als Juda genauer zusah, sprach er: Sie ist im Rechte gegen mich; warum habe ich sie meinem Sohne Sela nicht gegeben! Doch verkehrte er nicht mehr mit ihr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Als nun die Zeit kam, dass sie gebären sollte, siehe, da hatte sie Zwillinge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Bei der Geburt aber streckte einer eine Hand vor; die Hebamme ergriff sie und band einen roten Faden darum. Das wollte sagen: Der ist zuerst gekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Als er aber seine Hand zurückzog, da kam sein Bruder heraus. Und sie sprach: Wie hast du dir doch einen Riss gerissen! Und man nannte ihn Perez. (1) d.i. Riss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Darnach kam sein Bruder heraus, der den roten Faden um die Hand hatte; den nannte man Serah.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'ALS aber Joseph nach Ägypten hinabgeführt worden war, kaufte ihn Potiphar, der Kämmerer des Pharao, der Oberste der Leibwache, ein Ägypter, von den Ismaelitern, die ihn dorthin gebracht hatten. (a) 1Mo 37:36');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Und der Herr war mit Joseph, und es geriet ihm alles wohl, sodass er im Hause seines Gebieters, des Ägypters, bleiben durfte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Als nun sein Gebieter sah, dass der Herr mit ihm war und dass der Herr alles, was er tat, in seiner Hand wohl gelingen liess,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'kam Joseph in grosse Gunst bei ihm und wurde sein Leibdiener; und er setzte ihn über sein Haus, und alles, was er hatte, übergab er ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und von der Zeit an, da er ihn über sein Haus und alle seine Güter gesetzt hatte, segnete der Herr das Haus des Ägypters um Josephs willen, und der Segen des Herrn ruhte auf allem, was er hatte, in Haus und Feld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Darum überliess er Joseph alles, was er hatte, und kümmerte sich neben ihm um nichts als um die Speise, die er ass. Joseph aber war schön von Gestalt und schön von Aussehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Darnach begab es sich, dass die Frau seines Herrn ihre Augen auf Joseph warf und sprach: Lege dich zu mir!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu der Frau seines Herrn: Sieh, mein Herr kümmert sich neben mir um nichts im Hause, und alles, was er besitzt, hat er mir übergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Er selbst ist in diesem Hause nicht grösser als ich; er hat mir nichts vorenthalten als dich, weil du sein Weib bist. Wie sollte ich da ein so grosses Unrecht begehen und wider Gott sündigen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und ob sie auch täglich Joseph zuredete, hörte er nicht auf sie, dass er sich zu ihr gelegt hätte, um mit ihr Umgang zu pflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Es begab sich aber eines Tages, dass Joseph ins Haus kam, seine Geschäfte zu besorgen, als gerade niemand vom Gesinde zugegen war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Da fasste sie ihn beim Kleide und sprach: Lege dich zu mir! Er aber liess sein Kleid in ihrer Hand und floh und lief zum Hause hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Als sie nun sah, dass er sein Kleid in ihrer Hand gelassen hatte und zum Hause hinaus geflohen war,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'rief sie ihr Gesinde und sprach zu ihnen: Seht, da hat er uns einen Hebräer ins Haus gebracht, dass der seinen Mutwillen mit uns treibe. Er kam zu mir herein, um sich zu mir zu legen; aber ich schrie laut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Und als er hörte, dass ich ein Geschrei erhob und rief, liess er sein Kleid neben mir und floh und lief zum Hause hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie liess sein Kleid neben sich liegen, bis sein Herr heimkam.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Da erzählte sie ihm dieselbe Geschichte und sprach: Der hebräische Sklave, den du uns ins Haus gebracht hast, dass er seinen Mutwillen mit mir treibe, ist zu mir hereingekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Wie ich aber ein Geschrei erhob und rief, liess er sein Kleid neben mir und floh zum Hause hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als sein Herr die Geschichte hörte, die ihm seine Frau erzählte, indem sie sagte: \"So und so hat dein Sklave an mir getan\", ward er sehr zornig,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'und er nahm Joseph und legte ihn in das Gefängnis, wo die Gefangenen des Königs in Gewahrsam lagen. Und er blieb daselbst im Gefängnis.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Der Herr aber war mit Joseph und machte ihn beliebt und erwarb ihm die Gunst des Aufsehers über das Gefängnis,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'also dass ihm dieser alle Gefangenen im Gefängnis anvertraute; alles, was dort geschah, geschah durch ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der Aufseher über das Gefängnis kümmerte sich um nichts, was in seiner Hand lag, weil der Herr mit ihm war; und der Herr gab Glück zu allem, was er tat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'DARNACH begab es sich, dass der Mundschenk und der Bäcker des Königs von Ägypten sich wider ihren Herrn, den König von Ägypten, vergingen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Da ward der Pharao zornig über seine zwei Hofbeamten, über den Obermundschenken und über den Oberbäcker,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und er gab sie in Gewahrsam in das Haus des Obersten der Leibwache, in das Gefängnis, wo Joseph gefangenlag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Oberste der Leibwache gab ihnen Joseph bei, dass er sie bediene; so waren sie eine Zeitlang im Gefängnis.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Da hatten sie beide in derselben Nacht einen Traum, jeder einen andern, jeder einen Traum von besonderer Bedeutung, der Mundschenk und der Bäcker des Königs von Ägypten, die im Gefängnis lagen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Als nun Joseph am Morgen zu ihnen hereinkam, sah er, dass sie verdriesslich waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Da fragte er die Hofbeamten des Pharao, die bei ihm im Hause seines Herrn in Gewahrsam lagen: Warum seht ihr heute so missmutig aus?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie antworteten ihm: Es hat uns geträumt, und wir haben niemand, der es uns auslegt. Joseph sprach zu ihnen: Traumdeutung steht bei Gott. Doch erzählt mir einmal. (a) 1Mo 41:16; Da 2:28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der Obermundschenk dem Joseph seinen Traum und sprach zu ihm: Mir träumte, ich sehe einen Weinstock vor mir');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'und an dem Weinstock drei Schosse, und sobald er trieb, stand er auch schon in voller Blüte, und seine Trauben hatten reife Beeren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ich aber hielt den Becher des Pharao in der Hand, und ich nahm die Beeren und zerdrückte sie in den Becher des Pharao und gab dem Pharao den Becher in die Hand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joseph sprach zu ihm: Dies ist die Bedeutung: die drei Schosse sind drei Tage;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'in drei Tagen wird der Pharao dein Haupt erhöhen und dich wieder in dein Amt einsetzen, dass du dem Pharao den Becher reichen darfst wie früher, als du sein Mundschenk warst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber gedenke meiner, wenn es dir wohlgeht, und erweise mir die Liebe, dass du beim Pharao ein gutes Wort für mich einlegst, und hilf mir, dass ich aus diesem Hause komme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn ich bin schmählich aus dem Lande der Hebräer gestohlen worden, und auch hier habe ich es mit nichts verschuldet, dass sie mich in den Kerker geworfen haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Als der Oberbäcker sah, dass Joseph eine günstige Deutung gegeben hatte, sprach er zu ihm: Auch mir hat geträumt; mir war, ich trage drei Körbe voll Weissbrot auf dem Kopfe,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'und im obersten Korbe war allerlei Speise, Backwerk für den Pharao; aber die Vögel frassen es aus dem Korb auf meinem Kopfe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joseph antwortete und sprach: Dies ist die Bedeutung: die drei Körbe sind drei Tage;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'in drei Tagen wird der Pharao dein Haupt erhöhen und dich an den Pfahl hängen lassen, und die Vögel werden das Fleisch von dir wegfressen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und es geschah am dritten Tage, am Geburtstag des Pharao, da gab er allen seinen Dienern ein Mahl, und er erhöhte das Haupt des Obermundschenken und des Oberbäckers inmitten seiner Diener:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'den Obermundschenken setzte er wieder in sein Amt ein, dass er dem Pharao den Becher reichen durfte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'den Oberbäcker aber liess er hängen; wie Joseph es ihnen gedeutet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der Obermundschenk gedachte Josephs nicht, sondern vergass ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'NACH zwei Jahren hatte der Pharao einen Traum: er stand am Nil');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'und sah sieben schöne, fette Kühe aus dem Nil emporsteigen; die weideten im Grase.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Nach ihnen sah er aus dem Nil sieben andre Kühe steigen, hässlich und mager; die traten neben die Kühe am Ufer des Nil.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Und die hässlichen, magern Kühe frassen die sieben schönen, fetten Kühe. Da erwachte der Pharao.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Dann schlief er wieder ein und träumte abermals: sieben Ähren wuchsen auf einem Halme, dick und schön;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'nach ihnen sah er sieben dünne Ähren sprossen, die der Ostwind versengt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die dünnen Ähren verschlangen die sieben dicken, vollen Ähren. Da erwachte der Pharao, und siehe, es war ein Traum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Am Morgen aber wurde sein Geist beunruhigt. Darum sandte er hin und liess alle Wahrsager und alle Weisen von Ägypten rufen und erzählte ihnen seinen Traum; aber es war keiner, der ihn dem Pharao auslegen konnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da sprach der Obermundschenk zum Pharao: Ich muss heute an meine Verfehlung erinnern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Als der Pharao über seine Knechte zornig ward und sie in das Haus des Obersten der Leibwache in Gewahrsam gab, mich und den Oberbäcker,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'da hatten wir in derselben Nacht einen Traum, ich und er; jeder hatte einen Traum von besonderer Bedeutung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Nun war dort ein hebräischer Jüngling bei uns, ein Sklave des Obersten der Leibwache; dem erzählten wir es, und er legte uns unsre Träume aus, einem jeden legte er seinen Traum besonders aus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und wie er es uns ausgelegt, so ist es gekommen: mich hat man wieder in mein Amt eingesetzt, und ihn hat man gehängt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte der Pharao hin und liess Joseph rufen, und man holte ihn eilends aus dem Kerker. Er liess sich scheren und wechselte die Kleider, und dann erschien er vor dem Pharao.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Da sprach der Pharao zu Joseph: Ich habe einen Traum gehabt, und niemand kann ihn auslegen; ich habe aber von dir sagen hören, wenn du einen Traum nur hörest, so könnest du ihn auslegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph antwortete dem Pharao und sprach: Bei mir steht das nicht; Gott wird dem Pharao Heil verkünden. (a) 1Mo 40:8; Da 2:28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Nun sprach der Pharao zu Joseph: Mir träumte, ich stehe am Ufer des Nil.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Da stiegen aus dem Nil sieben fette, schöne Kühe und weideten im Grase.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Nach ihnen stiegen sieben andre Kühe herauf, dürr und überaus hässlich und mager; ich habe in ganz Ägypten nie so hässliche gesehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Und nun frassen die magern, hässlichen Kühe die sieben ersten, fetten Kühe auf;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'und wie sie die hineingefressen, merkte man ihnen gar nicht an, dass sie sie verschlungen hatten; sie waren noch so hässlich wie zuvor. Da erwachte ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Dann hatte ich (nochmals) einen Traum: sieben Ähren wuchsen auf einem Halme, voll und schön;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'nach ihnen sprossten sieben harte, dünne Ähren, vom Ostwind versengt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'und die dünnen Ähren verschlangen die sieben schönen Ähren. Das habe ich den Wahrsagern erzählt, aber keiner kann es mir erklären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da sprach Joseph zum Pharao: Beide Träume des Pharao bedeuten dasselbe. Gott hat dem Pharao verkündet, was er tun will.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schönen Kühe sind sieben Jahre, und die sieben schönen Ähren sind sieben Jahre; es ist ein und derselbe Traum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Die sieben magern, hässlichen Kühe, die nach ihnen heraufstiegen, sind sieben Jahre; und die sieben leeren, vom Ostwind versengten Ähren werden sieben Hungerjahre sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das meinte ich, als ich zum Pharao sagte: \"Gott hat dem Pharao gezeigt, was er tun will.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Siehe, es werden sieben Jahre kommen mit grosser Fülle in ganz Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Und nach ihnen werden sieben Hungerjahre kommen; da wird all die Fülle in Ägypten vergessen sein: der Hunger wird das Land verzehren,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'dass man nichts mehr spüren wird von der Fülle im Lande ob der Hungersnot, die hernach kommt; denn sie wird sehr schwer sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Dass aber dem Pharao zweimal geträumt hat, das bedeutet, dass die Sache bei Gott fest beschlossen ist und dass Gott es alsbald tun wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nun sehe sich der Pharao nach einem verständigen und weisen Manne um, den er über das Land Ägypten setze;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'und der Pharao greife ein und bestelle Amtleute über das Land, um in den sieben Jahren der Fülle den Fünften zu erheben vom Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Sie sollen alles Getreide dieser guten Jahre, die nun kommen werden, sammeln und das Korn aufspeichern zur Verfügung des Pharao; sie sollen das Getreide in die Städte schaffen und es dort verwahren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'So wird das Getreide dem Land als Vorrat dienen in den sieben Hungerjahren, die über das Land Ägypten kommen werden, dass nicht das Land vor Hunger verderbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Diese Rede gefiel dem Pharao und allen seinen Dienern wohl.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und der Pharao sprach zu seinen Dienern: Könnten wir wohl einen Mann finden, in dem der Geist Gottes wäre wie in diesem? (a) Da 5:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Und zu Joseph sprach der Pharao: Nachdem dir Gott das alles kundgetan hat, ist niemand so verständig und weise wie du.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst über mein Haus gesetzt sein, und deinem Worte soll mein ganzes Volk gehorchen; nur um den Thron will ich höher sein als du.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dann sprach der Pharao zu Joseph: Siehe, ich setze dich hiemit über das ganze Land Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Und der Pharao zog seinen Siegelring vom Finger und steckte ihn Joseph an die Hand, kleidete ihn in Gewänder von Byssus und hängte ihm die goldene Kette um den Hals.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Dann liess er ihn auf seinem zweiten Wagen fahren, und man rief vor ihm her: Abrek! So setzte er ihn über das ganze Land Ägypten. (1) d.h. vlt: Auf die Kniee!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und der Pharao sprach zu Joseph: Ich bin der Pharao, und ohne deinen Willen soll niemand im ganzen Lande Ägypten die Hand oder den Fuss regen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und der Pharao nannte Joseph hinfort Zaphnath-Paneah und gab ihm Asnath, die Tochter Potipheras, des Priesters von On, zum Weibe. So gebot Joseph über das Land Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joseph war dreissig Jahre alt, als er vor den Pharao, den König von Ägypten, trat. Und Joseph zog vom Pharao hinweg und fuhr durch das ganze Land Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Das Land aber trug in den sieben Jahren der Fülle Korn im Überfluss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Da sammelte er alles Getreide der sieben Jahre, in denen Überfluss herrschte im Lande Ägypten, und schaffte das Getreide in die Städte; in eine jede Stadt tat er das Getreide von den Feldern rings um sie her.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'So speicherte Joseph das Korn auf, über die Massen viel, wie Sand am Meer, sodass er davon abstand, es zu messen; denn es war unermesslich viel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Und Joseph wurden zwei Söhne geboren, ehe das Hungerjahr kam; die gebar ihm Asnath, die Tochter Potipheras, des Priesters von On.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und Joseph nannte den Erstgebornen Manasse; denn (sprach er) Gott hat mich all meine Mühsal und meines Vaters ganzes Haus vergessen lassen. (1) vgl. Anm. zu 1Mo 29:32.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den zweiten nannte er Ephraim; denn (sprach er) Gott hat mich fruchtbar gemacht im Lande meines Elends. (1) vgl. Anm. zu 1Mo 29:32.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Als die sieben Jahre der Fülle im Lande Ägypten um waren,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'begannen die sieben Hungerjahre, wie Joseph gesagt hatte, und es kam eine Hungersnot über alle Länder; im ganzen Lande Ägypten jedoch war Brot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Als aber ganz Ägypten Hunger litt, schrie das Volk zum Pharao um Brot. Da sprach der Pharao zu allen Ägyptern: Geht zu Joseph; was der euch sagt, das tut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Die Hungersnot aber herrschte auf der ganzen Erde. Nun öffnete Joseph alle Kornspeicher und verkaufte den Ägyptern Getreide. Und die Hungersnot wurde drückend im Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Und alle Welt kam zu Joseph nach Ägypten, um Korn zu kaufen; denn die Hungersnot war drückend in aller Welt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'ALS aber Jakob sah, dass in Ägypten Korn feil war, sprach er zu seinen Söhnen: Was schaut ihr einander an?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Ich höre doch, sprach er, dass in Ägypten Korn feil ist. Zieht hinab und kauft uns dort Getreide, dass wir zu leben haben und nicht sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Da zogen die Brüder Josephs, ihrer zehn Mann, hinab, um in Ägypten Korn zu kaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Aber Benjamin, den Bruder Josephs, liess Jakob nicht mit seinen Brüdern ziehen; denn er dachte, es könnte ihm ein Unfall zustossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'So kamen unter den Leuten, die hinzogen, auch die Söhne Israels, um Korn zu kaufen; denn es herrschte Hungersnot im Lande Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Nun war Joseph der Regent im Lande; er war es, der allem Volk im Lande Korn verkaufte. Als aber die Brüder Josephs zu ihm kamen, warfen sie sich vor ihm zur Erde nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Sobald Joseph seine Brüder sah, erkannte er sie; aber er stellte sich fremd gegen sie und redete hart mit ihnen und fragte sie: Wo kommt ihr her? Sie sprachen: Aus dem Lande Kanaan, um Speise zu kaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Während aber Joseph seine Brüder erkannte, erkannten sie ihn nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Da gedachte Joseph der Träume, die er von ihnen geträumt hatte. Und er sprach zu ihnen: Ihr seid Kundschafter! Die Blösse des Landes zu erspähen, seid ihr gekommen. (a) 1Mo 37:5-11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie erwiderten ihm: Nicht doch, Herr! Deine Knechte sind gekommen, Speise zu kaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir sind alle eines Mannes Söhne; wir sind ehrliche Leute, deine Knechte sind keine Kundschafter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Aber er sprach zu ihnen: Nichts da! ihr seid gekommen, die Blösse des Landes zu erspähen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie antworteten: Wir, deine Knechte, waren unser zwölf. Wir sind Brüder, Söhne eines Mannes im Lande Kanaan. Der jüngste ist jetzt noch bei unserm Vater, und einer ist nicht mehr da.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph aber sprach zu ihnen: Es ist so, wie ich euch gesagt habe: Kundschafter seid ihr!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran will ich euch erproben: So wahr der Pharao lebt, ihr sollt nicht von hinnen ziehen, es komme denn euer jüngster Bruder her.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sendet einen von euch hin, dass er euren Bruder hole; ihr aber bleibt gefangen. So will ich eure Rede prüfen, ob ihr mit der Wahrheit umgeht; wo nicht, so seid ihr Kundschafter, so wahr der Pharao lebt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und er tat sie alle zusammen in Gewahrsam, drei Tage lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tage aber sprach Joseph zu ihnen: Wollt ihr am Leben bleiben, so tut dies - denn ich bin gottesfürchtig -:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'seid ihr ehrliche Leute, so lasst einen von euch Brüdern hier im Gefängnis gebunden liegen, ihr aber ziehet hin und nehmt genug Getreide heim, den Hunger eurer Familien zu stillen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Dann bringt euern jüngsten Bruder zu mir, dass eure Worte sich als wahr erweisen und ihr nicht sterben müsset.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Da sprachen sie untereinander: Wahrlich, das haben wir an unserm Bruder verschuldet; denn wir sahen die Not seiner Seele, als er uns anflehte, aber wir hörten nicht auf ihn. Darum kommt nun diese Not über uns.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben antwortete ihnen: Habe ich euch nicht gesagt: \"Versündigt euch nicht an dem Knaben!\" Doch ihr wolltet nicht hören; und nun, seht ihr, wird sein Blut gefordert. (a) 1Mo 37:21 22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie wussten aber nicht, dass Joseph sie verstand; denn er redete durch einen Dolmetscher mit ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Nun ging er von ihnen hinweg und weinte. Dann kehrte er zu ihnen zurück und redete mit ihnen; und er nahm den Simeon von ihnen weg und liess ihn vor ihren Augen binden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Darnach befahl er, dass man ihre Säcke mit Korn fülle und einem jeden das Geld wieder in seinen Sack lege und dass man ihnen Zehrung auf den Weg mitgebe. Das tat man ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Sie aber luden ihr Korn auf ihre Esel und zogen von dannen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Als nun einer in der Herberge seinen Sack auftat, um seinem Esel Futter zu geben, sah er sein Geld oben im Sacke liegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Da sprach er zu seinen Brüdern: Mein Geld ist wieder da; hier in meinem Sacke ist es. Da entfiel ihnen der Mut, und sie sahen einander erschrocken an und sprachen: Was hat uns Gott da angetan!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Als sie nun heim zu ihrem Vater Jakob ins Land Kanaan kamen, erzählten sie ihm alles, was ihnen begegnet war, und sprachen:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Der Mann, der Herr im Lande ist, hat mit uns hart geredet und uns ins Gefängnis gelegt, als wären wir Kundschafter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Da sprachen wir zu ihm: \"Wir sind ehrliche Leute, wir sind keine Kundschafter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Wir sind unser zwölf Brüder, Söhne unsres Vaters; einer ist nicht mehr da, und der jüngste ist jetzt noch bei unserm Vater im Lande Kanaan.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Nun sprach der Mann, der Herr des Landes, zu uns: \"Daran will ich erkennen, dass ihr ehrliche Leute seid: lasst einen von euch Brüdern bei mir und nehmt genug Getreide mit, den Hunger eurer Familien zu stillen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Bringt mir aber euren jüngsten Bruder her, damit ich erkenne, dass ihr keine Kundschafter, sondern ehrliche Leute seid; dann will ich euch euren Bruder wieder geben, und ihr mögt frei im Lande umherziehen.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Und als sie die Säcke leerten, siehe, da fand ein jeder den Beutel mit seinem Geld in seinem Sacke. Als sie aber, sie und ihr Vater, die Beutel mit dem Gelde sahen, fürchteten sie sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Da sprach ihr Vater Jakob zu ihnen: Mich beraubt ihr der Kinder. Joseph ist nicht mehr, Simeon ist nicht mehr, und Benjamin wollt ihr auch wegnehmen; über mich kommt dieses alles.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da erwiderte Ruben seinem Vater: Meine beiden Söhne magst du töten, wenn ich ihn dir nicht wieder bringe. Überlass ihn mir; ich bringe ihn dir wieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Aber er sprach: Mein Sohn soll nicht mit euch hinabziehen; denn sein Bruder ist tot, und er ist allein noch übrig. Wenn ihm ein Unfall zustiesse auf dem Wege, den ihr zieht, so würdet ihr meine grauen Haare mit Kummer ins Totenreich hinunterbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'DIE Hungersnot aber lastete schwer auf dem Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Als sie nun das Korn, das sie aus Ägypten gebracht, aufgegessen hatten, sprach ihr Vater zu ihnen: Zieht wieder hin und kauft uns ein wenig Speise.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Da erwiderte ihm Juda: Der Mann hat uns nachdrücklich eingeschärft: \"Ihr dürft mir nicht mehr unter die Augen treten, wenn euer jüngster Bruder nicht bei euch ist.\" (a) 1Mo 42:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Willst du also unsern Bruder mit uns gehen lassen, so wollen wir hinabziehen und dir zu essen kaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Willst du ihn aber nicht mitgehen lassen, so ziehen wir nicht hinab; denn der Mann hat zu uns gesagt: \"Ihr dürft mir nicht mehr unter die Augen treten, wenn euer Bruder nicht bei euch ist.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sprach: Warum habt ihr mir das zuleide getan und dem Mann gesagt, dass ihr noch einen Bruder habt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Sie antworteten: Der Mann hat so genau nach uns und unsrer Verwandtschaft geforscht und uns gefragt: \"Lebt euer Vater noch? Habt ihr noch einen Bruder?\" Da sagten wir es ihm, wie die Dinge stehen. Konnten wir den wissen, dass er sagen würde: \"Bringt euren Bruder her!\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Dann sprach Juda zu seinem Vater Israel: Gib mir den Knaben mit, so wollen wir uns aufmachen und hinziehen, damit wir zu leben haben und nicht sterben, wir und du und unsre Kindlein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will Bürge für ihn sein, von meiner Hand sollst du ihn fordern; wenn ich ihn dir nicht wieder bringe und vor Augen stelle, so will ich vor dir mein Leben lang die Schuld tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Fürwahr, wenn wir nicht gezögert hätten, so wären wir jetzt schon zweimal wieder zurück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da sprach ihr Vater Israel zu ihnen: Muss es denn sein, so tut dies: nehmt von den besten Früchten des Landes in eure Säcke und bringt es dem Manne als Geschenk, ein wenig Balsam und ein wenig Honig, Gummi und Harz und Pistaziennüsse und Mandeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Und nehmt den doppelten Betrag an Geld mit euch: das Geld, das wieder oben in eure Säcke gelegt worden ist, müsst ihr auch mit zurücknehmen; vielleicht ist da ein Irrtum geschehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Dazu nehmt euren Bruder, macht euch auf und geht wieder zu dem Manne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Der allmächtige Gott lasse euch Barmherzigkeit finden vor dem Manne, dass er euren andern Bruder mit euch ziehen lasse und den Benjamin! Ich aber, wie ich nun einmal verwaist bin, so bin ich, ach, verwaist!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Da nahmen die Männer das Geschenk, auch den doppelten Betrag an Geld nahmen sie mit sich, dazu Benjamin, machten sich auf, zogen hinab nach Ägypten und traten vor Joseph.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Als Joseph den Benjamin bei ihnen sah, sprach er zu seinem Hausverwalter: Führe diese Männer ins Haus hinein, schlachte und richte zu, denn sie sollen mit mir zu Mittag essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Der Mann tat, wie Joseph befohlen hatte, und führte die Männer in Josephs Haus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Sie aber fürchteten sich, weil sie in Josephs Haus geführt wurden, und sprachen: Wir werden hier hereingeführt um des Geldes willen, welches das erste Mal wieder in unsre Säcke gekommen ist: man will auf uns eindringen und über uns herfallen und uns zu Sklaven machen und uns die Esel wegnehmen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Darum traten sie zu dem Manne, der über Josephs Haus gesetzt war, und redeten mit ihm an der Pforte');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'und sprachen: Lieber Herr, wir sind schon einmal herabgekommen, um Speise zu kaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Als wir nun in die Herberge kamen und unsre Säcke aufmachten, siehe, da lag eines jeden Geld oben in seinem Sacke, unser Geld nach seinem vollen Gewichte; das haben wir nun wieder mitgebracht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Wir haben aber auch noch andres Geld bei uns, um Speise zu kaufen. Wir wissen nicht, wer unser Geld in unsre Säcke gelegt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Er aber sprach: Seid getrost, fürchtet euch nicht! Euer Gott und eures Vaters Gott hat euch einen Schatz in die Säcke getan; euer Geld ist mir zugekommen. Und er brachte den Simeon zu ihnen heraus. (a) 1Mo 42:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Dann führte er die Männer in Josephs Haus, reichte ihnen Wasser, ihre Füsse zu waschen, und gab ihren Eseln Futter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sie aber machten das Geschenk bereit, bis Joseph am Mittag käme; denn sie hatten gehört, dass sie dort essen sollten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Als Joseph nun nach Hause kam, brachten sie ihm das Geschenk, das sie bei sich hatten, hinein und warfen sich vor ihm zur Erde nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Er aber begrüsste sie und sprach: Geht es eurem alten Vater wohl, von dem ihr erzählt habt? Ist er noch am Leben?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie antworteten: Es geht deinem Knechte, unserm Vater, wohl; er ist noch am Leben. Und sie verneigten sich und warfen sich nieder. (a) 1Mo 37:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Und als er seine Augen erhob und seinen Bruder Benjamin, den Sohn seiner Mutter, sah, sprach er: Ist das euer jüngster Bruder, von dem ihr mir erzählt habt? Darnach sprach er: Gott sei dir gnädig, mein Sohn!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Dann aber ging Joseph schnell in seine Kammer - denn sein Herz war tief bewegt beim Anblick seines Bruders, und das Weinen kam ihn an -, und er weinte daselbst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Und als er sein Angesicht gewaschen hatte, kam er wieder heraus und nahm sich zusammen und sprach: Tragt das Essen auf!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Und man trug ihm besonders auf und ihnen besonders, und ebenso den Ägyptern, die mit ihm assen. Denn die Ägypter dürfen nicht mit den Hebräern essen; das ist den Ägyptern ein Greuel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Man setzte sie aber ihm gegenüber, vom Erstgebornen bis zum Jüngsten, genau nach dem Alter; darob sahen sich die Männer verwundert an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Und er liess ihnen Gerichte auftragen von seinem Tische; dem Benjamin aber wurde fünfmal mehr aufgetragen als den andern. Und sie tranken mit ihm und wurden guter Dinge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'DANN gebot Joseph seinem Hausverwalter: Fülle den Männern die Säcke mit Getreide, so viel sie mitführen können, und lege einem jeden sein Geld oben in den Sack.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Meinen silbernen Becher aber lege oben in des Jüngsten Sack samt dem Geld für das Korn. Und er tat, wie ihm Joseph gesagt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Am Morgen, als es Tag ward, liess man die Männer mit den Eseln ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Kaum aber waren sie zur Stadt hinaus und noch nicht weit gekommen, da sprach Joseph zu seinem Hausverwalter: Auf, jage den Männern nach, und wenn du sie eingeholt hast, so sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten und meinen silbernen Becher gestohlen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist das nicht der, aus dem mein Herr trinkt und aus dem er weissagt? Daran habt ihr übelgetan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Als er sie nun eingeholt hatte, redete er solche Worte mit ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Sie antworteten: Warum redet mein Herr solche Worte? Ferne sei es von deinen Knechten, solches zu tun!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Das Geld, das wir oben in unsern Säcken gefunden, haben wir dir doch aus dem Lande Kanaan zurückgebracht; wie sollten wir da aus dem Hause deines Herrn Silber oder Gold stehlen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Der unter deinen Knechten, bei dem es gefunden wird, der sei des Todes; wir aber wollen überdies meines Herrn Knechte sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Er sprach zu ihnen: Ja, es sei, wie ihr gesagt habt: der, bei dem es gefunden wird, der soll mein Knecht sein; ihr aber geht frei aus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Und eilends liess ein jeder seinen Sack auf die Erde herab und machte ihn auf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Er aber suchte nach: beim Ältesten fing er an, und beim Jüngsten hörte er auf; und der Becher fand sich in Benjamins Sack.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider, luden die Säcke wieder auf die Esel und kehrten in die Stadt zurück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und Juda trat mit seinen Brüdern in das Haus Josephs, der noch da war, und sie warfen sich vor ihm zur Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Da sprach Joseph zu ihnen: Was ist das für eine Tat, die ihr begangen habt! Wusstet ihr nicht, dass ein Mann wie ich es gewiss erkunden würde?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda antwortete: Was sollen wir meinem Herrn sagen? wie sollen wir reden und womit uns rechtfertigen? Gott hat die Schuld deiner Knechte an den Tag gebracht. Siehe, wir sind meines Herrn Knechte, wir sowohl als der, bei dem sich der Becher gefunden hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Er aber sprach: Das sei ferne von mir, solches zu tun! Nur der, bei dem sich der Becher gefunden hat, soll mein Knecht sein; ihr aber mögt in Frieden hinauf zu eurem Vater ziehen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda zu ihm heran und sprach: Mit Verlaub, Herr, lass doch deinen Knecht ein Wort reden vor deinen Ohren, und dein Zorn entbrenne nicht über deinen Knecht; denn du bist wie der Pharao.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr hat seine Knechte gefragt: Habt ihr noch einen Vater oder einen Bruder?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da antworteten wir meinem Herrn: Wir haben noch unsern alten Vater und einen Knaben, der ihm im Alter geboren wurde; sein Bruder ist tot, und so ist er allein von seiner Mutter übriggeblieben, und der Vater hat ihn lieb. (a) 1Mo 42:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Da sprachst du zu deinen Knechten: Bringt ihn herab zu mir, dass ich ihn zu Gesicht bekomme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Wir aber antworteten meinem Herrn: Der Knabe kann seinen Vater nicht verlassen; wenn er seinen Vater verliesse, so würde dieser sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Da sprachst du zu deinen Knechten: Wenn euer jüngster Bruder nicht mit euch herabkommt, so dürft ihr mir nicht mehr unter die Augen treten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Als wir nun zu deinem Knechte, meinem Vater, hinaufkamen, taten wir ihm die Worte meines Herrn kund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Darnach sprach unser Vater: Zieht wieder hin und kauft uns ein wenig Speise.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Wir aber sprachen: Wir können nicht hinabziehen; nur wenn unser jüngster Bruder bei uns ist, ziehen wir hinab. Denn wir dürfen dem Manne nicht unter die Augen treten, wenn unser jüngster Bruder nicht bei uns ist. (a) 1Mo 43:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da sprach dein Knecht, mein Vater, zu uns: Ihr wisst ja selbst, dass mir mein Weib nur zwei Söhne geboren hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Der eine ist von mir gegangen, sodass ich mir sagen musste: \"Er ist gewiss zerrissen worden\", und ich habe ihn bis heute nicht wiedergesehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Nehmt ihr nun diesen auch von mir, und es stösst ihm ein Unfall zu, so bringt ihr meine grauen Haare mit Jammer ins Totenreich hinunter. (a) 1Mo 42:38');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Und nun, wenn ich zu deinem Knechte, meinem Vater, heimkäme und der Knabe wäre nicht bei uns, an dem er doch mit ganzer Seele hängt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'so stirbt er, wenn er sieht, dass der Knabe nicht mehr bei uns ist. So würden deine Knechte die grauen Haare deines Knechtes, unsres Vaters, mit Kummer ins Totenreich hinunterbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn dein Knecht ist für den Knaben Bürge geworden bei meinem Vater und hat gesprochen: \"Wenn ich ihn dir nicht wiederbringe, so will ich mein Leben lang die Schuld tragen vor meinem Vater.\" (a) 1Mo 43 9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Darum erlaube jetzt, dass dein Knecht an des Knaben Statt hier bleibe als Sklave meines Herrn; der Knabe aber möge mit seinen Brüdern hinaufziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie könnte ich zu meinem Vater hinaufziehen, wenn der Knabe nicht bei mir wäre? Ich möchte den Jammer nicht mitansehen, der über meinen Vater kommen würde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'DA konnte sich Joseph nicht mehr länger halten vor allen, die um ihn her standen, und er rief: Lasst jedermann von mir hinausgehen! So war niemand sonst bei Joseph, als er sich seinen Brüdern zu erkennen gab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Und er weinte laut, dass es die Ägypter hörten und man im Haus des Pharao davon vernahm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph; lebt mein Vater noch? Aber seine Brüder konnten ihm nicht antworten, so erschraken sie vor ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Dann sprach Joseph zu seinen Brüdern: Tretet doch zu mir heran! Und sie traten herzu. Da sprach er: Ich bin Joseph, euer Bruder, den ihr nach Ägypten verkauft habt. (a) 1Mo 37:28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Doch nun grämt euch nicht und lasst es euch nicht leid sein, dass ihr mich hierher verkauft habt; denn um (viele) am Leben zu erhalten, hat mich Gott vor euch her gesandt. (a) 1Mo 50:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Zwei Jahre ist ja nun schon die Hungersnot im Lande, und noch fünf Jahre lang wird kein Pflügen und Ernten sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Darum hat mich Gott vor euch her gesandt, um euch Nachkommenschaft zu sichern und von euch viele zu retten und am Leben zu erhalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'So habt nicht ihr mich hierher gesandt, sondern Gott; er hat mich dem Pharao zum Vater gesetzt und zum Herrn über sein ganzes Haus und zum Herrscher über das ganze Land Ägypten. (a) 1Mo 41:40');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Nun eilt und zieht hinauf zu meinem Vater und sagt ihm: Das lässt dir dein Sohn Joseph sagen: \"Gott hat mich zum Herrn über ganz Ägypten gemacht. Komm herab zu mir und säume nicht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du sollst im Lande Gosen wohnen und nahe bei mir sein, du und deine Kinder und deine Kindeskinder samt deinen Schafen und Rindern und allem, was dein ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ich will daselbst für dich sorgen - denn noch fünf Jahre dauert die Hungersnot -, dass du nicht in Armut gerätst, du und dein Haus samt allem, was dein ist.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ihr seht es ja mit eigenen Augen, und auch mein Bruder Benjamin sieht, dass ich selbst es bin, der mit euch redet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Erzählt denn meinem Vater von all meinen Ehren in Ägypten und von alledem, was ihr gesehen habt. Dann kommt eilends mit meinem Vater hierher.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und nun fiel er seinem Bruder Benjamin um den Hals und weinte; und auch Benjamin weinte an seinem Halse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Und er küsste alle seine Brüder und weinte, indem er sie umarmte. Darnach redeten seine Brüder mit ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Die Kunde davon kam auch in das Haus des Pharao; es hiess: Josephs Brüder sind gekommen. Das gefiel dem Pharao und seinen Dienern wohl.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Und der Pharao gab Joseph Weisung, zu seinen Brüdern zu sagen: Tut also: beladet eure Tiere und zieht heim ins Land Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Dann nehmt euren Vater und eure Familien und kommt zu mir; ich will euch das Beste geben, was das Land Ägypten bietet, dass ihr das Fett des Landes essen sollt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Auch liess er ihnen sagen: Tut also: nehmt euch aus Ägypten Wagen für eure Kinder und Frauen und bringt euren Vater hierher.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Und lasst euch euren Hausrat nicht reuen; denn das Beste, was das ganze Land Ägypten bietet, soll euer sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Die Söhne Israels taten so, und Joseph gab ihnen Wagen nach dem Befehl des Pharao; auch gab er ihnen Zehrung auf den Weg,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'und einem jeden schenkte er ein Feierkleid, dem Benjamin aber schenkte er dreihundert Lot Silber und fünf Feierkleider.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Ebenso sandte er seinem Vater zehn Esel, mit Gut aus Ägypten beladen, und zehn Eselinnen mit Korn, Brot und (andrer) Speise für seinen Vater auf den Weg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Damit entliess er seine Brüder, und sie zogen fort; und er sprach zu ihnen: Ereifert euch nicht unterwegs!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'So zogen sie aus Ägypten hinauf und kamen zu ihrem Vater Jakob ins Land Kanaan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Und sie erstatteten ihm Bericht und sprachen: Joseph ist noch am Leben; ja, er ist Herr über das ganze Land Ägypten. Aber sein Herz blieb kalt; denn er glaubte ihnen nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Da erzählten sie ihm alles, was Joseph zu ihnen geredet hatte. Und als er die Wagen sah, die Joseph gesandt hatte, um ihn hinzuführen, da lebte ihr Vater Jakob wieder auf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Und Israel sprach: Genug! mein Sohn Joseph lebt noch! Ich will hin und ihn sehen, ehe ich sterbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'UND Israel brach auf mit allem, was er hatte, und als er nach Beerseba kam, brachte er dem Gott seines Vaters Isaak Opfer dar. (a) 1Mo 26:23-25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Da redete Gott in einer nächtlichen Erscheinung mit Israel und sprach: Jakob! Jakob! Er antwortete: Hier bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Und er sprach: Ich bin Gott, der Gott deines Vaters. Fürchte dich nicht, nach Ägypten hinabzuziehen; denn ich will dich dort zu einem grossen Volke machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich selber ziehe mit dir hinab nach Ägypten, und ich werde dich auch wieder heraufführen, und Joseph soll dir die Augen zudrücken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da machte sich Jakob auf von Beerseba; und die Söhne Israels hoben ihren Vater Jakob, ihre Kinder und Frauen auf die Wagen, die der Pharao gesandt hatte, um ihn hinzuführen. (a) 1Mo 45:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und sie nahmen ihre Herden und ihre Habe, die sie im Lande Kanaan erworben hatten, und kamen so nach Ägypten, Jakob und sein ganzes Geschlecht mit ihm:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'seine Söhne und seine Enkel, seine Töchter und seine Enkelinnen und sein ganzes Geschlecht brachte er mit sich nach Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dies sind die Namen der Söhne Israels, die nach Ägypten kamen: Jakob und seine Söhne. Ruben, Jakobs Erstgeborner.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Die Söhne Rubens: Henoch, Pallu, Hezron und Charmi.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Die Söhne Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaaniterin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Die Söhne Levis: Gerson, Kahath und Merari.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Die Söhne Judas: Er, Onan, Sela, Perez und Serah. Aber Er und Onan starben im Lande Kanaan. Die Söhne des Perez waren Hezron und Hamul.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Die Söhne Issaschars: Thola, Puwa, Jasub und Simron.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Die Söhne Sebulons: Sered, Elon und Jahleel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Das sind die Söhne Leas, die sie dem Jakob in Mesopotamien gebar, samt seiner Tochter Dina. Die machen zusammen, Söhne und Töchter, 33 Seelen aus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Die Söhne Gads: Zephon, Haggi, Suni, Ezbon, Eri, Arodi und Areli.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Die Söhne Assers: Jimna, Jiswa, Jiswi und Beria, und ihre Schwester Serah. Die Söhne Berias: Heber und Malchiel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Das sind die Söhne der Silpa, die Laban seiner Tochter Lea gab; diese gebar sie dem Jakob, sechzehn Seelen. (a) 1Mo 29:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne Rahels, des Weibes Jakobs: Joseph und Benjamin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Dem Joseph wurden im Lande Ägypten Manasse und Ephraim geboren, die ihm Asnath gebar, die Tochter Potipheras, des Priesters von On. (a) 1Mo 41:50');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Die Söhne Benjamins: Bela, Becher, Asbel, Gera, Naeman, Ahiram, Supham, Hupham und Ard.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Das sind die Söhne Rahels, die sie dem Jakob gebar, zusammen vierzehn Seelen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Die Söhne Dans: Husim.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Die Söhne Naphthalis: Jahzeel, Guni, Jezer und Sillem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Das sind die Söhne der Bilha, die Laban seiner Tochter Rahel gab; diese gebar sie dem Jakob, zusammen sieben Seelen. (a) 1Mo 29:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle Seelen aus dem Geschlechte Jakobs, die nach Ägypten kamen, alle seine Nachkommen, nicht gerechnet die Frauen der Söhne Jakobs, waren zusammen 66 Seelen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und die Söhne Josephs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Alle Seelen des Hauses Jakobs, die nach Ägypten kamen, waren siebzig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Den Juda aber sandte er vor sich her zu Joseph, damit dieser vor seiner Ankunft nach Gosen Weisung gebe. Als sie nun ins Land Gosen kamen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'liess Joseph seinen Wagen anspannen und zog nach Gosen, seinem Vater Israel entgegen; und als er ihn sah, fiel er ihm um den Hals und weinte lange an seinem Halse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Dann sprach Israel zu Joseph: Jetzt will ich gerne sterben, nachdem ich dein Angesicht geschaut und gesehen habe, dass du noch am Leben bist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph aber sprach zu seinen Brüdern und zu seines Vaters Hause: Ich will hingehen und es dem Pharao melden und zu ihm sprechen: \"Meine Brüder und meines Vaters Haus, die im Lande Kanaan waren, sind zu mir gekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Die Männer sind Schafhirten - denn sie waren Viehzüchter -, und ihre Schafe und Rinder und alles, was sie besitzen, haben sie mitgebracht.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch nun der Pharao rufen lässt und fragt: \"Was ist euer Gewerbe?\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so sagt: \"Deine Knechte sind Viehzüchter gewesen von Jugend an bis jetzt, wir wie unsre Väter\", damit ihr im Lande Gosen wohnen dürft. - Alle Schafhirten sind nämlich den Ägyptern ein Greuel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'SO ging denn Joseph hinein und meldete es dem Pharao und sprach: Mein Vater und meine Brüder sind mit ihren Schafen und Rindern und ihrer ganzen Habe aus dem Lande Kanaan gekommen, und nun sind sie im Lande Gosen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Aus der Zahl seiner Brüder aber hatte er fünf mit sich genommen; die stellte er dem Pharao vor.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Da sprach der Pharao zu seinen Brüdern: Was ist euer Gewerbe? Sie antworteten dem Pharao: Deine Knechte sind Schafhirten, wir wie unsre Väter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Dann sagten sie zum Pharao: Wir sind gekommen, als Fremdlinge im Lande zu wohnen; denn deine Knechte haben keine Weide für ihre Schafe, so schwer ist die Hungersnot im Lande Kanaan. So lass doch nun deine Knechte im Lande Gosen bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sprach der Pharao zu Joseph: Dein Vater und deine Brüder sind also zu dir gekommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Das Land Ägypten steht dir offen. Lass deinen Vater und deine Brüder im besten Teil des Landes wohnen; sie mögen im Lande Gosen bleiben. Und wenn du weisst, dass tüchtige Leute unter ihnen sind, so setze sie zu Aufsehern über meine eignen Herden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph brachte auch seinen Vater Jakob hinein und stellte ihn dem Pharao vor, und Jakob entbot dem Pharao den Segensgruss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Und der Pharao fragte Jakob: Wie alt bist du?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob antwortete dem Pharao: Die ganze Zeit meiner Pilgerschaft ist 130 Jahre. Kurz und voll Leid war die Zeit meiner Lebensjahre, und sie reicht nicht an die Zeit der Lebensjahre, die meinen Vätern in den Tagen ihrer Pilgerschaft beschieden war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Dann nahm Jakob mit Segenswunsch Abschied vom Pharao und ging von ihm hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph aber verschaffte seinem Vater und seinen Brüdern Wohnsitze und gab ihnen eigenen Besitz im Lande Ägypten, im besten Teil des Landes, im Gebiet von Ramses, wie der Pharao geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Speise nach der Zahl der Kinder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'ES war aber im ganzen Lande kein Brot; denn die Hungersnot war sehr schwer, sodass das Land Ägypten und das Land Kanaan vor Hunger verschmachteten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'So brachte Joseph alles Geld zusammen, das sich im Lande Ägypten und im Lande Kanaan fand, für das Korn, das die Leute kauften. Und Joseph lieferte das Geld in das Haus des Pharao ab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Als nun im Lande Ägypten und im Lande Kanaan das Geld ausgegangen war, kamen alle Ägypter zu Joseph und sprachen: Verschaffe uns Brot! Warum lässest du uns vor deinen Augen sterben? Denn das Geld ist zu Ende.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sprach: Gebt euer Vieh her, so will ich euch Brot dafür geben, wenn das Geld zu Ende ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie dem Joseph ihr Vieh, und er gab ihnen Brot dafür, für die Pferde, die Schafherden, die Rinderherden und die Esel. So versorgte er sie in jenem Jahr mit Brot um den Preis all ihres Viehs.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Als dieses Jahr verflossen war, kamen sie im zweiten Jahre wieder und sprachen zu ihm: Wir können es unserm Herrn nicht verhehlen: das Geld ist zu Ende. Auch die Viehherden gehören unserm Herrn; so bleibt denn zur Verfügung unsers Herrn nichts mehr als unser Leib und unser Feld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollen wir vor deinen Augen zugrunde gehen, wir und unser Feld? Kaufe uns und unser Feld um Brot, so wollen wir samt unserm Felde dem Pharao dienstbar werden. Gib uns Saatgut, dass wir am Leben bleiben und nicht sterben und das Feld nicht veröde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'So kaufte Joseph für den Pharao alles Ackerland in Ägypten auf; denn die Ägypter verkauften ein jeder seinen Acker, weil die Hungersnot sie hart drückte, und so ward das Land Eigentum des Pharao.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Das Volk aber machte er ihm dienstbar von einem Ende Ägyptens bis zum andern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur das Ackerland der Priester kaufte er nicht; denn die Priester hatten vom Pharao ein festes Einkommen, und sie nährten sich von diesem Einkommen, das der Pharao ihnen gab; darum brauchten sie ihr Ackerland nicht zu verkaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Und Joseph sprach zum Volke: Damit habe ich euch und euer Ackerland heute für den Pharao gekauft; da habt ihr Saatgut, nun besät das Feld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Aber vom Ertrage müsst ihr dem Pharao den Fünften geben; die andern vier Teile sollen euer sein, das Feld zu besäen und damit ihr zu essen habt samt euren Hausgenossen und euren Kindern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Sie sprachen: Du hast uns das Leben erhalten; wenn wir nur Gnade finden vor unserm Herrn, so wollen wir gerne dem Pharao dienstbar sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'So machte Joseph dies zum Gesetz bis auf den heutigen Tag für das Ackerland der Ägypter, dass sie dem Pharao den Fünften geben müssen. Nur das Ackerland der Priester wurde nicht Eigentum des Pharao.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'ALSO blieb Israel im Lande Ägypten, im Lande Gosen; und sie setzten sich darin fest und mehrten sich und wurden sehr zahlreich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte noch siebzehn Jahre im Lande Ägypten, sodass die Zahl der Lebensjahre Jakobs 147 betrug.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Als nun die Zeit kam, dass Israel sterben sollte, liess er seinen Sohn Joseph rufen und sprach zu ihm: Willst du mir einen Gefallen tun, so lege deine Hand unter meine Hüfte und erweise mir die Liebe und Treue, dass du mich nicht in Ägypten begräbst;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sondern wenn ich mich nun zu meinen Vätern lege, so bringe mich aus Ägypten hinweg und begrabe mich in ihrer Grabstätte. Er sprach: Ich will tun, wie du gesagt hast. (a) 1Mo 50:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Er aber sprach: So schwöre mir! Und er schwur ihm. Da verneigte sich Israel zu Häupten des Bettes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Darnach begab es sich, dass dem Joseph berichtet ward: Siehe, dein Vater ist krank. Da nahm er seine beiden Söhne Manasse und Ephraim mit sich und kam zu Jakob.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Und man meldete Jakob: Siehe, dein Sohn Joseph kommt zu dir. Da raffte sich Israel zusammen und setzte sich im Bette auf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: Der allmächtige Gott erschien mir zu Lus im Lande Kanaan, segnete mich (a) 1Mo 35:6 11 12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'und sprach zu mir: \"Siehe, ich will dich fruchtbar machen und dich mehren, will dich zu einer Gemeinde von Völkern machen und deinem Geschlechte dieses Land zum ewigen Besitze geben.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Und nun sollen deine beiden Söhne, die dir in Ägypten geboren wurden, ehe ich zu dir nach Ägypten kam, die meinen sein; wie Ruben und Simeon sollen Manasse und Ephraim mir gelten. (a) 1Mo 41:50-52');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Die Kinder aber, die du nach ihnen gezeugt hast, sollen dein sein; nach dem Namen ihrer Brüder sollen sie benannt sein auf ihrem Erbteil.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Als ich aus Mesopotamien kam, starb mir Rahel im Lande Kanaan auf dem Wege, als es nur noch ein Stück weit bis Ephrath war, und ich begrub sie daselbst am Wege nach Ephrath - das ist Bethlehem. (a) 1Mo 35:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Als nun Israel die Söhne Josephs sah, sprach er: Wer sind diese?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph antwortete seinem Vater: Es sind meine Söhne, die Gott mir hier gegeben hat. Da sprach er: Bringe sie her zu mir, dass ich sie segne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Israels Augen aber waren vor Alter schwach geworden, sodass er nicht mehr sehen konnte. Und er führte sie nahe zu ihm hin; er aber küsste und umarmte sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Da sprach Israel zu Joseph: Ich hätte nicht gedacht, dass ich dein Angesicht je wiedersehen würde; und nun hat Gott mich sogar deine Kinder schauen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Dann zog sie Joseph von seinen Knieen zurück und verneigte sich mit dem Angesicht zur Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Darnach nahm Joseph die beiden, den Ephraim an seiner rechten Hand zur Linken Israels und den Manasse an seiner linken Hand zur Rechten Israels, und führte sie nahe zu ihm hin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Aber Israel streckte seine Rechte aus und legte sie auf Ephraims, des Jüngern, Haupt und seine Linke auf das Haupt Manasses, indem er die Arme kreuzte; Manasse war nämlich der Erstgeborne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Und er segnete Joseph und sprach: Der Gott, vor dem meine Väter Abraham und Isaak gewandelt, / der Gott, der mein Hirte gewesen mein Leben lang, bis auf diesen Tag, /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich aus aller Not erlöst hat: / er segne diese Knaben, dass in ihnen mein Name fortlebe / und der Name meiner Väter Abraham und Isaak, / dass sie wachsen und zahlreich werden auf der Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Als aber Joseph sah, dass sein Vater die rechte Hand auf Ephraims Haupt legte, missfiel es ihm, und er fasste seines Vaters Hand, um sie vom Haupte Ephraims auf Manasses Haupt zu legen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'und Joseph sprach zu seinem Vater: Nicht also, mein Vater! dieser ist der Erstgeborne, lege deine Rechte auf sein Haupt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Aber sein Vater weigerte sich und sprach: Ich weiss, mein Sohn, ich weiss wohl. Auch dieser wird zu einem Volke werden, und auch er wird gross sein; aber sein jüngerer Bruder wird grösser sein als er, und sein Geschlecht wird eine Menge von Völkern werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'So segnete er sie an jenem Tage und sprach: Mit eurem Namen wird man in Israel Segen wünschen und sprechen: Gott mache dich wie Ephraim und wie Manasse! und gab damit Ephraim den Vorrang vor Manasse. (a) 1Mo 12:2 3; 18:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Dann sprach Israel zu Joseph: Siehe, ich sterbe nun; Gott aber wird mit euch sein und wird euch wieder in das Land eurer Väter bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Und ich gebe dir als Vorzug vor deinen Brüdern einen Bergrücken, den ich den Amoritern abgenommen habe mit meinem Schwert und Bogen. (1) d.i. Sichem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'UND Jakob berief seine Söhne und sprach: Versammelt euch, dass ich euch verkünde, was euch am Ende der Tage begegnen wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommet zusammen, ihr Söhne Jakobs, / und höret auf Israel, euren Vater! /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, mein Erstgeborner bist du, / meine Kraft, der Erstling meiner Stärke; / überragend an Hoheit, überragend an Macht, /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'walltest du über wie Wasser, sollst der Erste nicht sein. / Denn du bestiegst deines Vaters Lager, / entweihtest damals das Bette, das du bestiegen. / (a) 1Mo 35:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon und Levi sind Brüder, / Werkzeuge des Frevels sind ihre Waffen. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Ihrem Rat bleibe fern meine Seele, / mit ihrer Versammlung eine sich nicht mein Herz; / denn im Zorne töten sie Männer, / und im Mutwillen verstümmeln sie Stiere. / (a) 1Mo 34:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Fluch über ihren Zorn, dass er so heftig, / und über ihren Grimm, dass er so grausam ist! / Ich will sie zerteilen in Jakob, / will sie zerstreuen in Israel. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, dich preisen deine Brüder! / Deine Hand packt die Feinde im Nacken, / vor dir neigen sich die Söhne deines Vaters. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Ein junger Löwe ist Juda; / vom Raube, mein Sohn, wardst du gross. / Er hat sich gekauert, gelagert wie ein Leu, / wie eine Löwin - wer will ihn aufstören? /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nie weicht das Szepter von Juda, / noch der Führerstab von seinen Füssen, / bis dass der Herrscher kommt, / dem die Völker gehorchen. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er bindet seinen Esel an den Weinstock / und an die Rebe das Füllen seiner Eselin, / er wäscht sein Gewand in Wein / und in Traubenblut seinen Mantel, /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'seine Augen funkeln von Wein, / und seine Zähne sind weiss von Milch. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wohnt am Ufer des Meeres; / er liegt am Gestade der Schiffe / und lehnt seinen Rücken an Sidon. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issaschar ist ein knochiger Esel, / der zwischen den Viehhürden lagert. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Und da er sah, dass die Ruhe so schön sei / und das Land so lieblich, / beugte er seinen Rücken zum Tragen / und ward ein fronender Knecht. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan schafft Recht seinem Volke, / wie nur irgendein Stamm in Israel. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan sei eine Schlange am Wege, / eine Otter auf dem Pfade, / die das Ross in die Fersen beisst, / dass sein Reiter rücklings stürzt. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Deiner Hilfe harre ich, Herr! /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad wird von Drängern bedrängt; / er aber drängt ihnen nach. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Assers Brot ist fett; / ja, Königsleckerbissen spendet er. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali ist eine flüchtige Hindin; / von ihm kommen liebliche Reden. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ein junger Fruchtbaum ist Joseph, / ein junger Fruchtbaum am Quell; / (seine) Schosse ranken über die Mauer. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Es reizten ihn und schossen, / es befeindeten ihn Pfeilschützen; /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'doch fest blieb sein Bogen / und gelenk die Kraft seiner Hände / durch die Hilfe des Starken Jakobs, / durch den Namen des Hirten Israels, /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'durch deines Vaters Gott, der dir helfe, / durch den allmächtigen Gott, der dich segne / mit Segensfülle vom Himmel droben, / mit Segensfülle aus der Flut, die drunten lagert, / mit Segensfülle aus Brüsten und Mutterschoss. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen deines Vaters sind reicher / als die Segensfülle der ewigen Berge, / als die Lust der uralten Höhen. / Das alles komme auf das Haupt Josephs, / auf den Scheitel des Geweihten unter seinen Brüdern! /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein reissender Wolf; / am Morgen verzehrt er Raub, / und am Abend verteilt er Beute.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Das sind die zwölf Stämme Israels insgesamt, und das ist\'s, was ihr Vater zu ihnen geredet hat. UND er segnete sie; einen jeden segnete er mit einem besonderen Segen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gab ihnen Weisung und sprach zu ihnen: Wenn ich nun versammelt werde zu meinen Stammesgenossen, so begrabet mich bei meinen Vätern in der Höhle auf dem Grundstück des Hethiters Ephron, (a) 1Mo 23:7-18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in der Höhle auf dem Grundstück Machpela, gegenüber Mamre, im Lande Kanaan, dem Grundstück, das Abraham von dem Hethiter Ephron als Grabstätte zu eigen erworben hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dort haben sie Abraham und sein Weib Sara begraben, dort haben sie Isaak und sein Weib Rebekka begraben, und dort habe ich Lea begraben, (a) 1Mo 23:19; 25:9; 35:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'auf dem Grundstück mit der Höhle darauf, das den Hethitern abgekauft wurde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Als nun Jakob seinen Söhnen alle diese Weisungen gegeben hatte, zog er seine Füsse auf das Bett zurück, verschied und ward versammelt zu seinen Stammesgenossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da warf sich Joseph über seinen Vater und weinte über ihm und küsste ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Dann befahl Joseph seinen Dienern, den Ärzten, seinen Vater einzubalsamieren; und die Ärzte balsamierten Israel ein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Darüber vergingen volle vierzig Tage; denn so lange währt das Einbalsamieren. Und die Ägypter beweinten ihn siebzig Tage lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Als nun die Trauerzeit vorbei war, sprach Joseph zum Hof des Pharao: Wollt ihr mir einen Gefallen tun, so redet für mich vor dem Pharao und sagt zu ihm:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat einen Eid von mir genommen und gesagt: \"Wenn ich nun sterbe, so begrabe mich in meiner Gruft, die ich mir im Lande Kanaan gegraben habe.\" So will ich denn hinaufziehen und meinen Vater begraben und dann zurückkommen. (a) 1Mo 47:29 30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Der Pharao sprach: So ziehe hinauf und begrabe deinen Vater, wie er dich hat schwören lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Da zog Joseph hinauf, seinen Vater zu begraben, und es zogen mit ihm alle Diener des Pharao, die Ältesten seines Hauses und alle Ältesten des Landes Ägypten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'dazu das ganze Haus Josephs, seine Brüder und seines Vaters Haus; nur ihre kleinen Kinder und ihre Rinder und Schafe liessen sie im Lande Gosen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Auch Wagen und Reiter zogen mit ihm hinauf, und es war ein sehr grosser Heerzug.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Als sie nun nach Goren-Atad kamen, das jenseits des Jordan liegt, hielten sie daselbst eine gar grosse und feierliche Totenklage, und er veranstaltete eine Trauerfeier für seinen Vater, sieben Tage lang. (1) d.i. die Dornentenne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Und als die Leute im Lande, die Kanaaniter, die Trauerfeier in Goren-Atad sahen, sprachen sie: Da halten die Ägypter eine grosse Trauerfeier. Daher nennt man den Ort Abel-Mizraim; das liegt jenseits des Jordan. (1) d.i. Trauer der Ägypter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Und seine Söhne taten mit ihm so, wie er ihnen befohlen hatte:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'sie brachten ihn in das Land Kanaan und begruben ihn gegenüber Mamre in der Höhle auf dem Grundstück Machpela, das Abraham von dem Hethiter Ephron als Grabstätte zu eigen erworben hatte. (a) 1Mo 23:7-18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Nachdem so Joseph seinen Vater begraben hatte, kehrte er nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, seinen Vater zu begraben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'ALS nun die Brüder Josephs sahen, dass ihr Vater gestorben war, sprachen sie: Wie? wenn nun Joseph feindselig gegen uns auftritt und uns all das Böse vergilt, das wir ihm angetan haben?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Darum liessen sie dem Joseph sagen: Dein Vater hat vor seinem Tod befohlen:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\"So sollt ihr zu Joseph sagen: Ach, vergib doch deinen Brüdern ihre Missetat und Sünde, dass sie so übel an dir gehandelt haben.\" So vergib uns nun unsre Missetat, da wir (doch auch) dem Gotte deines Vaters dienen. Joseph aber weinte, als sie ihm das sagen liessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Dann gingen seine Brüder selbst hin, fielen vor ihm nieder und sprachen: Da nimm uns hin, als deine Knechte!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph sprach zu ihnen: Fürchtet euch nicht! Bin ich denn an Gottes Statt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr zwar gedachtet mir Böses zu tun, aber Gott hat es zum Guten gewendet, dass er täte, was jetzt am Tage ist: ein grosses Volk am Leben zu erhalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'So fürchtet euch nun nicht! Ich will für euch und eure Kindlein sorgen. Und er tröstete sie und redete ihnen freundlich zu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'So blieb Joseph in Ägypten, er und seines Vaters Haus, und er lebte 110 Jahre.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Joseph sah von Ephraim Nachkommen bis ins dritte Geschlecht; auch wurden die Söhne Machirs, des Sohnes Manasses, von Joseph an Kindesstatt angenommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Dann sprach Joseph zu seinen Brüdern: Ich sterbe nun; Gott aber wird sich euer annehmen und euch aus diesem Lande hinaufführen in das Land, das er Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Und Joseph nahm einen Eid von den Söhnen Israels und sprach: Wenn sich Gott euer annehmen wird, so führet meine Gebeine von hier mit hinauf. (a) 2Mo 13:19; Jos 24:32');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Darnach starb Joseph, 110 Jahre alt; und man balsamierte ihn ein und legte ihn in Ägypten in einen Sarg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'DIES sind die Namen der Söhne Israels, die nach Ägypten kamen - mit Jakob waren sie gekommen, ein jeder mit seiner Familie -: (a) 1Mo 46:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Sebulon und Benjamin,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphthali, Gad und Asser.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Und alle zusammen, die von Jakob abstammten, waren siebzig Seelen; Joseph aber war schon in Ägypten. (a) 1Mo 46:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Und Joseph starb und alle seine Brüder und jenes ganze Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Die Israeliten aber waren fruchtbar und nahmen überhand, mehrten sich und wurden über alle Massen zahlreich, sodass das Land von ihnen voll ward. (a) 5Mo 26:5; Ps 105:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da erstand ein neuer König über Ägypten, der nichts von Joseph wusste.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Der sprach zu seinem Volke: Seht, das Volk der Israeliten ist uns zu zahlreich und zu stark.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, wir wollen klug gegen sie vorgehen, dass ihrer nicht noch mehr werden und dass sie nicht, wenn ein Krieg über uns kommt, sich auch noch zu unsern Feinden schlagen und wider uns kämpfen und aus dem Lande wegziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'So setzte man denn Fronvögte über sie, um sie mit Fronarbeiten zu bedrücken, und sie mussten dem Pharao die Vorratsstädte Pithom und Ramses bauen. (a) 1Mo 47:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber je mehr sie das Volk bedrückten, um so mehr nahm es zu und breitete sich aus, sodass ihnen vor den Israeliten graute.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Da zwangen die Ägypter die Israeliten zum Sklavendienst');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und machten ihnen das Leben sauer mit harter Arbeit in Lehm und Ziegeln und mit allerlei Arbeit auf dem Felde, lauter Arbeiten, zu denen man sie mit Gewalt anhielt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der König von Ägypten befahl den Hebammen der Hebräerinnen, von denen die eine Siphra, die andre Pua hiess:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Wenn ihr den Hebräerinnen bei der Geburt helft, so achtet auf das Kind: ist es ein Knabe, so tötet ihn; ist es aber ein Mädchen, so mag es am Leben bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Hebammen waren gottesfürchtig und taten nicht, wie der König von Ägypten ihnen geboten hatte, sondern liessen die Knäblein am Leben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da rief der König von Ägypten die Hebammen und sprach zu ihnen: Warum habt ihr das getan und die Knäblein am Leben gelassen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Hebammen antworteten dem Pharao: Die hebräischen Frauen sind nicht wie die ägyptischen, sondern naturwüchsiger; ehe die Hebamme zu ihnen kommt, haben sie schon geboren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Gott aber liess es den Hebammen gut ergehen, und das Volk mehrte sich und wurde sehr zahlreich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und weil die Hebammen gottesfürchtig waren, schenkte er ihnen Kindersegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da gebot der Pharao allen seinen Leuten: Alle Knaben, die den Hebräern geboren werden, werft in den Nil, alle Mädchen aber lasst am Leben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'UND ein Mann vom Hause Levi ging hin und heiratete eine Levitin. (a) 2Mo 6:20; 4Mo 26:59');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib ward schwanger und gebar einen Sohn. Als sie sah, dass er schön war, verbarg sie ihn drei Monate lang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Und da sie ihn nicht länger verbergen konnte, nahm sie ein Kästlein von Rohr, verklebte es mit Asphalt und Pech und legte das Kind darein; dann setzte sie es ins Schilf am Ufer des Nil.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Seine Schwester aber stellte sich in einiger Entfernung auf, um zu erfahren, wie es ihm ergehen würde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da kam die Tochter des Pharao an den Nil herunter, um zu baden. Während nun ihre Dienerinnen am Ufer des Nil hin und her gingen, sah sie das Kästlein mitten im Schilf, und sie sandte ihre Magd hin und liess es holen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Und als sie es auftat und das Kind sah - es war ein weinendes Knäblein -, da hatte sie Mitleid mit ihm, und sie sprach: Das ist eins von den Kindlein der Hebräer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Nun sprach seine Schwester zu der Tochter des Pharao: Soll ich hingehen und dir eine hebräische Amme rufen, dass sie dir das Kind stille?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Die Tochter des Pharao antwortete ihr: Ja, gehe. Und die Jungfrau ging hin und rief die Mutter des Kindes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Da sprach die Tochter des Pharao zu ihr: Nimm diesen Knaben mit dir und stille ihn; ich will dir deinen Lohn geben. Das Weib nahm den Knaben und stillte ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Und als der Knabe gross geworden war, brachte sie ihn der Tochter des Pharao. Die nahm ihn als Sohn an und nannte ihn Mose, indem sie sprach: Ich habe ihn ja aus dem Wasser gezogen. (1) vgl. Anm. zu 1Mo 29:32.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'ZU jener Zeit nun, als Mose gross geworden war, ging er einst hinaus zu seinen Brüdern und sah ihren Fronarbeiten zu. Da sah er, wie ein Ägypter einen Hebräer, einen seiner Brüder, schlug.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und er schaute sich nach allen Seiten um, und als er sah, dass kein Mensch zugegen war, erschlug er den Ägypter und verscharrte ihn im Sande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Als er am nächsten Tage wieder hinausging, zankten gerade zwei Hebräer miteinander. Da sprach er zu dem, der im Unrecht war: Warum schlägst du deinen Nächsten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Der aber erwiderte: Wer hat dich zum Obersten und Richter über uns gesetzt? Gedenkst du mich auch zu töten, wie du den Ägypter getötet hast? Da fürchtete sich Mose; denn er dachte: Wahrhaftig, die Sache ist ruchbar geworden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Auch der Pharao hörte von der Sache, und er trachtete danach, Mose zu töten. Aber Mose floh vor dem Pharao und nahm Aufenthalt im Lande Midian; da setzte er sich an einen Brunnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Nun hatte der Priester der Midianiter sieben Töchter; die kamen, schöpften Wasser und füllten die Tränkrinnen, um die Schafe ihres Vaters zu tränken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Da kamen die Hirten und jagten sie weg. Aber Mose erhob sich, half ihnen und tränkte ihre Schafe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Als sie nun zu ihrem Vater Reguel heimkamen, sprach er: Warum kommt ihr heute so bald heim?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie antworteten: Ein Ägypter hat uns gegen die Hirten geholfen; ja, er hat uns sogar Wasser geschöpft und die Schafe getränkt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sprach er zu seinen Töchtern: Wo ist er denn? Warum habt ihr den Mann dort gelassen? Ruft ihn her, dass er mit uns esse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose willigte ein, bei dem Manne zu bleiben, und dieser gab dem Mose seine Tochter Zippora.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Die gebar einen Sohn, und er nannte ihn Gersom, denn er sprach: Ich bin Gast geworden in fremdem Lande. (1) vgl. Anm. zu 1Mo 29:32.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Und es geschah im Verlaufe jener langen Zeit, dass der König von Ägypten starb. Die Israeliten aber seufzten ob der Sklaverei und schrieen, und ihr Wehgeschrei ob der Sklaverei drang empor zu Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott hörte ihr Wehklagen und gedachte seines Bundes mit Abraham, Isaak und Jakob. (a) 1Mo 15:18; 17:2; 26:3; 28:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah auf die Israeliten und gab sich ihnen kund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'MOSE aber hütete die Schafe seines Schwiegervaters Jethro, des Priesters der Midianiter. Einst trieb er die Schafe über die Steppe hinaus und kam an den Gottesberg, den Horeb.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Und der Engel des Herrn erschien ihm in einer Feuerflamme, die aus dem Dornbusch hervorschlug. Und als er hinsah, siehe, da brannte der Busch im Feuer, aber der Busch ward nicht verzehrt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da dachte Mose: Ich will doch hinübergehen und diese wunderbare Erscheinung ansehen, warum der Dornbusch nicht verbrennt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Und der Herr sah, dass er herüberkam, um nachzusehen. Und Gott rief ihm aus dem Dornbusch zu: Mose! Mose! Er antwortete: Hier bin ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Da sprach er: Tritt nicht heran! Ziehe die Schuhe von den Füssen; denn die Stätte, darauf du stehst, ist heiliges Land. (a) Jos 5:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Dann sprach er: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Da verhüllte Mose sein Antlitz; denn er fürchtete sich, Gott anzuschauen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Und der Herr sprach: Ich habe das Elend meines Volkes in Ägypten wohl gesehen, und ihr Schreien über ihre Treiber habe ich gehört; ja ich kenne ihre Leiden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Darum bin ich herniedergestiegen, sie aus der Gewalt der Ägypter zu erretten und sie aus jenem Lande hinauszuführen in ein schönes, weites Land, in ein Land, wo Milch und Honig fliesst, in das Gebiet der Kanaaniter, Hethiter, Amoriter, Pheresiter, Hewiter und Jebusiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nun ist das Schreien der Israeliten zu mir gedrungen, ich habe auch gesehen, wie hart die Ägypter sie bedrücken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Wohlan, so will ich dich denn zum Pharao senden, dass du mein Volk, die Israeliten, aus Ägypten führest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose aber sprach zu Gott: Wer bin ich, dass ich zum Pharao gehen und die Israeliten aus Ägypten führen sollte?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Er sprach: Ich werde mit dir sein; und dies sei dir das Zeichen, dass ich es bin, der dich gesandt hat: wenn du das Volk aus Ägypten führst, werdet ihr an diesem Berge Gott verehren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Da sprach Mose zu Gott: Siehe, wenn ich nun zu den Israeliten komme und ihnen sage: \"Der Gott eurer Väter hat mich zu euch gesandt\", und wenn sie mich fragen: \"Welches ist sein Name?\" - was soll ich ihnen dann antworten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Gott sprach zu Mose: \"Ich bin, der ich bin.\" Und er fuhr fort: So sollst du zu den Israeliten sagen: Der \"Ich bin\" hat mich zu euch gesandt. (1) der biblische Erzähler hörte in dem Gottesnamen [Jahwe] einen Anklang an das hebr. Zeitwort \"sein\". Vgl. auch Anm. zu 1Mo 4:26. (a) 2Mo 6:2; Jes 42:8; Off 1:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und Gott sprach weiter zu Mose: So sollst du zu den Israeliten sagen: \"Jahwe, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, hat mich zu euch gesandt.\" Das ist mein Name ewiglich, und so will ich angerufen sein von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Gehe hin und versammle die Ältesten Israels und sprich zu ihnen: Jahwe, der Gott eurer Väter, der Gott Abrahams, Isaaks und Jakobs, ist mir erschienen und hat gesagt: \"Ich habe achtgehabt auf euch und auf das, was euch in Ägypten widerfahren ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Da beschloss ich, euch aus dem Elend in Ägypten herauszuführen in das Land der Kanaaniter, Hethiter, Amoriter, Pheresiter, Hewiter und Jebusiter, in ein Land, wo Milch und Honig fliesst.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und sie werden auf dich hören; du aber sollst mit den Ältesten Israels zum König von Ägypten hineingehen, und ihr sollt zu ihm sagen: \"Der Herr, der Gott der Hebräer, ist uns begegnet. So lass uns nun drei Tagereisen weit in die Wüste ziehen, dass wir dem Herrn, unserm Gotte, opfern.\" (a) 2Mo 5:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber ich weiss, dass euch der König von Ägypten nicht wird ziehen lassen, es sei denn, er werde gezwungen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Darum werde ich meine Hand ausrecken und Ägypten mit all meinen Wundertaten schlagen, die ich darin tun werde; darnach wird er euch ziehen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und ich werde diesem Volke bei den Ägyptern Gunst verschaffen, sodass ihr, wenn ihr auszieht, nicht mit leeren Händen ausziehen müsst;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'sondern jedes Weib soll sich von ihrer Nachbarin und Hausgenossin silberne und goldene Schmucksachen und Kleider erbitten, die sollt ihr euren Söhnen und Töchtern anlegen und so die Ägypter berauben. (a) 2Mo 12:35');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Da entgegnete Mose: Wenn sie mir aber nicht glauben und nicht auf mich hören wollen, sondern sagen: \"Der Herr ist dir nicht erschienen\" -?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Der Herr sprach zu ihm: Was hast du da in der Hand? Er antwortete: Einen Stab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da sprach er: Wirf ihn auf die Erde! Und er warf ihn auf die Erde; da ward er zu einer Schlange, und Mose floh vor ihr. (a) 2Mo 7:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Aber der Herr sprach zu Mose: Strecke deine Hand aus und fasse sie beim Schwanz! Und er streckte seine Hand aus und ergriff sie; da ward sie in seiner Hand wieder zum Stabe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '\"Damit sie glauben, dass dir der Herr erschienen ist, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Und der Herr sprach weiter zu ihm: Stecke doch deine Hand in den Busen! Und er steckte die Hand in den Busen; und als er sie wieder hervorzog, siehe, da war sie vom Aussatz weiss wie Schnee.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Und er sprach: Stecke deine Hand nochmals in den Busen! Und er steckte die Hand nochmals in den Busen; und als er sie hervorzog, siehe, da war sie wieder wie sein (anderes) Fleisch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '\"Und wenn sie dir nicht glauben und auf das erste Zeichen hin nicht hören wollen, so werden sie doch auf das zweite Zeichen hin glauben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Wenn sie aber auch auf diese beiden Zeichen hin nicht glauben und nicht auf dich hören wollen, so nimm Wasser aus dem Nil und giesse es auf das Trockene; dann wird das Wasser, das du aus dem Nil genommen hast, auf dem Trockenen zu Blut werden.\" (a) 2Mo 7:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mose aber sprach zu dem Herrn: Ach Herr, ich bin kein beredter Mann; ich war es von jeher nicht und bin es auch jetzt nicht, seitdem du mit deinem Knechte redest, sondern schwerfällig ist mein Mund und meine Zunge. (a) Jer 1:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Da sprach der Herr zu ihm: Wer hat dem Menschen den Mund geschaffen? oder wer macht ihn stumm oder taub oder sehend oder blind? Bin nicht ich es, der Herr?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'So gehe nun hin: ich will mit deinem Munde sein und dich lehren, was du sagen sollst. (a) Mt 10:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Er aber sprach: Ach Herr, sende doch, wen du senden willst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da ward der Herr zornig über Mose und sprach: Ist denn nicht dein Bruder Aaron da, der Levit? Ich weiss, dass er beredt ist. Sieh, schon ist er im Begriffe, dir entgegenzugehen, und wenn er dich sieht, wird er sich von Herzen freuen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Rede also mit ihm und lege ihm die Worte in den Mund; ich aber will mit deinem und mit seinem Munde sein und euch lehren, was ihr tun sollt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Er soll für dich zum Volke reden und dein Mund sein, und du sollst ihm an Gottes Statt sein. (a) 2Mo 7:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und diesen Stab da nimm zur Hand; damit sollst du die Zeichen tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Da ging Mose hin, kehrte zu seinem Schwiegervater Jethro zurück und sprach zu ihm: Ich möchte gerne zu meinen Brüdern nach Ägypten zurückkehren, um zu sehen, ob sie noch am Leben sind. Jethro sprach zu ihm: Zieh hin in Frieden. (a) 2Mo 3:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Und der Herr sprach zu Mose in Midian: Geh, kehre nach Ägypten zurück; denn sie sind alle tot, die dir nach dem Leben stellten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Da nahm Mose sein Weib und seine Kinder und setzte sie auf den Esel und kehrte nach Ägypten zurück; auch nahm Mose den Stab Gottes zur Hand. (a) 2Mo 18:2-4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Darauf sprach der Herr zu Mose: Wenn du wieder nach Ägypten kommst, so siehe zu: alle die Wunder, die ich in deine Hand gegeben habe, die sollst du vor dem Pharao tun. Ich aber werde sein Herz verstocken, dass er das Volk nicht wird ziehen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Dann sollst du zum Pharao sagen: So spricht der Herr: \"Israel ist mein Sohn, mein Erstgeborner, (a) Jer 31:9; Hos 11:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'und ich befehle dir: Lass meinen Sohn ziehen, dass er mir diene! Weigerst du dich aber, ihn ziehen zu lassen, siehe, so werde ich deinen Sohn, deinen Erstgebornen, töten.\" (a) 2Mo 12:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Unterwegs aber, da wo er übernachtete, trat ihm der Herr entgegen und wollte ihn töten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zippora einen scharfen Stein, schnitt ihrem Sohne die Vorhaut ab und berührte damit Moses Lenden und sprach: Ein Blutbräutigam bist du mir. (a) Jos 5:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da liess er von ihm ab. Damals sagte sie \"Blutbräutigam\" um der Beschneidung willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und der Herr sprach zu Aaron: Gehe Mose entgegen in die Wüste. Und er ging hin und begegnete ihm am Berge Gottes und küsste ihn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose tat dem Aaron alle Worte kund, die der Herr ihm aufgetragen, und alle Zeichen, die er ihm befohlen hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Da gingen Mose und Aaron hin und versammelten alle Ältesten der Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron verkündete alle Worte, die der Herr zu Mose geredet hatte; und dieser tat die Zeichen vor den Augen des Volkes,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'und das Volk glaubte. Und als sie hörten, dass der Herr sich Israels angenommen und dass er ihr Elend angesehen habe, verneigten sie sich und warfen sich nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'DARNACH gingen Mose und Aaron hinein und sprachen zum Pharao: So spricht der Herr, der Gott Israels: Lass mein Volk ziehen, dass es mir in der Wüste ein Fest feire.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Der Pharao antwortete: Wer ist der Herr, dass ich ihm gehorchen und Israel ziehen lassen müsste? Ich weiss nichts von dem Herrn, und ich werde Israel auch nicht ziehen lassen. (a) Da 3:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Da sprachen sie: Der Gott der Hebräer ist uns begegnet. Lass uns doch drei Tagereisen weit in die Wüste ziehen und dem Herrn, unserm Gotte, opfern, dass er nicht mit der Pest oder mit dem Schwerte über uns komme. (a) 2Mo 3:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Der König von Ägypten aber sprach zu ihnen: Warum, Mose und Aaron, wollt ihr das Volk von seiner Arbeit abziehen? Fort an eure Fron!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Dann sprach der Pharao: Wahrlich, des Gesindels ist schon genug, und ihr wollt sie noch von ihrem Frondienst feiern heissen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Darum befahl der Pharao am selben Tage den Fronvögten und Aufsehern des Volkes:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ihr sollt den Leuten zum Ziegelmachen kein Stroh mehr geben wie bisher. Sie sollen selbst hingehen und sich Stroh zusammenlesen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Doch die bestimmte Zahl der Ziegel, die sie bisher machten, sollt ihr ihnen gleichwohl auflegen; ihr dürft nichts davon ablassen, denn sie sind faul. Darum schreien sie: \"Wir wollen hingehen und unserm Gotte opfern.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Die Arbeit soll schwer auf den Leuten lasten, dass sie damit zu schaffen haben und sich nicht an trügerische Worte kehren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gingen die Fronvögte und Aufseher des Volkes hinaus und verkündeten dem Volke: Der Pharao befiehlt, dass man euch kein Stroh mehr gebe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Geht selber hin und holt euch Stroh, wo ihr es findet; von der Arbeit aber wird euch nichts erlassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da zerstreute sich das Volk im ganzen Lande Ägypten, um Stroh zu Häckerling zu sammeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Und die Fronvögte bedrückten sie und sprachen: Ihr müsst dieselbe Arbeit leisten, an jedem Tage das bestimmte Mass, wie vorher, als das Stroh da war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die Aufseher der Israeliten, die von den Fronvögten des Pharao über sie gesetzt waren, wurden geschlagen, und man sprach zu ihnen: Warum habt ihr heute euer bestimmtes Mass Ziegel nicht voll abgeliefert wie bisher?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gingen die Aufseher der Israeliten hinein und klagten vor dem Pharao: Warum verfährst du so mit deinen Knechten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Man gibt deinen Knechten kein Stroh, und doch sagt man zu uns: \"Schaffet Ziegel!\" Und nun werden deine Knechte gar noch geschlagen; so versündigst du dich an deinem Volke.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Er aber sprach: Faulenzer seid ihr, Faulenzer! Darum sprecht ihr: \"Wir wollen hingehen und dem Herrn opfern.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Nun fort an die Arbeit! Stroh wird euch nicht geliefert, aber die bestimmte Zahl von Ziegeln sollt ihr liefern!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Da sahen die Aufseher der Israeliten, dass es mit ihnen übelstand, weil man sagte: Ihr dürft eure tägliche Leistung an Ziegeln nicht vermindern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Als sie nun vom Pharao hinweggingen, trafen sie Mose und Aaron an, die dastanden und auf sie warteten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'und sie sprachen zu ihnen: Der Herr strafe euch und ahnde es, dass ihr uns beim Pharao und seinen Leuten verhasst gemacht und ihnen das Schwert in die Hand gegeben habt, uns zu töten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da wandte sich Mose wieder an den Herrn und sprach: Herr, warum handelst du so übel an deinem Volke? Warum hast du mich denn gesandt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Seitdem ich zum Pharao gegangen bin, in deinem Namen zu reden, hat er an diesem Volke übel gehandelt; aber gerettet hast du dein Volk nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Der Herr aber sprach zu Mose: Nun sollst du sehen, was ich dem Pharao tun werde; denn durch eine starke Hand gezwungen, wird er sie ziehen lassen, ja, durch eine starke Hand gezwungen, wird er sie aus seinem Lande vertreiben. (a) 2Mo 12:33');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'DA redete Gott mit Mose und sprach zu ihm: Ich bin Jahwe. (1) vgl. Anm. zu 1Mo 4:26 und 2Mo 3:14.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ich bin dem Abraham, Isaak und Jakob erschienen als \"der allmächtige Gott\"; aber unter meinem Namen Jahwe habe ich mich ihnen nicht geoffenbart. (1) vgl. Anm. zu 1Mo 4:26 und 2Mo 3:14. (a) 1Mo 17:1; 2Mo 3:14 15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Auch habe ich einen Bund mit ihnen aufgerichtet, ihnen das Land Kanaan zu geben, das Land, darin sie Fremdlinge gewesen sind. (a) 1Mo 17:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Und ich habe auch das Wehklagen der Israeliten gehört, die von den Ägyptern geknechtet werden, und habe meines Bundes gedacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sage zu den Israeliten: Ich bin Jahwe; ich will euch von der Last der Fronarbeit Ägyptens frei machen und euch aus eurer Knechtschaft erretten und euch erlösen mit ausgerecktem Arm und durch gewaltige Gerichte. (1) vgl. Anm. zu 1Mo 4:26 und 2Mo 3:14.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Ich will euch als mein Volk annehmen und will euer Gott sein, und ihr sollt erkennen, dass ich, der Herr, euer Gott bin, der euch von der Last der Fronarbeit Ägyptens frei macht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Und ich will euch in das Land bringen, das ich Abraham, Isaak und Jakob zu geben geschworen habe; das will ich euch zu eigen geben, Ich, der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mose sagte dies den Israeliten; aber sie hörten nicht auf Mose, aus Kleinmut und vor harter Arbeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da sprach der Herr zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Geh, rede mit dem Pharao, dem König von Ägypten, dass er die Israeliten aus seinem Lande ziehen lasse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mose aber sprach vor dem Herrn: Sieh, die Israeliten haben nicht auf mich gehört, wie sollte da der Pharao auf mich hören? Ich bin ja ungeschickt im Reden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Da sprach der Herr mit Mose und Aaron und gab ihnen Befehl, den Israeliten und dem Pharao, dem König von Ägypten, zu sagen, dass sie die Israeliten aus dem Lande Ägypten wegführen müssten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind ihre Familienhäupter. Die Söhne Rubens, des Erstgebornen Israels, sind: Henoch, Pallu, Hezron und Charmi. Das sind die Geschlechter Rubens. (a) 1Mo 46:9; 4Mo 26:5 6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Die Söhne Simeons sind: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaaniterin. Das sind die Geschlechter Simeons. (a) 1Mo 46:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Dies sind die Namen der Söhne Levis nach ihrem Stammbaum: Gerson, Kahath und Merari. Levi aber wurde 137 Jahre alt. (a) 1Mo 46:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Söhne Gersons sind: Libni und Simei nach ihren Geschlechtern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Die Söhne Kahaths sind: Amram, Jizhar, Hebron und Ussiel. Kahath aber wurde 133 Jahre alt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Die Söhne Meraris sind: Mahli und Musi. Das sind die Geschlechter Levis nach ihrem Stammbaum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Und Amram nahm seine Tante Jochebed zum Weibe; die gebar ihm Aaron und Mose. Und Amram wurde 137 Jahre alt. (a) 2Mo 2:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Die Söhne Jizhars sind: Korah, Nepheg und Sichri.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Die Söhne Ussiels sind: Misael, Elzaphan und Sithri.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron aber nahm Eliseba, die Tochter Amminadabs, die Schwester Nahasons, zum Weibe; die gebar ihm Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Die Söhne Korahs sind: Assir, Elkana und Abiasaph. Das sind die Geschlechter der Korahiten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar aber, der Sohn Aarons, nahm sich ein Weib von den Töchtern Putiels; die gebar ihm den Pinehas. Das sind die Familienhäupter der Leviten nach ihren Geschlechtern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Das ist der Aaron und der Mose, zu denen der Herr sprach: Führt die Israeliten, nach ihren Heerscharen geordnet, aus dem Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Sie sind es, die mit dem Pharao, dem König von Ägypten, redeten, um die Israeliten aus Ägypten wegzuführen - Mose und Aaron.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'DAMALS nun, als der Herr mit Mose im Lande Ägypten redete,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da sprach er zu ihm: Ich bin der Herr; sage dem Pharao, dem König von Ägypten, alles, was ich dir sagen werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mose aber sprach vor dem Herrn: Siehe, ich bin ungeschickt im Reden; wird da der Pharao auf mich hören?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Da sprach der Herr zu Mose: Siehe, ich mache dich zum Gotte für den Pharao, und dein Bruder Aaron soll dein Prophet sein. (a) 2Mo 4:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst ihm alles sagen, was ich dir gebieten werde, und dein Bruder Aaron soll es dem Pharao sagen, damit er Israel aus seinem Lande ziehen lasse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ich aber will das Herz des Pharao verhärten und viele Zeichen und Wunder im Lande Ägypten tun. (a) 2Mo 4:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Der Pharao wird nicht auf euch hören; dann will ich die Hand an Ägypten legen und meine Heerscharen, mein Volk Israel, durch gewaltige Gerichte aus dem Lande Ägypten führen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'und die Ägypter werden erkennen, dass ich der Herr bin, wenn ich meine Hand über Ägypten ausstrecke und Israel aus ihrer Mitte hinwegführe. (a) 2Mo 14:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Da taten Mose und Aaron, wie ihnen der Herr geboten hatte; also taten sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mose war achtzig Jahre alt, und Aaron war 83 Jahre alt, als sie mit dem Pharao redeten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Darnach sprach der Herr zu Mose und zu Aaron:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Wenn der Pharao zu euch sagt: \"Weist euch durch ein Wunder aus!\" so sollst du zu Aaron sagen: \"Nimm deinen Stab und wirf ihn vor den Pharao hin\"; dann wird er zur Schlange werden. (a) 2Mo 4:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da gingen Mose und Aaron zum Pharao und taten so, wie der Herr geboten hatte: Aaron warf seinen Stab vor dem Pharao und seinen Leuten hin, und er ward zur Schlange.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Aber der Pharao liess auch seinerseits die Weisen und Zauberer rufen, und auch sie, die ägyptischen Zauberer, taten dasselbe mit ihren geheimen Künsten: (1) V. 22; 2Mo 8:7 18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'ein jeder warf seinen Stab hin, und es wurden Schlangen daraus; aber Aarons Stab verschlang ihre Stäbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Doch das Herz des Pharao blieb verstockt, und er hörte nicht auf sie, wie es der Herr vorausgesagt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'DA sprach der Herr zu Mose: Das Herz des Pharao ist verstockt; er weigert sich, das Volk ziehen zu lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Begib dich morgen früh zum Pharao, wenn er ans Wasser hinausgeht; tritt ihm entgegen am Ufer des Nil, in der Hand den Stab, der zur Schlange geworden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sprich zu ihm: Der Herr, der Gott der Hebräer, hat mich zu dir gesandt, um dir zu sagen: \"Lass mein Volk ziehen, dass es mir in der Wüste diene!\" Doch du hast bisher nicht hören wollen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Darum spricht der Herr also: Daran sollst du erkennen, dass ich der Herr bin: siehe, ich will mit dem Stab in meiner Hand auf das Wasser im Nil schlagen, und es wird sich in Blut verwandeln; (a) 2Mo 4:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'die Fische im Nil werden sterben, und der Nil wird stinkend werden, dass es die Ägypter ekeln wird, Wasser aus dem Nil zu trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Dann sprach der Herr zu Mose: Sage zu Aaron: Nimm deinen Stab und strecke deine Hand aus über die Gewässer Ägyptens, über die Flüsse und Kanäle, über die Teiche und alle Wasserbecken, dass sie zu Blut werden und dass im ganzen Land Ägypten Blut sei, in den hölzernen und steinernen Gefässen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose und Aaron taten so, wie der Herr geboten hatte: er erhob den Stab und schlug vor den Augen des Pharao und seiner Leute auf das Wasser im Nil, und alles Wasser im Nil verwandelte sich in Blut; (a) Ps 78:44; 105:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'die Fische im Nil starben, und der Nil ward stinkend, sodass die Ägypter kein Wasser aus dem Nil mehr trinken konnten. Und das Blut kam über das ganze Land Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Die ägyptischen Zauberer aber taten dasselbe mit ihren geheimen Künsten, und das Herz des Pharao blieb verstockt; er hörte nicht auf sie, wie es der Herr vorausgesagt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Dann wandte sich der Pharao und ging heim und nahm sich auch das nicht zu Herzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Alle Ägypter aber gruben in der Umgebung des Nil nach Wasser, um zu trinken; denn das Wasser aus dem Nil konnten sie nicht trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Das währte volle sieben Tage, nachdem der Herr den Nil geschlagen hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Darnach sprach der Herr zu Mose: Gehe zum Pharao und sage zu ihm: So spricht der Herr: Lass mein Volk ziehen, dass es mir diene! (1) die Lutherbibel hat für Kap. 8,1-32 die Zählung 7,26-29; 8,1-28.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Wenn du dich aber weigerst, es ziehen zu lassen, siehe, so will ich dein ganzes Gebiet mit Fröschen plagen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Der Nil soll von Fröschen wimmeln; sie sollen heraufsteigen und in dein Haus, in dein Schlafgemach und auf dein Lager kommen, auch in die Häuser deiner Leute und deines Volkes, in deine Backöfen und deine Backtröge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'An dir und deinem Volke und allen deinen Leuten sollen die Frösche heraufkriechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Und der Herr sprach zu Mose: Sage zu Aaron: Strecke deine Hand mit dem Stabe aus über die Flüsse, die Kanäle und die Teiche, und lass die Frösche über das Land Ägypten kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Und Aaron streckte seine Hand aus über die Gewässer Ägyptens; da kamen die Frösche herauf und bedeckten das Land Ägypten. (a) Ps 78:45; 105:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Aber die Zauberer taten dasselbe mit ihren geheimen Künsten: sie liessen die Frösche über das Land Ägypten kommen. (1) V. 18; 2Mo 7:11 22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Da berief der Pharao Mose und Aaron und sprach: Legt bei eurem Gott Fürbitte ein, dass er die Frösche von mir und meinem Volke nehme, so will ich das Volk ziehen lassen, dass es seinem Gotte opfere.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mose antwortete dem Pharao: Beliebe zu bestimmen, auf wann ich für dich, für deine Leute und für dein Volk bitten soll, dass die Frösche von dir und deinen Häusern vertrieben werden; nur im Nil sollen sie übrigbleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Er sprach: Auf morgen! Da sprach Mose: Nach deinem Wunsch! - damit du erkennst, dass der Herr, unser Gott, nicht seinesgleichen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Die Frösche sollen von dir und deinen Häusern, von deinen Leuten und von deinem Volk genommen werden; nur im Nil sollen sie noch bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Als Mose und Aaron vom Pharao hinausgegangen waren, betete Mose zum Herrn wegen der Frösche, die er dem Pharao geschickt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und der Herr tat nach dem Worte Moses: Die Frösche starben in den Häusern, in den Höfen und auf dem Felde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Und man schüttete sie haufenweise zusammen, dass das Land davon stank.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Als aber der Pharao sah, dass er Luft bekommen hatte, verstockte er sein Herz und hörte nicht auf sie, wie es der Herr vorausgesagt. (a) 2Mo 7:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Darnach sprach der Herr zu Mose: Sage zu Aaron: \"Strecke deinen Stab aus und schlage in den Staub auf der Erde\", so wird er zu Mücken werden im ganzen Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Und sie taten also: Aaron streckte die Hand mit dem Stabe aus und schlug in den Staub auf der Erde; da kamen die Mücken über die Menschen und das Vieh. Aller Staub auf der Erde ward zu Mücken im ganzen Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Und die Zauberer taten dasselbe mit ihren geheimen Künsten, um Mücken hervorzubringen; aber sie konnten es nicht. So kamen die Mücken über die Menschen und das Vieh.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Da sprachen die Zauberer zum Pharao: Das ist eines Gottes Finger. Aber das Herz des Pharao blieb verhärtet, und er hörte nicht auf sie, wie es der Herr vorausgesagt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Darnach sprach der Herr zu Mose: Tritt morgen in der Frühe vor den Pharao, wenn er ans Wasser hinausgeht, und sage zu ihm: So spricht der Herr: Lass mein Volk ziehen, dass es mir diene!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Denn wenn du mein Volk nicht ziehen lässest, siehe, so lasse ich wider dich und deine Leute, wider dein Volk und deine Häuser die Bremsen los, dass die Häuser der Ägypter voll werden von den Bremsen, und sogar der Boden, auf dem sie stehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'An jenem Tage will ich mit dem Lande Gosen, wo mein Volk wohnt, eine Ausnahme machen, sodass es dort keine Bremsen geben soll, damit du erkennst, dass ich, der Herr, inmitten des Landes bin. (a) 1Mo 47:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ich will eine Scheidewand setzen zwischen meinem Volk und deinem Volk. Morgen soll dieses Zeichen geschehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Und der Herr tat also: eine Menge Bremsen kam in das Haus des Pharao und in die Häuser seiner Leute, ja, über das ganze Land Ägypten, und das Land litt schwer unter den Bremsen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Da berief der Pharao Mose und Aaron und sprach: Wohlan, opfert eurem Gott hier im Lande!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mose sprach: Es geht nicht an, dass wir das tun; denn den Ägyptern ist ein Greuel, was wir dem Herrn, unserm Gotte, opfern. Wenn wir vor den Augen der Ägypter opfern, was ihnen ein Greuel ist, so steinigen sie uns ja!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Drei Tagereisen weit wollen wir in die Wüste ziehen und dann dem Herrn, unserm Gotte, opfern, wie uns der Herr befohlen hat. (a) 2Mo 3:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Da sprach der Pharao: Ich will euch ziehen lassen, damit ihr eurem Gott in der Wüste opfern könnt; nur dass ihr nicht allzu weit wegzieht! Legt Fürbitte für mich ein!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mose antwortete: Sobald ich von dir hinausgegangen bin, will ich den Herrn bitten, dass die Bremsen morgen vom Pharao, von seinen Leuten und von seinem Volke weichen; nur soll der Pharao uns nicht wiederum täuschen, indem er das Volk doch nicht ziehen lässt, dem Herrn zu opfern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Dann ging Mose vom Pharao hinaus und legte Fürbitte ein bei dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Und der Herr tat nach dem Worte Moses: er liess die Bremsen weichen vom Pharao, von seinen Leuten und von seinem Volke, sodass nicht eine übrigblieb.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Aber der Pharao verstockte sein Herz auch diesmal und liess das Volk nicht ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Darnach sprach der Herr zu Mose: Gehe zum Pharao und sage zu ihm: So spricht der Herr, der Gott der Hebräer: \"Lass mein Volk ziehen, dass es mir diene!\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn wenn du dich weigerst, sie ziehen zu lassen, und sie noch weiter festhältst,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'siehe, so wird die Hand des Herrn über dein Vieh auf dem Felde kommen, über Pferde, Esel und Kamele, über Rinder und Schafe, mit einer furchtbaren Pest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Aber der Herr wird einen Unterschied machen zwischen dem Vieh der Israeliten und dem Vieh der Ägypter: von allem, was den Israeliten gehört, wird kein Stück umkommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Auch hat der Herr eine Zeit bestimmt, indem er sprach: Morgen wird der Herr solches tun im Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und am andern Morgen tat der Herr solches: alles Vieh der Ägypter starb, von dem Vieh der Israeliten aber starb nicht ein Stück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Da liess der Pharao nachsehen, und es ergab sich, dass von dem Vieh der Israeliten auch nicht ein einziges Stück gestorben war. Gleichwohl blieb das Herz des Pharao verstockt, und er liess das Volk nicht ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Darnach sprach der Herr zu Mose und Aaron: Nehmt euch beide Hände voll Ofenruss, und Mose streue ihn vor den Augen des Pharao gen Himmel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Dann wird er zu Staub werden über dem ganzen Lande Ägypten, und es werden daraus an den Menschen und am Vieh im ganzen Lande Ägypten Beulen entstehen, die zu Geschwüren aufbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Und sie nahmen den Ofenruss und traten vor den Pharao, und Mose streute ihn gen Himmel. Da entstanden an den Menschen und am Vieh Geschwürbeulen, die aufbrachen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Die Zauberer aber konnten wegen der Beulen Mose nicht entgegentreten; denn die Beulen kamen an die Zauberer wie an alle Ägypter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Aber der Herr verhärtete das Herz des Pharao, und er hörte nicht auf sie, wie es der Herr dem Mose vorausgesagt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Darnach sprach der Herr zu Mose: Tritt morgen in der Frühe vor den Pharao und sage zu ihm: So spricht der Herr, der Gott der Hebräer: Lass mein Volk ziehen, dass es mir diene!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn diesmal will ich dich und deine Leute und dein Volk all meine Plagen spüren lassen, damit du erkennst, dass in aller Welt nicht meinesgleichen ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Denn schon jetzt hätte ich meine Hand ausstrecken und dich samt deinem Volke mit der Pest schlagen können, und du wärest von der Erde vertilgt gewesen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'aber deswegen habe ich dich bestehen lassen, dass du meine Macht erfahrest und dass mein Name in aller Welt verkündet werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Noch immer stemmst du dich dagegen, mein Volk ziehen zu lassen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'darum will ich morgen um diese Zeit einen furchtbaren Hagel niedergehen lassen, desgleichen in Ägypten noch nicht dagewesen ist, seit der Zeit, da es gegründet wurde, bis jetzt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'So sende nun hin und bringe dein Vieh und alles, was du auf dem Felde hast, in Sicherheit; denn alle Menschen und die Tiere, die sich auf dem Felde befinden und sich nicht ins Haus zurückziehen, werden sterben, wenn der Hagel auf sie niedergeht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer nun unter den Leuten des Pharao das Wort des Herrn fürchtete, der liess seine Knechte und sein Vieh in die Häuser flüchten;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'wer sich aber nicht an das Wort des Herrn kehrte, der liess seine Knechte und sein Vieh auf dem Felde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Nun sprach der Herr zu Mose: Strecke deine Hand aus gen Himmel, so wird Hagel fallen im ganzen Lande Ägypten, auf die Menschen und auf das Vieh und auf alles Feldgewächs im Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Da streckte Mose seinen Stab gen Himmel, und der Herr liess donnern und hageln, und Feuer fuhr zur Erde hernieder. Und der Herr liess Hagel fallen auf das Land Ägypten. (a) Ps 78:47; 105:32');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Es war ein Hagel und ein unaufhörliches Feuer unter dem Hagel, ganz furchtbar, desgleichen niemals gewesen im ganzen Lande Ägypten, seit es bevölkert war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel erschlug im ganzen Lande Ägypten alles, was auf dem Felde war, Menschen sowohl als Vieh; auch alles Feldgewächs zerschlug der Hagel, und alle Bäume auf dem Felde zerschmetterte er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur im Lande Gosen, wo die Israeliten wohnten, hagelte es nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da schickte der Pharao hin und liess Mose und Aaron rufen und sprach zu ihnen: Diesmal stehe ich als schuldig da; euer Gott ist im Recht, ich aber und mein Volk, wir sind im Unrecht. (a) 2Mo 10:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Legt Fürbitte ein bei eurem Gott; es ist nun des furchtbaren Donners und des Hagels mehr als genug. Ich will euch ziehen lassen, und ihr sollt nicht länger bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose erwiderte ihm: Wenn ich zur Stadt hinausgehe, will ich meine Hände zu dem Herrn ausbreiten; dann wird der Donner aufhören und der Hagel nicht mehr fallen - damit du erkennst, dass die Erde des Herrn ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Von dir und deinen Leuten aber ist mir gewiss, dass ihr euch vor Gott, dem Herrn, noch nicht fürchtet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Der Flachs und die Gerste waren zerschlagen; denn die Gerste stand in Ähren und der Flachs in Blüte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Der Weizen aber und der Spelt waren nicht zerschlagen; denn die kommen später.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Als nun Mose vom Pharao hinweg und zur Stadt hinausgegangen war, breitete er seine Hände zu dem Herrn aus; da hörten Donner und Hagel auf, und der Regen ergoss sich nicht mehr auf die Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Sobald aber der Pharao sah, dass Regen und Hagel und Donner aufgehört hatten, verharrte er in seiner Sünde und verstockte sein Herz, er und seine Leute.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Das Herz des Pharao blieb hart, und er liess die Israeliten nicht ziehen, wie es der Herr durch Mose vorausgesagt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Darnach sprach der Herr zu Mose: Gehe zum Pharao; denn ich habe sein und seiner Leute Herz verstockt, damit ich diese meine Zeichen unter ihnen tue,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und damit du deinen Kindern und Kindeskindern erzählest, wie übel ich den Ägyptern zugesetzt und was für Zeichen ich unter ihnen getan habe, damit ihr erkennet, dass ich der Herr bin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Da gingen Mose und Aaron zum Pharao und sagten zu ihm: So spricht der Herr, der Gott der Hebräer: Wie lange willst du dich noch weigern, dich vor mir zu demütigen? Lass mein Volk ziehen, dass es mir diene!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Denn wenn du dich weigerst, mein Volk ziehen zu lassen, siehe, so bringe ich morgen Heuschrecken in dein Land;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'die sollen den ganzen Boden bedecken, dass man die Erde nicht mehr sehen kann, und sollen alles auffressen, was euch vom Hagel noch verschont geblieben ist, und auch alle Bäume kahl fressen, die euch auf dem Felde wachsen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Sie sollen deine Häuser und die Häuser deiner Leute und die Häuser aller Ägypter füllen, wie es deine Väter und Vorväter nie gesehen haben, seitdem sie im Lande wohnen, bis auf diesen Tag. Und er wandte sich und ging vom Pharao hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Nun sprachen die Diener zum Pharao: Wie lange noch soll dieser Mensch unser Verderben sein? Lass doch die Leute ziehen, dass die dem Herrn, ihrem Gott, dienen! Siehst du noch nicht ein, dass Ägypten zugrunde geht?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Da wurden Mose und Aaron zum Pharao zurückgerufen, und er sprach zu ihnen: Geht und dient dem Herrn, eurem Gott! Wer alles soll denn mitziehen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose antwortete: Wir alle wollen gehen, auch die Kinder und Greise, mit unsern Söhnen und Töchtern, und auch unsre Schafe und Rinder wollen wir mitnehmen; denn wir haben das Fest des Herrn zu feiern. (a) 2Mo 5:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Er aber sprach zu ihnen: So gewiss möge euer Gott mit euch sein, als ich euch mit euren Kindern ziehen lasse! Seht da, dass ihr Böses im Sinne habt!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Daraus wird nichts! Ihr Männer mögt hingehen und eurem Gotte dienen; das ist ja euer Begehr. Und man jagte sie vom Pharao hinaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da sprach der Herr zu Mose: Strecke deine Hand aus über das Land Ägypten, dass die Heuschrecken über das Land Ägypten kommen und alles Gewächs der Erde auffressen, alles, was der Hagel übriggelassen hat. (a) Ps 78:46; 105:34 35');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Und Mose streckte seinen Stab aus über das Land Ägypten. Der Herr aber liess einen Ostwind ins Land wehen jenen ganzen Tag und die ganze Nacht; und als es Morgen ward, hatte der Ostwind die Heuschrecken gebracht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Da kamen die Heuschrecken über das ganze Land Ägypten und liessen sich im ganzen Gebiete von Ägypten nieder, eine gewaltige Menge; nie zuvor waren so viele Heuschrecken gekommen, und nie wieder werden so viele kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Und sie bedeckten den ganzen Boden, sodass man die Erde nicht mehr sah; und sie frassen alles Gewächs der Erde und alle Früchte auf den Bäumen, was der Hagel übriggelassen hatte, sodass nichts Grünes mehr übrigblieb an den Bäumen und am Gewächs des Feldes im ganzen Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da liess der Pharao eilends Mose und Aaron rufen und sprach: Ich habe gesündigt gegen den Herrn, euren Gott, und gegen euch. (a) 2Mo 9:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Und nun vergebt mir meine Sünde nur noch diesmal und bittet den Herrn, euren Gott, dass er nur dieses Verderben von mir abwende.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Und Mose ging hinaus vom Pharao und betete zum Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Da verwandelte der Herr den Wind in einen sehr starken Westwind; der hob die Heuschrecken auf und warf sie ins Schilfmeer, sodass nicht eine Heuschrecke mehr übrigblieb im ganzen Gebiet von Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber der Herr verstockte das Herz des Pharao, und er liess die Israeliten nicht ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Darnach sprach der Herr zu Mose: Strecke deine Hand aus gen Himmel, so wird eine solche Finsternis kommen über das Land Ägypten, dass man die Finsternis greifen kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Da streckte Mose seine Hand gen Himmel, und es entstand dichte Finsternis im ganzen Lande Ägypten, drei Tage lang:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'keiner konnte den andern sehen, und keiner stand auf von seinem Platze, drei Tage lang; aber die Israeliten alle hatten hellen Tag an ihren Wohnsitzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da liess der Pharao Mose rufen und sprach: Geht und dient eurem Gott; nur eure Schafe und Rinder sollen hier bleiben. Auch eure Kinder mögen mit euch ziehen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose erwiderte: Du sogar musst uns Schlachtopfer und Brandopfer geben, dass wir sie dem Herrn, unserm Gott, darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Und auch unser Vieh soll mit uns gehen, nicht eine Klaue darf dahintenbleiben; denn davon müssen wir nehmen, um dem Herrn, unserm Gott, zu opfern. Wir wissen ja nicht, wieviel wir dem Herrn opfern müssen, bis wir dorthin kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber der Herr verstockte das Herz des Pharao, und er wollte sie nicht ziehen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und der Pharao sprach zu ihm: Hinweg von mir! Hüte dich, mir nochmals unter die Augen zu treten; denn sobald du mir wieder unter die Augen trittst, musst du sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose antwortete: Du hast\'s gesagt - ich werde dir nicht wieder unter die Augen treten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'DARNACH sprach der Herr zu Mose: Noch eine Plage will ich über den Pharao und über Ägypten bringen; dann wird er euch von hier wegziehen lassen, und wenn er euch entlässt, wird er euch sogar samt und sonders von hier fortjagen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Sage den Leuten, sie sollen sich ein jeder von seinem Nachbar und eine jede von ihrer Nachbarin silberne und goldene Schmucksachen erbitten. (a) 2Mo 3:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Und der Herr verschaffte dem Volke Gunst bei den Ägyptern; der Mann Mose war sogar hochangesehen im Lande Ägypten, bei den Leuten des Pharao und beim Volke.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Und Mose sprach (zum Pharao): So spricht der Herr: Um Mitternacht werde ich mitten durch Ägypten schreiten;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'dann wird jeder Erstgeborne in Ägypten sterben, vom Erstgebornen des Pharao, der auf seinem Throne sitzt, bis zum Erstgebornen der Sklavin hinter der Handmühle, auch alle Erstgeburt unter dem Vieh. (a) 2Mo 12:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Da wird grosses Wehklagen sein im ganzen Lande Ägypten, desgleichen nie gewesen ist und nie wieder sein wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Gegen die Israeliten aber soll auch nicht ein Hund mucksen, weder gegen Mensch noch Vieh, damit ihr erkennet, dass der Herr einen Unterschied macht zwischen Ägypten und Israel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann werden alle diese deine Leute zu mir herabkommen und mir zu Füssen fallen und sagen: \"Ziehe aus, du und alles Volk, das hinter dir steht\", und darnach werde ich ausziehen. Und er ging hinaus vom Pharao in grimmigem Zorn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Der Herr aber sprach zu Mose: Der Pharao wird nicht auf euch hören, damit meiner Wunder in Ägypten viel geschehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Und Mose und Aaron taten alle diese Wunder vor dem Pharao; doch der Herr verstockte das Herz des Pharao, und er liess die Israeliten nicht aus seinem Lande ziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Darnach sprach der Herr zu Mose und Aaron im Lande Ägypten:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Dieser Monat soll für euch der erste Monat sein; von ihm an sollt ihr die Monate des Jahres zählen. (a) 2Mo 13:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Sprecht zu der ganzen Gemeinde Israels: Am zehnten Tage dieses Monats nehme sich ein jeder ein Lamm, nach der Zahl der Familien, je ein Lamm für eine Haushaltung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Wenn aber für ein Lamm in einem Hause zu wenige sind, so nehme er es zusammen mit dem Nachbar, der zunächst bei seinem Hause wohnt, nach der Zahl der Seelen; so viele, als nötig sind, ein Lamm aufzuessen, sollt ihr auf das Lamm rechnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ein fehlloses, männliches, einjähriges Lamm soll es sein; aus den Schafen oder Ziegen sollt ihr es nehmen. (a) 3Mo 1:3; 22:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Und ihr sollt es aufbehalten bis zum vierzehnten Tage dieses Monats; dann soll die ganze Gemeinde Israels es schlachten um die Abendzeit. (a) 4Mo 9:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und sie sollen von dem Blute nehmen und die beiden Türpfosten und die Oberschwelle an den Häusern, in denen sie es essen, damit bestreichen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'das Fleisch aber sollen sie in derselben Nacht noch essen; am Feuer gebraten sollen sie es essen, und ungesäuertes Brot mit bittern Kräutern dazu.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr sollt nichts davon roh essen oder im Wasser gesotten, sondern am Feuer gebraten, den Kopf mitsamt den Schenkeln und den innern Teilen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Und ihr sollt davon nichts übriglassen bis zum Morgen. Was aber bis zum Morgen davon übrigbleibt, sollt ihr verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'So sollt ihr es essen: die Lenden gegürtet, die Schuhe an den Füssen und den Stab in der Hand. Ihr sollt es essen in angstvoller Eile; ein Passa für den Herrn ist es. (a) 5Mo 16:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Und ich werde in derselben Nacht durch das Land Ägypten schreiten und alle Erstgeburt im Lande Ägypten erschlagen, von den Menschen sowohl als vom Vieh, und an allen Göttern der Ägypter werde ich ein Strafgericht vollstrecken, Ich, der Herr. (a) 4Mo 33:4; Ps 136:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut soll ein Schutzzeichen für euch sein an den Häusern, in denen ihr seid: wenn ich das Blut sehe, werde ich an euch vorübergehen, und kein Schlag soll euch vernichtend treffen, wenn ich das Land Ägypten schlage.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und dieser Tag soll für euch ein Gedenktag werden, und ihr sollt ihn feiern als ein Fest des Herrn; von Geschlecht zu Geschlecht, als ewige Ordnung, sollt ihr ihn feiern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage lang sollt ihr ungesäuertes Brot essen; gleich am ersten Tage sollt ihr den Sauerteig aus euren Häusern hinwegtun. Denn jeder, der gesäuertes Brot isst, dessen Seele soll aus Israel ausgerottet werden - (das gilt) vom ersten Tage bis zum siebenten Tag. (a) 2Mo 13:7; 23:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Am ersten Tage sollt ihr eine heilige Versammlung halten, ebenso am siebenten Tage eine heilige Versammlung. Keinerlei Arbeit soll an diesen (Tagen) getan werden; nur was ein jeder zum Essen nötig hat, das allein darf von euch zubereitet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und beobachtet (die Vorschrift über) die ungesäuerten Brote. Denn an ebendiesem Tage habe ich eure Heerscharen aus dem Lande Ägypten herausgeführt; darum sollt ihr diesen Tag halten von Geschlecht zu Geschlecht, als ewige Ordnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Am vierzehnten Tage des ersten Monats, am Abend, sollt ihr ungesäuertes Brot essen bis zum Abend des 21. Tages des Monats. (a) 3Mo 23:6; 4Mo 28:17; 5Mo 16:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sieben Tage lang darf sich kein Sauerteig in euren Häusern finden. Denn jeder, der Gesäuertes isst, dessen Seele soll ausgerottet werden aus der Gemeinde Israels, er sei Fremder oder Einheimischer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nichts Gesäuertes dürft ihr essen; in all euren Wohnsitzen sollt ihr ungesäuertes Brot essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Da berief Mose alle Ältesten Israels und sprach zu Ihnen: Nehmt eilends Schafe, für jede Familie eines, und schlachtet das Passa.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Dann nehmt ein Büschel Ysop und tunkt es in das Blut im Becken und streicht von dem Blut im Becken an die Oberschwelle und die beiden Türpfosten; von euch aber soll bis zum Morgen keiner vor die Türe seines Hauses treten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Denn der Herr wird durch das Land schreiten, um die Ägypter zu schlagen. Wenn dann der Herr das Blut an der Oberschwelle und an den beiden Pfosten sieht, so wird er an der Türe vorübergehen und den Würgengel nicht in eure Häuser kommen lassen, (euch) zu schlagen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Dieses Gebot sollt ihr halten, du und deine Kinder, als ewige Ordnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und wenn ihr in das Land kommt, das der Herr euch geben wird, wie er verheissen hat, so sollt ihr diesen heiligen Brauch stets üben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Wenn eure Kinder euch dann fragen: \"Was bedeutet denn der heilige Brauch, den ihr da übt?\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'so sollt ihr sagen: \"Das ist das Passaopfer für den Herrn, weil er an den Häusern Israels vorüberschritt in Ägypten, als er die Ägypter schlug, und unsre Häuser verschonte.\" Da verneigte sich das Volk und warf sich nieder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Und die Israeliten gingen hin und taten, wie der Herr dem Mose und dem Aaron geboten hatte; so taten sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Und es begab sich um Mitternacht, da schlug der Herr alle Erstgeburt im Lande Ägypten, vom Erstgebornen des Pharao, der auf seinem Throne sass, bis zum Erstgebornen des Gefangenen, der im Kerker lag, und alle Erstgeburt des Viehs. (a) Ps 78:51; 105:36; 135:8; 136:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stand der Pharao auf in jener Nacht, er und alle seine Leute und alle Ägypter, und es erhob sich grosses Wehklagen in Ägypten; denn es gab kein Haus, in dem nicht ein Toter war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Und er liess noch in der Nacht Mose und Aaron rufen und sprach: Macht euch auf und zieht hinweg aus meinem Volke, ihr sowohl als die Israeliten! Geht, dient eurem Gott, wie ihr gesagt habt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Nehmt auch eure Schafe und Rinder mit euch, wie ihr gesagt habt, und geht, und verschafft auch mir Segen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Und die Ägypter drängten das Volk, um es eilends aus dem Lande zu bringen; denn sie sagten: Wir sind sonst alle des Todes. (a) Ps 105:38');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Und die Leute nahmen ihren Teig mit, ehe er durchsäuert war, indem sie die Backschüsseln in ihre Mäntel gewickelt auf den Achseln trugen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Die Israeliten hatten aber nach dem Worte Moses getan und sich von den Ägyptern silberne und goldene Schmucksachen und Kleider erbeten. (a) 2Mo 3:22; 11:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Und der Herr hatte dem Volke bei den Ägyptern Gunst verschafft, dass sie ihrem Begehren willfahrten; so beraubten sie die Ägypter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Nun brachen die Israeliten auf von Ramses nach Sukkoth, an die 600 000 Mann zu Fuss, die Kinder nicht gerechnet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Auch viel fremdes Volk zog mit ihnen, dazu Schafe und Rinder, eine gewaltige Menge Vieh.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Und sie buken aus dem Teige, den sie aus Ägypten mitgebracht, ungesäuerte Brotkuchen; denn er war noch ungesäuert, weil sie aus Ägypten vertrieben worden waren und nicht länger hatten zögern können; auch hatten sie sich keine Wegzehrung bereitet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Die Zeit aber, welche die Israeliten in Ägypten gewohnt haben, beträgt 430 Jahre. (a) 1Mo 15:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Nach Verlauf von 430 Jahren, an ebendiesem Tage, zogen alle Heerscharen des Herrn aus dem Lande Ägypten hinweg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Eine Nacht des Wachens, dem Herrn geweiht, ist dies, da er sie aus dem Lande Ägypten hinausführte; das ist diese dem Herrn geweihte Nacht, ein Wachen für alle Israeliten von Geschlecht zu Geschlecht. (1) die Üs. dieses Verses ist unsicher.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und der Herr sprach zu Mose und Aaron: Dies ist die Satzung für das Passa: kein Fremder soll davon essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Aber jeder um Geld gekaufte Sklave darf davon essen, wenn er beschnitten ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisasse oder Tagelöhner soll nicht davon essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soll man es essen. Du sollst vom Fleisch nichts aus dem Haus hinaustragen, und ihr sollt keinen Knochen an ihm zerbrechen. (a) 4Mo 9:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israels soll es feiern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Wenn aber ein Fremder bei dir wohnt und er dem Herrn das Passa halten will, so soll alles Männliche, das zu ihm gehört, beschnitten werden; dann mag er herzutreten, um es zu feiern, und er gelte wie ein Einheimischer; aber kein Unbeschnittener soll davon essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein und dasselbe Gesetz soll gelten für den Einheimischen und für den Fremden, der unter euch wohnt. (a) 3Mo 24:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Da taten alle Israeliten, wie der Herr dem Mose und dem Aaron geboten hatte; so taten sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'An ebendiesem Tage führte der Herr die Israeliten nach ihren Heerscharen geordnet aus dem Lande Ägypten hinweg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Darnach sprach der Herr zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Weihe mir alle Erstgeburt bei den Israeliten, alles was zuerst den Mutterschoss durchbricht, unter den Menschen und unter dem Vieh; mir gehört es. (a) 2Mo 22:29; 34:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Da sprach Mose zum Volke: Gedenket dieses Tages, an dem ihr aus Ägypten, aus dem Sklavenhause, ausgezogen seid; denn mit starker Hand hat euch der Herr von dort herausgeführt. Darum soll man kein gesäuertes Brot essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute zieht ihr aus, im Ährenmonat. (1) entspricht unserm Monat März/April. (a) 2Mo 23:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Wenn dich nun der Herr in das Land der Kanaaniter, Hethiter, Amoriter, Hewiter und Jebusiter bringt, von dem er deinen Vätern geschworen hat, dass er es dir geben wolle, ein Land, das von Milch und Honig fliesst, so sollst du in diesem Monat diesen heiligen Brauch üben: (a) 1Mo 15:18-21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'sieben Tage lang sollst du ungesäuertes Brot essen, und am siebenten Tage ist ein Fest des Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Ungesäuertes Brot soll man die sieben Tage hindurch essen, und es soll bei dir nichts gesäuertes und kein Sauerteig zu sehen sein, in deinem ganzen Gebiete.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und du sollst das deinem Sohn an jenem Tage erklären und sagen: \"(Es geschieht) um dessen willen, was der Herr für mich getan hat, als ich aus Ägypten zog.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es soll dir sein wie ein Zeichen auf der Hand und wie ein Denkzeichen auf der Stirne, damit das Gesetz des Herrn in deinem Munde sei; denn mit starker Hand hat dich der Herr aus Ägypten herausgeführt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Darum sollst du diese Satzung halten, alljährlich zur bestimmten Zeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Wenn dich nun der Herr ins Land der Kanaaniter bringt, wie er dir und deinen Vätern geschworen hat, und es dir gibt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du alles, was zuerst den Mutterschoss durchbricht, dem Herrn darbringen; jeder erste Wurf des Viehs, den du bekommst, gehört, soweit er männlich ist, dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Jede Erstgeburt vom Esel aber sollst du mit einem Lamm auslösen; willst du sie jedoch nicht auslösen, so brich ihr das Genick. Auch alle Erstgeburt von Menschen unter deinen Söhnen sollst du auslösen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Wenn dich dann künftig dein Sohn fragt: \"Was hat das zu bedeuten?\" so sollst du ihm antworten: \"Mit starker Hand hat uns der Herr aus Ägypten, aus dem Sklavenhause, herausgeführt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Denn als der Pharao sich hartnäckig weigerte, uns ziehen zu lassen, da tötete der Herr alle Erstgeburt in Ägypten, die Erstgeburt der Menschen wie die Erstgeburt des Viehs; darum opfere ich dem Herrn alles, was zuerst den Mutterschoss durchbricht, soweit es männlich ist, alle Erstgeburt aber unter meinen Söhnen löse ich aus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und das soll dir wie ein Zeichen auf der Hand und wie ein Merkzeichen auf der Stirne sein; denn mit starker Hand hat uns der Herr aus Ägypten herausgeführt.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'ALS nun der Pharao das Volk ziehen liess, führte sie Gott nicht den Weg nach dem Philisterland - der wäre ja der nächste gewesen -; denn Gott dachte: Vielleicht könnte es das Volk gereuen, wenn es Kämpfe vor sich sieht, und sie könnten nach Ägypten zurückkehren;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'sondern Gott liess das Volk einen Umweg machen, durch die Wüste an das Schilfmeer, und kampfgerüstet zogen die Israeliten aus dem Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Mose nahm die Gebeine Josephs mit; denn dieser hatte einen Eid von den Söhnen Israels genommen und gesprochen: Gewiss wird Gott sich euer annehmen; führt dann meine Gebeine mit von hier hinauf. (a) 1Mo 50:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Darnach brachen sie von Sukkoth auf und lagerten sich in Etham am Rande der Wüste. (a) 4Mo 33:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Der Herr aber zog vor ihnen her, am Tage in einer Wolkensäule, um ihnen den Weg zu zeigen, und des Nachts in einer Feuersäule, um ihnen zu leuchten, damit sie bei Tag und bei Nacht wandern könnten. (a) 2Mo 40:38; Ne 9:19; Ps 78:14; 105:39');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nie wich die Wolkensäule am Tage und nie die Feuersäule bei Nacht von der Spitze des Zuges.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Da sprach der Herr zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Befiehl den Israeliten, umzukehren und sich bei Pihahiroth zu lagern, zwischen Migdol und dem Meere; angesichts von Baal-Zephon, diesem gegenüber, sollt ihr euch am Meere lagern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Der Pharao aber wird von den Israeliten denken: Sie haben sich im Lande verirrt, die Wüste hält sie umschlossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Dann will ich das Herz des Pharao verstocken, dass er ihnen nachjagt, damit ich mich am Pharao und seiner ganzen Macht verherrliche; die Ägypter sollen erkennen, dass ich der Herr bin. Und sie taten also. (a) 2Mo 4:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Als nun dem König von Ägypten gemeldet wurde, dass das Volk geflohen sei, da änderte sich der Sinn des Pharao und seiner Leute gegenüber dem Volke, und sie sprachen: Was haben wir da getan, dass wir Israel haben ziehen lassen, sodass sie uns nicht mehr dienen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und er liess seinen Streitwagen anspannen und nahm seine Leute mit sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Er nahm sechshundert auserlesene Streitwagen und alle Streitwagen Ägyptens und Wagenkämpfer auf einem jeden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Und der Herr verstockte das Herz des Pharao, des Königs von Ägypten, sodass er den Israeliten nachjagte, obwohl sie unter dem Schutze einer hocherhobenen Hand auszogen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'So jagten ihnen die Ägypter nach und erreichten sie, als sie am Meere lagerten - alle Rosse der Streitwagen, die Reiter und die Kriegsmacht des Pharao -, bei Pihahiroth gegenüber Baal-Zephon. (a) Jos 24:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Als nun der Pharao schon nahe herangekommen war, erhoben die Israeliten ihre Augen, und siehe, die Ägypter zogen hinter ihnen her; da fürchteten sie sich sehr. Und die Israeliten schrieen zum Herrn');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'und sprachen zu Mose: Gab es denn keine Gräber in Ägypten, dass du uns wegführen musstest, damit wir in der Wüste sterben? Was hast du uns da angetan, dass du uns aus Ägypten weggeführt hast! (a) Ps 106:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Haben wir dir\'s nicht schon in Ägypten gesagt: \"Lass uns in Ruhe! Wir wollen den Ägyptern dienen\"? Denn es wäre uns ja besser, den Ägyptern zu dienen, als in der Wüste zu sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose aber sprach zum Volke: Fürchtet euch nicht! Haltet stand, so werdet ihr sehen, wie der Herr euch heute helfen wird; denn so, wie ihr die Ägypter heute seht, werdet ihr sie niemals wieder sehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Der Herr wird für euch streiten, seid ihr nur stille. (a) 5Mo 1:30; 2Ch 20:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Darnach sprach der Herr zu Mose: Was schreist du zu mir? Sage den Israeliten, sie sollen aufbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber hebe deinen Stab empor und recke deine Hand aus über das Meer und spalte es, dass die Israeliten mitten im Meere auf dem Trockenen gehen können.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Und ich will dann das Herz der Ägypter verstocken, dass sie ihnen nacheilen, damit ich mich verherrliche am Pharao und seiner ganzen Kriegsmacht, an seinen Streitwagen und seinen Reitern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Die Ägypter sollen erkennen, dass ich der Herr bin, wenn ich am Pharao, an seinen Streitwagen und seinen Reitern mich verherrliche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Da machte sich der Engel Gottes auf, der vor dem Heere Israels einherzog, und trat hinter sie; und die Wolkensäule vor ihnen ging weg und stellte sich hinter sie. (a) 2Mo 13:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Und jener kam zwischen das Heer der Ägypter und das Heer Israels zu stehen. Es geschah aber, dass die Wolke sich verfinsterte; da zogen sie während der Nacht hindurch, sodass während der ganzen Nacht keiner dem andern nahekam.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Und Mose reckte seine Hand aus über das Meer, und der Herr trieb das Meer die ganze Nacht durch einen starken Ostwind zurück und legte das Meer trocken; und die Wasser spalteten sich. (a) Jos 4:23; Ps 78:13; Jes 63:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'So gingen die Israeliten mitten im Meere auf dem Trockenen, während die Wasser ihnen zur Rechten und zur Linken wie eine Mauer standen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Die Ägypter aber jagten nach und zogen hinter ihnen her, alle Rosse des Pharao, seine Streitwagen und Reiter, mitten ins Meer hinein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Und um die Zeit der Morgenwache schaute der Herr in der Feuer- und Wolkensäule auf das Heer der Ägypter und verwirrte das Heer der Ägypter;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'er hemmte die Räder ihrer Wagen und liess sie nur mühsam vorwärtskommen. Da sprachen die Ägypter: Lasst uns vor Israel fliehen; denn der Herr streitet für sie wider Ägypten. (a) Jos 10:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Und der Herr sprach zu Mose: Recke deine Hand aus über das Meer, dass die Wasser zurückfluten auf die Ägypter, auf ihre Wagen und ihre Reiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Und Mose reckte die Hand aus über das Meer, und beim Anbruch des Morgens strömte das Meer in sein Bette zurück, während die Ägypter ihm entgegenflohen, und der Herr trieb die Ägypter mitten ins Meer hinein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Die Wasser strömten zurück und bedeckten die Wagen und Reiter, die ganze Streitmacht des Pharao, die ihnen ins Meer nachgefolgt war, sodass nicht einer von ihnen am Leben blieb.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Die Israeliten aber waren mitten im Meere auf dem Trockenen gegangen, während die Wasser ihnen zur Rechten und zur Linken wie eine Mauer standen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'So errettete der Herr an jenem Tage Israel aus der Hand der Ägypter, und Israel sah die Ägypter tot am Gestade des Meeres liegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Als Israel sah, wie gewaltig sich die Hand des Herrn an den Ägyptern erwiesen hatte, da fürchtete das Volk den Herrn, und sie glaubten an den Herrn und an seinen Knecht Mose.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'DAMALS sangen Mose und die Israeliten dem Herrn dieses Lied; sie hoben an: Singen will ich dem Herrn, denn hoch erhaben ist er; / Ross und Reiter warf er ins Meer. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Meine Stärke und mein Loblied ist der Herr, und er ward mein Heil; / er ist mein Gott, ich will ihn preisen, / der Gott meines Vaters, ich will ihn erheben. / (a) Jes 12:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Der Herr ist ein Kriegsheld, Herr ist sein Name. / (a) 2Mo 3:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen des Pharao und seine Streitmacht warf er ins Meer, / ins Schilfmeer sind versenkt seine auserlesenen Krieger. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Die Fluten bedeckten sie, sie fuhren zur Tiefe wie Steine. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Deine Rechte, o Herr, herrlich in Kraft, / deine Rechte, o Herr, zerschmettert den Feind. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'In der Fülle deiner Hoheit wirfst du nieder die Gegner; / du lässest los deinen Grimm, er verzehrt sie wie Stoppeln. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Beim Schnauben deines Zorns türmten die Wasser sich hoch, / standen aufrecht wie ein Damm die Wogen, / erstarrten die Fluten mitten im Meer. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Der Feind sprach: \"Ich jage nach, hole ein, / verteile den Raub, sättige meine Gier; / ich zücke mein Schwert, meine Hand vertilgt sie.\" /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du bliesest darein mit deinem Hauch, und sie deckte das Meer; / sie versanken wie Blei in mächtigen Wassern. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer ist wie du, Herr, unter den Göttern? / wer ist wie du so hehr und heilig, / furchtbar in Ruhmestaten, Wunder verrichtend? /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du recktest aus deine Rechte, da verschlang sie die Erde. / (a) 4Mo 16:32');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Gnädig hast du geleitet das Volk, das du erlöst, / hast es machtvoll geführt zu deiner heiligen Wohnstatt. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Die Völker hörten\'s, und sie erbebten; / Angst ergriff Philistäas Bewohner. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Damals erschraken die Fürsten von Edom, / die Gewaltigen Moabs - Zittern ergriff sie. / Die Bewohner Kanaans verzagten zumal; /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'es überfiel sie Schrecken und Furcht, / ob der Gewalt deines Arms wurden sie starr wie Stein. / So zog hindurch dein Volk, o Herr, / zog hindurch das Volk, das du erworben. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du führtest sie hinein und pflanztest sie auf den Berg, der dein eigen, / an die Stätte, die du, Herr, zu deiner Wohnung gemacht hast, / in das Heiligtum, Herr, das deine Hände gegründet. /');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Der Herr ist König immer und ewig! (a) Ps 93:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn als die Rosse des Pharao mit seinen Wagen und Reitern ins Meer hineingingen, liess der Herr die Wasser des Meeres über sie zurückfluten, während die Israeliten im Trockenen mitten durch das Meer gezogen waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Da griff die Prophetin Mirjam, Aarons Schwester, zur Handpauke, und alle Frauen zogen hinter ihr her mit Handpauken und im Reigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam sang ihnen vor: Singet dem Herrn, denn hoch erhaben ist er; / Ross und Reiter warf er ins Meer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'DARNACH liess Mose die Israeliten vom Schilfmeer aufbrechen, und sie zogen nach der Wüste Sur und wanderten drei Tage in der Wüste, ohne dass sie Wasser fanden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Da kamen sie nach Mara; aber sie konnten das Wasser wegen seiner Bitterkeit nicht trinken, denn es war sehr bitter. Daher hiess man den Ort Mara. (1) d.i. Bitterquell. (a) 4Mo 33:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Nun murrte das Volk wider Mose und sprach: Was sollen wir trinken?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Er aber schrie zum Herrn, und der Herr wies ihm ein Holz; das warf er ins Wasser, und das Wasser wurde süss. Dort gab er ihm Satzung und Recht, und dort stellte er es auf die Probe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Und er sprach: Wenn du dem Herrn, deinem Gott, treulich gehorchst und tust, was vor ihm recht ist, wenn du auf seine Gebote hörst und alle seine Satzungen hältst, so will ich keine von den Krankheiten über dich bringen, die ich über Ägypten gebracht habe; denn ich, der Herr, bin dein Arzt. (a) 5Mo 7:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Dann kamen sie nach Elim; da waren zwölf Quellen mit Wasser und siebzig Palmen, und sie lagerten sich daselbst am Wasser. (a) 4Mo 33:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Darnach brachen sie von Elim auf, und die ganze Gemeinde Israels gelangte in die Wüste Sin, die zwischen Elim und dem Sinai liegt, am fünfzehnten Tage des zweiten Monats nach ihrem Auszug aus dem Lande Ägypten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Da murrte die ganze Gemeinde Israels wider Mose und Aaron in der Wüste. (a) 2Mo 17:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Die Israeliten sprachen zu ihnen: Wären wir doch durch die Hand des Herrn im Lande Ägypten gestorben, als wir bei den Fleischtöpfen sassen und Brot die Fülle zu essen hatten! Denn ihr habt uns in diese Wüste herausgeführt, um diese ganze Gemeinde Hungers sterben zu lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach der Herr zu Mose: Siehe, ich will euch Brot vom Himmel regnen lassen; dann mag das Volk hinausgehen und sich Tag für Tag seinen Bedarf sammeln. Damit will ich sie auf die Probe stellen, ob sie nach meiner Weisung wandeln wollen oder nicht. (a) Ne 9:15; Ps 78:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Wenn sie dann am sechsten Tage zubereiten, was sie heimbringen, so wird es doppelt soviel sein, als sie sonst täglich sammeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Nun sprachen Mose und Aaron zu allen Israeliten: Am Abend werdet ihr erkennen, dass es der Herr war, der euch aus dem Lande Ägypten herausgeführt hat,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'und am Morgen werdet ihr die Herrlichkeit des Herrn sehen; denn er hat euer Murren wider den Herrn gehört. Wir aber, was sind wir, dass ihr wider uns murrt?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Weiter sprach Mose: (Jenes wird geschehen,) wenn euch der Herr am Abend Fleisch zu essen gibt und am Morgen Brot die Fülle; denn der Herr hat euer Murren gehört, womit ihr wider ihn murrt. Wir aber, was sind wir? Euer Murren ist nicht wider uns, sondern wider den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Dann sprach Mose zu Aaron: Befiehl der ganzen Gemeinde Israels: \"Tretet vor den Herrn, denn er hat euer Murren gehört.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Als Aaron der ganzen Gemeinde Israels dies befahl, wandten sie sich nach der Wüste hin, und siehe, die Herrlichkeit des Herrn erschien in der Wolke. (a) 2Mo 24:16; 4Mo 14:10; 16:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und der Herr sprach zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe das Murren der Israeliten gehört. Sprich zu ihnen also: \"Um die Abendzeit werdet ihr Fleisch zu essen bekommen und am Morgen Brot die Fülle, damit ihr erkennet, dass ich, der Herr, euer Gott bin.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und es kam so: am Abend zogen Wachteln heran und bedeckten das Lager, und am Morgen lag der Tau rings um das Lager her. (a) 4Mo 11:31; Ps 78:27; 105:40');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und als der Taunebel aufgestiegen war, siehe, da lag auf dem Boden der Wüste etwas Feines, Körniges, fein wie der Reif auf der Erde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Als die Israeliten es sahen, sprachen sie zueinander: Was ist dies? Denn sie wussten nicht, was es war. Da sprach Mose zu ihnen: Das ist das Brot, das euch der Herr zu essen gibt. (1) hebr: [man hu], Anspielung auf das Wort Manna hebr: [man]');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Und das ist\'s, was der Herr gebietet: Sammelt davon, ein jeder, so viel er braucht; einen Gomer auf den Kopf sollt ihr nehmen, nach der Zahl eurer Seelen, ein jeder für seine Zeltgenossen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Israeliten taten so und sammelten, der eine mehr, der andre weniger.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Als man es aber mit dem Gomer mass, da hatte der, der viel gesammelt hatte, keinen Überschuss, und der, der wenig gesammelt hatte, keinen Mangel; ein jeder hatte gesammelt, so viel er brauchte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Dann sprach Mose zu ihnen: Niemand hebe etwas davon bis zum Morgen auf!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie gehorchten Mose nicht, sondern etliche hoben bis zum Morgen davon auf; da verfaulte es und wurde voller Würmer und stinkend. Mose aber ward zornig über sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Und sie sammelten es alle Morgen, ein jeder, so viel er brauchte; wenn aber die Sonne heiss schien, schmolz es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Und am sechsten Tage sammelten sie doppelt soviel Brot, zwei Gomer für jeden einzelnen. Da kamen alle Stammeshäupter der Gemeinde und berichteten es Mose.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Der sprach zu ihnen: Das ist es, was der Herr befohlen hat: Morgen ist ein Feiertag, ein dem Herrn geweihter Ruhetag. Was ihr backen wollt, das backt, und was ihr kochen wollt, das kocht; was aber übrigbleibt, das legt beiseite, um es bis zum Morgen aufzuheben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie legten es bis zum Morgen beiseite, wie Mose geboten hatte, und es ward nicht stinkend, und es entstanden keine Würmer darin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sprach Mose: Esst das heute; denn heute ist ein dem Herrn geweihter Ruhetag, heute werdet ihr auf dem Felde nichts finden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr es sammeln, aber am siebenten ist ein Ruhetag, da gibt es keines.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Am siebenten Tage aber gingen etliche hinaus, um zu sammeln, doch sie fanden nichts.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sprach der Herr zu Mose: Wie lange weigert ihr euch, meine Gebote und Weisungen zu halten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Seht, der Herr hat euch den Ruhetag gegeben; darum gibt er euch am sechsten Tage Brot für zwei Tage. So bleibe denn ein jeder daheim, niemand verlasse am siebenten Tage seine Wohnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Also feierte das Volk am siebenten Tage.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Und die Israeliten nannten es Manna. Es war weiss wie Koriandersamen und hatte einen Geschmack wie Honigkuchen. (a) 4Mo 11:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Mose sprach: Dies ist\'s, was der Herr gebietet: Einen Gomer voll sollt ihr davon für eure künftigen Geschlechter aufbehalten, damit sie das Brot sehen, mit dem ich euch in der Wüste gespeist habe, als ich euch aus dem Lande Ägypten herausführte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Dann sprach Mose zu Aaron: Nimm einen Krug, tue einen Gomer voll Manna darein und stelle ihn vor den Herrn, damit er für eure künftigen Geschlechter aufbehalten werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, '(Und man tat,) wie der Herr dem Mose geboten hatte, und Aaron stellte es vor das Gesetz zur Aufbewahrung. (a) 2Mo 25:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Die Israeliten aber assen das Manna vierzig Jahre lang, bis sie in bewohntes Land kamen; bis sie an die Grenze des Landes Kanaan kamen, assen sie das Manna. (a) Jos 5:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Der Gomer ist der zehnte Teil des Epha.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Darnach brach die ganze Gemeinde Israels nach dem Befehl des Herrn aus der Wüste Sin auf (und zog weiter,) von Station zu Station, und sie lagerten sich in Rephidim; aber da war kein Wasser für das Volk zum Trinken. (a) 4Mo 33:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Da haderte das Volk mit Mose und sprach: Schaffe uns Wasser, dass wir zu trinken haben! Mose erwiderte ihnen: Was hadert ihr mit mir? Warum versucht ihr den Herrn?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Als nun das Volk daselbst nach Wasser dürstete, murrte es wider Mose und sprach: Warum hast du uns aus Ägypten heraufgeführt, um uns und unsre Kinder und unsre Herden vor Durst umkommen zu lassen? (a) 4Mo 20:2-4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da schrie Mose zum Herrn und sprach: Was soll ich mit diesem Volke anfangen? Es fehlt nicht viel, so steinigen sie mich. (a) 4Mo 14:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Der Herr antwortete Mose: Ziehe vor dem Volke einher und nimm etliche von den Ältesten Israels mit dir; auch deinen Stab, mit dem du den Nil geschlagen hast, nimm zur Hand und gehe (a) 2Mo 7:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'zu dem Felsen am Horeb; siehe, ich werde daselbst vor dich treten. Dann schlage an den Felsen, so wird Wasser hervorströmen, und das Volk hat zu trinken. Und Mose tat so vor den Augen der Ältesten Israels. (a) 4Mo 20:11; Ps 78:15; 105:41');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Und man nannte den Ort Massa und Meriba, weil die Israeliten gehadert und weil sie den Herrn versucht hatten, indem sie sprachen: Ist der Herr in unsrer Mitte oder nicht? (1) d.i. Versuchung. (2) d.i. Hader.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Da kamen die Amalekiter und stritten wider Israel in Rephidim. (a) 5Mo 25:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Mose sprach zu Josua: Erwähle dir Männer und ziehe morgen aus, wider die Amalekiter zu streiten. Ich aber will mich auf die Höhe des Hügels stellen mit dem Gottesstabe in der Hand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josua tat, wie Mose ihm befohlen hatte: er zog aus, wider die Amalekiter zu streiten; Mose aber und Aaron und Hur stiegen auf die Höhe des Hügels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Solange nun Mose seine Arme hochhielt, hatte Israel die Oberhand; wenn er aber seine Arme sinken liess, hatte Amalek die Oberhand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Da jedoch die Arme Moses schwer wurden, nahmen sie einen Stein und legten denselben unter ihn, und er setzte sich darauf, während Aaron und Hur seine Arme stützten, der eine auf dieser, der andre auf jener Seite. So blieben seine Arme fest, bis die Sonne unterging.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Und Josua warf die Amalekiter und ihr Kriegsvolk nieder mit der Schärfe des Schwertes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Darnach sprach der Herr zu Mose: Schreibe dies zum Gedächtnis in ein Buch und schärfe es Josua ein: \"Ich will das Andenken Amaleks ganz und gar austilgen unter dem Himmel.\" (a) 4Mo 24:20; 5Mo 25:19; 1Sa 15:2 3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Mose baute einen Altar und nannte ihn \"Der Herr ist mein Panier\".');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Und er sprach: Die Hand an das Panier des Herrn! / Krieg hat der Herr mit Amalek / von Geschlecht zu Geschlecht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'JETHRO aber, der Priester der Midianiter, der Schwiegervater Moses, hörte, was Gott alles an Mose und seinem Volke Israel getan, dass der Herr die Israeliten aus Ägypten herausgeführt habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Da nahm Jethro, Moses Schwiegervater, die Zippora, das Weib Moses, die dieser zurückgesandt hatte, (a) 2Mo 2:21; 4:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'und ihre beiden Söhne. Der eine hiess Gersom, weil er gesagt hatte: ich bin Gast geworden in fremdem Lande; (1) vgl. Anm. zu 1Mo 29:32. (a) 2Mo 2:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'der andre hiess Elieser, weil (er gesagt hatte): Der Gott meines Vaters ist meine Hilfe gewesen und hat mich vor dem Schwert des Pharao errettet. (1) vgl. Anm. zu 1Mo 29:32.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jethro also, der Schwiegervater Moses, kam mit den Söhnen und dem Weibe Moses zu diesem in die Wüste, wo er sich gelagert hatte, an den Berg Gottes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Und er liess Mose sagen: Ich, dein Schwiegervater Jethro, komme zu dir mit deinem Weibe und ihren beiden Söhnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging Mose seinem Schwiegervater entgegen, verneigte sich und küsste ihn. Und als sie einander begrüsst hatten, gingen sie ins Zelt hinein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Da erzählte Mose seinem Schwiegervater alles, was der Herr dem Pharao und den Ägyptern um Israels willen angetan, von all der Mühsal, die sie auf dem Wege betroffen, und wie der Herr sie errettet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jethro aber freute sich über all das Gute, das der Herr für Israel getan, dass er sie aus der Hand der Ägypter errettet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gelobt sei der Herr, der euch aus der Hand der Ägypter und aus der Hand des Pharao errettet hat!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun weiss ich, dass der Herr grösser ist als alle Götter; denn ebendeshalb, weil die Ägypter so vermessen an ihnen handelten, hat er das Volk aus ihrer Hand errettet. (a) 2Mo 15:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Dann brachte Jethro, der Schwiegervater Moses, Gott Brandopfer und Schlachtopfer dar, und Aaron und alle Ältesten Israels kamen, um mit dem Schwiegervater Moses das Mahl vor Gott zu halten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Am andern Morgen setzte sich Mose hin, um dem Volke Recht zu sprechen, und die Leute traten vor Mose vom Morgen bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Als aber Moses Schwiegervater sah, was er alles mit dem Volk zu tun hatte, sprach er: Was machst du dir da mit dem Volk zu schaffen? Warum sitzest du allein (zu Gericht), während die Leute vom Morgen bis zum Abend vor dich treten?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose antwortete seinem Schwiegervater: Die Leute kommen zu mir, um Gott zu befragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Denn wenn sie eine Rechtssache haben, so kommen sie zu mir, und ich entscheide zwischen den Parteien und tue ihnen die Satzungen und Weisungen Gottes kund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sprach sein Schwiegervater zu ihm: Es ist nicht gut, wie du das machst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du wirst dich selbst und diese Leute, die bei dir sind, völlig erschöpfen; denn die Sache ist für dich zu schwer, du kannst sie nicht allein besorgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'So höre nun auf mich, ich will dir raten, und Gott wird mit dir sein. Sei du vor Gott der Anwalt für das Volk, und bringe du die Rechtssachen vor Gott;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'belehre sie über die Satzungen und Weisungen und zeige ihnen den Weg, auf dem sie wandeln, und die Werke, die sie tun sollen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Du aber erwähle dir aus dem ganzen Volke wackere und gottesfürchtige Männer, zuverlässige Leute, die sich nicht bestechen lassen, und mache sie zu ihren Vorgesetzten, zu Vorgesetzten über je tausend, je hundert, je fünfzig und je zehn, (a) 5Mo 1:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'damit sie dem Volke jederzeit Recht sprechen. Jede grosse Sache sollen sie vor dich bringen, jede kleine aber selbst entscheiden; so werden sie dir\'s leichter machen und dir tragen helfen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wenn du das tust und Gott es dir gebietet, so kannst du dabei bestehen, und auch alle diese Leute werden befriedigt heimgehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose hörte auf seinen Schwiegervater und tat alles, was er sagte:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Mose wählte wackere Männer aus ganz Israel und machte sie zu Häuptern über das Volk, zu Vorgesetzten über je tausend, je hundert, je fünfzig und je zehn,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'damit sie dem Volke jederzeit Recht sprächen; schwere Sachen sollten sie vor Mose bringen, kleine aber selbst entscheiden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Darauf entliess Mose seinen Schwiegervater, und dieser zog in seine Heimat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'IM dritten Monat nach dem Auszug der Israeliten aus dem Lande Ägypten, an diesem Tage kamen sie in die Wüste Sinai. (a) 4Mo 33:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sie brachen von Rephidim auf und kamen in die Wüste Sinai, und sie lagerten sich in der Wüste. Und Israel lagerte sich daselbst dem Berge gegenüber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mose aber stieg hinauf zu Gott. Und der Herr rief ihm vom Berge aus zu und sprach: So sollst du zum Hause Jakobs sprechen und den Söhnen Israels verkünden:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '\"Ihr habt selbst gesehen, was ich den Ägyptern getan und wie ich euch auf Adlersflügeln getragen und euch hierher zu mir gebracht habe. (a) 5Mo 29:2; 32:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Und nun, wenn ihr auf meine Stimme hört und meinen Bund haltet, so sollt ihr vor allen Völkern mein Eigentum sein; denn mein ist die ganze Erde. (a) 5Mo 5:2; Ps 24:1; 50:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Ihr sollt mir ein Königreich von Priestern werden und ein heiliges Volk.\" Das sind die Worte, die du den Israeliten sagen sollst. (a) 3Mo 19:2; 5Mo 7:6; Jes 61:6; 1Pe 2:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Da ging Mose hin, berief die Ältesten des Volkes und legte ihnen alle diese Worte vor, die der Herr ihm aufgetragen hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Und das ganze Volk antwortete einmütig: Alles, was der Herr befohlen hat, wollen wir tun. Und Mose überbrachte dem Herrn die Antwort des Volkes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Der Herr aber sprach zu Mose: Siehe, ich werde im dichten Gewölke zu dir kommen, damit das Volk es hört, wenn ich mit dir rede, und dir für immer vertraut. Und Mose verkündete dem Herrn die Antwort des Volkes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Da sprach der Herr zu Mose: Gehe hin zum Volke und ordne an, dass sie sich heute und morgen rein halten und ihre Kleider waschen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'und auf übermorgen bereit seien; denn übermorgen wird der Herr vor den Augen des ganzen Volkes auf den Berg Sinai herabfahren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Und ziehe eine Grenze rings um den Berg und sprich zu ihnen: Hütet euch, auf den Berg zu steigen oder auch nur seinen Saum zu berühren; denn wer den Berg berührt, der ist des Todes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Keine Hand soll ihn berühren; er soll gesteinigt oder erschossen werden; es sei Tier oder Mensch, er soll nicht am Leben bleiben! Wenn das Widderhorn ertönt, sollen sie den Berg hinansteigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Darauf stieg Mose vom Berge zum Volk hinab und befahl ihnen, sich rein zu halten, und sie wuschen ihre Kleider.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und er sprach zum Volke: Seid bereit auf übermorgen; keiner nahe sich einem Weibe!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Am dritten Tage aber, als es Morgen wurde, erhob sich ein Donnern und Blitzen, und eine schwere Wolke lag auf dem Berge, und mächtiger Posaunenschall ertönte, sodass das ganze Volk im Lager erschrak.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Da führte Mose das Volk aus dem Lager heraus, Gott entgegen, und sie stellten sich unten am Berge auf. (a) 5Mo 4:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Der Berg Sinai aber war ganz in Rauch gehüllt, weil der Herr im Feuer auf ihn herabgefahren war. Und der Rauch stieg von ihm auf wie von einem Schmelzofen, und der ganze Berg erbebte stark.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und der Posaunenschall wurde je länger je stärker: Mose redete, und Gott antwortete ihm im Donner.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Als nun der Herr auf den Berg Sinai herabgefahren war, auf die Spitze des Berges, rief er Mose auf die Spitze des Berges, und Mose stieg hinauf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Da sprach der Herr zu Mose: Steige hinab und warne das Volk, dass sie nicht zu dem Herrn vordringen, ihn zu sehen; sonst müssten viele unter ihnen umkommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Auch die Priester, die dem Herrn sich nahen dürfen, sollen sich rein halten, damit der Herr nicht eine Lücke reisse unter ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose aber sprach zum Herrn: Das Volk kann ja nicht auf den Berg Sinai steigen; denn du selbst hast uns gewarnt und gesagt: Ziehe eine Grenze um den Berg und erkläre ihn für heilig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Da sprach der Herr zu ihm: Geh, steige hinab und komm dann wieder herauf, du und Aaron mit dir; die Priester aber und das Volk sollen nicht vordringen, um zu dem Herrn heraufzusteigen, damit er nicht eine Lücke reisse unter ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Und Mose stieg zu dem Volke hinab und sagte es ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'UND Gott redete alle diese Worte und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin der Herr, dein Gott, der ich dich aus dem Lande Ägypten, aus dem Sklavenhause, herausgeführt habe; (a) Ps 81:11; Hos 13:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'du sollst keine andern Götter neben mir haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein Gottesbild machen, keinerlei Abbild, weder dessen, was oben im Himmel, noch dessen, was unten auf Erden, noch dessen, was in den Wassern unter der Erde ist; (a) 3Mo 26:1; Jes 40:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'du sollst sie nicht anbeten und ihnen nicht dienen; denn ich, der Herr, dein Gott, bin ein eifersüchtiger Gott, der die Schuld der Väter heimsucht bis ins dritte und vierte Geschlecht an den Kindern derer, die mich hassen, (a) 2 Mo 34:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'der aber Gnade übt bis ins tausendste Geschlecht an den Kindern derer, die mich lieben und meine Gebote halten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen des Herrn, deines Gottes, nicht missbrauchen; denn der Herr wird den nicht ungestraft lassen, der seinen Namen missbraucht. (a) 3Mo 19:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbattages, dass du ihn heilig haltest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und all dein Werk tun; (1) V. 9-10: 2Mo 23:12; 31:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'aber der siebente Tag ist ein Ruhetag, dem Herrn, deinem Gott, geweiht. Da sollst du keine Arbeit tun, weder du noch dein Sohn, noch deine Tochter, noch dein Sklave, noch deine Sklavin, noch dein Vieh, noch der Fremdling, der innert deiner Tore ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat der Herr Himmel und Erde gemacht und das Meer und alles, was in ihnen ist, und er ruhte am siebenten Tage; darum segnete der Herr den Sabbattag und heiligte ihn. (a) 1Mo 2:2; 2Mo 31:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Ehre deinen Vater und deine Mutter, auf dass du lange lebest in dem Lande, das der Herr, dein Gott, dir geben will. (a) 3Mo 19:3; Mt 15:4; Eph 6:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht töten. (a) 1Mo 9:6; 2Mo 21:12; Mt 5:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen. (a) 3Mo 20:10; Mt 5:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen. (a) 3Mo 19:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst nicht falsches Zeugnis reden wider deinen Nächsten. (a) 2Mo 23:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst nicht begehren nach dem Hause deines Nächsten: du sollst nicht begehren nach dem Weibe deines Nächsten, nach seinem Sklaven oder seiner Sklavin, nach seinem Rinde oder seinem Esel, nach irgend etwas, was dein Nächster hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Als aber das ganze Volk die Donnerschläge und Blitze, den Posaunenschall und den rauchenden Berg wahrnahm, da fürchtete sich das Volk und zitterte und blieb in der Ferne stehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Und sie sprachen zu Mose: Rede du mit uns, so wollen wir zuhören; aber Gott soll nicht mit uns reden, sonst müssen wir sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose aber sprach zum Volke: Fürchtet euch nicht; denn Gott ist nur gekommen, um euch auf die Probe zu stellen und damit die Furcht vor ihm euch gegenwärtig bleibe, auf dass ihr nicht sündiget.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'So blieb das Volk in der Ferne stehen, während Mose sich dem Wolkendunkel nahte, in dem Gott war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'DA sprach der Herr zu Mose: So sollst du zu den Israeliten sagen: Ihr habt gesehen, dass ich vom Himmel her mit euch geredet habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ihr sollt mir nichts an die Seite stellen: silberne und goldene Götter sollt ihr euch nicht machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar von Erde sollst du mir machen und darauf deine Brandopfer und Heilsopfer, deine Schafe und Rinder, opfern. An jeder Stätte, die ich für meine Anbetung bestimme, werde ich zu dir kommen und dich segnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Willst du mir aber einen Altar aus Steinen machen, so sollst du ihn nicht aus behauenen Steinen bauen; denn wenn du sie mit dem Eisen behaust, so entweihst du sie. (a) 5Mo 27:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Du sollst auch nicht auf Stufen zu meinem Altar emporsteigen, damit nicht deine Blösse vor ihm enthüllt werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Dies sind die Rechtssatzungen, die du ihnen vorlegen sollst:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Wenn du einen hebräischen Sklaven kaufst, soll er sechs Jahre dienen, im siebenten aber soll er ohne Entgelt freigelassen werden. (a) 3Mo 25:39; 5Mo 15:12: Jer 34:8-16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ist er allein gekommen, so soll er auch allein entlassen werden; war er aber verheiratet, so soll sein Weib mit ihm entlassen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hat ihm dagegen sein Herr ein Weib gegeben, und sie hat ihm Söhne oder Töchter geboren, so soll die Frau samt ihren Kindern ihrem Herrn gehören; er soll allein entlassen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Erklärt jedoch der Sklave: Ich habe meinen Herrn, mein Weib und meine Kinder lieb, ich will nicht freigelassen werden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'so führe ihn sein Herr vor Gott; er führe ihn an die Türe oder an den Türpfosten, und dort durchbohre ihm sein Herr das Ohr mit einem Pfriem, und dann ist er für immer sein Sklave.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Verkauft jemand seine Tochter als Sklavin, so soll sie nicht entlassen werden wie die Sklaven.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Gefällt sie ihrem Herrn nicht, nachdem er ihr beigewohnt hat, so soll er sie loskaufen lassen; doch ist er nicht befugt, sie an fremde Leute zu verkaufen, indem er treulos an ihr handelt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Bestimmt er sie aber für seinen Sohn, so soll er sie nach dem Töchterrecht ausstatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nimmt er sich noch eine andre (Frau), so soll er jener an der Nahrung, der Kleidung und dem ehelichen Umgang nichts entziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Erfüllt er an ihr diese drei (Pflichten) nicht, so wird sie ohne weiteres frei, ohne Lösegeld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Menschen schlägt, sodass er stirbt, der soll getötet werden. (a) 2Mo 20:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er ihm aber nicht nachgestellt, sondern hat Gott es so durch ihn gefügt, so will ich dir eine Stätte bestimmen, wohin er fliehen kann. (a) 4Mo 35:11; 5Mo 19:2-6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Doch wenn jemand an seinem Nächsten frevelt, indem er ihn hinterlistig mordet, so sollst du ihn von meinem Altar wegreissen, damit man ihn töte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater oder seine Mutter schlägt, der soll getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Menschen raubt - ob er ihn nun verkaufe, oder ob man ihn noch bei ihm finde -, der soll getötet werden. (a) 5Mo 24:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Wer seinem Vater oder seiner Mutter flucht, der soll getötet werden. (a) 3Mo 20:9; 5Mo 27:16; Spr 20:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Wenn Männer miteinander streiten und einer schlägt den andern mit einem Stein oder mit der Faust, sodass er zwar nicht stirbt, aber doch bettlägerig wird,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'so soll der Täter straflos bleiben, wenn jener wieder aufkommt und an seinem Stocke draussen umhergehen kann; nur soll er ihm vergüten, was er versäumt hat, und den Arzt bezahlen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Wenn jemand seinen Sklaven oder seine Sklavin mit dem Stocke schlägt, sodass sie ihm unter der Hand sterben, so soll er bestraft werden;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'bleiben sie aber noch einen oder zwei Tage am Leben, so soll er nicht bestraft werden, denn es ist sein Geld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn Männer miteinander raufen und sie verletzen dabei ein schwangeres Weib, sodass eine Fehlgeburt eintritt, aber kein (weiterer) Schaden entsteht, so soll es mit Geld gebüsst werden; was der Ehemann dem Täter auferlegt, das soll dieser geben für die Fehlgeburt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Entsteht aber ein (weiterer) Schaden, so sollst du geben Leben um Leben, (a) 3Mo 24:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand; Fuss um Fuss,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Wenn jemand seinen Sklaven oder seine Sklavin ins Auge schlägt und es zerstört, so soll er sie für das Auge freilassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Und wenn er seinem Sklaven oder seiner Sklavin einen Zahn ausschlägt, so soll er sie für den Zahn freilassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Wenn ein Rind einen Mann oder ein Weib stösst, sodass sie sterben, so soll man das Rind steinigen und sein Fleisch nicht essen; der Besitzer des Rindes aber bleibt straflos.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'War jedoch das Rind schon seit einiger Zeit stössig, und sein Besitzer ist gewarnt worden, und er hat es doch nicht gehütet, so soll man das Rind, wenn es einen Mann oder ein Weib tötet, steinigen, und auch sein Besitzer soll getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wird aber ein Sühnegeld auferlegt, so soll er als Lösegeld für sein Leben so viel zahlen, als man ihm auferlegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Nach dem gleichen Recht soll man mit ihm verfahren, wenn es einen Knaben oder ein Mädchen stösst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stösst das Rind einen Sklaven oder eine Sklavin, so soll der Besitzer ihrem Herrn dreissig Lot Silber zahlen, das Rind aber soll man steinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Wenn jemand eine Zisterne offen lässt, oder wenn jemand eine Zisterne gräbt und sie nicht zudeckt, und es fällt ein Rind oder ein Esel hinein,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so soll der Besitzer der Zisterne Ersatz leisten: Geld soll er dem Besitzer (des Tieres) bezahlen, das tote Tier aber gehört ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Rind das Rind eines andren stösst, sodass es stirbt, so sollen sie das lebende Rind verkaufen und den Erlös teilen, und auch das tote sollen sie teilen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'War es aber bekannt, dass das Rind schon seit einiger Zeit stössig war, und sein Besitzer hat es nicht gehütet, so soll er ein Rind für das andre erstatten, das tote aber gehört ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wenn jemand ein Rind oder ein Schaf stiehlt und es schlachtet oder verkauft, so soll er fünf Rinder für das eine Rind und vier Schafe für das eine Schaf erstatten. (1) Die Lutherbibel hat für 2.Mo. 22,1-31 die Zählung 2.Mo. 21,37; 22,1-30.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Wenn der Dieb beim Einbruch ertappt und totgeschlagen wird, so trifft den Täter keine Blutschuld.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Geschieht es aber nach Sonnenaufgang, so trifft ihn Blutschuld. Ersatz muss er leisten; hat er nichts, so soll er um den Wert des Gestohlenen verkauft werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Findet man das Gestohlene, es sei Rind oder Esel oder Schaf, noch lebend bei ihm, so soll er es doppelt erstatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Wenn jemand ein Feld oder einen Weinberg abweiden und sein Vieh dabei frei laufen lässt, sodass es auf dem Felde eines andern weidet, so soll er mit dem Besten (vom Ertrage) seines Feldes oder seines Weinbergs Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn Feuer ausbricht und Dorngestrüpp ergreift, und es wird so ein Garbenhaufen oder das Korn, das noch steht, oder das Feld zerstört, so soll der, der das Feuer angezündet hat, Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Wenn jemand einem andern Geld oder Kostbarkeiten zu verwahren gibt, und es wird diesem aus dem Hause gestohlen, so soll der Dieb, wenn man ihn findet, doppelten Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Findet man aber den Dieb nicht, so soll der Besitzer des Hauses vor Gott treten, (damit man sehe,) ob er sich nicht am Gute des andern vergriffen habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn es sich um Unterschlagung handelt, sei es eines Rindes, eines Esels, eines Schafes, eines Mantels oder sonst einer Sache, die verlorengegangen ist und die einer als Eigentum anspricht, so soll die Sache der beiden vor Gott kommen; wen Gott schuldig spricht, der soll dem andern doppelten Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Wenn jemand einem andern einen Esel, ein Rind, ein Schaf oder sonst ein Tier zu hüten gibt, und es stirbt oder bricht ein Bein, ohne dass es jemand sieht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'so soll zwischen den beiden ein Eid bei dem Herrn entscheiden, ob der Hüter sich nicht am Gute seines Nächsten vergriffen habe; dann muss der Besitzer es hinnehmen und (der andre) braucht nicht Ersatz zu leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Wird es ihm aber gestohlen, so soll er dem Besitzer Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wird es (von einem Raubtier) zerrissen, so soll er es als Beweis beibringen; dann braucht er das Zerrissene nicht zu ersetzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Wenn jemand von einem andern (ein Tier) entlehnt, und es bricht ein Bein oder stirbt, ohne dass der Besitzer dabei ist, so muss er Ersatz leisten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Ist aber der Besitzer dabei, so muss er nicht Ersatz leisten; ist es (um Geld) gemietet, so geht der Mietpreis dafür.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Wenn jemand eine Jungfrau, die noch nicht verlobt ist, verführt und ihr beiwohnt, so soll er den Brautpreis für sie zahlen und sie zum Weibe nehmen. (a) 5Mo 22:28 29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Weigert sich aber ihr Vater, sie ihm zu geben, so soll er doch Geld darwägen, soviel der Brautpreis für eine Jungfrau beträgt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Eine Zauberin sollst du nicht am Leben lassen. (a) 5Mo 18:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Ein jeder, der einem Tiere beiwohnt, soll getötet werden. (a) 3Mo 18:23; 5Mo 27:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Wer andern Göttern opfert, und nicht dem Herrn allein, der soll dem Bann verfallen. (a) 5Mo 17:2-5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Einen Fremdling sollst du nicht bedrücken noch bedrängen; ihr seid ja auch Fremdlinge gewesen in Ägypten. (a) 2Mo 23:9; 3Mo 19:33-34; 5Mo 10:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Witwen und Waisen sollt ihr nicht bedrücken. (a) Jes 1:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Wenn du sie doch bedrückst, und sie schreien zu mir, so werde ich ihr Schreien gewiss erhören,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'und mein Zorn wird entbrennen, und ich werde euch mit dem Schwerte töten, dass eure Frauen Witwen und eure Kinder Waisen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du (einem aus) meinem Volke Geld leihst, einem Armen neben dir, so handle an ihm nicht wie ein Wucherer; ihr sollt ihm keinen Zins auflegen. (a) 3Mo 25:36; 5Mo 23:19; Hes 22:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Wenn du den Mantel eines andern zum Pfande nimmst, so sollst du ihm denselben zurückgeben, ehe die Sonne untergeht; (a) 5Mo 24:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'ist er doch seine einzige Decke, die Hülle seines Leibes. Worauf sollte er sonst schlafen? Wenn er zu mir schreit, so werde ich ihn erhören; denn ich bin gnädig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Gott sollst du nicht lästern, und den Fürsten in deinem Volke sollst du nicht verfluchen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Die Fülle (deiner Tenne) und den Saft (deiner Kelter) sollst du nicht zurückbehalten. Deinen erstgeborenen Sohn sollst du mir geben. (a) 2Mo 13:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Ebenso sollst du es halten mit deinem Rind und deinem Schaf: sieben Tage mag es bei seiner Mutter bleiben, am achten Tage aber sollst du es mir geben. (a) 3Mo 22:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Ihr sollt mir heilige Leute sein: Fleisch von zerrissenen Tieren dürft ihr nicht essen; den Hunden sollt ihr es vorwerfen. (a) 3Mo 19:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst kein falsches Gerücht vorbringen. Du sollst dem Frevler nicht Beistand leisten, indem du als ungerechter Zeuge auftrittst. (a) 2Mo 20:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst nicht dem grossen Haufen folgen zum Bösen, und auch in deinem Zeugnis vor Gericht sollst du nicht dem grossen Haufen folgen, um das Recht zu beugen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Auch den Geringen sollst du in seiner Rechtssache nicht begünstigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn sich das Rind oder der Esel deines Feindes verirrt hat und du triffst sie an, so sollst du sie ihm wieder zuführen. (a) 5Mo 22:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du den Esel deines Feindes unter seiner Last erliegen siehst, so sollst du ihn nicht ohne Beistand lassen, sondern ihm aufhelfen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht des Armen in seinem Rechtshandel nicht beugen. (a) 5Mo 27:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Von betrügerischer Sache halte dich fern. Du sollst nicht den Unschuldigen, der im Rechte ist, zum Tode verurteilen, und nicht dem, der im Unrecht ist, Recht geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Bestechung sollst du nicht annehmen; denn die Bestechung macht Sehende blind und verdreht die Sache derer, die im Rechte sind. (a) 5Mo 16:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Einen Fremdling sollst du nicht bedrücken. Ihr wisst, wie dem Fremdling zumute ist; seid ihr doch auch Fremdlinge gewesen im Lande Ägypten. (a) 2Mo 22:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sechs Jahre sollst du dein Land bestellen und seinen Ertrag einsammeln. (1) V. 10-11: 3Mo 25:3-7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Im siebenten Jahre aber sollst du es brach liegen lassen und freigeben, damit die Armen deines Volkes sich davon nähren können; und was übrigbleibt, mag das Wild des Feldes fressen. Ebenso sollst du es mit deinem Weinberg und deinen Ölbäumen halten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du deine Arbeit tun, am siebenten Tage aber sollst du feiern, damit dein Rind und dein Esel ruhen und der Sohn deiner Sklavin und der Fremdling aufatmen können. (a) 2Mo 20:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Habt acht auf euch in allem, was ich euch befohlen habe! Den Namen andrer Götter sollst du nicht anrufen, und er soll aus deinem Munde nicht gehört werden. (a) Jos 23:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahre sollst du mir ein Fest feiern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du halten: sieben Tage sollst du ungesäuertes Brot essen, wie ich dir geboten habe, zur bestimmten Zeit im Ährenmonat; denn in diesem bist du aus Ägypten ausgezogen. Und man soll nicht mit leeren Händen vor meinem Angesicht erscheinen. (1) vgl. Anm. zu 2Mo 13:4. (a) 2Mo 12:17 19; 34:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Sodann das Fest der Kornernte, der Erstlinge vom Ertrage deiner Aussaat auf dem Felde, und das Fest der Lese am Ausgang des Jahres, wenn du deinen Ertrag vom Felde einsammelst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahre sollen alle deine Männer vor Gott dem Herrn erscheinen. (1) V. 17-19: 2Mo 34:23 26; 5Mo 16:16; 14:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst das Blut meines Schlachtopfers nicht zusammen mit Gesäuertem darbringen, und das Fett von meinem Festopfer soll nicht bis zum andern Morgen aufbehalten werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das Beste, die Erstlinge von deinem Acker, sollst du in das Haus des Herrn, deines Gottes, bringen. Du sollst ein Böcklein nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'SIEHE, ich sende einen Engel vor dir her, dich zu behüten auf dem Wege und dich an die Stätte zu bringen, die ich bestimmt habe. (a) 2Mo 32:34; 33:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Habe acht auf dich, ihm gegenüber, und höre auf seine Stimme, sei nicht widerspenstig gegen ihn; er wird eure Übertretung nicht vergeben, denn ich selber bin in ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Wenn du aber ernstlich auf ihn hörst und alles tust, was ich befehle, so will ich deiner Feinde Feind und der Bedränger deiner Bedränger sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Wenn nun mein Engel vor dir her zieht und dich zu den Amoritern, Hethitern, Pheresitern, Kanaanitern, Hewitern und Jebusitern bringt und ich sie vertilge,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'so sollst du ihre Götter nicht anbeten, noch ihnen dienen und nicht tun, wie jene tun, sondern niederreissen sollst du sie, und ihre Malsteine sollst du zerschlagen. (a) 2Mo 20:5; 3Mo 18:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Dem Herrn, eurem Gott, sollt ihr dienen, so werde ich dein Brot und dein Wasser segnen und alle Krankheit aus deiner Mitte hinwegnehmen. (a) 5Mo 7:13 15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Kein Weib wird fehlgebären oder unfruchtbar sein in deinem Lande; ich werde die Zahl deiner Tage voll machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Meinen Schrecken werde ich vor dir her senden und alle Völker, zu denen du kommst, in Verwirrung bringen, sodass alle deine Feinde vor dir fliehen. (a) 5Mo 11:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ich werde die Hornissen vor dir her senden, damit sie die Hewiter, Kanaaniter und Hethiter vor dir vertreiben. (a) 5Mo 7:20; Jos 24:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ich werde sie nicht in einem Jahre vor dir vertreiben, damit das Land nicht zur Wüste werde und nicht der wilden Tiere für dich zu viele werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Ganz allmählich werde ich sie vor dir vertreiben, bis du so zahlreich bist, dass du das Land besetzen kannst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und dein Gebiet soll reichen vom Schilfmeer bis zum Meere der Philister und von der Wüste bis zum (Euphrat-)Flusse. Ja, ich werde die Bewohner des Landes in deine Hand geben, und du wirst sie vor dir vertreiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du sollst mit ihnen und mit ihren Göttern kein Abkommen treffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Sie sollen nicht in deinem Lande wohnen bleiben, damit sie dich nicht zur Sünde wider mich verleiten; denn wenn du ihren Göttern dientest, so würde dir das zum Fallstrick werden. (a) 5Mo 7:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'UND zu Mose sprach er: Steiget herauf zum Herrn, du und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels, und betet an aus der Ferne. (a) 4Mo 11:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mose allein nahe sich dem Herrn, sie aber sollen sich nicht nahen, und das Volk soll nicht mit ihm heraufkommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Darnach kam Mose und berichtete dem Volke alle Gebote des Herrn und alle Rechtssatzungen. Da antwortete das ganze Volk einmütig und sprach: Alle Gebote, die der Herr gegeben hat, wollen wir halten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Da schrieb Mose alle Gebote des Herrn auf. Am andern Morgen aber in der Frühe errichtete er einen Altar unten am Berge und zwölf Malsteine nach der Zahl der zwölf Stämme Israels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Dann entbot er die jungen Männer unter den Israeliten, dem Herrn Brandopfer darzubringen und junge Stiere als Heilsopfer zu schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Und Mose nahm die eine Hälfte des Blutes und goss es in die Becken, die andre Hälfte des Blutes sprengte er auf den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Dann nahm er das Bundesbuch und las es dem Volke vor. Und sie sprachen: Alles, was der Herr geboten hat, wollen wir tun und darauf hören.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Darnach nahm Mose das Blut, besprengte das Volk damit und sprach: Seht, das ist das Blut des Bundes, den der Herr auf Grund all dieser Gebote mit euch geschlossen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Da stiegen Mose und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels hinauf,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'und sie schauten den Gott Israels: der Boden zu seinen Füssen war wie aus Saphirfliesen und klar wie der Himmel selbst. (a) Jes 6:1; Hes 1:26');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Wider die Vornehmen Israels aber reckte er seine Hand nicht aus; sie schauten Gott, assen und tranken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Da sprach der Herr zu Mose: Steige herauf zu mir auf den Berg und bleibe daselbst, dass ich dir die steinernen Tafeln gebe, die Gesetze und Gebote, die ich aufgeschrieben habe, sie zu unterweisen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Und Mose machte sich auf mit seinem Diener Josua und stieg auf den Berg Gottes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Zu den Ältesten aber sprach er: Bleibet ihr hier, bis wir zu euch zurückkommen. Seht, Aaron und Hur sind bei euch; wer eine Rechtssache hat, der wende sich an sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Als nun Mose auf den Berg kam, bedeckte die Wolke den Berg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit des Herrn thronte auf dem Berge Sinai, und die Wolke bedeckte den Berg sechs Tage lang; dann, am siebenten Tage, rief er Mose aus der Wolke heraus zu. (a) 2Mo 16:10; 4Mo 14:10; 16:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Die Herrlichkeit des Herrn aber war für die Augen der Israeliten anzusehen wie ein verzehrendes Feuer auf dem Gipfel des Berges. (a) 5Mo 4:24; Heb 12:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Da ging Mose mitten in die Wolke hinein. Und Mose stieg auf den Berg und blieb vierzig Tage und vierzig Nächte auf dem Berge. (a) 2Mo 34:28; 5Mo 9:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'UND der Herr sprach zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Sage den Israeliten, sie sollen eine Abgabe für mich erheben; von einem jeden, den sein Herz dazu treibt, sollt ihr die Abgabe für mich erheben. (a) 2Mo 35:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Dies aber sei die Abgabe, die ihr von ihnen erheben sollt: Gold, Silber und Erz;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Stoffe von blauem und rotem Purpur, von Karmesin, von Byssus und von Ziegenhaar;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'rotgefärbte Widderfelle, Seehundsfelle und Akazienholz;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öl für den Leuchter, Spezerei für das Salböl und das wohlriechende Räucherwerk;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Sohamsteine und (andre) Edelsteine zum Besatz des Ephod und des Brustschilds. (a) 2Mo 28:2-28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen mir ein Heiligtum machen, dass ich mitten unter ihnen wohne.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Genau nach dem Urbild der Wohnung und nach dem Urbild aller ihrer Geräte, das ich dir zeigen werde, so sollt ihr es machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Mache eine Lade aus Akazienholz, zwei und eine halbe Elle lang, anderthalb Ellen breit und anderthalb Ellen hoch; (a) 2Mo 37:1-24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'die sollst du mit reinem Gold überziehen, inwendig und auswendig sollst du sie überziehen, und oben ringsherum sollst du einen goldenen Kranz anbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Du sollst für sie auch vier goldene Ringe giessen und sie über ihren vier Füssen anbringen, und zwar zwei Ringe auf der einen und zwei Ringe auf der andern Seite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Auch Stangen von Akazienholz sollst du machen und sie mit Gold überziehen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'und die Stangen sollst du in die Ringe an den Seiten der Lade stecken, dass man sie daran tragen kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Die Stangen sollen in den Ringen der Lade bleiben, sie sollen nicht herausgezogen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'In die Lade aber lege das Gesetz, das ich dir geben werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Dann sollst du eine Deckplatte aus reinem Gold machen, zwei und eine halbe Elle lang und anderthalb Ellen breit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und du sollst zwei Cherube aus Gold machen; in getriebener Arbeit sollst du sie machen, an den beiden Enden der Deckplatte:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'stelle den einen Cherub an das eine Ende und den andern Cherub an das andre Ende; an den beiden Enden der Deckplatte sollst du die Cherube anbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Und die Cherube sollen ihre Flügel nach oben ausbreiten, indem sie mit ihren Flügeln die Deckplatte bedecken, während eines jeden Angesicht dem andern zugekehrt ist; der Deckplatte sollen die Gesichter der Cherube zugekehrt sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Und du sollst die Deckplatte oben auf die Lade legen und in die Lade das Gesetz tun, das ich dir geben werde. (a) 1Kön 8:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Daselbst will ich mit dir zusammenkommen, und von der Deckplatte aus, zwischen den zwei Cheruben hervor, die auf der Lade des Gesetzes stehen, will ich dir alles kundtun, was ich durch dich den Israeliten befehlen will. (a) 3Mo 16:2; 4Mo 7:89');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Du sollst auch einen Tisch aus Akazienholz machen, zwei Ellen lang, eine Elle breit und anderthalb Ellen hoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Den sollst du mit reinem Gold überziehen und daran ringsherum einen goldenen Kranz anbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Auch eine handbreite Leiste sollst du daran ringsherum anbringen und einen goldenen Kranz an der Leiste ringsherum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Ferner sollst du vier goldene Ringe für ihn machen und sie an die vier Ecken über seinen vier Füssen setzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht an der Leiste sollen die Ringe sein, dass man die Stangen darein stecken und so den Tisch tragen kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Die Stangen aber sollst du aus Akazienholz machen und sie mit Gold überziehen, und an ihnen soll der Tisch getragen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Du sollst auch die dazugehörigen Schüsseln und Schalen, Kannen und Becher machen, mit denen man das Trankopfer spendet; aus reinem Gold sollst du sie machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und auf den Tisch sollst du allezeit Schaubrote vor mich hinlegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Sodann sollst du einen Leuchter aus reinem Gold machen; in getriebener Arbeit soll der Leuchter gemacht werden, der Fuss und der Schaft; seine Kelche - Knoten mit Blumen - sollen aus einem Stück mit ihm sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sechs Röhren sollen von seinen Seiten ausgehen, drei Leuchterröhren auf der einen Seite und drei Leuchterröhren auf der andern Seite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Eine jede Röhre soll drei Kelche - Knoten mit Blumen - in der Form von Mandelblüten haben; so an allen sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Der Leuchter selbst aber soll vier Kelche - die Knoten mit den Blumen - in der Form von Mandelblüten haben,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'nämlich (einen Knoten an der Spitze, dann) einen Knoten unter dem (ersten) Röhrenpaar, ferner einen Knoten unter dem (zweiten) Röhrenpaar und noch einen Knoten unter dem (dritten) Röhrenpaar, also bei allen sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Die Knoten und Röhren sollen aus einem Stück mit ihm sein, alles aus einem Stück in getriebener Arbeit, aus reinem Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Ferner sollst du sieben Lampen für ihn machen und die Lampen auf ihn stellen, damit sie den Raum vor ihm erleuchten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Und die dazugehörigen Lichtscheren und Pfannen sollen von reinem Gold sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Talent reinen Goldes soll man ihn und alle diese Geräte machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und sieh zu, dass du alles genau nach dem Urbild machst, das dir auf dem Berge gezeigt werden soll. (a) 2Mo 25:9; 26:30; 27:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Die Wohnung aber sollst du machen aus zehn Teppichen von gezwirntem Byssus, blauem und rotem Purpur und Karmesin; mit Cheruben, wie sie der Kunstweber wirkt, sollst du sie machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Länge jedes Teppichs soll 28 Ellen sein, und die Breite jedes Teppichs vier Ellen; die Teppiche sollen alle dasselbe Mass haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fünf der Teppiche sollen aneinander gefügt sein, die fünf andern ebenso.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Dann sollst du am Saum des Teppichs zuäusserst an dem einen Stück Schleifen von blauem Purpur anbringen, und dasselbe sollst du tun am Saum des äussersten Teppichs an dem andern Stück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Fünfzig Schleifen sollst du an dem einen Teppich anbringen, und fünfzig Schleifen sollst du am Saum des Teppichs anbringen, der zum andern Stück gehört; die Schleifen sollen einander gegenüberstehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Dann sollst du fünfzig goldene Haken machen und mit den Haken die Teppiche aneinander heften, sodass die Wohnung ein Ganzes wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Ferner sollst du Teppiche aus Ziegenhaar machen, als Zeltdach über der Wohnung; elf solche Teppiche sollst du machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Länge jedes Teppichs soll dreissig Ellen sein, und die Breite jedes Teppichs vier Ellen; die elf Teppiche sollen alle dasselbe Mass haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fünf der Teppiche sollst du für sich aneinander fügen, und ebenso die sechs andern für sich, und den sechsten Teppich sollst du doppelt legen, auf der Vorderseite des Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Und du sollst am Saum des Teppichs zuäusserst an dem einen Stück fünfzig Schleifen anbringen, und ebenso fünfzig Schleifen am Saum des (äussersten) Teppichs an dem andern Stück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Dann sollst du fünfzig eherne Haken machen und die Haken in die Schleifen stecken und damit das Zeltdach zusammenfügen, sodass es ein Ganzes wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Von dem überschüssigen Rest an den Teppichen des Zeltes aber soll die Hälfte an der Rückwand der Wohnung überhängen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Und die Elle, die auf der einen, sowie die Elle, die auf der andern Seite an der Länge der Teppiche des Zeltes überschüssig ist, die sollen auf beiden Seiten der Wohnung überhängen, um sie zu bedecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Endlich sollst du für das Zeltdach eine Decke aus rotgefärbten Widderfellen machen und oben darüber eine Decke von Seehundfellen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Dann sollst du die Bretter für die Wohnung machen, aufrechtstehende, aus Akazienholz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Zehn Ellen soll die Länge des Brettes sein, und anderthalb Ellen die Breite jedes Brettes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Jedes Brett soll zwei Zapfen haben, die untereinander verbunden sind; das sollst du an allen Brettern der Wohnung machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Was aber die Zahl der Bretter für die Wohnung betrifft, so sollst du deren zwanzig für die südliche Seitenwand machen -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'auch vierzig silberne Füsse unter die zwanzig Bretter sollst du machen, je zwei Füsse unter ein Brett für seine beiden Zapfen -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'und ebenso für die andere, nördliche Seitenwand der Wohnung zwanzig Bretter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Und ihre vierzig Füsse sollen von Silber sein, je zwei Füsse unter einem Brett.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Für die hintere, westliche Wand der Wohnung aber sollst du sechs Bretter machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Und zwei Bretter sollst du machen für die Ecken der Wohnung auf der Hinterseite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Die sollen doppelt sein von unten auf, und gleichmässig sollen sie doppelt sein bis zum obern Ende, bis zum einen Ring, so sollen beide sein; sie sollen die beiden Ecken bilden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Es sollen also acht Bretter sein mit ihren silbernen Füssen, sechzehn Füssen, je zwei Füssen unter einem Brett.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Ferner sollst du Riegel aus Akazienholz machen: fünf für die Bretter der einen Seitenwand der Wohnung,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'und fünf Riegel für die Bretter der andern Seitenwand der Wohnung, und fünf Riegel für die Bretter der hintern, westlichen Wand der Wohnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Und der mittlere Riegel soll an der Mitte der Bretter durchlaufen, vom einen Ende bis zum andern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Die Bretter aber sollst du mit Gold überziehen und ihre Ringe, durch die man die Riegel steckt, aus Gold machen; und auch die Riegel sollst du mit Gold überziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'So sollst du die Wohnung aufrichten, in der Weise, wie es dir auf dem Berge gezeigt wurde. (a) 2Mo 25:40; 27:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Ferner sollst du einen Vorhang machen aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus; in Kunstweberarbeit soll man ihn machen, mit Cheruben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Den sollst du an vier Säulen aus Akazienholz aufhängen, die mit Gold überzogen sind, goldene Nägel haben und auf vier silbernen Füssen stehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Und zwar sollst du den Vorhang unten an die Haken hängen, und dort, innerhalb des Vorhangs, sollst du die Lade des Gesetzes aufstellen, sodass der Vorhang euch als Scheidewand zwischen dem Heiligen und dem Allerheiligsten dient.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Dann sollst du die Deckplatte auf die Lade des Gesetzes legen im Allerheiligsten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Den Tisch aber stelle ausserhalb des Vorhangs auf, und den Leuchter dem Tisch gegenüber auf der Südseite der Wohnung, während du den Tisch auf die Nordseite stellst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Endlich sollst du einen Vorhang machen für den Eingang des Zeltes, aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Buntweberarbeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und für den Vorhang sollst du fünf Säulen aus Akazienholz machen und sie mit Gold überziehen; auch ihre Nägel sollen von Gold sein. Und du sollst fünf eherne Füsse für sie giessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Dann sollst du den Altar machen aus Akazienholz, fünf Ellen lang und fünf Ellen breit; viereckig soll der Altar sein und drei Ellen hoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Und die Hörner sollst du an seinen vier Ecken anbringen; die Hörner sollen aus einem Stück mit ihm sein, und du sollst ihn mit Erz überziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Dann sollst du die dazugehörigen Töpfe machen, um die Asche zu entfernen, ferner die Schaufeln, Sprengschalen, Gabeln und Pfannen. Alle seine Geräte sollst du aus Erz machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Du sollst für ihn auch ein Gitterwerk machen, ein Netz aus Erz, und sollst an dem Netz vier eherne Ringe befestigen, an den vier Ecken des Altars;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'und zwar sollst du es unterhalb der Einfassung des Altars anbringen von unten auf, sodass das Netz bis zur halben Höhe des Altars reicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Auch sollst du Stangen machen für den Altar, Stangen aus Akazienholz, und sie mit Erz überziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Die Stangen sollen in die Ringe gesteckt werden, sodass sie zu beiden Seiten des Altars sind, wenn man ihn trägt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Aus Brettern sollst du ihn machen, sodass er inwendig hohl ist; wie es dir auf dem Berge gezeigt worden ist, so sollst du es machen. (a) 2Mo 25:40; 26:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Dann sollst du den Vorhof der Wohnung machen: auf der Südseite Umhänge für den Vorhof, aus gezwirntem Byssus, hundert Ellen lang für die eine Seite;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'der Säulen sollen zwanzig sein und der zugehörigen Füsse ebenfalls zwanzig, aus Erz, die Nägel der Säulen aber und die Querstangen aus Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Ebenso Umhänge auf der Nordseite der Länge nach, hundert Ellen lang, ferner die Säulen, zwanzig an der Zahl und die zugehörigen Füsse, zwanzig an der Zahl, aus Erz, die Nägel der Säulen aber und die Querstangen aus Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Der Breite nach aber, gegen Westen, soll der Vorhof fünfzig Ellen Umhänge haben; der zugehörigen Säulen seien zehn und der Füsse ebenfalls zehn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Auch vorn, gegen Osten, soll die Breite des Vorhofs fünfzig Ellen betragen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'und zwar sollen fünfzehn Ellen Umhänge mit den drei zugehörigen Säulen und den drei Füssen auf die eine Seite kommen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'und ebenso auf die andre Seite fünfzehn Ellen Umhänge mit den drei zugehörigen Säulen und den drei Füssen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Das Tor des Vorhofs aber soll einen Vorhang haben, zwanzig Ellen breit, aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Buntweberarbeit, dazu die vier Säulen mit ihren vier Füssen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen um den Vorhof her sollen silberne Querstangen und silberne Nägel, aber eherne Füsse haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Die Länge des Vorhofs soll hundert Ellen sein, die Breite fünfzig Ellen, die Höhe fünf Ellen, aus gezwirntem Byssus; und die zugehörigen Füsse sollen aus Erz sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Und alle Geräte der Wohnung für den ganzen Dienst in ihr und alle ihre Pflöcke und alle Pflöcke des Vorhofs sollen aus Erz sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Du aber gebiete den Israeliten, dass sie dir reines Öl aus zerstoßenen Oliven für den Leuchter bringen, damit man eine immerbrennende Lampe aufstecken kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im heiligen Zelte ausserhalb des Vorhangs, der vor (der Lade mit) dem Gesetz hängt, sollen Aaron und seine Söhne ihn herrichten, (dass er) vom Abend bis zum Morgen vor dem Herrn (brenne). Das ist für die Israeliten eine immerwährende, für alle Geschlechter gültige Verpflichtung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'DU aber lass nun aus der Mitte der Israeliten deinen Bruder Aaron und mit ihm seine Söhne zu dir herantreten, dass er mein Priester sei, nämlich Aaron samt seinen Söhnen Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und du sollst für deinen Bruder Aaron heilige Kleider machen zur Ehre und zur Zierde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Rede du mit allen, die kunstverständig sind, die ich mit dem Geist der Kunstfertigkeit erfüllt habe, dass sie die Kleider Aarons machen, damit man ihn weihe und er mein Priester sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Dies aber sind die Kleider, die sie machen sollen: Brusttasche, Ephod, Obergewand, Leibrock aus gewürfeltem Zeug, Kopfbund und Gürtel. So sollen sie für deinen Bruder Aaron und seine Söhne heilige Kleider machen, damit er mein Priester sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Und dazu sollen sie das Gold, die Zeuge von blauem und rotem Purpur, das Karmesin und den Byssus verwenden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Das Ephod sollen sie aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus machen, in Kunstweberarbeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Zwei (mit ihm) verbundene Schulterstücke soll es haben, an seinen beiden Enden soll es (mit ihnen) verbunden werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Die Binde an ihm aber, die dazu dient, es anzulegen, soll von der gleichen Arbeit und aus einem Stück mit ihm sein, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Dann sollst du die beiden Sohamsteine nehmen und die Namen der Söhne Israels darauf eingraben,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sechs Namen auf dem einen Stein und die sechs übrigen Namen auf dem andern Stein, nach der Reihenfolge ihrer Geburt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'In Steinschneiderarbeit, nach Art des Siegelstechers, sollst du auf den beiden Steinen die Namen der Söhne Israels eingraben; mit einem Geflecht von Gold sollst du sie einfassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Und die beiden Steine sollst du auf die Schulterstücke des Ephod heften, als Steine, (die dazu dienen,) dass der Israeliten gedacht werde; Aaron soll ihre Namen auf seinen beiden Schultern tragen vor dem Herrn, damit der Herr ihrer gedenke.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ferner sollst du Geflechte von Gold');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwei Ketten von reinem Gold machen; als Schnüre sollst du sie herstellen, wie man Stricke flicht, und sollst die geflochtenen Ketten an den Geflechten befestigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Dann sollst du eine Brusttasche für den Rechtsspruch machen, in Kunstweberarbeit; wie das Ephod gemacht ist, sollst du sie machen: aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus sollst du sie machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig soll sie sein, doppelt gelegt, eine Spanne lang und eine Spanne breit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und du sollst sie mit einem Besatz von Edelsteinen besetzen in vier Reihen von Steinen: in der ersten Reihe stehen nebeneinander ein Karneol, ein Topas und ein Smaragd;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'in der zweiten Reihe ein Rubin, ein Saphir und ein Jaspis;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'in der dritten Reihe ein Hyazinth, ein Achat und ein Amethyst;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'in der vierten Reihe ein Chrysolith, ein Soham und ein Onyx. In ein Geflecht von Gold gefasst sollen sie den Besatz bilden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und der Steine sollen nach den Namen der Söhne Israels zwölf sein, nach ihren Namen; in Siegelstecherarbeit soll auf jedem der Name eines der zwölf Stämme stehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Dann sollst du an der Brusttasche schnurartig geflochtene Ketten aus reinem Gold anbringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'und sollst an der Brusttasche zwei goldene Ringe anbringen; und zwar sollst du die zwei Ringe an die beiden Enden der Brusttasche setzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Darnach befestige die beiden goldenen Schnüre an den beiden Ringen an den Enden der Brusttasche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Die beiden andern Enden der zwei Schnüre aber befestige an den zwei Geflechten und hefte diese auf die Schulterstücke des Ephod auf dessen Vorderseite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Ferner sollst du (noch) zwei goldene Ringe machen und sie an den zwei Enden der Brusttasche auf ihrem innern, dem Ephod zugekehrten Rande befestigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Dann sollst du (noch) zwei goldene Ringe machen und sie unten an den beiden Schulterstücken des Ephod auf seiner Vorderseite anbringen, da wo es (mit ihnen) zusammengefügt ist, oberhalb der Binde des Ephod.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und man soll die Brusttasche mit ihren Ringen durch eine Schnur von blauem Purpur an die Ringe des Ephod festbinden, sodass sie an der Binde des Ephod anliegt, so kann die Brusttasche sich über dem Ephod nicht verschieben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Also soll Aaron, wenn er ins Heiligtum hineingeht, die Namen der Söhne Israels in der Brusttasche für den Rechtsspruch immer auf der Brust tragen, damit der Herr (ihrer) gedenke.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'In die Brusttasche für den Rechtsspruch aber sollst du die Urim und Thummim legen, damit sie auf der Brust Aarons liegen, wenn er hineingeht vor den Herrn; und so soll Aaron den Rechtsspruch für die Israeliten allezeit vor dem Herrn auf seiner Brust tragen. (a) 3Mo 8:8; 4Mo 27:21; 5Mo 33:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Und das Obergewand zum Ephod sollst du ganz aus blauem Purpur machen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'und in der Mitte soll die Öffnung für den Kopf sein. Rings um die Öffnung soll ein Saum laufen, in Weberarbeit; eine Öffnung wie die eines Panzers soll es haben, damit es nicht zerreisst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Und an seinem Saum sollst du Granatäpfel aus blauem und rotem Purpur und aus Karmesin anbringen, ringsum an seinem Saum; und zwischen denselben goldene Schellen, ringsum,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'sodass ringsum am Saum des Obergewandes je eine goldene Schelle und ein Granatapfel miteinander abwechseln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aaron soll es tragen beim heiligen Dienst, und man soll es klingen hören, wenn er im Heiligtum vor dem Herrn aus und ein geht, damit er nicht sterbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Du sollst auch ein Stirnblatt von reinem Gold machen und darauf nach Art des Siegelstechers eingraben: Dem Herrn geweiht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Und du sollst es mit einer Schnur von blauem Purpur am Kopfbund befestigen; vorn am Kopfbund soll es sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Und es soll auf der Stirne Aarons liegen, damit Aaron alles trage, womit sich die Israeliten verfehlen an den heiligen Dingen, die sie darbringen, an allen ihren heiligen Gaben. Es soll allezeit auf seiner Stirne liegen, damit es sie vor dem Herrn wohlgefällig mache.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Ferner sollst du den Leibrock machen, ein Gewebe aus Byssus in gewürfeltem Muster, und sollst einen Kopfbund aus Byssus anfertigen, und einen Gürtel sollst du machen in Buntweberarbeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Und für die Söhne Aarons sollst du Leibröcke machen und sollst Gürtel für sie machen, und hohe Mützen sollst du für sie machen zur Ehre und zur Zierde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und du sollst deinen Bruder Aaron und seine Söhne damit bekleiden und sollst sie salben und ihnen die Hand füllen und sie dadurch weihen, damit sie mir als Priester dienen. (1) Sinnbild der Einsetzung in die Priesterrechte. (a) 2Mo 29:9 24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und du sollst ihnen linnene Beinkleider machen, die Blösse zu bedecken; von den Hüften bis zu den Schenkeln sollen sie reichen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aaron und seine Söhne sollen sie tragen, wenn sie ins heilige Zelt hineingehen oder an den Altar treten, um den Dienst im Heiligtum zu tun, damit sie nicht Schuld auf sich laden und sterben müssen. Das ist für ihn und seine Nachkommen eine immerwährende Verpflichtung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Und dies ist\'s, was du mit ihnen tun sollst, um sie zu weihen, damit sie mir als Priester dienen: Nimm einen jungen Stier und zwei fehllose Widder,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ungesäuertes Brot und ungesäuerte, mit Öl eingerührte Kuchen, dazu ungesäuerte, mit Öl bestrichene Fladen; aus feinem Weizenmehl sollst du das alles machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Dann lege es in einen Korb und bringe es in dem Korbe dar, zugleich mit dem Stier und den zwei Widdern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Aaron aber und seine Söhne sollst du an den Eingang des heiligen Zeltes treten lassen und sie mit Wasser waschen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'dann nimm die Kleider, bekleide Aaron mit dem Leibrock, mit dem Obergewand zum Ephod, mit dem Ephod und der Brusttasche, und umgürte ihn mit der Binde des Ephod,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'setze ihm den Kopfbund auf das Haupt und hefte das heilige Diadem an den Kopfbund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Alsdann nimm das Salböl, giesse es ihm auf das Haupt und salbe ihn so.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Auch seine Söhne lass herzutreten und bekleide sie mit den Leibröcken,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'umgürte sie, Aaron und seine Söhne, mit Gürteln und setze ihnen die hohen Mützen auf, damit ihnen das Priesteramt als immerwährende Verpflichtung zufalle. Dann fülle Aaron und seinen Söhnen die Hand. (1) vgl. Anm. zu 2Mo 28:41.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Darnach sollst du den Stier herführen vor das heilige Zelt, und Aaron und seine Söhne sollen die Hand auf den Kopf des Stiers stützen. (a) 3Mo 1:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Hierauf schlachte den Stier vor dem Herrn, am Eingang des heiligen Zeltes,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'nimm von dem Blut des Stiers und streiche es mit dem Finger an die Hörner des Altars; alles (übrige) Blut aber schütte beim Altar auf den Boden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Dann nimm alles Fett, das die Eingeweide bedeckt, und den Lappen an der Leber, sowie die beiden Nieren mit dem Fett daran, und verbrenne es als Opfer auf dem Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Das Fleisch, die Haut und den Mist des Stiers aber sollst du draussen vor dem Lager verbrennen; denn es ist ein Sündopfer. (a) 3Mo 4:11 12; 8:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Darnach nimm den einen Widder, und Aaron und seine Söhne sollen die Hand auf den Kopf des Widders stützen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'dann schlachte den Widder, nimm sein Blut und sprenge es rings auf den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Den Widder aber zerlege in seine Stücke, wasche dann seine Eingeweide und Beine, lege dies zu den (übrigen) Stücken und zu dem Kopfe');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'und verbrenne den ganzen Widder als Opfer auf dem Altar; denn es ist ein Brandopfer für den Herrn, ein lieblicher Duft, ein Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Darnach nimm den andern Widder, und Aaron und seine Söhne sollen die Hand auf den Kopf des Widders stützen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'dann schlachte den Widder, nimm von seinem Blute und streiche es Aaron und seinen Söhnen an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses; das (übrige) Blut aber sprenge rings auf den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Dann nimm von dem Blut auf dem Altar und von dem Salböl und besprenge damit Aaron und seine Kleider und ebenso seine Söhne und ihre Kleider, so wird er samt seinen Kleidern geweiht und mit ihm auch seine Söhne samt ihren Kleidern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Dann nimm von dem Widder das Fett, den Fettschwanz und das Fett, das die Eingeweide bedeckt, den Lappen an der Leber und die beiden Nieren mit dem Fett daran, sowie die rechte Keule (denn es ist ein Einweihungswidder), (a) 3Mo 7:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'ferner einen Laib Brot, einen mit Öl zubereiteten Brotkuchen und einen Fladen aus dem Korbe mit dem Ungesäuerten, der vor dem Herrn steht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Das alles lege Aaron und seinen Söhnen in die Hände und schwinge es als Webeopfer vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Darnach nimm es ihnen wieder aus den Händen und verbrenne es auf dem Altar zu dem Brandopfer hinzu, als lieblichen Duft vor dem Herrn; denn es ist ein Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Hierauf nimm die Brust von dem Einweihungswidder Aarons und schwinge sie vor dem Herrn als Webeopfer; dann soll sie dir als Anteil zufallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Und du sollst die Webebrust und die Hebekeule von dem Einweihungswidder Aarons und seiner Söhne, (die Stücke,) die geschwungen und abgehoben worden sind, für heilig erklären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Und das soll für die Israeliten eine immerwährende Verpflichtung sein zugunsten Aarons und seiner Söhne; denn es ist ein Hebeopfer, und als Hebe von den Heilsopfern soll es von den Israeliten dargebracht werden, als ihr Hebeopfer für den Herrn. (a) 3Mo 7:34; 10:14; 4Mo 18:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Die heiligen Kleider Aarons aber sollen nach ihm an seine Söhne kommen, damit sie darin gesalbt und ins Priesteramt eingesetzt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sieben Tage hindurch soll sie derjenige unter seinen Söhnen anziehen, der an seiner Statt Priester wird, der in das heilige Zelt hineingehen wird, um den Dienst im Heiligtum zu tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du sollst aber den Einweihungswidder nehmen und sein Fleisch an heiliger Stätte kochen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aaron und seine Söhne sollen das Fleisch des Widders samt dem Brot, das in dem Korbe ist, am Eingang des heiligen Zeltes essen. (a) 3Mo 8:31');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Sie sollen aber das essen, womit die Sühne vollzogen wurde, als man sie ins Priesteramt einsetzte und weihte. Ein Fremder darf nicht davon essen, denn es ist heilig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Wenn aber etwas von dem Fleisch des Einweihungsopfers und von dem Brot bis zum Morgen übrigbleibt, so sollst du das Übriggebliebene verbrennen; es darf nicht gegessen werden, denn es ist heilig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'So sollst du es mit Aaron und seinen Söhnen halten, genau wie ich dir geboten habe. Sieben Tage soll die Einweihung dauern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Täglich sollst du einen Sündopferstier herrichten für die Sühnung und sollst den Altar entsündigen, indem du die Sühne an ihm vollziehst, und sollst ihn salben, um ihn zu weihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage sollst du die Sühne am Altar vollziehen und ihn weihen, so wird der Altar hochheilig. Jeder, der den Altar berührt, verfällt dem Heiligtum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Und dies ist\'s, was du auf dem Altar darbringen sollst: Tag für Tag zwei einjährige Lämmer als tägliches Brandopfer. (a) 4Mo 28:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Das eine Lamm sollst du am Morgen darbringen, das andre um die Abendzeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Und zu dem ersten Lamm gehört ein zehntel (Epha) Semmelmehl, eingerührt mit einem viertel Hin Öl von zerstossenen Oliven, und ein Trankopfer von einem viertel Hin Wein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Das andre Lamm aber sollst du um die Abendzeit darbringen - mit dem Speisopfer und Trankopfer sollst du es dabei halten wie am Morgen -, als lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, '(Das ist) das tägliche Brandopfer von Geschlecht zu Geschlecht, am Eingang des heiligen Zeltes vor dem Herrn, wo ich mit dir zusammenkommen will, um daselbst mit dir zu reden. (1) w: \"des Zeltes der Zusammenkunft\" (nämlich Gottes mit Mose oder dem Volke) zum Zweck der Offenbarung Vgl 2Mo 33:7 (a) 3Mo 1:1; 4Mo 12:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Dort will ich mit den Israeliten zusammenkommen, und es soll durch meine Herrlichkeit geheiligt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'So will ich das Zelt der Zusammenkunft und den Altar weihen, und Aaron und seine Söhne will ich weihen, dass sie mir als Priester dienen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und ich will inmitten der Israeliten wohnen und ihr Gott sein, (a) 2Mo 25:8; 3Mo 26:12; Off 21:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'damit sie erkennen, dass ich, der Herr, ihr Gott bin, der sie aus dem Lande Ägypten herausgeführt hat, um mitten unter ihnen zu wohnen, ich, der Herr, ihr Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Du sollst auch einen Altar machen zum Verbrennen von Räucherwerk; aus Akazienholz sollst du ihn machen. (a) 2Mo 37:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Eine Elle lang und eine Elle breit, viereckig soll er sein, und zwei Ellen hoch; seine Hörner sollen aus einem Stück mit ihm sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Und du sollst ihn mit reinem Gold überziehen, seine obere Fläche und seine Wände ringsum und auch seine Hörner; und ringsherum sollst du einen Kranz von Gold anbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Und zwei goldene Ringe sollst du unterhalb des Kranzes anbringen; an den beiden Ecken sollst du sie anbringen auf jeder der zwei Seiten, damit man die Stangen darein stecken kann, an denen er getragen wird.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen sollst du aus Akazienholz machen und sie mit Gold überziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und du sollst ihn vor den Vorhang stellen, der die Lade des Gesetzes verdeckt, vor die Deckplatte, die über dem Gesetze liegt, wo ich mit dir zusammenkommen will.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und Aaron soll darauf wohlriechendes Räucherwerk verbrennen, jeden Morgen, wenn er die Lampen herrichtet, soll er es verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Auch um die Abendzeit soll Aaron, wenn er die Lampen aufsteckt, es verbrennen, als tägliches Räucherwerk vor dem Herrn, von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr sollt darauf kein fremdes Räucherwerk darbringen, auch kein Brandopfer oder Speiseopfer; auch Trankopfer sollt ihr nicht darauf ausgiessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Und Aaron soll einmal im Jahr an den Altarhörnern die Sühne vollziehen; mit dem Blute des Sündopfers der Sühnung soll er einmal im Jahr an ihm die Sühne vollziehen, von Geschlecht zu Geschlecht; hochheilig ist er dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und der Herr sprach zu Mose: (a) 4Mo 1:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Zahl der Israeliten feststellst, derer, die gemustert werden, so soll ein jeder dem Herrn ein Lösegeld für sein Leben geben, damit nicht eine Plage über sie komme, wenn man sie mustert.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Und zwar soll ein jeder, der zu den Gemusterten gehört, ein halbes Lot Silber geben, nach heiligem Gewicht, das Lot Silber zu zwanzig Gera gerechnet; das halbe Lot Silber ist ein Hebeopfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Jeder, der zu den Gemusterten gehört, von zwanzig Jahren an und darüber, soll das Hebeopfer für den Herrn geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche soll nicht mehr und der Arme nicht weniger als das halbe Lot Silber geben, wenn ihr dem Herrn das Hebeopfer als Lösegeld für euer Leben darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und du sollst das Sühnegeld von den Israeliten erheben und es für den Dienst am heiligen Zelt verwenden, damit es als Lösegeld für euer Leben den Israeliten ein Gedenken bei dem Herrn erwirke.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Dann sprach der Herr zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du sollst auch einen ehernen Kessel mit einem ehernen Gestell machen zum Waschen; den sollst du zwischen dem heiligen Zelt und dem Altar aufstellen und Wasser darein tun, (a) 2Mo 38:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'und Aaron und seine Söhne sollen sich die Hände und die Füsse damit waschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie in das heilige Zelt hineingehen, sollen sie sich mit Wasser waschen, damit sie nicht sterben; ebenso, wenn sie zum Altar herantreten, um ihren Dienst zu tun, um Feueropfer für den Herrn zu verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Da sollen sie sich die Hände und die Füsse waschen, damit sie nicht sterben. Das soll für sie eine immerwährende Verpflichtung sein, für ihn und seine Nachkommen, von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Dann sprach der Herr zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Du aber nimm dir wohlriechende, auserlesene Spezerei: fünfhundert Lot vonselbst ausgeflossene Myrrhe, halb so viel Zimmet, also 250 Lot, ferner 250 Lot Würzrohr');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und fünfhundert Lot Kassia, nach heiligem Gewicht, dazu ein Hin Olivenöl,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'und mache daraus ein heiliges Salböl, ein Gemisch von Würzwerk, wie es der Salbenmischer bereitet; ein heiliges Salböl soll es sein. (a) 2Mo 37:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Damit sollst du das heilige Zelt und die Lade des Gesetzes salben, (a) 3Mo 8:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'den Tisch samt allen seinen Geräten, den Leuchter samt seinen Geräten und den Räucheraltar,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'ferner den Brandopferaltar samt allen seinen Geräten und den Kessel samt seinem Gestell.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'So sollst du sie weihen, damit sie hochheilig seien; ein jeder, der sie berührt, verfällt dem Heiligtum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Auch Aaron und seine Söhne sollst du salben und sie dadurch weihen, mir Priesterdienste zu tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Zu den Israeliten aber sollst du sprechen: Als heiliges Salböl soll euch dies gelten, von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf Menschenleiber soll es nicht gegossen werden, und ihr sollt auch keines in der gleichen Mischung herstellen; heilig ist es, als heilig soll es euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer (unbefugt) dergleichen mischt oder davon an einen Fremden bringt, der soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und der Herr sprach zu Mose: Nimm dir Spezerei: wohlriechendes Harz, Räucherklaue, Galbanum und reinen Weihrauch, von jedem gleich viel,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'und mache Räucherwerk daraus, ein Würzgemisch, wie es der Salbenmischer bereitet, gesalzen und rein, für den heiligen Gebrauch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und du sollst etwas davon fein zerstossen und davon in das heilige Zelt vor das Gesetz bringen, wo ich mit dir zusammenkommen will; als hochheilig soll es euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'In derselben Mischung aber, in der du das Räucherwerk herstellst, sollt ihr für euch selbst keines machen; als etwas dem Herrn Geweihtes soll es dir gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer dergleichen macht, um sich an seinem Wohlgeruch zu freuen, der soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Dann sprach der Herr zu Mose: (a) 2Mo 35:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Siehe, ich habe Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, mit Namen berufen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'und habe ihn mit göttlichem Geiste erfüllt, mit Weisheit, mit Verstand und mit Kenntnis in allerlei Arbeiten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'um Erfindungen zu ersinnen und sie auszuführen in Gold, Silber und Erz');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'und durch Bearbeitung von Edelsteinen zum Besetzen und durch Bearbeitung von Holz, um allerlei Werke herzustellen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Und siehe, ich habe ihm Oholiab, den Sohn Ahisamachs, vom Stamme Dan, beigegeben, und allen Kunstverständigen habe ich künstlerischen Sinn verliehen, damit sie alles machen, was ich dir geboten habe:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'das heilige Zelt, die Lade für das Gesetz, die Deckplatte darauf und alle Geräte des Zeltes,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'den Tisch mit seinen Geräten, den Leuchter aus reinem Gold mit allen seinen Geräten und den Räucheraltar,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Brandopferaltar mit allen seinen Geräten und den Kessel mit seinem Gestell,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'die gewirkten Kleider und die heiligen Kleider des Priesters Aaron und die Kleider seiner Söhne für den priesterlichen Dienst,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'das Salböl und das wohlriechende Räucherwerk für das Heiligtum. Genau, wie ich es dir geboten habe, sollen sie es machen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und der Herr sprach zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Rede mit den Israeliten und sage ihnen: Haltet nur ja meine Ruhetage! Denn das ist ein Zeichen zwischen mir und euch, von Geschlecht zu Geschlecht, damit man wisse, dass ich, der Herr, es bin, der euch heiligt. (a) 2Mo 20:8; 5Mo 5:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Darum haltet den Ruhetag; denn er muss euch heilig sein. Wer ihn entweiht, soll sterben; denn wer an ihm eine Arbeit verrichtet, dessen Seele soll aus seinen Volksgenossen ausgerottet werden. (a) 4Mo 15:32-36');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage darf man arbeiten; am siebenten Tage aber ist hoher Feiertag, dem Herrn geweiht. Wer am Sabbattag arbeitet, der soll sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Darum sollen die Israeliten den Ruhetag halten, indem sie den Ruhetag feiern von Geschlecht zu Geschlecht, als immerwährende Verpflichtung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Er ist für alle Zeiten ein Zeichen zwischen mir und den Israeliten. Denn in sechs Tagen hat der Herr den Himmel und die Erde gemacht; am siebenten Tage aber hat er geruht und sich erquickt. (a) 1Mo 2:2; 2Mo 20:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Und als er mit Mose auf dem Berge Sinai zu Ende geredet hatte, übergab er ihm die beiden Tafeln des Gesetzes, steinerne Tafeln, vom Finger Gottes beschrieben. (a) 5Mo 9:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'ALS aber das Volk sah, dass Mose so lange nicht vom Berge herabkam, sammelte es sich um Aaron und sprach zu ihm: Auf, mache uns einen Gott, der vor uns her ziehe; denn wir wissen nicht, was dem da zugestossen ist, dem Mose, dem Mann, der uns aus dem Lande Ägypten heraufgeführt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron sprach zu ihnen: Reisst die goldenen Ringe ab, die eure Frauen, eure Söhne und Töchter an den Ohren tragen, und bringt sie zu mir her.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da rissen sich alle Leute die goldenen Ringe ab, die sie an den Ohren trugen, und brachten sie zu Aaron.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Und er nahm (das Gold) aus ihrer Hand, goss es in eine Tonform und machte daraus ein gegossenes Kalb. Da sprachen sie: Das ist dein Gott, Israel, der dich aus dem Lande Ägypten heraufgeführt hat. (a) 1Kön 12:28; Ps 106:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Als Aaron das sah, baute er einen Altar vor demselben und liess ausrufen: Morgen ist ein Fest für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Und am andern Morgen in der Frühe opferten sie Brandopfer und brachten Heilsopfer dar; darnach setzte sich das Volk nieder, zu essen und zu trinken, und dann erhoben sie sich, um sich zu belustigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sprach der Herr zu Mose: Geh, steige hinab; denn dein Volk, das du aus dem Lande Ägypten heraufgeführt hast, frevelt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Gar bald sind sie von dem Wege abgewichen, den ich ihnen geboten habe. Sie haben sich ein gegossenes Kalb gemacht, haben es angebetet und ihm geopfert und gesagt: Das ist dein Gott, Israel, der dich aus dem Lande Ägypten heraufgeführt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Dann sprach der Herr zu Mose: Ich sehe, dass dieses Volk ein halsstarriges Volk ist. (a) 2Mo 33:3; Jes 48:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Und nun lass mich, dass mein Zorn wider sie entbrenne und ich sie vertilge; dich aber will ich zu einem grossen Volke machen. (a) 4Mo 14:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mose aber flehte den Herrn, seinen Gott, an und sprach: Ach Herr, warum entbrennt dein Zorn wider dein Volk, das du mit grosser Kraft und starker Hand aus dem Lande Ägypten herausgeführt hast? (a) Ps 106:23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Ägypter sagen: \"In böser Absicht hat er sie hinausgeführt, um sie im Gebirge umkommen zu lassen und sie vom Erdboden zu vertilgen\"? Lass ab von der Glut deines Zorns und lass dich das Unheil gereuen, das du über dein Volk bringen willst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke deiner Knechte Abraham, Isaak und Israel, denen du bei dir selbst geschworen und verheissen hast: Ich will eure Nachkommen so zahlreich machen wie die Sterne am Himmel, und dieses ganze Land, von dem ich gesprochen habe, will ich euren Nachkommen geben, und sie sollen es für immer besitzen. (a) 1Mo 12:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Da liess sich der Herr das Unheil gereuen, das er seinem Volke angedroht hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Darnach wandte sich Mose und stieg vom Berge herab, die beiden Gesetzestafeln in der Hand, Tafeln, die auf beiden Seiten beschrieben waren; vorn und hinten waren sie beschrieben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Die Tafeln waren Gottes Werk, und die Schrift war Gottesschrift, auf den Tafeln eingegraben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Als nun Josua das laute Geschrei des Volkes hörte, sprach er zu Mose: Es ist Kriegslärm im Lager.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Der aber antwortete: Das ist kein Geschrei von Siegern und kein Geschrei von Besiegten; lärmenden Gesang höre ich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Und als Mose sich dem Lager näherte und das Kalb und die Reigentänze sah, entbrannte sein Zorn, und er warf die Tafeln aus der Hand und zerschmetterte sie unten am Berge.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Dann nahm er das Kalb, das sie gemacht hatten, verbrannte es und zermalmte es zu Pulver, streute es auf Wasser und gab es den Israeliten zu trinken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Zu Aaron aber sprach Mose: Was hat dir dieses Volk getan, dass du eine so grosse Schuld über sie gebracht hast?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron erwiderte: Dein Zorn entbrenne nicht, o Herr; du weisst ja selbst, wie zügellos dieses Volk ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie sprachen zu mir: \"Mache uns einen Gott, der vor uns her ziehe; denn wir wissen nicht, was dem da zugestossen ist, dem Mose, dem Mann, der uns aus dem Lande Ägypten heraufgeführt hat.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Da sprach ich zu ihnen: \"Wer Goldschmuck trägt, der reisse ihn ab!\" Und sie gaben es mir, und ich warf es ins Feuer; da wurde dieses Kalb daraus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Als nun Mose sah, wie zügellos das Volk war (denn Aaron hatte ihm die Zügel schiessen lassen zur Schadenfreude seiner Widersacher),');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'trat er in das Tor des Lagers und rief: Her zu mir, wer zu dem Herrn hält! Da scharten sich um ihn alle Leviten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Und er sprach zu ihnen: So spricht der Herr, der Gott Israels: Gürte ein jeder sein Schwert an die Hüfte! Geht im Lager hin und her, von einem Tor zum andern, und tötet alles, Brüder, Freunde und Verwandte!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Und die Leviten taten, wie Mose ihnen befohlen hatte. So fielen an jenem Tage vom Volk an die dreitausend Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Und Mose sprach: Weiht euch heute dem Dienste des Herrn, ein jeder um den Preis seines Sohnes und seines Bruders, damit er heute Segen auf euch lege.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Am andern Morgen aber sprach Mose zum Volke: Ihr habt eine grosse Sünde begangen. So will ich denn zum Herrn hinaufsteigen; vielleicht kann ich Sühne schaffen für eure Sünde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Also ging Mose wieder zum Herrn und sprach: Ach, dieses Volk hat eine grosse Sünde begangen: sie haben sich einen Gott aus Gold gemacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun vergib ihnen doch ihre Sünde! Wo nicht, so tilge mich aus deinem Buche, das du geschrieben hast. (a) Ps 69:29');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Der Herr aber sprach zu Mose: Wer sich an mir versündigt, den tilge ich aus meinem Buche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'So gehe nun und führe das Volk dorthin, wohin ich dir gesagt habe. Siehe, mein Engel soll vor dir her gehen. Aber zu meiner Zeit will ich ihre Sünde an ihnen heimsuchen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Und der Herr brachte eine Plage über das Volk, dafür dass sie das Kalb angebetet, das Aaron gemacht hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'DARNACH sprach der Herr zu Mose: Geh, ziehe mit dem Volke, das du aus dem Lande Ägypten heraufgeführt hast, von hier hinauf in das Land, das ich Abraham, Isaak und Jakob zugeschworen habe, indem ich sprach: \"Deinen Nachkommen will ich es geben\" -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'und ich will einen Engel vor dir her senden und die Kanaaniter, Amoriter, Hethiter, Pheresiter, Hewiter und Jebusiter vertreiben -, (a) 2Mo 23:20; 32:34; Jos 24:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'in ein Land, das von Milch und Honig fliesst. Denn ich will nicht mit euch hinaufziehen, weil ihr ein halsstarriges Volk seid; ich könnte euch sonst unterwegs vertilgen. (a) 2Mo 32:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Als das Volk diese harte Rede hörte, wurde es betrübt, und niemand legte seinen Schmuck an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Da sprach der Herr zu Mose: Sage zu den Israeliten: Ihr seid ein halsstarriges Volk. Wenn ich nur einen Augenblick in eurer Mitte hinaufzöge, würde ich euch vertilgen. Und nun legt euren Schmuck von euch, dann will ich sehen, was ich für euch tun kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da taten die Israeliten ihren Schmuck von sich, vom Berge Horeb an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mose aber nahm jeweilen das Zelt und schlug es ausserhalb des Lagers in einiger Entfernung vom Lager für ihn auf, und er nannte es Zelt der Zusammenkunft. Wer nun den Herrn befragen wollte, der ging zum Zelt der Zusammenkunft hinaus, das ausserhalb des Lagers stand. (1) d.h. den Herrn. (2) vgl. Anm. zu 2Mo 29:42.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Und wenn Mose zu dem Zelt hinausging, erhob sich das ganze Volk, und jeder blieb am Eingang seines Zeltes stehen, und sie schauten Mose nach, bis er in das Zelt hineinging.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Und wenn Mose in das Zelt hineinging, kam die Wolkensäule herab und stellte sich an den Eingang des Zeltes, und er redete mit Mose. (1) d.h. der Herr. (a) 4Mo 11:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Wenn nun das ganze Volk die Wolkensäule am Eingang des Zeltes stehen sah, erhoben sie sich alle und warfen sich nieder, ein jeder am Eingang seines Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Der Herr aber redete mit Mose von Angesicht zu Angesicht, wie jemand mit seinem Freunde redet. Dann kehrte er zum Lager zurück, während sein Diener Josua, der Sohn Nuns, ein junger Mann, das Zelt nie verliess. (a) 4Mo 12:8; 5Mo 34:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Und Mose sprach zum Herrn: Siehe, du befiehlst mir, dieses Volk hinaufzuführen; doch hast du mich nicht wissen lassen, wen du mit mir senden willst, wo du doch gesagt hast: \"Ich kenne dich mit Namen, und du hast Gnade gefunden in meinen Augen.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Nun denn, wenn ich Gnade gefunden habe in deinen Augen, so lass mich doch deine Pläne wissen, damit ich dich erkenne, auf dass ich Gnade finde in deinen Augen; und bedenke doch, dass dieses Volk dein Volk ist. (a) Ps 103:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Er erwiderte: Mein Angesicht wird vor dir her gehen, und ich will dich zur Ruhe bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Er aber sprach zu ihm: Wenn nicht dein Angesicht mitgeht, so lass uns nicht von hier hinaufziehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Woran soll man denn sonst erkennen, dass ich und dein Volk Gnade gefunden haben in deinen Augen, wenn nicht daran, dass du mit uns gehst und dass ich und dein Volk so vor allen Völkern auf dem Erdboden ausgezeichnet werden?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da sprach der Herr zu Mose: Auch was du jetzt erbeten hast, will ich tun; denn du hast Gnade gefunden in meinen Augen, und ich kenne dich mit Namen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Er aber sprach: Lass mich doch deine Herrlichkeit schauen!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und er antwortete: Ich will all meine Pracht vor deinem Angesicht vorübergehen lassen und will den Namen des Herrn vor dir ausrufen: wem ich gnädig bin, dem bin ich gnädig, und wessen ich mich erbarme, dessen erbarme ich mich. (a) 2Mo 34:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Dann sprach er: Du kannst mein Angesicht nicht schauen, denn kein Mensch bleibt am Leben, der mich schaut. (a) 5Mo 4:12; Joh 1:18; 1Ti 6:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und der Herr sprach: Siehe, da ist Raum neben mir; tritt auf den Felsen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Wenn nun meine Herrlichkeit vorübergeht, will ich dich in eine Kluft des Felsens stellen und meine Hand schützend über dich breiten, bis ich vorüber bin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Und wenn ich dann meine Hand weghebe, darfst du mir nachschauen, aber mein Angesicht kann niemand sehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'UND der Herr sprach zu Mose: Haue dir zwei steinerne Tafeln zurecht, wie die ersten waren; dann will ich auf die Tafeln die Worte schreiben, die auf den ersten Tafeln standen, welche du zerschmettert hast. (a) 2Mo 32:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Und halte dich für morgen bereit, in der Frühe auf den Berg Sinai zu steigen und dort auf der Spitze des Berges vor mich zu treten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Es soll aber niemand mit dir hinaufsteigen und es soll auch niemand am ganzen Berg sich sehen lassen; sogar die Schafe und die Rinder dürfen nicht gegen diesen Berg hin weiden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Da hieb Mose zwei steinerne Tafeln zurecht, wie die ersten gewesen waren. Und am andern Morgen in der Frühe stieg er auf den Berg Sinai, wie ihm der Herr geboten hatte, und nahm die zwei steinernen Tafeln mit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da fuhr der Herr in der Wolke herab und trat daselbst neben ihn. Und als Mose den Namen des Herrn anrief,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'ging der Herr vor seinem Angesicht vorüber und rief: Der Herr, der Herr - ein barmherziger und gnädiger Gott, langmütig und reich an Huld und Treue, (a) 2Mo 33:19; Ne 9:17; Ps 103:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'der Gnade bewahrt bis ins tausendste Geschlecht, der Schuld und Missetat und Sünde verzeiht, aber nicht ganz ungestraft lässt, sondern die Schuld der Väter heimsucht an Kindern und Kindeskindern, bis ins dritte und vierte Geschlecht. (a) 2Mo 20:5 6; 4Mo 14:18; Jer 32:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Da verneigte sich Mose alsbald bis zur Erde, warf sich nieder');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'und sprach: Herr, habe ich Gnade gefunden in deinen Augen, so wollest du, o Herr, mitten unter uns einherziehen; denn es ist ein halsstarriges Volk. Vergib uns unsre Schuld und Sünde und mache uns zu deinem Eigentum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Er erwiderte: Siehe, ich schliesse einen Bund: vor deinem ganzen Volke will ich Wunder tun, dergleichen nicht gewirkt worden sind auf der ganzen Erde und unter allen Völkern, und das ganze Volk, unter dem du weilst, soll das Tun des Herrn sehen; denn furchtbar ist, was ich für dich tun werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Halte, was ich dir heute gebiete. Siehe, ich werde die Amoriter, Kanaaniter, Hethiter, Pheresiter, Hewiter und Jebusiter vor dir vertreiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich, mit den Bewohnern des Landes, in das du kommst, ein Abkommen zu treffen, damit sie dir nicht zum Fallstrick werden, wenn sie mit dir zusammen wohnen. (a) 2Mo 23:32 33');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Vielmehr sollt ihr ihre Altäre niederreissen, ihre Malsteine zerschlagen und ihre Ascheren umhauen; (a) 2Mo 23:24; 5Mo 7:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'denn du sollst keinen andern Gott anbeten. Denn eifersüchtig heisst der Herr, ein eifersüchtiger Gott ist er. (a) 2Mo 20:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Dass du mir ja nicht mit den Bewohnern des Landes ein Abkommen triffst! Denn wenn sie ihren Göttern sich hingeben und ihren Göttern opfern und dich dazu einladen, so könntest du von ihrem Opfer essen; (a) 4Mo 25:1 2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'auch könntest du Frauen für deine Söhne aus ihren Töchtern nehmen, und wenn dann ihre Töchter sich ihren Göttern hingeben, könnten sie deine Söhne verführen, sich auch ihren Göttern hinzugeben. (a) 5Mo 7:3 4; Ri 3:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Gegossene Gottesbilder sollst du dir nicht machen. (a) 2Mo 20:23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote sollst du halten. Sieben Tage sollst du ungesäuertes Brot essen, wie ich dir geboten habe, zur bestimmten Zeit im Ährenmonat; denn im Ährenmonat bist du aus Ägypten ausgezogen. (1) vgl. Anm. zu 2Mo 13:4. (a) 2Mo 12:18; 23:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alle Erstgeburt ist mein: all dein männliches Vieh, die Erstgeburt von Rind und Schaf. (a) 2Mo 13:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Die Erstgeburt vom Esel sollst du mit einem Lamm auslösen; willst du sie aber nicht auslösen, so brich ihr das Genick. Alle Erstgeburt unter deinen Söhnen sollst du auslösen. Und man soll nicht mit leeren Händen vor meinem Angesicht erscheinen. (a) 2Mo 13:13; 23:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage darfst du arbeiten; am siebenten Tage aber sollst du feiern, (auch) in der Zeit des Pflügens und der Ernte sollst du feiern. (a) 2Mo 20:9; 31:15; 35:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Und das Wochenfest sollst du halten, mit den Erstlingen der Weizenernte, und das Fest der Lese an der Wende des Jahres. (a) 2Mo 23:16-19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahre sollen alle deine Männer vor dem Herrn, dem Gott Israels, erscheinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Denn ich werde Völker vor dir vertreiben und dein Gebiet weit machen, und niemand soll nach deinem Lande begehren, während du, dreimal im Jahre, hinaufziehst, um vor dem Herrn, deinem Gott, zu erscheinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst das Blut meines Schlachtopfers nicht zusammen mit Gesäuertem darbringen und das Opfer des Passafestes soll nicht bis zum andern Morgen aufbehalten werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Das Beste, die Erstlinge von deinem Acker sollst du in das Haus des Herrn, deines Gottes, bringen. Du sollst ein Böcklein nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und der Herr sprach zu Mose: Schreibe dir diese Worte auf; denn auf Grund dieser Worte schliesse ich mit dir und mit Israel einen Bund.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er blieb daselbst bei dem Herrn vierzig Tage und vierzig Nächte, ohne Brot zu essen und Wasser zu trinken. Und er schrieb auf die Tafeln die Worte des Bundes, die zehn Worte. (a) 2Mo 24:18; 31:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Als Mose darnach vom Berge Sinai herabstieg (Mose hatte aber die beiden Tafeln des Gesetzes in der Hand, als er vom Berge herabstieg), da wusste er nicht, dass die Haut seines Antlitzes strahlend geworden war, während der Herr mit ihm redete.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Als nun Aaron und alle Israeliten Mose sahen, siehe, da strahlte die Haut seines Antlitzes; darum fürchteten sie sich, ihm zu nahen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Aber Mose rief sie heran; da wandten sich Aaron und alle Fürsten in der Gemeinde ihm wieder zu, und Mose redete mit ihnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Darnach traten alle Israeliten heran, und er trug ihnen alles auf, was der Herr mit ihm auf dem Berge Sinai geredet hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Als aber Mose aufhörte, mit ihnen zu reden, legte er eine Hülle auf sein Antlitz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Und wenn Mose hineinging vor den Herrn, um mit ihm zu reden, legte er die Hülle ab, bis er wieder herauskam; und wenn er herauskam, teilte er den Israeliten mit, was ihm befohlen war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Dann sahen die Israeliten, dass die Haut auf Moses Antlitz strahlte; Mose aber legte die Hülle wieder auf sein Antlitz, bis er hineinging, um mit ihm zu reden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'UND Mose versammelte die ganze Gemeinde Israels und sprach zu ihnen: Dies ist\'s, was der Herr zu tun geboten hat:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage darf man arbeiten; am siebenten Tage aber ist für euch hoher Feiertag, dem Herrn geweiht. Wer an ihm arbeitet, der soll sterben. (a) 2Mo 20:9; 31:15; 34:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Am Sabbattag sollt ihr in keiner eurer Wohnungen Feuer anzünden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Und Mose sprach zu der ganzen Gemeinde Israels: Dies ist\'s, was der Herr geboten hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Nehmt aus eurem Besitz eine Abgabe für den Herrn; ein jeder, den sein Herz dazu treibt, bringe sie her, die Abgabe für den Herrn: Gold, Silber und Erz; (1) V. 5-9: 2Mo 25:2-7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Stoffe von blauem und rotem Purpur, von Karmesin, von Byssus und von Ziegenhaaren;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'rotgefärbte Widderfelle, Seehundsfelle und Akazienholz;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Öl für den Leuchter und Spezerei für das Salböl und für das wohlriechende Räucherwerk;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Sohamsteine und (andre) Edelsteine zum Besatz des Ephod und der Brusttasche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und alle unter euch, die kunstverständig sind, mögen kommen und alles machen, was der Herr geboten hat:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'die Wohnung mit ihren Zeltwänden und ihrem Dach, ihren Haken, Brettern, Riegeln, Säulen und Füssen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade mit ihren Stangen, die Deckplatte und den verhüllenden Vorhang;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Stangen und allen seinen Geräten und den Schaubroten;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter mit seinen Geräten und Lampen und das Öl für den Leuchter;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Räucheraltar mit seinen Stangen, das Salböl, das wohlriechende Räucherwerk und den Türvorhang für den Eingang der Wohnung;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar mit seinem ehernen Gitterwerk, mit seinen Stangen und allen seinen Geräten und den Kessel mit seinem Gestell;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'die Umhänge des Vorhofs nebst seinen Säulen und Füssen und den Vorhang für das Tor des Vorhofs;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Pflöcke der Wohnung und die Pflöcke des Vorhofs nebst ihren Stricken;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die gewirkten Kleider für den Dienst im Heiligtum, die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne für den priesterlichen Dienst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Da ging die ganze Gemeinde Israels von Mose hinweg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Dann aber kamen sie, ein jeder, den sein Herz dazu trieb, ein jeder, dessen Geist willig war, und brachten die Abgabe für den Herrn zur Herstellung des heiligen Zeltes und für den ganzen Dienst darin und für die heiligen Kleider.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Männer wie Frauen kamen: alle, die ihr Herz dazu trieb, brachten Spangen, Ohrringe, Siegelringe und andern Schmuck, allerlei goldenes Geschmeide, auch alle, die dem Herrn eine Gabe von Gold geweiht hatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und alle, die blauen und roten Purpur, Karmesin, Byssus und Ziegenhaare, rotgefärbte Widderfelle und Seehundsfelle hatten, die brachten es herbei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Und wer eine Abgabe von Silber oder Erz entrichten wollte, der brachte die Abgabe für den Herrn herbei. Und wer Akazienholz hatte für alle die Arbeiten bei der Herstellung, der brachte es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle Frauen, die kunstverständig waren, spannen eigenhändig und brachten das Gesponnene: den blauen und roten Purpur, das Karmesin und den Byssus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und alle Frauen, die ihr Herz dazu trieb und die sich darauf verstanden, spannen Ziegenhaare.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Fürsten aber brachten die Sohamsteine und die (andern) Edelsteine zum Besatz des Ephod und der Brusttasche,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'ferner die Spezerei und das Öl für den Leuchter und zum Salböl und zu dem wohlriechenden Räucherwerk.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'So brachten die Israeliten dem Herrn freiwillige Gaben, alle Männer und Frauen, die ihr Herz dazu trieb, etwas zu bringen für alle die Arbeiten, deren Ausführung der Herr durch Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Da sprach Mose zu den Israeliten: Seht, der Herr hat Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, mit Namen berufen (1) V. 30-34: 2Mo 31:2-6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'und hat ihn mit göttlichem Geiste erfüllt, mit Weisheit, mit Verstand und mit Kenntnis in allerlei Arbeiten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'um Erfindungen zu ersinnen und sie auszuführen in Gold, Silber und Erz');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'und durch Bearbeitung von Edelsteinen zum Besetzen und durch Bearbeitung von Holz, um allerlei kunstvolle Arbeiten zu schaffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Er hat ihm auch die Gabe verliehen, (andere) zu unterweisen, ihm und Oholiab, dem Sohne Ahisamachs, vom Stamme Dan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie erfüllt mit künstlerischem Sinn, um allerlei Arbeiten zu schaffen, wie sie der Schmied und Zimmermann, der Kunstweber, der Buntweber in blauem und rotem Purpur, in Karmesin und Byssus, und der Weber schafft, indem sie allerlei Arbeiten ausführen und Erfindungen ersinnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Und nun sollen Bezaleel und Oholiab und alle kunstverständigen Männer, denen der Herr Weisheit und Verstand gegeben hat, sodass sie sich auf die Ausführung verstehen, alle Arbeiten für die Herstellung des Heiligtums ausführen, ganz so, wie es der Herr geboten hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Also berief Mose den Bezaleel und den Oholiab und alle kunstverständigen Männer, denen der Herr künstlerischen Sinn verliehen hatte, alle, die ihr Herz dazu trieb, sich an die Arbeit zu machen, um sie auszuführen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie empfingen von Mose die ganze Abgabe, welche die Israeliten für die Ausführung der Arbeiten zur Herstellung des Heiligtums gebracht hatten; man brachte ihm aber immer noch alle Morgen freiwillige Gaben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da kamen alle Künstler, die alle die Arbeiten für das Heiligtum ausführten, ein jeder von seiner Arbeit, die er gerade tat,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sprachen zu Mose: Die Leute bringen zuviel, mehr als für die Arbeiten nötig ist, die der Herr auszuführen geboten hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da liess Mose im ganzen Lager den Befehl ausrufen: Niemand, es sei Mann oder Weib, soll noch weiter etwas herstellen als Abgabe für das Heiligtum. So wurde den Leuten gewehrt, (noch mehr) zu bringen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'denn des Stoffes war genug und übergenug vorhanden, um alle Arbeiten auszuführen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So machten denn alle Kunstverständigen unter denen, die am Werke arbeiteten, die Wohnung aus zehn Teppichen von gezwirntem Byssus, blauem und rotem Purpur und Karmesin; mit Cheruben, wie sie der Kunstweber wirkt, machte man sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Länge jedes Teppichs war 28 Ellen und die Breite jedes Teppichs vier Ellen; die Teppiche hatten alle dasselbe Mass.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Und er fügte fünf Teppiche aneinander und die fünf andern ebenso.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Und er brachte am Saume des Teppichs zuäusserst an dem einen Stück Schleifen von blauem Purpur an, und dasselbe tat er am Saume des äussersten Teppichs an dem andern Stück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen brachte er an dem einen Teppich an, und fünfzig Schleifen brachte er am Saume des Teppichs an, der zum zweiten Stück gehörte, sodass die Schleifen einander gegenüberstanden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Dann machte er fünfzig goldene Haken und heftete die Teppiche mit den Haken aneinander, sodass die Wohnung ein Ganzes wurde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Ferner machte er Teppiche aus Ziegenhaar als Zeltdach über die Wohnung; elf solche Teppiche machte er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Die Länge jedes Teppichs war dreissig Ellen und die Breite jedes Teppichs vier Ellen; die elf Teppiche hatten alle dasselbe Mass.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Und er fügte fünf der Teppiche für sich aneinander und ebenso die sechs andern für sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Und er brachte am Saume des Teppichs zuäusserst an dem einen Stück fünfzig Schleifen an und ebenso fünfzig Schleifen am Saume des (äussersten) Teppichs an dem andern Stück.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Dann machte er fünfzig eherne Haken, um das Zeltdach zusammenzufügen, damit es ein Ganzes würde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Endlich machte er für das Zeltdach eine Decke aus rotgefärbten Widderfellen und oben darüber eine Decke aus Seehundsfellen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Dann machte er die Bretter für die Wohnung, aufrechtstehende, aus Akazienholz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Zehn Ellen war die Länge und anderthalb Ellen die Breite jedes Brettes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Jedes Brett hatte zwei Zapfen, die untereinander verbunden waren; das machte er an allen Brettern der Wohnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Was aber die Zahl der Bretter für die Wohnung betrifft, so machte er deren zwanzig für die südliche Seitenwand -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'auch machte er vierzig silberne Füsse unter die zwanzig Bretter, je zwei Füsse unter ein Brett für seine beiden Zapfen -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'und ebenso machte er für die andre, nördliche Seitenwand der Wohnung zwanzig Bretter;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'und ihre vierzig Füsse waren von Silber, je zwei Füsse unter einem Brett.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Für die hintere, westliche Wand der Wohnung aber machte er sechs Bretter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Und zwei Bretter machte er für die Ecken der Wohnung auf der Hinterseite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Die waren doppelt von unten auf, gleichmässig waren sie doppelt bis zum obern Ende, bis zu dem einen Ringe; so machte er sie beide für die beiden Ecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Es waren also acht Bretter mit ihren silbernen Füssen, sechzehn Füssen, unter jedem Brett zwei Füsse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Ferner machte er Riegel von Akazienholz, fünf für die Bretter der einen Seitenwand der Wohnung,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'und fünf Riegel für die Bretter der andern Seitenwand der Wohnung, und fünf Riegel für die Bretter der Wohnung auf der hintern, westlichen Wand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Den mittelsten Riegel aber machte er so, dass er an der Mitte der Bretter durchlief, vom einen Ende bis zum andern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Die Bretter überzog er mit Gold, und ihre Ringe, in die man die Riegel steckte, machte er aus Gold, und auch die Riegel überzog er mit Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Dann machte er den Vorhang aus Stoffen von blauem und rotem Purpur, Karmesin und gezwirntem Byssus; in Kunstweberarbeit machte er ihn, mit Cheruben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und er machte für denselben vier Säulen von Akazienholz und überzog sie mit Gold; auch ihre Nägel waren von Gold. Und er goss für sie vier silberne Füsse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Endlich machte er für den Eingang des Zeltes einen Vorhang aus Stoffen von blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Buntweberarbeit,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'und fünf Säulen für denselben nebst ihren Nägeln; und er überzog ihre Köpfe und Querstangen mit Gold. Die fünf Füsse aber waren von Erz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Dann machte Bezaleel die Lade aus Akazienholz, zwei und eine halbe Elle lang, anderthalb Ellen breit und anderthalb Ellen hoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Und er überzog sie inwendig und auswendig mit reinem Gold und brachte daran ringsherum einen goldenen Kranz an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Auch goss er für ihre vier Ecken vier goldene Ringe, und zwar zwei Ringe auf die eine und zwei Ringe auf die andre Seite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Und er machte Stangen aus Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Und er steckte die Stangen in die Ringe an den Seiten der Lade, dass man die Lade tragen konnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Dann machte er eine Deckplatte aus reinem Gold, zwei und eine halbe Elle lang und anderthalb Ellen breit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Auch machte er zwei Cherube aus Gold; in getriebener Arbeit machte er sie, an den beiden Enden der Deckplatte:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'den einen Cherub am einen Ende und den andern Cherub am andern Ende. An der Deckplatte brachte er die Cherube an, auf ihren beiden Enden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Die Cherube aber hielten ihre Flügel ausgebreitet nach oben, indem sie mit ihren Flügeln die Deckplatte bedeckten, während eines jeden Angesicht dem andern zugekehrt war; der Deckplatte also war das Angesicht der Cherube zugekehrt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Dann machte er den Tisch aus Akazienholz, zwei Ellen lang, eine Elle breit und anderthalb Ellen hoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Und er überzog ihn mit reinem Gold und brachte an ihm ringsherum einen goldenen Kranz an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Auch brachte er daran ringsherum eine handbreite Leiste an, und einen goldenen Kranz an der Leiste ringsherum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Ferner goss er für ihn vier goldene Ringe und setzte sie an die vier Ecken über seinen vier Füssen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'dicht an der Leiste waren die Ringe, dass man die Stangen darein stecken und so den Tisch tragen konnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Die Stangen aber machte er aus Akazienholz und überzog sie mit Gold, den Tisch daran zu tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Er machte auch die Geräte auf dem Tisch, seine Schüsseln und Schalen, Becher und Kannen, mit denen man das Trankopfer spendet - (alles) aus reinem Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Sodann machte er den Leuchter aus reinem Gold, in getriebener Arbeit machte er den Leuchter, den Fuss und den Schaft; die Kelche - Knoten mit Blumen - waren aus einem Stück mit ihm.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sechs Röhren gingen von seinen Seiten aus, drei Leuchterröhren auf der einen Seite und drei Leuchterröhren auf der andern Seite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'An jeder Röhre waren drei Kelche - Knoten mit Blumen - in der Form von Mandelblüten; so an allen sechs Röhren, die von dem Leuchter ausgingen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'An dem Leuchter selbst aber waren vier Kelche - die Knoten mit den Blumen - in der Form von Mandelblüten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'nämlich (ein Knoten an der Spitze, dann) ein Knoten unter dem (ersten) Röhrenpaar, ferner ein Knoten unter dem (zweiten) Röhrenpaar und noch ein Knoten unter dem (dritten) Röhrenpaar, so bei allen sechs Röhren, die von dem Leuchter ausgingen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knoten und Röhren waren aus einem Stück mit ihm, alles aus einem Stück in getriebener Arbeit, aus reinem Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Er machte auch die sieben Lampen für ihn nebst den dazugehörigen Lichtscheren und Pfannen aus reinem Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Talent reinen Goldes machte er ihn und alle seine Geräte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Dann machte er den Räucheraltar aus Akazienholz, eine Elle lang und eine Elle breit, viereckig, und zwei Ellen hoch; seine Hörner waren aus einem Stück mit ihm. (a) 2Mo 30:1-10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Er überzog ihn mit reinem Gold, seine Deckplatte und seine Wände ringsum und auch seine Hörner; und er machte daran ringsherum einen Kranz von Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Und unterhalb des Kranzes brachte er zwei goldene Ringe an, an den beiden Ecken auf jeder der zwei Seiten, um die Stangen darein zu stecken, an denen man ihn tragen konnte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Die Stangen machte er aus Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Auch machte er das heilige Salböl und das reine, wohlriechende Räucherwerk, wie es der Salbenmischer bereitet. (a) 2Mo 30:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Darnach machte er den Brandopferaltar aus Akazienholz, fünf Ellen lang und fünf Ellen breit, viereckig, und drei Ellen hoch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Und er brachte seine Hörner an den vier Ecken an - die Hörner waren aus einem Stück mit ihm - und überzog ihn mit Erz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Dann machte er alle Geräte für den Altar: die Töpfe, Schaufeln, Sprengschalen, Gabeln und Pfannen; alle seine Geräte machte er aus Erz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Auch fertigte er für den Altar ein Gitterwerk an, ein Netz aus Erz, unterhalb der Einfassung, von unten auf bis zur halben Höhe,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'und goss vier Ringe für die vier Ecken des ehernen Gitterwerks, um die Stangen hineinzustecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Die Stangen machte er aus Akazienholz und überzog sie mit Erz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Dann steckte er die Stangen in die Ringe an den Seiten des Altars, dass man ihn daran tragen konnte. Er machte ihn aus Brettern, sodass er inwendig hohl war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Ferner machte er den Kessel aus Erz und auch sein Gestell aus Erz, aus den Spiegeln der dienenden Frauen, die am Eingang des heiligen Zeltes Dienst taten. (a) 2Mo 30:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Hierauf machte er den Vorhof: auf der Südseite die Umhänge für den Vorhof, aus gezwirntem Byssus, hundert Ellen lang,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'nebst ihren zwanzig Säulen und den dazugehörigen zwanzig Füssen aus Erz, die Nägel der Säulen aber und ihre Querstangen aus Silber;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'ebenso hundert Ellen auf der Nordseite mit den zwanzig Säulen und zwanzig Füssen aus Erz und den Nägeln und Querstangen der Säulen aus Silber;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'auf der Westseite aber fünfzig Ellen Umhänge mit ihren zehn Säulen und den dazugehörigen zehn Füssen und den Nägeln und Querstangen der Säulen aus Silber,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'und auf der vordern, östlichen Seite fünfzig Ellen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'fünfzehn Ellen Umhänge mit ihren drei Säulen und den dazugehörigen drei Füssen auf die eine Seite');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und ebenso auf die andre Seite; zu beiden Seiten des Vorhoftors waren fünfzehn Ellen Umhänge mit ihren drei Säulen und den dazugehörigen drei Füssen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Umhänge des Vorhofs ringsum waren von gezwirntem Byssus,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'die Füsse der Säulen aus Erz, ihre Nägel aus Silber und der Überzug ihrer Köpfe aus Silber, und alle Säulen des Vorhofs waren durch silberne Querstangen verbunden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Der Vorhang für das Tor des Vorhofs aber war Buntweberarbeit aus Stoffen von blauem und rotem Purpur, Karmesin und gezwirntem Byssus, zwanzig Ellen lang und fünf Ellen hoch, entsprechend der Breite (des Stoffes), wie bei den Umhängen des Vorhofs;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'die dazugehörigen vier Säulen und ihre vier Füsse waren aus Erz, die Nägel aus Silber und auch der Überzug ihrer Köpfe und ihre Querstangen aus Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle Pflöcke der Wohnung und des Vorhofs ringsum aber waren aus Erz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Es folgt nun die Berechnung für die Wohnung, die Wohnung des Gesetzes, wie sie nach dem Befehle Moses vorgenommen wurde, sie wurde besorgt durch die Leviten unter der Leitung Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bezaleel aber, der Sohn Uris, des Sohnes Hurs, vom Stamme Juda, machte alles, was der Herr dem Mose geboten hatte, (a) 2Mo 31:1-11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, der Sohn Ahisamachs, vom Stamme Dan, als Schmied und Zimmermann und als Kunstweber und Buntweber in blauem und rotem Purpur, in Karmesin und Byssus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, das für das Werk bei allen Arbeiten am Heiligtum verarbeitet wurde, alles Gold, das als Weihegabe gespendet wurde, wog 29 Talente und 730 Lot nach heiligem Gewicht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Das Silber aber von den Gemusterten der Gemeinde wog hundert Talente und 1 775 Lot nach heiligem Gewicht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'ein halbes Lot auf den Kopf, die Hälfte eines Lots nach heiligem Gewicht, von allen, die gemustert wurden, von zwanzig Jahren an und darüber, von 603 550 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Aus den hundert Talenten Silber goss man die Füsse des Heiligtums und die Füsse des Vorhangs, hundert Füsse aus hundert Talenten, aus jedem Talent einen Fuss.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aus den 1 775 Lot aber machte er die Nägel für die Säulen, überzog ihre Köpfe und verband sie durch Querstangen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Das als Weihegabe gespendete Erz wog siebzig Talente und 2 400 Lot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus machte er die Füsse für die Türe des heiligen Zeltes, den ehernen Altar nebst dem ehernen Gitterwerk daran und alle Geräte des Altars,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'ferner die Füsse des Vorhofs ringsum und die Füsse des Vorhoftors, sowie alle Pflöcke der Wohnung und alle Pflöcke des Vorhofs ringsum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Aus dem blauen und roten Purpur aber und dem Karmesin machten sie gewirkte Kleider für den Dienst im Heiligtum; und sie machten die heiligen Kleider für Aaron, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und sie machten das Ephod aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Das Gold hämmerten sie zu dünnem Blech und zerschnitten es in Fäden, um es in den blauen und roten Purpur, in das Karmesin und den Byssus zu wirken, wie es der Kunstweber macht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Sie machten Schulterstücke daran, die (mit ihm) verbunden waren; an seinen beiden Enden wurde es (mit ihnen) verbunden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Und die Binde daran, womit man es anlegt, war von derselben Arbeit und aus einem Stück mit ihm, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Dann machten sie die Sohamsteine zurecht, in ein Geflecht von Gold gefasst, in welche nach Art der Siegelstecherarbeit die Namen der Söhne Israels eingegraben waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Und sie hefteten sie auf die Schulterstücke des Ephod als Steine, (die dazu dienen sollten,) dass der Israeliten gedacht werde - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Dann machten sie die Brusttasche in Kunstweberarbeit, wie das Ephod gemacht war, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Viereckig war sie; doppeltgelegt machten sie die Tasche, eine Spanne lang und eine Spanne breit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und sie besetzten sie mit vier Reihen von Edelsteinen: in die erste Reihe kamen ein Karneol, ein Topas und ein Smaragd zu stehen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'in die zweite Reihe ein Rubin, ein Saphir und ein Jaspis;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'in die dritte Reihe ein Hyazinth, ein Achat und ein Amethyst;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'in die vierte Reihe ein Chrysolith, ein Soham und ein Onyx. In ein Geflecht von Gold gefasst, bildeten sie den Besatz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Und der Steine waren nach den Namen der Söhne Israels zwölf, nach ihren Namen; in Siegelstecherarbeit stand auf jedem der Name eines der zwölf Stämme.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Darnach brachten sie an der Tasche schnurartig geflochtene Ketten aus reinem Gold an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Dann machten sie zwei goldene Geflechte und zwei goldene Ringe und setzten die zwei Ringe an die beiden Enden der Tasche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Und sie befestigten die beiden goldenen Schnüre an den zwei Ringen an den Enden der Tasche.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Die beiden Enden der zwei Schnüre aber befestigten sie an den zwei Geflechten und hefteten diese auf die Schulterstücke des Ephod an dessen Vorderseite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Dann machten sie (noch) zwei goldene Ringe und setzten sie an die zwei Enden der Tasche auf ihhrem innern, dem Ephod zugekehrten Rande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Und sie machten (noch) zwei goldene Ringe und setzten sie an die beiden Schulterstücke des Ephod unten auf seiner Vorderseite, da wo es (mit ihnen) zusammengefügt war, über der Binde des Ephod.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Dann banden sie die Tasche mit ihren Ringen vermittelst einer Schnur von blauem Purpur an den Ringen des Ephod fest, sodass die Tasche an der Binde des Ephod anlag und sich über dem Ephod nicht verschob - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Weiter machen sie das Obergewand für das Ephod, in Weberarbeit, ganz aus blauem Purpur,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'und mitten darin die Öffnung des Obergewandes, wie die Öffung eines Panzers, mit einem Saum rings um das Loch, damit es nicht zerreisse.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Und sie brachten am Saum des Obergewandes Granatäpfel aus blauem und rotem Purpur, Karmesin und gezwirntem Byssus an,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'machten dann Schellen aus reinem Gold und setzten sie zwischen die Granatäpfel, ringsum am Saum des Obergewandes zwischen die Granatäpfel,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'abwechselnd eine Schelle und einen Granatapfel ringsum am Saum des Obergewandes, für den heiligen Dienst, - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Dann machten sie die Leibröcke aus Byssus für Aaron und seine Söhne, in Weberarbeit,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'ferner den Kopfbund aus Byssus und die hohen Mützen aus Byssus und die linnenen Beinkleider aus gezwirntem Byssus,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'endlich den Gürtel aus gezwirntem Byssus, blauem und rotem Purpur und Karmesin in Buntweberarbeit, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Endlich machten sie das Stirnblatt, das heilige Diadem, aus reinem Gold und schrieben darauf in Siegelstecherschrift: Dem Herrn geweiht!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und sie banden eine Schnur von blauem Purpur daran, um es oben am Kopfbund zu befestigen - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'So wurden alle Arbeiten für die heilige Zeltwohnung vollendet: die Israeliten taten genau, wie der Herr dem Mose geboten hatte; so taten sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Und sie brachten die Wohnung zu Mose, das Zelt und alle seine Geräte: die Haken, Bretter, Riegel, Säulen und Füsse;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'die Decke aus den rotgefärbten Widderfellen, die Decke aus den Seehundsfellen und den verhüllenden Vorhang;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Lade des Gesetzes mit ihren Stangen und die Deckplatte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch mit allen seinen Geräten und die Schaubrote;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den Leuchter aus reinem Gold mit seinen Lampen, den geordnet aufgesteckten Lampen, und allen seinen Geräten und das Öl für den Leuchter;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'den goldenen Altar, das Salböl, das wohlriechende Räucherwerk und den Vorhang für den Eingang des Zeltes;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den ehernen Altar und das zugehörige eherne Gitterwerk, seine Stangen und alle seine Geräte, den Kessel mit seinem Gestell;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhänge des Vorhofs nebst seinen Säulen und Füssen, den Vorhang für das Tor des Vorhofs nebst seinen Seilen und Pflöcken und alle Geräte für den Dienst der heiligen Zeltwohnung;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die gewirkten Kleider für den Dienst im Heiligtum, die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne für den priesterlichen Dienst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Genau so, wie der Herr dem Mose geboten hatte, führten die Israeliten alle Arbeiten aus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Als nun Mose sah, dass sie das ganze Werk ausgeführt hatten - wie der Herr geboten hatte, so hatten sie es gemacht - da segnete er sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und der Herr sprach zu Mose:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Am ersten Tage des ersten Monats sollst du die heilige Zeltwohnung aufrichten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'die Lade des Gesetzes hineinstellen und die Lade mit dem Vorhang verhüllen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Dann sollst du den Tisch hineintun und die Schaubrote aufschichten und sollst den Leuchter hineintun und die Lampen darauf stecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Und den goldenen Räucheraltar sollst du vor die Lade des Gesetzes stellen und den Türvorhang an der Wohnung anbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Den Brandopferaltar aber sollst du vor dem Eingang der heiligen Zeltwohnung aufstellen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Und den Kessel sollst du zwischen dem heiligen Zelt und dem Altar aufstellen und Wasser darein tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Und ringsum sollst du den Vorhof einrichten und sollst den Vorhang des Vorhofs aufhängen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Dann sollst du das Salböl nehmen und die Wohnung und alles, was darin ist, salben und sie dadurch weihen samt allen ihren Geräten, damit sie heilig sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Du sollst auch den Brandopferaltar samt allen seinen Geräten salben und ihn so weihen, damit der Altar hochheilig sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Du sollst auch den Kessel und sein Gestell salben und ihn so weihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Dann sollst du Aaron und seine Söhne an den Eingang des heiligen Zeltes treten lassen und sie mit Wasser waschen (a) 2Mo 29:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'und sollst Aaron mit den heiligen Kleidern bekleiden und salben und ihn so weihen, damit er mein Priester sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Auch seine Söhne sollst du herantreten lassen und sie mit Leibröcken bekleiden;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'dann sollst du sie salben, wie du ihren Vater gesalbt hast, damit sie meine Priester seien. Und ihre Salbung soll ihnen das ewige Priestertum verleihen von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose tat genau, wie ihm der Herr geboten hatte; so tat er.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Im ersten Monat des zweiten Jahrs, am ersten Tage des Monats, wurde die Wohnung aufgerichtet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Mose richtete die Wohnung auf: Er stellte ihre Füße hin, setzte die Bretter darauf, legte die Riegel an und richtete die Säulen auf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Er spannte das Zeltdach über der Wohnung aus und legte die Decke des Zeltdachs oben darauf - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Dann nahm er das Gesetz und legte es in die Lade, steckte die Stangen an die Lade, und legte die Deckplatte oben auf die Lade.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Darnach brachte er die Lade in die Wohnung hinein, hängte den verhüllenden Vorhang auf und verhüllte so die Lade des Gesetzes - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Dann stellte er den Tisch in das heilige Zelt auf die nördliche Seite der Wohnung, ausserhalb des Vorhangs,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'und legte Brot in Schichten darauf vor dem Herrn - wie der Herr dem Mose geboten hatte. (a) 2Mo 25:30; 3Mo 24:5-9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Hierauf stellte er den Leuchter in das heilige Zelt dem Tische gegenüber, auf die südliche Seite der Wohnung,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'und steckte die Lampen darauf vor dem Herrn - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Dann stellte er den goldenen Altar in das heilige Zelt vor den Vorhang');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und räucherte darauf mit wohlriechendem Räucherwerk - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Dann brachte er den Türvorhang an der Wohnung an.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Den Brandopferaltar aber stellte er an den Eingang der heiligen Zeltwohnung und brachte darauf das Brandopfer und das Speisopfer dar - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Darnach stellte er den Kessel zwischen dem heiligen Zelt und dem Altar auf und tat Wasser darein zum Waschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Und Mose, Aaron und seine Söhne wuschen sich damit jeweilen Hände und Füsse;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'sooft sie in das heilige Zelt hineingingen oder zum Altar traten, wuschen sie sich - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Endlich richtete er den Vorhof ein rings um die Wohnung und um den Altar und hängte den Vorhang des Vorhoftores auf. So vollendete Mose das ganze Werk.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Da bedeckte die Wolke das heilige Zelt, und die Herrlichkeit des Herrn erfüllte die Wohnung. (a) 4Mo 9:15; 1Kön 8:10; Jes 4:5; Hes 43:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose konnte nicht in das heilige Zelt hineingehen, weil die Wolke darauf lagerte und die Herrlichkeit des Herrn die Wohnung erfüllte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Und wenn die Wolke sich vor der Wohnung hinweghob, brachen die Israeliten auf, solange sie auf der Wanderung waren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Wenn sich die Wolke aber nicht erhob, brachen sie nicht auf, bis sie sich erhob.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn die Wolke des Herrn war bei Tage über der Wohnung; des Nachts aber wurde sie feurig vor den Augen des ganzen Hauses Israel, solange sie auf der Wanderung waren. (a) 2Mo 13:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'DARNACH berief der Herr den Mose und redete mit ihm vom heiligen Zelte aus, indem er sprach: (a) 2Mo 29:42');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn jemand von euch dem Herrn eine Opfergabe darbringen will, so sollt ihr eure Opfergaben von den Haustieren, vom Grossvieh oder Kleinvieh, darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ist seine Opfergabe ein Brandopfer vom Grossvieh, so bringe er ein fehlloses männliches Tier dar; er führe es an den Eingang des heiligen Zeltes, damit es ihn vor dem Herrn wohlgefällig mache.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Dann stütze er seine Hand auf den Kopf des Brandopfers, damit es ihm wohlgefällig aufgenommen werde, ihm Sühne zu schaffen. (a) 2Mo 29:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Hierauf schlachte er das Rind vor dem Herrn; die Söhne Aarons aber, die Priester, sollen das Blut darbringen: sie sollen das Blut ringsum an den Altar sprengen, der am Eingang des heiligen Zeltes steht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Darnach soll er dem Brandopfer die Haut abziehen und es regelrecht in Stücke zerlegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Die Söhne Aarons, des Priesters, aber sollen Feuer auf den Altar tun und Holzstücke auf das Feuer schichten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Dann sollen die Söhne Aarons, die Priester, die Fleischstücke samt dem Kopf und dem Fett auf dem Holz zurechtlegen, das über dem Feuer auf dem Altar liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Die Eingeweide aber und die Unterschenkel soll man mit Wasser waschen, und der Priester soll das alles auf dem Altar verbrennen; ein Brandopfer ist es, ein lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Auch wenn seine Opfergabe für das Brandopfer ein Stück Kleinvieh ist, ein Lamm oder eine Ziege, so bringe er ein fehlloses männliches Tier dar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Dieses schlachte er vor dem Herrn auf der Nordseite des Altars; und die Söhne Aarons, die Priester, sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Dann soll er es regelrecht in Stücke zerlegen, und der Priester soll diese samt dem Kopf und dem Fett auf dem Holz zurechtlegen, das über dem Feuer auf dem Altar liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Die Eingeweide aber und die Unterschenkel soll man mit Wasser waschen, und der Priester soll das alles darbringen und auf dem Altar verbrennen; ein Brandopfer ist es, ein lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ist aber seine Opfergabe für den Herrn ein Brandopfer von den Vögeln, so bringe er seine Opfergabe von den Turteltauben oder jungen gewöhnlichen Tauben dar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Der Priester soll das Tier zum Altar bringen und ihm den Hals knicken und es auf dem Altar verbrennen, sein Blut aber soll an der Wand des Altars ausgedrückt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Und den Kropf mit den Federn soll er beseitigen und östlich neben dem Altar auf den Aschenhaufen werfen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'dann soll er ihm die Flügel einreissen, sie aber nicht abtrennen. Und der Priester soll es auf dem Altar verbrennen, auf dem Holz, das über dem Feuer liegt; ein Brandopfer ist es, ein lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'WENN jemand dem Herrn ein Speisopfer darbringen will, so soll seine Opfergabe in Semmelmehl bestehen, und er soll Öl darüber giessen und Weihrauch darauf tun; (a) 4Mo 15:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'dann bringe er es den Söhnen Aarons, den Priestern. Der Priester aber nehme davon eine Handvoll, von dem Mehl und Öl, samt allem Weihrauch und verbrenne den als Duftopfer bestimmten Teil auf dem Altar als lieblich duftendes Feueropfer für den Herrn. (a) 3Mo 5:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Der Rest des Speisopfers aber gehört Aaron und seinen Söhnen, als Hochheiliges von den Feueropfern des Herrn. (a) 3Mo 10:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Willst du aber Ofengebäck als Speisopfer darbringen, so sei es von Semmelmehl; ungesäuerte Kuchen, mit Öl eingerührt, oder ungesäuerte Fladen, mit Öl bestrichen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ist aber deine Opfergabe ein Speisopfer, das auf dem Backblech gebacken wird, so soll es von Semmelmehl sein, mit Öl eingerührt und ungesäuert,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'und du sollst es in Brocken zerbrechen und Öl darüber giessen; ein Speisopfer ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ist aber deine Opfergabe ein im Topf gekochtes Speisopfer, so soll es aus Semmelmehl mit Öl gemacht werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Und du sollst das Speisopfer, das aus diesen Dingen gemacht wird, dem Herrn bringen; man übergebe es dem Priester, und der trage es zum Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Dann hebe der Priester von dem Speisopfer den als Duftopfer bestimmten Teil ab und verbrenne ihn auf dem Altar als lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Der Rest des Speisopfers aber gehört Aaron und seinen Söhnen, als Hochheiliges von den Feueropfern des Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kein Speisopfer, das ihr dem Herrn darbringt, darf aus Gesäuertem gemacht werden; denn ihr sollt dem Herrn weder Sauerteig noch Honig als Feueropfer verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Als Erstlingsopfergabe mögt ihr sie dem Herrn darbringen; auf den Altar aber sollen sie nicht kommen zum lieblichen Geruch.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle deine Speisopfergaben sollst du salzen, du darfst das Salz des Bundes deines Gottes bei deinem Speisopfer nicht fehlen lassen; mit jeder deiner Opfergaben sollst du Salz darbringen. (a) Mr 9:49');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Willst du aber dem Herrn ein Speisopfer von Erstlingsfrüchten darbringen, so sollst du am Feuer geröstete Ähren, zerriebene Körner von Frühfrucht, als dein Erstlingsspeisopfer darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Und du sollst Öl darauf tun und Weihrauch darauf legen; ein Speisopfer ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Und der Priester soll alsdann den als Duftopfer bestimmten Teil von den zerriebenen Körnern und dem Öl samt allem Weihrauch verbrennen als Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'IST aber seine Opfergabe ein Heilsopfer, so soll er, wenn er ein Stück Grossvieh darbringen will, ein fehlloses männliches oder weibliches Tier vor den Herrn bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Und er soll seine Hand auf den Kopf seines Opfers stützen und es am Eingang des heiligen Zeltes schlachten; die Söhne Aarons aber, die Priester, sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Dann soll er von dem Heilsopfer dem Herrn ein Feueropfer darbringen: alles Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'ferner die beiden Nieren mit dem Fett daran, das bei den Lenden aufliegt, und das Fett neben der Leber bei den Nieren soll er es abtrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Und die Söhne Aarons sollen es auf dem Altar über dem Brandopfer, das auf dem Holz über dem Feuer liegt, verbrennen, als lieblich duftendes Feueropfer für den Herrn. (a) 2Mo 29:25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ist aber seine Opfergabe, die zum Heilsopfer für den Herrn bestimmt ist, ein Stück Kleinvieh, so soll er ein fehlloses männliches oder weibliches Tier darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Will er ein Lamm als Opfergabe darbringen, so bringe er es vor den Herrn,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'stütze seine Hand auf den Kopf des Opfers und schlachte es vor dem heiligen Zelte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Dann soll er von dem Heilsopfer dem Herrn als Feueropfer das Fett darbringen: den ganzen Fettschwanz, den er dicht am Schwanzwirbel abtrennen soll, das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'ferner die beiden Nieren mit dem Fett daran, das bei den Lenden aufliegt, und das Fett neben der Leber bei den Nieren soll er es abtrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Und der Priester soll es auf dem Altar als Feueropferspeise für den Herrn verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ist aber seine Opfergabe eine Ziege, so bringe er sie vor den Herrn,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'stütze seine Hand auf ihren Kopf und schlachte sie vor dem heiligen Zelte; die Söhne Aarons aber sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Dann soll er davon dem Herrn seine Opfergabe als Feueropfer darbringen: das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'ferner die beiden Nieren mit dem Fett daran, das bei den Lenden aufliegt, und das Fett neben der Leber bei den Nieren soll er es abtrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Das alles soll der Priester auf dem Altar als lieblich duftende Feueropferspeise für den Herrn verbrennen. Alles Fett gehört dem Herrn. (a) 3Mo 7:23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Es ist eine immerwährende Satzung für euch von Geschlecht zu Geschlecht in allen euren Wohnsitzen: ihr sollt nie und nimmer Fett oder Blut essen. (a) 1Mo 9:4; 3Mo 7:26; 17:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Rede mit den Israeliten und sprich: Wenn sich jemand unwissentlich gegen irgendein Verbot des Herrn versündigt und irgend etwas dergleichen tut, (so gilt folgendes:)');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Wenn sich der gesalbte Priester versündigt, sodass das Volk in Schuld verfällt, so soll er für die Sünde, die er begangen hat, dem Herrn einen fehllosen jungen Stier als Sündopfer darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Er bringe den Stier an den Eingang des heiligen Zeltes vor den Herrn, stütze seine Hand auf den Kopf des Stiers und schlachte den Stier vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Dann nehme der gesalbte Priester von dem Blute des Stiers und bringe es in das heilige Zelt;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'und der Priester tauche seinen Finger in das Blut und sprenge vor dem Herrn siebenmal von dem Blute vor den Vorhang des Heiligtums hin.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Hierauf streiche der Priester etwas von dem Blute vor dem Herrn an die Hörner des Altars mit dem wohlriechenden Räucherwerk, der im heiligen Zelte steht; alles (übrige) Blut des Stiers aber soll er beim Brandopferaltar, der am Eingang des heiligen Zeltes steht, auf den Boden giessen. (a) 2Mo 29:12; 3Mo 9:9 10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Dann soll er alles Fett an dem Sündopferstier abheben: das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'ferner die beiden Nieren mit dem Fett daran, das bei den Lenden aufliegt, und das Fett neben der Leber bei den Nieren soll er es abtrennen -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'gerade so, wie man es beim Rind des Heilsopfers abhebt -, und der Priester soll das alles auf dem Brandopferaltar verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Die Haut des Stiers aber und all sein Fleisch, samt dem Kopf und den Unterschenkeln, den Eingeweiden und dem Mist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'den ganzen Stier soll er vor das Lager hinaus an eine reine Stätte schaffen, an den Ort, wo man die Asche hinschüttet, und soll ihn auf Holzstücken verbrennen; an dem Orte, wo man die Asche hinschüttet, soll man ihn verbrennen. (a) 2Mo 29:14; 3Mo 6:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Wenn aber die ganze Gemeinde Israel sich vergeht, ohne dass die Gemeinde dessen gewahr wird -, wenn sie irgendein Verbot des Herrn übertreten und sich so verschulden, (1) V. 13-14: 4Mo 15:22-24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'und es kommt hernach die Sünde, mit der sie sich versündigt haben, an den Tag, so soll die Gemeinde einen jungen Stier als Sündopfer darbringen. Man bringe ihn vor das heilige Zelt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'und die Ältesten der Gemeinde sollen vor dem Herrn ihre Hände auf den Kopf des Stiers stützen; dann schlachte man den Stier vor dem Herrn,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'und der gesalbte Priester bringe von dem Blute des Stiers in das heilige Zelt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Dann tauche der Priester seinen Finger in das Blut und besprenge damit den Vorhang siebenmal vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Auch streiche er von dem Blute an die Hörner des Altars, der vor dem Herrn im heiligen Zelte steht; alles (übrige) Blut aber soll er beim Brandopferaltar, der am Eingang des heiligen Zeltes steht, auf den Boden giessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Dann soll er alles Fett an ihm abheben und es auf dem Altar verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Er soll mit dem Stier verfahren, wie er mit dem (andern) Sündopferstier verfährt; gerade so soll er mit ihm verfahren. So erwirkt der Priester ihnen Sühne, und es wird ihnen vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Den Stier aber soll man vor das Lager hinausschaffen und verbrennen, wie man den ersten Stier verbrennt. Das ist das Sündopfer der Gemeinde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Wenn ein Fürst sich versündigt, indem er irgendeines von den Verboten des Herrn, seines Gottes, unwissentlich übertritt und sich so verschuldet,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'und er wird hernach die Sünde, mit der er sich versündigt hat, inne, so soll er als Opfergabe einen fehllosen Ziegenbock bringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'und er stütze seine Hand auf den Kopf des Bockes und schlachte ihn vor dem Herrn an der Stätte, wo man das Brandopfer schlachtet; ein Sündopfer ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Der Priester aber nehme mit dem Finger von dem Blute des Sündopfers und streiche es an die Hörner des Brandopferaltars, und alles (übrige) Blut giesse er beim Brandopferaltar auf den Boden;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'alles Fett desselben aber soll er auf dem Altar verbrennen, wie das Fett des Heilsopfers. So erwirkt ihm der Priester Sühne für seine Sünde, und es wird ihm vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Wenn sich aber jemand aus dem gemeinen Volke unwissentlich versündigt, indem er eines von den Verboten des Herrn übertritt und sich so verschuldet,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'und er wird hernach die Sünde, die er begangen hat, inne, so soll er für die Sünde, die er begangen hat, eine Ziege, ein fehlloses weibliches Tier, als Opfergabe bringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'und er stütze seine Hand auf den Kopf des Sündopfers und schlachte es an der Stätte, wo man das Brandopfer schlachtet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Der Priester aber nehme mit dem Finger von dem Blute und streiche es an die Hörner des Brandopferaltars, und alles (übrige) Blut giesse er beim Altar auf den Boden;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'alles Fett aber soll er abtrennen, wie man das Fett am Heilsopfer abtrennt, und der Priester soll es auf dem Altar zum lieblichen Geruch für den Herrn verbrennen. So erwirkt ihm der Priester Sühne, und es wird ihm vergeben. (a) 3Mo 3:14 15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Will er aber als Opfergabe ein Lamm zum Sündopfer bringen, so bringe er ein fehlloses weibliches Tier,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'und er stütze seine Hand auf den Kopf des Sündopfers und schlachte es als Sündopfer an der Stätte, wo man das Brandopfer schlachtet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Der Priester aber nehme mit dem Finger von dem Blute des Sündopfers und streiche es an die Hörner des Brandopferaltars, und alles (übrige) Blut giesse er beim Altar auf den Boden;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'alles Fett aber soll er abtrennen, wie man das Fett beim Lamm des Heilsopfers abtrennt, und der Priester soll es auf dem Altar über den Feueropfern des Herrn verbrennen. So erwirkt ihm der Priester Sühne für die Sünde, die er begangen hat, und es wird ihm vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Wenn sich jemand versündigt, indem er eine Verfluchung (über einen Missetäter) aussprechen hört, und er könnte Zeuge sein, sei es, dass er den Tatbestand gesehen oder dass er ihn erfahren hat, aber er sagt nicht aus und lädt so Schuld auf sich -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'oder wenn jemand etwas Unreines berührt, sei es das Aas eines unreinen Wildes oder das Aas eines unreinen Haustiers oder das Aas eines unreinen Kriechtiers, ohne dass er sich dessen bewusst wird, und er wird so unrein und gerät in Schuld - (a) 3Mo 11:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'oder wenn jemand etwas Unreines an einem Menschen berührt - irgend etwas, wodurch ein Mensch unrein werden kann -, ohne dass er sich dessen bewusst wird, er wird es aber nachher inne und gerät so in Schuld -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'oder wenn jemand unbedacht schwört, irgend etwas Böses oder Gutes tun zu wollen, wie etwa einem Menschen unbedacht ein Schwur entfahren kann, ohne dass er sich dessen bewusst wird, er wird es aber nachher inne und gerät so in Schuld -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'wenn sich jemand mit etwas der Art verschuldet, so soll er die Sünde bekennen, mit der er sich versündigt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Alsdann soll er für die Sünde, die er begangen hat, dem Herrn seine Busse darbringen, ein weibliches Tier vom Kleinvieh, ein Schaf oder eine Ziege als Sündopfer. So erwirkt ihm der Priester Sühne für die Sünde, die er begangen hat, und es wird ihm vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Wenn er aber kein Schaf vermag, so bringe er dem Herrn als Busse für seine Sünde zwei Turteltauben oder zwei junge gewöhnliche Tauben, die eine als Sündopfer, die andre als Brandopfer. (a) 3Mo 12:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Er bringe sie dem Priester, und dieser soll die zum Sündopfer bestimmte zuerst darbringen und ihr dicht am Genick den Hals knicken, den Kopf aber nicht abtrennen. (a) 3Mo 1:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Dann soll er von dem Blute des Sündopfers an die Wand des Altars sprengen, und das, was übrig ist an Blut, soll beim Altar auf den Boden ausgedrückt werden; ein Sündopfer ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Die andre aber soll er als Brandopfer herrichten nach der Vorschrift. So erwirkt ihm der Priester Sühne für die Sünde, die er begangen hat, und es wird ihm vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Vermag er aber nicht einmal zwei Turteltauben oder zwei junge gewöhnliche Tauben, so bringe er als Opfergabe für seine Sünde ein zehntel Epha Semmelmehl zum Sündopfer. Er braucht kein Öl darauf zu tun und keinen Weihrauch darauf zu legen; denn es ist ein Sündopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Das bringe er dem Priester, und der Priester soll eine Handvoll davon nehmen als Duftopfer und es auf dem Altar über den Feueropfern des Herrn verbrennen; ein Sündopfer ist es. (a) 3Mo 2:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'So erwirkt ihm der Priester Sühne für die Sünde, die er in einem jener Fälle begangen hat, und es wird ihm vergeben. Das (Übrige) gehört dem Priester wie beim Speisopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn jemand etwas veruntreut und sich unwissentlich an etwas vergreift, das dem Herrn geweiht ist, so soll er dem Herrn als Busse einen fehllosen Widder aus der Herde, der nach deiner Schätzung mindestens zwei Lot Silber nach heiligem Gewicht wert ist, zum Schuldopfer bringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'und das Geweihte, an dem er sich vergriffen hat, soll er zurückerstatten und den fünften Teil des Wertes hinzufügen. Das soll er dem Priester geben, und dieser erwirkt ihm Sühne mit dem Schuldopferwidder, und es wird ihm vergeben. (a) 3Mo 6:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Und wenn jemand einen Fehler begeht, indem er irgendeines von den Verboten des Herrn unwissentlich übertritt, und er versündigt sich so und lädt Schuld auf sich,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'so soll er einen fehllosen Widder aus der Herde nach deiner Schätzung als Schuldopfer zum Priester bringen, und der Priester erwirkt ihm Sühne für das unwissentliche Vergehen, das er, ohne es zu merken, begangen hat, und es wird ihm vergeben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ein Schuldopfer ist es; er hat sich gegen den Herrn verschuldet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und der Herr redete mit Mose und sprach: (1) die Lutherbibel hat für Kap. 6,1-30 die Zählung 5,20-26; 6,1-23.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Wenn jemand sich versündigt und wider den Herrn eine Veruntreuung begeht, indem er seinem Nächsten etwas Anvertrautes oder Hinterlegtes oder Geraubtes ableugnet oder von seinem Nächsten etwas erpresst');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'oder, wenn er etwas Verlorenes gefunden hat, es ableugnet, und indem er falsch schwört wegen irgend etwas, womit der Mensch sich versündigen kann -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'wenn sich einer so versündigt und dadurch in Schuld verfällt, so soll er das Geraubte, das er geraubt, oder das Erpresste, das er erpresst, oder das Anvertraute, das bei ihm hinterlegt war, oder das Verlorene, das er gefunden hat, zurückgeben,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'überhaupt alles, um dessentwillen er falsch geschworen hat. Er soll den vollen Wert zurückerstatten und noch den fünften Teil hinzufügen; dem Eigentümer soll er es geben an dem Tage, da er sein Schuldopfer bringt. (a) 3Mo 5:16; 4Mo 5:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Als Busse aber soll er für den Herrn einen fehllosen Widder aus der Herde nach deiner Schätzung als Schuldopfer zum Priester bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'So erwirkt ihm der Priester Sühne vor dem Herrn, und es wird ihm alles vergeben, womit immer er sich verschuldet haben mag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Gebiete Aaron und seinen Söhnen folgendes: Dies ist das Gesetz über das Brandopfer; das ist das Opfer, welches die ganze Nacht hindurch bis zum Morgen an seiner Brandstätte auf dem Altar bleibt, und es soll dadurch das Feuer des Altars brennend erhalten werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Und der Priester ziehe sein Linnengewand an und bedecke mit den linnenen Beinkleidern seine Blösse; dann hebe er die Asche weg, zu welcher das Feuer das Brandopfer auf dem Altar verbrannt hat, und schütte sie neben den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Darnach ziehe er seine Kleider aus und lege andre Kleider an und schaffe die Asche vor das Lager hinaus an eine reine Stätte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Das Feuer auf dem Altar soll dadurch unterhalten werden und darf nie erlöschen. Der Priester aber soll jeden Morgen Holzstücke darauf anzünden, das Brandopfer darauf zurechtlegen und die Fettstücke der Heilsopfer darauf verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Beständig soll das Feuer auf dem Altar unterhalten werden; es darf nie erlöschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Und dies ist das Gesetz über das Speisopfer: die Söhne Aarons sollen es vor den Herrn an den Altar heranbringen. (a) 3Mo 2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Dann nehme er eine Handvoll davon, von dem Semmelmehl des Speisopfers und von dem Öl, samt allem Weihrauch, der auf dem Speisopfer liegt, und verbrenne es als Duftopfer auf dem Altar zum lieblichen Geruch für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Was davon übrigbleibt, sollen Aaron und seine Söhne essen. Ungesäuert soll man es essen an heiliger Stätte, im Vorhof des heiligen Zeltes;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'es darf nicht mit Sauerteig gebacken werden. Als ihren Anteil an meinen Feueropfern gebe ich es ihnen; etwas Hochheiliges ist es, wie das Sündopfer und das Schuldopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Was männlich ist unter den Nachkommen Aarons, darf davon essen; das ist euer ewiges Recht an den Feueropfern des Herrn von Geschlecht zu Geschlecht. Jeder, der sie berührt, wird heilig. (a) 2Mo 29:37');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Dies ist die Opfergabe Aarons und seiner Söhne, die sie dem Herrn darbringen sollen an dem Tage, da er gesalbt wird: ein zehntel Epha Semmelmehl als tägliches Speisopfer, die eine Hälfte am Morgen und die andre Hälfte am Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Auf dem Backblech soll man es mit Öl zubereiten, eingerührt sollst du es bringen; als Mehlgebäck, als Speisopfer in Brocken sollst du es darbringen zum lieblichen Geruch für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Der Priester, der unter seinen Söhnen an seiner Statt gesalbt wird, soll es zubereiten; es ist eine ewige Gebühr für den Herrn und soll ganz verbrannt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Jedes Speisopfer eines Priesters soll Ganzopfer sein; es darf nicht gegessen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Rede mit Aaron und seinen Söhnen und sprich: Dies ist das Gesetz über das Sündopfer: an der Stätte, wo man das Brandopfer schlachtet, soll man auch das Sündopfer vor dem Herrn schlachten; etwas Hochheiliges ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Der Priester, der das Sündopfer darbringt, soll es essen; an heiliger Stätte, im Vorhof des heiligen Zeltes, soll es gegessen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Jeder, der das Fleisch des Opfers berührt, wird heilig; und wenn etwas von seinem Blute ans Kleid spritzt, so sollst du das bespritzte Stück an heiliger Stätte waschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Das irdene Geschirr, in dem es gekocht wird, soll man zerbrechen; ist es aber in einem ehernen Geschirr gekocht worden, so muss dieses gescheuert und mit Wasser ausgespült werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Alles, was männlich ist unter den Priestern, darf davon essen; etwas Hochheiliges ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Kein Sündopfer aber, von dessen Blut man etwas in das heilige Zelt hineinbringt, um im Heiligtum die Sühne zu vollziehen, darf gegessen werden, sondern es muss verbrannt werden. (a) 3Mo 4:5 12 16 21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies ist das Gesetz über das Schuldopfer: etwas Hochheiliges ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'An der Stätte, wo man das Brandopfer schlachtet, soll man auch das Schuldopfer schlachten, und sein Blut soll man ringsum an den Altar sprengen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'und alles Fett davon soll man darbringen: den Fettschwanz und das Fett, das die Eingeweide bedeckt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'ferner die beiden Nieren mit dem Fett daran, das bei den Lenden aufliegt, und das Fett neben der Leber bei den Nieren soll man es abtrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester soll das alles auf dem Altar als Feueropfer für den Herrn verbrennen; ein Schuldopfer ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alles, was männlich ist unter den Priestern, darf davon essen, an heiliger Stätte soll man es essen; etwas Hochheiliges ist es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Für das Schuldopfer gilt dasselbe Gesetz wie für das Sündopfer: dem Priester, der die Sühne damit vollzieht, dem gehört es.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Auch gehört dem Priester, der jemandes Brandopfer darbringt, die Haut des Brandopfers, das er darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ferner gehört jedes Speisopfer, das im Ofen gebacken, und jedes, das in einem Topf oder auf einem Backblech zubereitet wird, dem Priester, der es darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Jedes Speisopfer aber, das mit Öl eingerührt oder trocken ist, gehört allen Söhnen Aarons, dem einen wie dem andern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies ist das Gesetz über das Heilsopfer, das man dem Herrn darbringt:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'wenn jemand es darbringt, um zu danken, so soll er zu dem Dankopfer hinzu ungesäuerte Kuchen, mit Öl eingerührt, und ungesäuerte, mit Öl bestrichene Fladen und mit Öl eingerührtes Semmelmehl darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Zusammen mit Kuchen von gesäuertem Brot soll er seine Opfergabe darbringen, abgesehen von dem Opfertier, das er zum Dank als Heilsopfer darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und er soll je ein Stück von jeder Opfergabe dem Herrn als Hebeopfer darbringen; das gehört dem Priester, der das Blut des Heilsopfers sprengt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Das Fleisch seines Dankheilsopfers aber soll an demselben Tage gegessen werden, an dem es dargebracht wird; er darf nichts davon übriglassen bis zum Morgen. (a) 3Mo 22:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Auch wenn er sein Opfer infolge eines Gelübdes oder als freiwillige Gabe darbringt, so soll es an demselben Tage gegessen werden, an dem er sein Opfer darbringt; doch wenn etwas davon übrigbleibt, darf es noch am folgenden Tag gegessen werden. (a) 3Mo 19:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was (auch dann noch) von dem Fleisch des Opfers übrigbleibt, das muss am dritten Tage verbrannt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Wenn aber am dritten Tag doch noch von dem Fleisch seines Heilsopfers gegessen wird, so wird es nicht wohlgefällig aufgenommen; es wird dem, der es darbringt, nicht angerechnet, sondern gilt als Greuel. Wer immer davon isst, der lädt Schuld auf sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Auch das Fleisch, das mit etwas Unreinem in Berührung kommt, darf nicht gegessen, sondern muss verbrannt werden; was aber sonst das Fleisch betrifft, so darf jeder, der rein ist, Fleisch essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Wer aber Fleisch von dem für den Herrn bestimmten Heilsopfer isst, während Unreinheit an ihm haftet, dessen Seele soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Und wer etwas Unreines berührt, es sei nun eine Unreinheit an einem Menschen oder ein unreines Haustier oder irgendein unreines Kriechtier, und doch von dem Fleisch des für den Herrn bestimmten Heilsopfers isst, dessen Seele soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und der Herr redete mit Mose und sprach: (a) 3Mo 3:17; 11:40; 17:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Rede mit den Israeliten und sprich: Ihr dürft kein Fett von Rindern, Lämmern oder Ziegen essen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'doch das Fett von verendeten oder zerrissenen Tieren darf zu allerlei gebraucht werden, nur essen dürft ihr es nicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn wenn irgend jemand Fett isst von den Haustieren, von denen man dem Herrn Feueropfer darbringt, so soll die Seele dessen, der isst, aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Auch Blut dürft ihr nicht essen, weder von den Vögeln noch von den Haustieren, in allen euren Wohnsitzen. (a) 3Mo 17:10; 1Mo 9:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jeder, der irgend Blut isst, dessen Seele soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Rede mit den Israeliten und sprich: Wer dem Herrn sein Heilsopfer darbringt, der gebe dem Herrn von seinem Heilsopfer den Anteil, den er ihm schuldet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Eigenhändig soll er bringen, was zum Feueropfer für den Herrn bestimmt ist; das Fett samt der Brust soll er bringen: die Brust, um sie als Webeopfer vor dem Herrn zu schwingen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'das Fett aber soll der Priester auf dem Altar verbrennen, während die Brust Aaron und seinen Söhnen zufällt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Auch die rechte Keule sollt ihr von euren Heilsopfern als Hebe dem Priester geben;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'demjenigen unter den Söhnen Aarons, der das Blut der Heilsopfer und das Fett darbringt, soll die rechte Keule als Anteil zufallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn die Webebrust und die Hebekeule nehme ich den Israeliten von ihren Heilsopfern weg und gebe sie dem Priester Aaron und seinen Söhnen als ewige Gebühr von seiten der Israeliten. (a) 3Mo 10:14; 4Mo 18:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Das ist der Anteil Aarons und seiner Söhne an den Feueropfern des Herrn - an dem Tage, da er sie herzutreten liess, dem Herrn Priesterdienst zu tun -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'den der Herr ihnen zuwies an dem Tage, da er sie salbte, als Gabe von seiten der Israeliten, als ewige Gebühr von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Das sind die Gesetze über das Brandopfer, das Speisopfer, das Sündopfer, das Schuldopfer, das Einweihungsopfer und das Heilsopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'die der Herr dem Mose auf dem Berge Sinai gebot, an dem Tage, da er den Israeliten Befehl gab, dem Herrn ihre Opfergaben darzubringen, in der Wüste am Sinai.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aaron samt seinen Söhnen, ferner die Kleider, das Salböl, den Sündopferstier, die beiden Widder und den Korb mit den ungesäuerten Broten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'und versammle die ganze Gemeinde am Eingang des heiligen Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose tat, wie ihm der Herr geboten hatte, und die Gemeinde versammelte sich am Eingang des heiligen Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Und Mose sprach zu der Gemeinde: Dies ist es, was der Herr zu tun geboten hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Dann liess Mose den Aaron und seine Söhne herzutreten und wusch sie mit Wasser.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Und er legte ihm den Leibrock an, umgürtete ihn mit dem Gürtel, bekleidete ihn mit dem Oberkleid, legte ihm das Ephod an, umgürtete ihn mit der Binde des Ephod und band es damit an ihm fest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Darnach legte er ihm die Brusttasche an und tat die Urim und Thummim in die Brusttasche. (a) 2Mo 28:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Und er setzte ihm den Kopfbund auf das Haupt und befestigte am Kopfbund auf der Vorderseite das goldene Stirnblatt, das heilige Diadem - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Dann nahm Mose das Salböl und salbte die (heilige) Wohnung und alles, was darin war, und weihte es so;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'und er sprengte davon siebenmal an den Altar und salbte den Altar mit allen seinen Geräten, auch den Kessel mit seinem Gestell, um alles zu weihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Und er goss von dem Salböl auf das Haupt Aarons und salbte ihn, um ihn zu weihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Hierauf liess Mose die Söhne Aarons herzutreten, bekleidete sie mit Leibröcken, umgürtete sie mit einem Gürtel und setzte ihnen hohe Mützen auf - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Dann liess er den Sündopferstier herbeibringen, und Aaron und seine Söhne stützten die Hand auf den Kopf des Sündopferstiers.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Und Mose schlachtete ihn, nahm das Blut, strich davon mit dem Finger ringsum an die Hörner des Altars und entsündigte so den Altar; das (übrige) Blut aber goss er beim Altar auf den Boden. So weihte er ihn, indem er ihm Sühne schaffte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Und Mose nahm alles Fett an den Eingeweiden, das Fett neben der Leber und die beiden Nieren mit dem Fett daran und verbrannte es auf dem Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Den Stier aber verbrannte er mitsamt Haut und Fleisch und Mist ausserhalb des Lagers - wie der Herr dem Mose geboten hatte. (a) 3Mo 4:11 12; 9:11; 16:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Dann liess er den Brandopferwidder herbeibringen, und Aaron und seine Söhne stützten die Hand auf den Kopf des Widders.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Und Mose schlachtete ihn, sprengte das Blut ringsum an den Altar');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'und zerlegte den Widder regelrecht in Stücke; dann verbrannte Mose den Kopf, die Stücke und das Fett.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Die Eingeweide aber und die Unterschenkel wusch er mit Wasser, und dann verbrannte Mose den ganzen Widder auf dem Altar. Ein Brandopfer war es zum lieblichen Geruch, ein Feueropfer für den Herrn - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Dann liess er den andern Widder, den Einweihungswidder, herbeibringen, und Aaron und seine Söhne stützten die Hand auf den Kopf des Widders.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Und Mose schlachtete ihn, nahm von dem Blute und strich es Aaron an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Dann liess Mose die Söhne Aarons herzutreten und strich auch ihnen von dem Blute an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses; das (übrige) Blut aber sprengte Mose ringsum an den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Dann nahm er das Fett: den Fettschwanz und alles Fett an den Eingeweiden, das Fett neben der Leber und die beiden Nieren mit dem Fett daran, sowie die rechte Keule;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'auch nahm er aus dem Korbe mit den ungesäuerten Broten, der vor dem Herrn stand, einen ungesäuerten Kuchen, einen mit Öl zubereiteten Brotkuchen und einen Fladen und legte es zu den Fettstücken und zu der rechten Keule.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Das alles gab er Aaron und seinen Söhnen in die Hände und schwang es als Webeopfer vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Darnach nahm ihnen Mose alles wieder aus den Händen und verbrannte es auf dem Altar über dem Brandopfer; ein Einweihungsopfer war es zum lieblichen Geruch, ein Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Auch nahm Mose die Brust und schwang sie als Webeopfer vor dem Herrn; sie fiel Mose als Anteil am Einweihungswidder zu - wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Hierauf nahm Mose von dem Salböl und von dem Blut auf dem Altar und besprengte damit Aaron und seine Kleider, und ebenso seine Söhne und ihre Kleider, und weihte so Aaron und seine Kleider, und ebenso seine Söhne und ihre Kleider.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Und Mose sprach zu Aaron und seinen Söhnen: Kocht das Fleisch am Eingang des heiligen Zeltes und esst es daselbst, zusammen mit dem Brot aus dem Korbe des Einweihungsopfers, wie mir geboten wurde mit den Worten: Aaron und seine Söhne sollen es essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was aber übrigbleibt an Fleisch und Brot, das sollt ihr verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Und ihr sollt sieben Tage lang nicht vom Eingang des heiligen Zeltes weggehen, bis zu dem Tage, da die Zeit eurer Einweihung vorbei ist; denn sieben Tage soll die Einweihung dauern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Wie er heute getan, so hat der Herr geboten (auch fernerhin) zu tun, um euch Sühne zu erwirken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Am Eingang des heiligen Zeltes sollt ihr sieben Tage lang bleiben, Tag und Nacht, und die Vorschriften des Herrn befolgen, damit ihr nicht sterbet; denn so ist es mir geboten worden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Und Aaron und seine Söhne taten alles, was der Herr durch Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'AM achten Tage aber berief Mose den Aaron und seine Söhne und die Ältesten Israels');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'und sprach zu Aaron: Nimm für dich ein junges Rind zum Sündopfer und einen Widder zum Brandopfer, beide fehllos, und bringe sie vor dem Herrn dar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Zu den Israeliten aber sollst du sagen: Nehmt einen Ziegenbock zum Sündopfer und ein Kalb und ein Schaf, beide einjährig und fehllos, zum Brandopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'ferner ein Rind und einen Widder zum Heilsopfer, um sie vor dem Herrn zu schlachten, endlich ein Speisopfer, mit Öl eingerührt; denn heute wird euch der Herr erscheinen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Da holten sie, was Mose geboten hatte, vor das heilige Zelt, und die ganze Gemeinde trat herzu und stellte sich vor den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Und Mose sprach: Das hat euch der Herr zu tun befohlen, damit euch die Herrlichkeit des Herrn erscheine.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Dann sprach Mose zu Aaron: Tritt zum Altar und verrichte dein Sündopfer und dein Brandopfer, und schaffe so Sühne für dich und dein Haus. Darnach bringe die Opfergabe des Volkes dar und schaffe ihnen Sühne, wie der Herr geboten hat. (a) 3Mo 16:6; Heb 7:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Da trat Aaron zum Altar und schlachtete das Kalb, das zum Sündopfer für ihn bestimmt war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Die Söhne Aarons aber brachten ihm das Blut, und er tauchte den Finger in das Blut und strich davon an die Hörner des Altars; das (übrige) Blut goss er am Altar auf den Boden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Das Fett des Sündopfers aber und die Nieren und das Fett neben der Leber verbrannte er auf dem Altar, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Und das Fleisch nebst der Haut verbrannte er ausserhalb des Lagers. (a) 3Mo 4:11 12; 8:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Darnach schlachtete er das Brandopfer, und die Söhne Aarons brachten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Und das Brandopfer selbst brachten sie ihm regelrecht in Stücke zerlegt samt dem Kopf, und er verbrannte es auf dem Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Dann wusch er die Eingeweide und die Unterschenkel und verbrannte sie über dem Brandopfer auf dem Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Darnach brachte er die Opfergabe des Volkes dar: er nahm den Bock, der zum Sündopfer für das Volk bestimmt war, und schlachtete ihn und brachte ihn als Sündopfer dar, wie das erstemal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Hierauf brachte er das Brandopfer dar und besorgte es nach der Vorschrift.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Er brachte auch das Speisopfer dar: er nahm eine Handvoll davon und verbrannte es auf dem Altar, ausser dem Morgenbrandopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Endlich schlachtete er das Rind und den Widder, die zum Heilsopfer für das Volk bestimmt waren. Und die Söhne Aarons brachten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Die Fettstücke des Rindes und des Widders aber, den Fettschwanz und (das Fett), das (die Eingeweide) bedeckt, die Nieren und das Fett neben der Leber -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'alle diese Fettstücke legten sie auf die Brust, und er verbrannte die Fettstücke auf dem Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Die Brust aber und die rechte Keule schwang Aaron als Webeopfer vor dem Herrn, wie Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Dann erhob Aaron seine Hände gegen das Volk hin und segnete es, und nachdem er das Sündopfer, das Brandopfer und das Heilsopfer dargebracht hatte, stieg er herab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Hierauf gingen Mose und Aaron in das heilige Zelt hinein, und als sie wieder herauskamen, segneten sie das Volk. Da erschien die Herrlichkeit des Herrn dem ganzen Volke,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'und Feuer ging aus von dem Herrn und verzehrte das Brandopfer und die Fettstücke auf dem Altar. Als alles Volk das sah, jubelten sie und fielen auf ihr Angesicht. (a) 1Kön 18:38');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'NADAB und Abihu aber, die Söhne Aarons, nahmen ein jeder seine Räucherpfanne, taten Feuer darein und legten Räucherwerk darauf und brachten so vor dem Herrn ein ungehöriges Feueropfer dar, das er ihnen nicht geboten hatte. (a) 2Mo 30:9; 4Mo 3:4');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer aus von dem Herrn und verzehrte sie, sodass sie vor dem Herrn starben. (a) 4Mo 16:35');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sprach Mose zu Aaron: Das ist es, was der Herr gemeint hat, als er sprach: Die mir nahe stehen, an ihnen erweise ich mich heilig, / und vor allem Volk verherrliche ich mich. Und Aaron schwieg.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mose aber rief Misael und Elzaphan, die Söhne Ussiels, des Oheims Aarons, und sprach zu ihnen: Tretet herzu und tragt eure Verwandten von dem Platze vor dem Heiligtum hinaus vor das Lager.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Und sie traten herzu und trugen sie in ihren Leibröcken hinaus vor das Lager, wie Mose gesagt hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Dann sprach Mose zu Aaron und seinen Söhnen Eleasar und Ithamar: Ihr dürft euer Haupthaar nicht frei flattern lassen und eure Kleider nicht zerreissen, damit ihr nicht sterbet und der Zorn (Gottes) über die ganze Gemeinde komme. Doch eure Brüder, das ganze Haus Israel, sie mögen weinen über den Brand, den der Herr entzündet hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ihr dürft nicht vom Eingang des heiligen Zeltes weggehen, damit ihr nicht sterbet; denn das Salböl des Herrn ist auf euch. Und sie taten, wie Mose gebot.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Und der Herr redete mit Aaron und sprach: (a) Hes 44:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Wein und berauschendes Getränk sollt ihr nicht trinken, weder du noch deine Söhne, wenn ihr in das heilige Zelt hineingeht; sonst müsst ihr sterben. Das ist eine immerwährende Satzung für euch von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Ihr sollt unterscheiden zwischen dem, was heilig, und dem, was nicht heilig ist, zwischen dem, was unrein, und dem, was rein ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und sollt die Israeliten alle Satzungen lehren, die ihnen der Herr durch Mose kundgetan hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose sprach zu Aaron und seinen Söhnen Eleasar und Ithamar, die ihm noch geblieben waren: Nehmt das Speisopfer, das von den Feueropfern des Herrn übriggeblieben ist, und esst es ungesäuert beim Altar; denn es ist hochheilig. (a) 3Mo 2:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Ihr sollt es an heiliger Stätte essen, denn es ist der Anteil, der dir und deinen Söhnen von den Feueropfern des Herrn zukommt; so ist es mir geboten worden. (a) 3Mo 6:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Und die Webebrust und die Hebekeule sollt ihr an reiner Stätte essen, du und deine Söhne und Töchter mit dir. Denn sie sind dir und deinen Kindern gegeben als der Anteil, der euch von den Heilsopfern der Israeliten zukommt. (a) 3Mo 7:34; 4Mo 18:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Die Hebekeule und die Webebrust soll man zusammen mit den zum Feueropfer bestimmten Fettstücken herbringen, um sie als Webeopfer vor dem Herrn zu schwingen. Dies soll dir und auch deinen Kindern für alle Zeiten als Gebühr zufallen, wie der Herr geboten hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Als nun Mose den Sündopferbock suchte, siehe, da war er schon verbrannt. Da wurde er zornig über Eleasar und Ithamar, die Söhne Aarons, die noch übrig waren, und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr das Sündopfer nicht gegessen an heiliger Stätte? Denn es ist hochheilig, und er hat es euch gegeben, um die Schuld der Gemeinde hinwegzunehmen und ihr Sühne zu schaffen vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Sein Blut ist ja nicht ins Innere des Heiligtums hineingebracht worden; so hättet ihr es an heiliger Stätte essen sollen, wie ich geboten habe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Aaron aber sprach zu Mose: Siehe, heute haben sie ihr Sündopfer und ihr Brandopfer vor dem Herrn dargebracht, und doch ist mir solches widerfahren. Hätte ich nun heute vom Sündopfer gegessen, wäre es dem Herrn wohlgefällig gewesen?');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Als Mose das hörte, war er es zufrieden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'UND der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Gebietet den Israeliten folgendes: Dies sind die Tiere, die ihr essen dürft von allem Getier auf Erden:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'alle Tiere, die gespaltene Klauen, und zwar zwei völlig getrennte Klauen, haben und Wiederkäuer sind, die dürft ihr essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Doch dürft ihr von denen, welche wiederkäuen, und von denen, die gespaltene Klauen haben, folgende nicht essen: das Kamel - denn es ist zwar ein Wiederkäuer, hat aber keine gespaltenen Klauen; als unrein soll es euch gelten -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'den Klippdachs - denn er ist zwar ein Wiederkäuer, hat aber keine gespaltenen Klauen; als unrein soll er euch gelten -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'den Hasen - denn er ist zwar ein Wiederkäuer, hat aber keine gespaltenen Klauen; als unrein soll er euch gelten -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'und das Schwein; denn es hat allerdings gespaltene Klauen, und zwar völlig getrennte Klauen, ist aber kein Wiederkäuer; als unrein soll es euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Von ihrem Fleisch dürft ihr nicht essen, und ihren Leichnam dürft ihr nicht berühren; als unrein sollen sie euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Dies ist\'s, was ihr essen dürft von allem, was im Wasser lebt: alles, was Flossen und Schuppen hat im Wasser, in grossen und kleinen Gewässern, das dürft ihr essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Was aber keine Flossen und Schuppen hat in grossen und kleinen Gewässern, was immer im Wasser wimmelt und was immer im Wasser lebt, das alles soll euch ein Greuel sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ja, ein Greuel sollen sie euch sein: von ihrem Fleisch dürft ihr nicht essen, und ihren Leichnam sollt ihr verabscheuen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alle Wassertiere, die keine Flossen und Schuppen haben, sollen euch ein Greuel sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Und von den Vögeln sollt ihr folgende verabscheuen - man darf sie nicht essen, denn sie sind ein Greuel -: den Adler, den Lämmergeier, den Bartgeier,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'die Weihe und die Falkenarten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'alle Rabenarten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'den Strauss, die Ohreule, die Möwe und die Habichtarten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'das Käuzchen, den Sturzpelikan und den Uhu,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'die Eule, die Rohrdommel und den Aasgeier,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'den Storch, die Reiherarten, den Wiedehopf und die Fledermaus.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Auch alles geflügelte Geziefer, das auf vieren geht, soll euch ein Greuel sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Von allem geflügelten Geziefer, das auf vieren geht, dürft ihr nur solches essen, das über den Füssen zwei Schenkel hat, mit denen es auf der Erde hüpft.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von diesen dürft ihr folgende essen: die Arten der Wanderheuschrecke und die Arten des Soleam, des Hargol und des Hagab. (1) Namen verschiedener, nicht mehr näher bestimmbarer Heuschreckenarten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Alles (übrige) geflügelte Geziefer aber, das vier Füsse hat, soll euch ein Greuel sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Und an folgenden (Tieren) verunreinigt ihr euch - wer deren Leichnam berührt, ist unrein bis zum Abend, (a) 3Mo 5:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'und wer einen solchen Leichnam trägt, der soll seine Kleider waschen, und er ist unrein bis zum Abend -:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'an jedem Tier, das zwar gespaltene, aber nicht völlig getrennte Klauen hat und das nicht wiederkäut; als unrein sollen sie euch gelten. Wer ihren Leichnam berührt, ist unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Auch alles, was auf Tatzen geht unter allen Tieren, die auf vieren gehen, soll euch als unrein gelten. Wer ihren Leichnam berührt, ist unrein bis zum Abend,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'und wer ihren Leichnam trägt, soll seine Kleider waschen, und er bleibt unrein bis zum Abend; als unrein sollen sie euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Und unter den kleinen Tieren, die auf der Erde wimmeln, sollen euch die folgenden als unrein gelten: das Wiesel, die Maus und die Eidechsenarten, nämlich der Zab,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'die Anaka, der Koah, die Letaa und der Homet, und das Chamäleon.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese sollen euch als unrein gelten unter allen kleinen Tieren. Wer sie berührt, wenn sie tot sind, wird unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Und jeder Gegenstand, auf den eine solche Tierleiche fällt, wird unrein, sei es nun ein hölzernes Geschirr oder ein Kleidungsstück oder Lederzeug oder ein Sack - jedes Gerät, das zu irgendwelchem Gebrauche dient. Man soll es ins Wasser tun, und es bleibt unrein bis zum Abend; dann ist es wieder rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Und wenn eine solche (Tierleiche) in irgendein irdenes Geschirr fällt, so wird alles unrein, was darin ist, und ihr sollt es zerbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'In jedem solchen Geschirr wird jede Speise, die man isst, unrein, wenn Wasser darein kommt, und wird jedes Getränk, das man trinkt, unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Und alles, worauf eine solche Tierleiche fällt, wird unrein; ist es ein Backofen oder ein Kochherd, so soll er eingerissen werden; sie sind unrein, und als unrein sollen sie euch gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Quellen jedoch und Zisternen, in denen sich Wasser sammelt, bleiben rein. Wer aber die Tierleiche darin berührt, wird unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Und wenn eine solche Tierleiche auf irgendwelchen Samen fällt, den man aussät, so bleibt er doch rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Wenn man aber Wasser auf den Samen giesst, und es fällt dann eine solche Tierleiche darauf, so soll er euch als unrein gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Wenn eines von den Tieren, die ihr essen dürft, stirbt, so ist, wer die Tierleiche berührt, unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Wer aber von der Tierleiche isst, der soll seine Kleider waschen, und er bleibt unrein bis zum Abend. Ebenso muss, wer die Tierleiche aufhebt, seine Kleider waschen, und er bleibt unrein bis zum Abend. (a) 3Mo 22:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Alle kleinen Tiere, die auf der Erde wimmeln, sollen euch ein Greuel sein; man darf sie nicht essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alles, was auf dem Bauche kriecht, und alles, was auf vier oder mehr Füssen geht, unter all den kleinen Tieren, die auf der Erde wimmeln, das dürft ihr nicht essen; denn es ist ein Greuel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Macht euch nicht selbst zum Greuel durch all das kriechende Getier und verunreinigt euch nicht damit, sodass ihr unrein werdet;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'denn ich bin der Herr, euer Gott. Darum sollt ihr euch heilig halten und sollt heilig sein; denn ich bin heilig. Und verunreinigt euch nicht selbst durch all das Getier, das auf der Erde wimmelt. (a) 3Mo 19:2; 2Mo 22:31');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich bin der Herr, der euch aus dem Lande Ägypten heraufgeführt hat, dass ich euer Gott sei; darum sollt ihr heilig sein, denn ich bin heilig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Das ist das Gesetz über das Vieh und die Vögel und alle die Lebewesen, von denen das Wasser wimmelt, und über all das Getier, das auf der Erde sich tummelt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'damit ihr unterscheidet zwischen dem, was unrein, und dem, was rein ist, zwischen den Tieren, die man essen, und denen, die man nicht essen darf.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Sage zu den Israeliten: Wenn ein Weib Mutter wird und einen Knaben gebiert, so bleibt sie sieben Tage lang unrein; wie in den Tagen ihrer Unreinheit infolge des Monatsflusses wird sie unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Am achten Tage sodann soll man das Kind an der Vorhaut beschneiden. (a) 1Mo 17:10-12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Sie aber soll (noch weitere) 33 Tage daheim bleiben im Blute der Reinigung; sie darf nichts Heiliges berühren, und zum Heiligtum darf sie nicht kommen, bis die Tage ihrer Reinigung um sind.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Gebiert sie aber ein Mädchen, so bleibt sie zwei Wochen unrein wie bei ihrem Monatsfluss, und sie soll (dann noch) 66 Tage daheim bleiben im Blute der Reinigung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Wenn dann die Tage ihrer Reinigung um sind, handle es sich nun um einen Knaben oder ein Mädchen, so soll sie dem Priester ein einjähriges Lamm zum Brandopfer und eine junge gewöhnliche Taube oder eine Turteltaube zum Sündopfer an den Eingang des heiligen Zeltes bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Der soll das Opfer vor dem Herrn darbringen und ihr so Sühne schaffen; dann wird sie rein von ihrem Blutfluss. Das ist das Gesetz über die Wöchnerin, sei es, dass sie einen Knaben oder ein Mädchen geboren hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Vermag sie aber kein Schaf, so nehme sie zwei Turteltauben oder zwei junge gewöhnliche Tauben, die eine zum Brandopfer und die andre zum Sündopfer, und der Priester soll ihr Sühne schaffen; dann wird sie rein. (a) 3Mo 5:7; Lu 2:24');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'UND der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Wenn sich bei jemandem auf der Haut eine Geschwulst oder ein Ausschlag oder ein heller Fleck zeigt und daraus auf seiner Haut ein Aussatzmal entsteht, so soll man ihn zu Aaron, dem Priester, oder zu einem von seinen Söhnen, den Priestern, führen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Wenn dann der Priester das Mal auf der Haut besieht, und die Haare an der kranken Stelle sind weiss geworden und das Mal erscheint tiefer als die (übrige) Haut, so ist es ein Aussatzmal; wenn der Priester das sieht, soll er ihn für unrein erklären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Wenn es aber ein weisser Fleck auf der Haut ist, und dieser erscheint nicht tiefer als die (übrige) Haut, und die Haare darauf sind nicht weiss geworden, so soll der Priester den Betroffenen sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Besieht ihn dann der Priester am siebenten Tage, und das Mal ist in seinem Aussehen gleich geblieben, ohne auf der Haut weiter um sich zu greifen, so soll ihn der Priester abermals sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Wenn ihn dann der Priester am siebenten Tage zum zweitenmal besieht und findet, dass das Mal am Verschwinden ist, ohne auf der Haut weiter um sich zu greifen, so soll ihn der Priester für rein erklären - es ist nur ein Ausschlag; er aber soll seine Kleider waschen, dann ist er wieder rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Ausschlag auf der Haut weiter um sich greift, nachdem er sich dem Priester gezeigt hat, um wieder rein zu werden, und er zeigt sich nun dem Priester zum zweitenmal,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'und der Priester sieht, dass der Ausschlag auf der Haut weiter um sich gegriffen hat, so soll ihn der Priester für unrein erklären - es ist Aussatz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Wenn sich an jemandem ein Aussatzmal zeigt, so soll man ihn zum Priester führen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Sieht dann der Priester, dass sich auf der Haut eine weisse Geschwulst befindet und dass die Haare darauf weiss geworden sind und wildes Fleisch in der Geschwulst wuchert,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so ist es ein alter Aussatz auf seiner Haut, und der Priester soll ihn für unrein erklären und ihn nicht absondern; denn er ist schon unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz auf der Haut so ausbricht, dass der Aussatz die ganze Haut des Kranken vom Kopf bis zu den Füssen bedeckt, wohin auch der Priester schauen mag -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'wenn also der Priester sieht, dass der Aussatz den ganzen Leib bedeckt, so soll er den Kranken für rein erklären; er ist ja ganz weiss geworden und ist also rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Sobald sich aber wildes Fleisch an ihm zeigt, wird er unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und wenn der Priester das wilde Fleisch sieht, soll er ihn für unrein erklären; denn das wilde Fleisch ist unrein - es ist ein Aussatz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Geht aber das wilde Fleisch wieder zurück, und er wird weiss, so soll er zum Priester kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Findet dann der Priester, wenn er ihn besieht, dass das Mal weiss geworden ist, so soll der Priester den Kranken für rein erklären; er ist rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Wenn auf jemandes Haut ein Geschwür entsteht und wieder heilt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'dann aber an der Stelle des Geschwürs eine weisse Geschwulst sich bildet oder ein weissrötlicher Fleck, so soll er sich dem Priester zeigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Sieht dann der Priester, dass die Stelle tiefer erscheint als die (übrige) Haut und dass das Haar darauf weiss geworden ist, so soll ihn der Priester für unrein erklären; es ist ein Mal von Aussatz, der in dem Geschwür ausgebrochen ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Findet aber der Priester beim Besehen, dass keine weissen Haare darauf sind und dass der Fleck nicht tiefer erscheint als die (übrige) Haut und am Verschwinden ist, so soll der Priester den Kranken sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Greift es dann auf der Haut weiter um sich, so soll ihn der Priester für unrein erklären - es ist ein Aussatzmal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Bleibt aber der helle Fleck an Ort und Stelle, ohne weiter um sich zu greifen, so ist es die Narbe des Geschwürs, und der Priester soll ihn für rein erklären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Oder wenn jemand auf der Haut eine Brandwunde bekommt, und das wilde Fleisch in der Brandwunde erscheint als weissrötlicher oder weisser Fleck,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester findet beim Besehen, dass die Haare auf dem hellen Fleck weiss geworden sind und dass die Stelle tiefer erscheint als die (übrige) Haut, so ist es Aussatz, der in der Brandwunde ausgebrochen ist, und der Priester soll den Kranken für unrein erklären - es ist ein Aussatzmal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Findet aber der Priester beim Besehen, dass keine weissen Haare auf dem hellen Fleck sind und dass dieser nicht tiefer erscheint als die (übrige) Haut und am Verschwinden ist, so soll der Priester den Kranken sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Am siebenten Tage soll der Priester ihn besehen; hat es dann auf der Haut weiter um sich gegriffen, so soll ihn der Priester für unrein erklären - es ist ein Aussatzmal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Bleibt aber der helle Fleck an Ort und Stelle, ohne auf der Haut weiter um sich zu greifen, und ist er am Verschwinden, so ist es die Narbe der Brandwunde, und der Priester soll ihn für rein erklären, weil es nur die Narbe der Brandwunde ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Wenn bei einem Manne oder einem Weibe auf dem Kopf oder am Bart ein Mal entsteht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester besieht das Mal und findet, dass es tiefer erscheint als die (übrige) Haut und dass goldfarbene, dünne Haare darauf sind, so soll der Priester den Kranken für unrein erklären - es ist bösartiger Ausschlag, der Aussatz des Kopfes oder des Bartes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Findet aber der Priester, wenn er den Ausschlag besieht, dass er nicht tiefer erscheint als die (übrige) Haut, dass aber auch keine dunklen Haare darauf sind, so soll der Priester den vom Ausschlag Betroffenen sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Am siebenten Tage soll der Priester das Mal besehen; hat dann der Ausschlag nicht weiter um sich gegriffen, und sind keine goldfarbenen Haare darauf entstanden, erscheint auch der Ausschlag nicht tiefer als die (übrige) Haut,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so soll er sich scheren; doch die Ausschlagstelle darf er nicht scheren. Hierauf soll der Priester den vom Ausschlag Betroffenen abermals sieben Tage lang absondern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Wenn dann am siebenten Tage der Priester den Ausschlag besieht und findet, dass der Ausschlag auf der Haut nicht weiter um sich gegriffen hat und dass er nicht tiefer erscheint als die (übrige) Haut, so soll ihn der Priester für rein erklären; er aber soll seine Kleider waschen, dann ist er rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Greift aber der Ausschlag auf der Haut weiter um sich, nachdem der Kranke für rein erklärt worden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester findet beim Besehen, dass der Ausschlag auf der Haut weiter um sich gegriffen hat, so braucht der Priester nicht mehr nach goldfarbenen Haaren zu suchen; er ist unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ist aber der Ausschlag in seinem Aussehen gleich geblieben, und sind dunkle Haare darauf gewachsen, so ist der Ausschlag geheilt; er ist rein, und der Priester soll ihn für rein erklären.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Wenn sich bei einem Manne oder einem Weibe auf der Haut helle Flecken zeigen, weisse helle Flecken,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester findet beim Besehen auf ihrer Haut nur matte, weisse Flecken, so ist es ein gutartiger Ausschlag, der auf der Haut ausgebrochen ist; er ist rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wenn jemandem die Haupthaare ausfallen, sodass er hinten kahl wird, so bleibt er rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Fallen sie ihm auf der Vorderseite des Kopfes aus, sodass er vorn eine Glatze bekommt, so bleibt er rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Entsteht aber auf der hintern oder vordern Glatze ein weissrötliches Mal, so ist es Aussatz, der auf seiner hintern oder vordern Glatze ausbricht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Besieht ihn dann der Priester und findet, dass die Geschwulst des Males auf seiner hintern oder vordern Glatze weissrötlich ist und aussieht wie der Aussatz auf der Haut am Leibe,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist er ein Aussätziger; er ist unrein, und der Priester soll ihn für unrein erklären; er hat die Krankheit auf dem Kopfe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Es soll aber der Aussätzige, der die Krankheit an sich hat, zerrissene Kleider tragen, die Haare frei flattern lassen und den Bart verhüllen, und er soll rufen: Unrein, unrein!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Solange er die Krankheit an sich hat, bleibt er unrein. Er ist unrein; abgesondert soll er wohnen, seine Wohnstätte soll ausserhalb des Lagers sein. (a) 4Mo 5:2; 2Kön 7:3; 15:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Wenn sich an einem Kleide, sei es nun von Wolle oder von Flachs, ein Aussatzmal zeigt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'oder an gewobenem oder gewirktem Zeug, es sei von Flachs oder von Wolle, oder an Leder oder an irgend etwas, was aus Leder gemacht wird,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und das Mal an dem Kleid oder dem Leder oder dem gewobenen oder gewirkten Zeug oder an irgendwelchem aus Leder gemachten Gegenstand ist grünlich oder rötlich, so ist es ein Aussatzmal und soll dem Priester gezeigt werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und wenn der Priester das Mal besehen hat, soll er den schadhaften Gegenstand sieben Tage lang einschliessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Wenn er dann am siebenten Tage sieht, dass der Schaden an dem Kleid oder dem gewobenen oder gewirkten Zeug oder dem Leder - an irgend etwas, was man aus Leder macht - weiter um sich gegriffen hat, so ist der Schaden ein bösartiger Aussatz; es ist unrein,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'und er soll das Kleid oder das gewobene oder gewirkte Zeug, es sei von Wolle oder von Flachs, oder jeden ledernen Gegenstand, an dem sich der Schaden zeigt, verbrennen; denn es ist ein bösartiger Aussatz, man soll es verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Sieht aber der Priester, dass der Schaden an dem Kleid oder dem gewobenen oder gewirkten Zeug oder an irgendwelchem ledernen Gegenstand nicht weiter um sich gegriffen hat,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so soll der Priester gebieten, dass man den Gegenstand, an dem der Schaden ist, wasche, und soll ihn abermals sieben Tage lang einschliessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Sieht dann der Priester, nachdem die schadhafte Stelle gewaschen worden ist, dass sie ihr Aussehen nicht geändert hat, so ist es unrein, auch wenn der Schaden nicht weiter um sich gegriffen hat, du sollst es ausbrennen; es ist eine eingefressene Vertiefung, sei es auf der hintern oder der vordern Seite.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Sieht aber der Priester, dass der Schaden, nachdem die Stelle gewaschen worden, verblasst ist, so soll er das Stück aus dem Kleid oder dem Leder oder dem gewobenen oder gewirkten Zeug herausreissen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Zeigt es sich aber wieder an dem Kleid oder dem gewobenen oder gewirkten Zeug oder an irgendwelchem ledernen Gegenstand, so ist es neu ausbrechender (Aussatz); du sollst es verbrennen, (das ganze Stück,) an dem der Schaden ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Wenn aber an dem Kleid oder dem gewobenen oder gewirkten Zeug oder an irgendwelchem ledernen Gegenstand der Schaden beim Waschen verschwindet, so soll man es nochmals waschen, dann ist es rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Das ist das Gesetz über das Aussatzmal an Kleidern, seien sie von Wolle oder von Flachs, oder an gewobenem oder gewirktem Zeug oder an irgendwelchem ledernen Gegenstand, wornach sie für rein oder für unrein zu erklären sind.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Dies ist das Gesetz über den Aussätzigen für den Tag seiner Reinigung: er soll zum Priester geführt werden, (a) Mt 8:4; Lu 17:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'und zwar soll der Priester vor das Lager hinausgehen. Wenn dann der Priester sieht, dass das Aussatzmal an dem Aussätzigen heil geworden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so lasse der Priester für den, der sich reinigen lässt, zwei lebende Vögel, welche rein sind, und Zedernholz, Karmesin und Ysop bringen. (a) Ps 51:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Dann lasse der Priester den einen Vogel schlachten (und das Blut abtropfen) in ein irdenes Geschirr über Quellwasser;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'den lebenden Vogel aber, den nehme er nebst dem Zedernholz, dem Karmesin und Ysop, tauche das alles samt dem lebenden Vogel in das Blut des über dem Quellwasser geschlachteten Vogels,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'besprenge damit siebenmal denjenigen, der sich vom Aussatz reinigen lässt, und reinige ihn so; dann lasse er den lebenden Vogel ins freie Feld fliegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Der aber, der sich reinigen lässt, soll seine Kleider waschen, alle seine Haare abscheren und sich in Wasser baden; dann ist er rein. Darnach darf er wieder ins Lager hereinkommen; doch muss er noch sieben Tage lang ausserhalb seines Zeltes bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Am siebenten Tage sodann soll er alle seine Haare abscheren, das Haupthaar, den Bart und die Augenbrauen - alle seine Haare soll er abscheren. Hierauf soll er seine Kleider waschen und seinen Leib in Wasser baden; dann ist er rein. (a) 2Kön 5:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Und am achten Tage nehme er zwei fehllose männliche Lämmer und ein einjähriges, fehlloses weibliches Lamm, ferner drei zehntel (Epha) Semmelmehl, mit Öl eingerührt, zum Speisopfer, und ein Log Öl.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Und der Priester, der die Reinigung vollzieht, soll den Mann, der sich reinigen lässt, samt diesen Dingen vor dem Herrn darstellen, am Eingang des heiligen Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Dann nehme der Priester das eine männliche Lamm, bringe es mit dem Log Öl als Schuldopfer dar und schwinge beides als Webeopfer vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Und zwar soll man das Lamm an der Stätte schlachten, wo man das Sündopfer und das Brandopfer schlachtet, an heiliger Stätte. Denn wie das Sündopfer, so gehört auch das Schuldopfer dem Priester; es ist hochheilig.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Dann nehme der Priester von dem Blute des Schuldopfers und streiche es dem, der sich reinigen lässt, an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Darnach nehme der Priester etwas von dem Log Öl und giesse es in seine eigene linke Hand.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Dann tauche der Priester seinen rechten Finger in das Öl, das in seiner linken Hand ist, und sprenge von dem Öl mit seinem Finger siebenmal vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Von dem übrigen Öl in seiner Hand aber streiche der Priester dem, der sich reinigen lässt, an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses, auf das Blut des Schuldopfers.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Und den Rest des Öls in seiner Hand tue der Priester dem, der sich reinigen lässt, auf das Haupt und schaffe ihm so Sühne vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Hierauf soll der Priester das Sündopfer darbringen und dem, der sich reinigen lässt, für seine Unreinheit Sühne schaffen, und darnach soll er das Brandopfer schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Und der Priester soll das Brandopfer samt dem Speisopfer auf dem Altar darbringen und ihm so Sühne schaffen; dann ist er rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ist der Betreffende aber arm und vermag er nicht so viel, so nehme er ein männliches Lamm zum Schuldopfer, damit es geschwungen und ihm so Sühne geschafft werde, dazu ein zehntel (Epha) Semmelmehl, mit Öl eingerührt, zum Speisopfer, und ein Log Öl,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'ferner zwei Turteltauben oder zwei junge gewöhnliche Tauben, was er eben zu leisten vermag, die eine zum Sündopfer, die andre zum Brandopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Das alles bringe er am achten Tage seiner Reinigung zum Priester an den Eingang des heiligen Zeltes vor den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Und der Priester nehme das Schuldopferlamm und das Log Öl und schwinge es vor dem Herrn als Webeopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Dann schlachte man das Schuldopferlamm, und der Priester nehme von dem Blute des Schuldopfers und streiche es dem, der sich reinigen lässt, an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Von dem Öl aber giesse der Priester in seine eigene linke Hand');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und sprenge mit seinem rechten Finger von dem Öl, das in seiner linken Hand ist, siebenmal vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Dann streiche der Priester von dem Öl in seiner Hand dem, der sich reinigen lässt, an das rechte Ohrläppchen, sowie an den Daumen der rechten Hand und an die grosse Zehe des rechten Fusses, auf das Blut des Schuldopfers.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Den Rest des Öls in seiner Hand aber tue der Priester dem, der sich reinigen lässt, auf das Haupt, um ihm so Sühne zu schaffen vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Darnach soll er von den Turteltauben oder den jungen gewöhnlichen Tauben, die jener vermag,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'die eine als Sündopfer, die andre als Brandopfer darbringen, samt dem Speisopfer; so soll der Priester dem, der sich reinigen lässt, Sühne schaffen vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das ist das Gesetz über den, der ein Aussatzmal an sich hat und bei seiner Reinigung nicht so viel vermag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihr in das Land Kanaan kommt, das ich euch zu eigen geben will, und ich lasse dann in dem Lande, das ihr besitzt, an einem Hause ein Aussatzmal entstehen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soll der, dem das Haus gehört, herkommen und es dem Priester anzeigen, indem er sagt: \"An meinem Hause zeigt sich etwas wie ein (Aussatz-)Mal.\"');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Dann soll der Priester, ehe er hineingeht, um das Mal zu besehen, das Haus ausräumen lassen, damit nicht alles unrein werde, was im Hause ist; darnach erst soll der Priester hineingehen, um das Haus zu besehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Wenn er nun beim Besehen des Mals findet, dass der Schaden an den Wänden des Hauses in grünlichen oder rötlichen Grübchen besteht, die tiefer erscheinen als die Wand sonst,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soll der Priester aus dem Hause hinaus an die Türe des Hauses treten und das Haus für sieben Tage verschliessen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Wenn dann der Priester am siebenten Tage wieder kommt und sieht, dass der Schaden an den Wänden des Hauses weiter um sich gegriffen hat,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soll der Priester die Steine, an denen der Schaden ist, ausbrechen und vor die Stadt hinaus an einen unreinen Ort werfen lassen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'das Haus aber soll man inwendig ringsherum abkratzen und den Schutt, den man abgekratzt hat, draussen vor der Stadt an einen unreinen Ort schütten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Dann soll man andre Steine nehmen und an Stelle jener Steine einsetzen, soll auch andern Mörtel nehmen und das Haus frisch bewerfen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn dann der Schaden am Hause wiederum auftritt, nachdem man die Steine ausgebrochen und das Haus abgekratzt und frisch beworfen hat,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soll der Priester hineingehen, und wenn er sieht, dass der Schaden am Hause weiter um sich gegriffen hat, so ist es ein bösartiger Aussatz am Hause; es ist unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Dann soll man das Haus abbrechen, die Steine, das Holz und allen Mörtel am Hause, und soll alles vor die Stadt hinaus an einen unreinen Ort führen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus hineingeht, solange es verschlossen ist, der wird unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Und wer in dem Hause schläft, der soll seine Kleider waschen; auch wer in dem Hause isst, soll seine Kleider waschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wenn aber der Priester hineingeht und beim Besehen findet, dass der Schaden am Hause nicht weiter um sich gegriffen hat, nachdem das Haus frisch beworfen worden ist, so soll der Priester das Haus für rein erklären; denn der Schaden ist geheilt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Dann nehme er, um das Haus zu entsündigen, zwei Vögel, Zedernholz, Karmesin und Ysop.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Den einen Vogel schlachte er (und lasse das Blut abtropfen) in ein irdenes Geschirr über Quellwasser,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'nehme dann das Zedernholz, den Ysop, das Karmesin und den lebenden Vogel, tauche alles in das Blut des geschlachteten Vogels und in das Quellwasser und besprenge das Haus siebenmal.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'So soll er das Haus mit dem Blute des Vogels und dem Quellwasser, mit dem lebenden Vogel, dem Zedernholz, dem Ysop und dem Karmesin entsündigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Dann lasse er den lebenden Vogel vor die Stadt hinaus ins freie Feld fliegen und schaffe so Sühne für das Haus; dann ist es rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Das ist das Gesetz über alle Aussatzmäler und über den Ausschlag,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'über den Aussatz an Kleidern und an Häusern,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'über die Geschwulst, den Schorf und die hellen Flecken,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um Weisung zu geben, wann etwas für unrein oder für rein zu erklären sei. Das ist das Gesetz über den Aussatz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'UND der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet mit den Israeliten und sprecht zu ihnen: Wenn irgendein Mann an seinem Glied mit einem Fluss behaftet ist, so ist er durch den Fluss unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Und mit seiner Unreinheit infolge des Flusses steht es so: ob sein Glied den Fluss triefen lässt oder ob sein Glied verstopft ist, er ist unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jedes Lager, auf dem der an Fluss Leidende liegt, wird unrein, und jedes Gerät, auf dem er sitzt, wird unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Und wer sein Lager berührt, der soll seine Kleider waschen und sich in Wasser baden und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Und wer sich auf das Gerät setzt, auf dem der Leidende sass, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Und wer den Leib des Leidenden berührt, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Und wenn der Leidende einen Reinen anspeit, so soll der seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Auch jeder Sitz, auf dem der Leidende reitet oder fährt, wird unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Und wer irgend etwas berührt, das sich unter jenem befindet, der wird unrein bis zum Abend; und wer es wegträgt, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und wen der Leidende berührt, ohne zuvor die Hände mit Wasser abgespült zu haben, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Und ein irdenes Geschirr, das der Leidende berührt, soll man zerbrechen; jedes hölzerne aber soll man mit Wasser abspülen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Wenn aber der Leidende von seinem Flusse rein wird, so soll er von seinem Reinwerden an sieben Tage zählen; dann soll er seine Kleider waschen und seinen Leib in Quellwasser baden - dann ist er rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Und am achten Tage nehme er zwei Turteltauben oder zwei junge gewöhnliche Tauben, komme damit vor den Herrn, an den Eingang des heiligen Zeltes, und übergebe sie dem Priester;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'der Priester aber soll sie darbringen, die eine als Sündopfer und die andre als Brandopfer; so schaffe ihm der Priester Sühne vor dem Herrn wegen seines Flusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Wenn bei einem Manne Samenerguss eintritt, so soll er seinen ganzen Leib in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und jedes Kleid oder Fell, an das solcher Same kommt, soll mit Wasser gewaschen werden und ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und wenn ein Mann bei einem Weibe liegt und Samenerguss eintritt, so sollen sie sich in Wasser baden, und sie sind unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Wenn ein Weib den Monatsfluss hat, so bleibt sie sieben Tage lang in ihrer Unreinheit, und jeder, der sie berührt, wird unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Auch alles, worauf sie während ihrer Unreinheit liegt, wird unrein, und alles, worauf sie sitzt, wird unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und wer ihr Lager berührt, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und wer irgendein Gerät berührt, auf dem sie sass, der soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Auch wenn jemand etwas berührt, das auf ihrem Lager oder auf dem Gerät war, auf dem sie sass, so wird er unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn ein Mann bei ihr liegt, und es kommt ihre Unreinheit an ihn, so wird er sieben Tage lang unrein, und jedes Lager, auf dem er liegt, wird unrein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Wenn aber ein Weib den Blutfluss lange Zeit hindurch hat, nicht zur Zeit ihres Monatsflusses, oder über die Zeit ihres Monatsflusses hinaus, so ist sie während der ganzen Zeit ihres unreinen Flusses unrein, wie in den Tagen ihres Monatsflusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Jedes Lager, auf dem sie liegt, solange ihr Fluss andauert, soll ihr gelten wie das Lager während ihres Monatsflusses; und jedes Gerät, auf dem sie sitzt, wird unrein, wie dann, wenn sie infolge des Monatsflusses unrein ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Und wer diese Dinge berührt, der wird unrein, und er soll seine Kleider waschen und sich in Wasser baden, und er ist unrein bis zum Abend.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Wenn sie aber rein geworden ist von ihrem Flusse, so soll sie sieben Tage zählen; darnach gilt sie als rein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage nehme sie zwei Turteltauben oder zwei junge gewöhnliche Tauben und bringe sie zum Priester an den Eingang des heiligen Zeltes;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'der Priester aber soll die eine als Sündopfer und die andre als Brandopfer darbringen, und so soll ihr der Priester Sühne schaffen vor dem Herrn wegen ihres unreinen Flusses.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'So sollt ihr die Israeliten von ihrer Unreinheit befreien, damit sie nicht um ihrer Unreinheit willen sterben, wenn sie meine Wohnung verunreinigen, die mitten unter ihnen ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Das ist das Gesetz über den, der an einem Fluss leidet, und über den, der einen Samenerguss hat, sodass er dadurch unrein wird,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und über die, welche am Monatsfluss leidet, und über den, der einen Fluss hat, es sei Mann oder Weib, und über einen Mann, der bei einer Unreinen liegt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'UND der Herr redete mit Mose nach dem Tode der beiden Söhne Aarons, die sterben mussten, als sie vor den Herrn traten, (a) 3Mo 10:1 2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'und sprach zu ihm: Sage deinem Bruder Aaron, dass er nicht zu jeder Zeit in das Heiligtum hineingehe hinter den Vorhang vor die Deckplatte, die auf der Lade liegt; er müsste sonst sterben. Denn ich erscheine auf der Deckplatte in der Wolke. (a) 2Mo 25:22; 30:6; 40:34');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Nur unter der Bedingung darf Aaron in das Heiligtum hineingehen, dass er einen jungen Stier als Sündopfer und einen Widder als Brandopfer darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Er soll einen heiligen linnenen Leibrock anziehen und mit linnenen Beinkleidern seine Blösse bedecken, mit einem linnenen Gürtel soll er sich gürten und einen linnenen Kopfbund umbinden; es sind heilige Kleider; und er soll sie anziehen, nachdem er seinen Leib in Wasser gebadet hat. (a) 2Mo 28:39 42');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Dann nehme er von der Gemeinde der Israeliten zwei Ziegenböcke zum Sündopfer und einen Widder zum Brandopfer.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Hierauf soll Aaron den für ihn bestimmten Sündopferstier darbringen und so sich und seinem Hause Sühne schaffen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'die beiden Böcke aber soll er nehmen und sie vor den Herrn stellen, an den Eingang des heiligen Zeltes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Darnach soll Aaron über die beiden Böcke das Los werfen, ein Los für den Herrn und ein Los für Asasel. (1) ein böser Wüstengeist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Und Aaron soll den Bock, auf den das Los für den Herrn fällt, herzuführen und ihn als Sündopfer darbringen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'der Bock aber, auf den das Los für Asasel fällt, soll lebend vor den Herrn gestellt werden, damit man über ihm die Sühne vollziehe, um ihn dann zu Asasel in die Wüste zu treiben. (a) Jes 13:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Und Aaron soll den für ihn bestimmten Sündopferstier herzubringen und sich und seinem Hause Sühne schaffen, und er soll den für ihn bestimmten Sündopferstier schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Dann nehme er die Räucherpfanne voll glühender Kohlen von dem Altar, der vor dem Herrn steht, und beide Hände voll feinzerstossenes, wohlriechendes Räucherwerk und trage es hinein hinter den Vorhang;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'und er lege das Räucherwerk vor dem Herrn auf die Kohlen, damit die Wolke von dem Räucherwerk die Deckplatte, die über dem Gesetze liegt, verhülle und er nicht sterbe.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Hierauf hole er von dem Blute des Stiers und sprenge es mit dem Finger gegen die vordere Seite der Deckplatte, und vor die Deckplatte hin sprenge er mit dem Finger siebenmal von dem Blute.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Darnach soll er den Sündopferbock des Volkes schlachten und sein Blut hinter den Vorhang bringen, und mit dem Blute soll er ebenso verfahren wie mit dem Blute des Stiers: er soll es auf die Deckplatte und vor die Deckplatte hin sprengen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'So schaffe er Sühne für das Heiligtum wegen der Unreinheiten der Israeliten und wegen all der Übertretungen, mit denen sie sich versündigt haben, und dasselbe tue er für das heilige Zelt, das bei ihnen weilt inmitten ihrer Unreinheiten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Es darf aber kein Mensch im heiligen Zelte sein, wenn er hineingeht, um im Heiligtum die Sühne zu vollziehen, bis er wieder herauskommt. So soll er sich und seinem Hause und der ganzen Gemeinde Israels Sühne schaffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Und wenn er zum Altar herauskommt, der vor dem Herrn steht, so soll er auch für diesen die Sühne vollziehen: er nehme von dem Blute des Stiers und von dem Blute des Bocks und streiche es an die Hörner des Altars, ringsum,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'und siebenmal sprenge er mit dem Finger von dem Blute auf denselben; so soll er ihn von den Unreinheiten der Israeliten reinigen und weihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Wenn er so die Sühne für das Heiligtum, für das heilige Zelt und für den Altar vollendet hat, soll er den lebenden Bock herzubringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Dann soll Aaron beide Hände auf den Kopf des lebenden Bockes stützen und über ihm alle Verschuldungen und alle Übertretungen bekennen, mit denen die Israeliten sich versündigt haben, und soll sie dem Bock auf den Kopf legen und ihn durch einen bereitstehenden Mann in die Wüste treiben lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'So soll der Bock alle ihre Verschuldungen auf sich in eine Wildnis wegtragen; und er soll ihn in der Wüste loslassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Darnach soll Aaron in das heilige Zelt hineingehen und die linnenen Kleider ausziehen, die er anzog, als er in das Heiligtum hineinging, und soll sie dort niederlegen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'dann soll er seinen Leib an heiliger Stätte in Wasser baden und seine eignen Kleider anziehen, und wenn er herauskommt, soll er sein Brandopfer und das Brandopfer des Volkes darbringen und so sich und dem Volke Sühne schaffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Das Fett des Sündopfers soll er auf dem Altar verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Der Mann aber, der den Bock zu Asasel hinausgebracht hat, soll seine Kleider waschen und seinen Leib in Wasser baden; hernach darf er wieder ins Lager kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Sündopferstier jedoch und den Sündopferbock, deren Blut hineingebracht wurde, um damit im Heiligtum die Sühne zu vollziehen, soll man vor das Lager hinausschaffen und verbrennen, ihre Haut, ihr Fleisch und ihren Mist. (a) 3Mo 4:11 12; 6 30; Hes 43:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der, welcher sie verbrennt, soll seine Kleider waschen und seinen Leib in Wasser baden; hernach darf er wieder ins Lager kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Und folgendes soll euch als ewige Satzung gelten: Am zehnten Tage des siebenten Monats sollt ihr fasten und keinerlei Arbeit verrichten, weder der Einheimische noch der Fremde, der unter euch weilt. (a) 3Mo 23:27');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage schafft man euch Sühne, indem man euch reinigt; von allen euren Sünden sollt ihr rein werden vor dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein hoher Feiertag soll es für euch sein, und ihr sollt fasten; das ist ewiggültige Satzung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Die Sühne aber soll der Priester vollziehen, den man salben und dem man die Hand füllen wird, damit er an seines Vaters Statt Priesterdienst tue, und er soll die linnenen Kleider, die heiligen Kleider, anziehen. (1) vgl. Anm. zu 2Mo 28:41.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Der soll für das Heiligtum die Sühne vollziehen; auch für das heilige Zelt und für den Altar soll er die Sühne vollziehen, und ebenso für die Priester und das ganze Volk der Gemeinde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Das soll euch als ewige Ordnung gelten, für die Israeliten Sühne zu erwirken wegen all ihrer Sünden, einmal im Jahr. Und Aaron tat, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Rede mit Aaron und seinen Söhnen und allen Israeliten und sprich zu ihnen: Das ist\'s, was der Herr geboten hat:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ein jeder aus dem Hause Israel, der ein Rind oder ein Lamm oder eine Ziege im Lager schlachtet oder der ausserhalb des Lagers schlachtet,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'es aber nicht an den Eingang des heiligen Zeltes bringt, um es dem Herrn als Opfergabe darzubringen vor der Wohnung des Herrn, dem soll das als Blutschuld angerechnet werden: er hat Blut vergossen, und ein solcher Mensch soll aus seinem Volke ausgerottet werden -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'damit die Israeliten ihre Schlachtopfer, die sie auf freiem Felde zu opfern pflegen, herbringen; sie sollen sie für den Herrn an den Eingang des heiligen Zeltes zum Priester bringen und sie als Heilsopfer für den Herrn schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester soll das Blut auf den Altar des Herrn am Eingang des heiligen Zeltes sprengen und das Fett verbrennen zum lieblichen Geruch für den Herrn. (a) 3Mo 4:30 31');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Und sie sollen ihre Schlachtopfer nicht mehr den Feldteufeln darbringen, denen sie sich jetzt hingeben. Das soll ihnen als ewige Satzung gelten, von Geschlecht zu Geschlecht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und du sollst zu ihnen sagen: Ein jeder aus dem Hause Israel und von den Fremden, die unter ihnen wohnen, der ein Brandopfer oder Schlachtopfer darbringen will');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht an den Eingang des heiligen Zeltes bringt, um es dem Herrn zu opfern, der soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und wider einen jeden, der irgend Blut isst, sei er aus dem Hause Israel oder von den Fremden, die unter ihnen wohnen, wider einen solchen, der Blut isst, werde ich mein Angesicht wenden und ihn aus seinem Volk ausrotten. (a) 1Mo 9:4; 3Mo 7:27; 1Sa 14:33');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn die Seele des Fleisches ist im Blute, und ich habe es euch für den Altar gegeben, dass man euch damit Sühne erwirke; denn das Blut ist es, das durch die (in ihm wohnende) Seele Sühne erwirkt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum habe ich den Israeliten geboten: Niemand unter euch darf Blut essen; auch der Fremdling, der unter euch wohnt, darf kein Blut essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und ein jeder von den Israeliten und von den Fremden, die unter ihnen wohnen, der ein Stück Wild oder Geflügel erjagt, das man essen darf, der soll das Blut ausschütten und mit Erde bedecken;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'denn das Blut ist die Seele alles Fleisches. Darum habe ich den Israeliten geboten: Von keinem Fleisch dürft ihr das Blut essen; denn das Blut ist die Seele alles Fleisches. Ein jeder, der es isst, soll ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und ein jeder, der ein verendetes oder zerrissenes Tier isst, er sei Einheimischer oder Fremdling, der soll seine Kleider waschen und sich in Wasser baden, und er bleibt unrein bis zum Abend; dann ist er wieder rein. (a) 2Mo 22:31; 3Mo 7:24; 11:40');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wenn er aber (seine Kleider) nicht wäscht und seinen Leib nicht badet, so hat er seine Schuld zu tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Rede mit den Israeliten und sprich zu ihnen: Ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr sollt nicht tun, wie man im Lande Ägypten tut, wo ihr gewohnt habt, und sollt nicht tun, wie man im Lande Kanaan tut, in das ich euch führen will; ihr sollt nicht nach ihren Bräuchen wandeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Nach meinen Vorschriften sollt ihr tun und meine Satzungen sollt ihr halten, indem ihr darnach wandelt; ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Darum sollt ihr meine Satzungen und meine Vorschriften halten. Der Mensch, der darnach tut, wird durch sie leben; ich bin der Herr. (a) Hes 20:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Keiner von euch soll seinen nächsten Blutsverwandten nahen, um ehelichen Umgang zu pflegen; ich bin der Herr. (a) 3Mo 20:11-21; 5Mo 27:20-23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Mit Vater oder Mutter sollst du nicht ehelichen Umgang pflegen; es ist deine Mutter, du sollst nicht ehelichen Umgang mit ihr pflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du sollst mit dem Weibe deines Vaters nicht ehelichen Umgang pflegen; damit schändest du den Vater. (1) d.h. der Stiefmutter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du sollst mit deiner Schwester, die deines Vaters oder deiner Mutter Tochter ist, sei sie nun im Hause oder auswärts geboren, nicht ehelichen Umgang pflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Mit der Tochter deines Sohnes oder derjenigen deiner Tochter sollst du nicht ehelichen Umgang pflegen; damit schändest du dich selbst.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Mit der Tochter des Weibes deines Vaters, die deinem Vater geboren und somit deine Schwester ist, sollst du nicht ehelichen Umgang pflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Mit der Schwester deines Vaters sollst du nicht ehelichen Umgang pflegen; sie ist deines Vaters nächste Blutsverwandte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Mit der Schwester deiner Mutter sollst du nicht ehelichen Umgang pflegen; sie ist deiner Mutter nächste Blutsverwandte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du sollst die Ehe des Bruders deines Vaters nicht schänden, du sollst dich seinem Weibe nicht nahen; sie ist deine Tante.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Mit deiner Sohnsfrau sollst du nicht ehelichen Umgang pflegen; sie ist deines Sohnes Weib, du sollst nicht ehelichen Umgang mit ihr pflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Mit dem Weibe deines Bruders sollst du nicht ehelichen Umgang pflegen; damit schändest du deinen Bruder.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du sollst nicht mit einem Weibe und ihrer Tochter ehelichen Umgang pflegen; auch die Tochter ihres Sohnes oder ihrer Tochter sollst du nicht nehmen, um mit ihr ehelichen Umgang zu pflegen; sie sind ihre nächsten Blutsverwandten. Das wäre eine Schandtat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du sollst auch nicht ein Weib zu ihrer Schwester hinzu als Nebenfrau nehmen, um mit ihr ehelichen Umgang zu pflegen, während jene noch lebt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du sollst dich einem Weibe nicht nahen, um mit ihr ehelichen Umgang zu pflegen, wenn sie durch ihren Monatsfluss unrein ist.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Auch mit dem Weibe deines Nächsten sollst du nicht fleischlichen Umgang haben und dich so an ihr verunreinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du sollst nicht eines deiner Kinder hingeben, um es dem Moloch zu opfern, damit du nicht den Namen deines Gottes entweihest; ich bin der Herr. (a) 3Mo 20:2; 2Kön 17:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du sollst nicht bei einem Manne liegen, wie man bei einem Weibe liegt; das wäre ein Greuel.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du sollst nicht mit irgendeinem Tiere Umgang haben und dich so an ihm verunreinigen. Und kein Weib soll sich vor ein Tier hinstellen, um sich mit ihm zu begatten; das wäre eine Schändlichkeit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ihr sollt euch durch nichts dergleichen verunreinigen; denn durch alles das haben sich die Heiden verunreinigt, die ich vor euch vertreiben will.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Dadurch wurde das Land unrein, und ich suchte seine Schuld an ihm heim, sodass das Land seine Bewohner ausspie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'So haltet nun ihr meine Satzungen und Vorschriften und verübt keinen dieser Greuel, weder der Einheimische noch der Fremdling, der unter euch wohnt -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'denn alle diese Greuel haben die Leute dieses Landes verübt, die vor euch waren, und dadurch ist das Land unrein geworden -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'damit euch das Land nicht ausspeie, wenn ihr es verunreinigt, wie es die Heiden, die vor euch waren, ausgespieen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn alle, die irgendeinen dieser Greuel verüben, solche, die das tun, sollen aus ihren Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Darum befolgt meine Vorschriften, dass ihr nicht nach den schändlichen Bräuchen tut, die man vor euch geübt hat, und euch dadurch verunreinigt; ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede mit der ganzen Gemeinde der Israeliten und sprich zu ihnen: Ihr sollt heilig sein, denn ich bin heilig, der Herr, euer Gott. (a) 3Mo 11:44; 2Mo 22:31');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr sollt ein jeglicher seine Mutter und seinen Vater fürchten, und meine Ruhetage sollt ihr halten; ich bin der Herr, euer Gott. (a) 2Mo 20:8 12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht zu den Götzen wenden und sollt euch keine gegossenen Gottesbilder machen; ich bin der Herr, euer Gott. (a) 2Mo 20:4; 34:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr dem Herrn ein Heilsopfer schlachtet, sollt ihr es so opfern, dass es euch wohlgefällig macht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'An demselben Tage, an dem ihr es opfert, und am folgenden Tage soll es gegessen werden; was bis zum dritten Tage übrigbleibt, das soll verbrannt werden. (a) 3Mo 7:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Wird aber noch am dritten Tage davon gegessen, so gilt es als Greuel, es wird nicht wohlgefällig aufgenommen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'und wer davon isst, der lädt Schuld auf sich, weil er das dem Herrn Geheiligte entweiht, und seine Seele soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn ihr die Ernte eures Landes schneidet, sollst du dein Feld nicht vollständig bis in die Ecken abernten und nach deiner Ernte nicht Nachlese halten. (a) 3Mo 23:22; 5Mo 24:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Auch in deinem Weinberg sollst du nicht Nachlese halten, noch die abgefallenen Beeren deines Weinbergs auflesen: dem Armen und dem Fremdling sollst du sie lassen; ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen und nicht ableugnen und nicht einer den andern betrügen. (a) 2Mo 20:15 16; Eph 4:25; 1Th 4:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt bei meinem Namen nicht falsch schwören und so den Namen eures Gottes entweihen; ich bin der Herr. (a) 2Mo 20:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Nächsten nicht bedrücken noch berauben; der Lohn des Taglöhners soll nicht bei dir bleiben bis zum (andern) Morgen. (a) 5Mo 24:14 15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst einem Tauben nicht fluchen und einem Blinden nichts in den Weg legen, sondern du sollst deinen Gott fürchten; ich bin der Herr. (a) 5Mo 27:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt nicht unrecht handeln im Gerichte: du sollst die Person des Geringen nicht ansehen, aber auch den Vornehmen nicht begünstigen; gerecht sollst du deinen Nächsten richten. (a) 2Mo 23:3; 5Mo 1:17; 16:19');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst nicht als Verleumder unter deinen Volksgenossen umhergehen und sollst nicht wider das Leben deines Nächsten auftreten; ich bin der Herr. (a) 2Mo 23:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst deinen Bruder nicht hassen in deinem Herzen; zurechtweisen sollst du deinen Nächsten, dass du nicht seinethalben Sünde auf dich ladest. (a) 1Jo 3:15; Mt 18:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst dich nicht rächen, auch nicht deinen Volksgenossen etwas nachtragen, sondern du sollst deinen Nächsten lieben wie dich selbst; ich bin der Herr. (a) Mt 22:39');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollt ihr halten: du sollst nicht zweierlei Vieh sich begatten lassen und dein Feld nicht mit zweierlei Samen besäen, und es soll kein Kleid auf deinen Leib kommen, das aus zweierlei Fäden gewoben ist. (a) 5Mo 22:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wenn ein Mann mit einem Weibe Umgang hat, das als Sklavin einem andern zugehört, aber noch nicht losgekauft oder freigelassen ist, so soll es geahndet werden; doch sollen sie nicht getötet werden, denn sie war nicht freigelassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Er soll aber dem Herrn als Busse einen Widder zum Schuldopfer an den Eingang des heiligen Zeltes bringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'und der Priester soll ihm mit dem Schuldopferwidder vor dem Herrn Sühne erwirken wegen der Sünde, die er begangen hat; so wird ihm die Sünde vergeben, die er begangen hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Wenn ihr in das Land kommt und allerlei Bäume mit essbaren Früchten pflanzt, so sollt ihr ihre Vorhaut, das heisst ihre Früchte, stehen lassen; drei Jahre lang sollen sie euch als unbeschnitten gelten, man soll nicht davon essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahre aber sollen alle ihre Früchte unter Festjubel dem Herrn geweiht werden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'und erst im fünften Jahre dürft ihr ihre Früchte essen, damit sie euch ihren Ertrag auch fernerhin liefern; ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr dürft nichts samt dem Blute essen. Ihr sollt nicht Wahrsagerei noch Zeichendeuterei treiben. (a) 3Mo 17:13 14; 5Mo 18:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt den Rand eures Haupthaars nicht rundum abscheren, auch sollst du den Rand deines Bartes nicht stutzen. (a) 3Mo 21:5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ihr sollt euch am Leibe nicht Einschnitte machen um eines Toten willen, auch sollt ihr euch nicht Zeichen einritzen; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht entweihen, indem du sie zur Unzucht anhältst, damit nicht das Land voll Unzucht und voll Schandtat werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Ruhetage sollt ihr halten und euch vor meinem Heiligtum scheuen; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ihr sollt euch nicht an die Totengeister und an die Wahrsagegeister wenden, ihr sollt sie nicht befragen und euch so an ihnen verunreinigen; ich bin der Herr, euer Gott. (a) 3Mo 20:6; 5Mo 18:11; 1Sa 28:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem grauen Haupte sollst du aufstehen und das Alter ehren und sollst dich vor deinem Gott fürchten; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Wenn ein Fremdling bei dir wohnt in eurem Lande, so sollt ihr ihn nicht bedrücken. (a) 2Mo 22:21; 23:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Wie ein Einheimischer aus eurer eignen Mitte soll euch der Fremdling gelten, der bei euch wohnt, und du sollst ihn lieben wie dich selbst - seid ihr doch auch Fremdlinge gewesen im Lande Ägypten; ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt nicht unrecht handeln mit dem Längenmass, mit dem Gewicht oder mit dem Hohlmass. (a) 5Mo 25:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Richtige Waage, richtige Gewichtsteine, richtiges Epha und richtiges Hin sollt ihr brauchen; ich bin der Herr, euer Gott, der euch aus dem Lande Ägypten herausgeführt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'So haltet denn alle meine Satzungen und alle meine Vorschriften und tut darnach; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Zu den Israeliten sollst du sagen: Wer von den Israeliten oder von den Fremden, die in Israel wohnen, eines seiner Kinder dem Moloch hingibt, der soll getötet werden; das Volk des Landes soll ihn steinigen. (a) 3Mo 18:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und ich werde mein Angesicht wider einen solchen Menschen wenden und ihn aus seinem Volk ausrotten, weil er dem Moloch eines seiner Kinder hingegeben hat, mein Heiligtum zu verunreinigen und meinen heiligen Namen zu entweihen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wenn das Volk des Landes es einem solchen Menschen nachsieht, dass er eines seiner Kinder dem Moloch hingibt, indem es ihn nicht tötet,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so werde ich selbst mein Angesicht wider einen solchen Menschen und wider sein Geschlecht wenden und werde ihn und alle, die sich mit ihm dem Moloch hingeben, aus ihrem Volk ausrotten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Und wenn sich jemand an die Totengeister und Wahrsagegeister wendet und sich ihnen hingibt, so werde ich mein Angesicht wider einen solchen wenden und ihn aus seinem Volk ausrotten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Darum heiligt euch und seid heilig! Denn ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Und haltet meine Satzungen und tut darnach; ich bin der Herr, der euch heiligt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Denn ein jeder, der seinem Vater und seiner Mutter flucht, soll getötet werden. Seinem Vater und seiner Mutter hat er geflucht; sein Blut komme über ihn! (a) 2Mo 21:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Wenn einer mit dem Weibe seines Nächsten Ehebruch begeht, so sollen beide, der Ehebrecher und die Ehebrecherin, getötet werden. (a) 2Mo 20:14; 3Mo 18:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Wenn einer bei dem Weibe seines Vaters liegt und so seinen Vater schändet, so sollen beide getötet werden; ihr Blut komme über sie! (1) d.h. der Stiefmutter. (a) 3Mo 18:6-23');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Wenn einer bei seiner Sohnsfrau liegt, so sollen beide getötet werden. Sie haben eine Schändlichkeit begangen; ihr Blut komme über sie!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Wenn einer bei einem Manne liegt, wie man bei einem Weibe liegt, so haben beide einen Greuel verübt. Sie sollen getötet werden; ihr Blut komme über sie!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Wenn einer ein Weib ehelicht und ihre Mutter dazu, so ist das eine Schandtat; man soll ihn und die beiden Frauen verbrennen, damit keine Schandtat unter euch sei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Wenn einer mit einem Tiere Umgang hat, so soll er getötet werden, und auch das Tier sollt ihr umbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Wenn ein Weib sich irgendeinem Tiere naht, um sich mit ihm zu begatten, so sollst du das Weib und das Tier umbringen. Sie sollen getötet werden; ihr Blut komme über sie!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Wenn einer seine (Stief-)Schwester nimmt, die Tochter seines Vaters oder seiner Mutter, und sie miteinander ehelichen Umgang pflegen, so ist das eine Schandtat, und sie sollen vor den Augen ihrer Volksgenossen ausgerottet werden; er hat mit seiner Schwester Umgang gepflegt und lädt dadurch Schuld auf sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Wenn ein Mann bei einem Weibe liegt zur Zeit ihres Monatsflusses und mit ihr Umgang pflegt und so ihren Blutfluss aufdeckt und sie ihren Blutfluss entblösst, so sollen beide aus ihrem Volke ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Mit der Schwester deiner Mutter oder deines Vaters sollst du nicht ehelichen Umgang pflegen; denn ein solcher entblösst seine Blutsverwandte, und sie laden Schuld auf sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Wenn einer bei dem Weibe des Bruders seines Vaters liegt, so schändet er seinen Oheim; sie laden Sünde auf sich, kinderlos sollen sie sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Wenn einer das Weib seines Bruders nimmt, so ist das eine Schändlichkeit; er schändet damit seinen Bruder, sie sollen kinderlos bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'So haltet nun alle meine Satzungen und alle meine Vorschriften und tut darnach, dass euch das Land nicht ausspeie, in das ich euch bringen will, damit ihr darin wohnet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Und wandelt nicht in den Bräuchen der Heiden, die ich vor euch vertreiben will; denn das alles haben sie getan, und darum habe ich sie verabscheut.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Zu euch aber habe ich gesagt: Ihr sollt ihr Land zu eigen bekommen; ich selbst will es euch zu eigen geben, ein Land, das von Milch und Honig fliesst. Ich bin der Herr, euer Gott, der euch aus den Völkern ausgesondert hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So sollt ihr denn einen Unterschied machen zwischen den reinen und den unreinen Tieren und zwischen den unreinen und den reinen Vögeln, damit ihr euch nicht selbst zum Greuel machet durch die Tiere, die Vögel und all die Kriechtiere auf dem Erdboden, die ich ausgeschieden habe, damit sie euch als unrein gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Ihr sollt mir heilig sein, denn ich, der Herr, bin heilig, und ich habe euch aus den Völkern ausgesondert, dass ihr mein seiet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Wenn in einem Mann oder Weib ein Totengeist oder Wahrsagegeist ist, so sollen sie getötet werden. Man soll sie steinigen; ihr Blut komme über sie! (a) 2Mo 22:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'UND der Herr sprach zu Mose: Sage den Priestern, den Söhnen Aarons, und sprich zu ihnen: Ein Priester darf sich an keinem Toten unter seinen Volksgenossen verunreinigen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'ausser an seinen nächsten Blutsverwandten: an seiner Mutter, an seinem Vater, an seinem Sohn, an seiner Tochter, an seinem Bruder');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'und an seiner Schwester, die noch nicht verheiratet, sondern noch Jungfrau ist und ihm darum nahesteht; an dieser darf er sich verunreinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'An einer verheirateten (Schwester) darf er sich nicht verunreinigen, da er dadurch entweiht würde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen sich den Kopf nicht kahl scheren, noch den Rand des Bartes stutzen, noch sich am Leibe Einschnitte machen. (1) d.h. die Priester. (a) 3Mo 19:27 28');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein und den Namen ihres Gottes nicht entweihen; denn sie bringen die Feueropfer des Herrn, die Speise ihres Gottes, dar, darum sollen sie heilig sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Sie sollen sich keine Dirne zum Weibe nehmen, noch eine Geschwächte; auch eine, die von ihrem Mann verstossen ist, sollen sie nicht nehmen; denn er ist seinem Gott geweiht. (1) d.h. der Priester.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Darum sollst du ihn heilig halten; denn er bringt die Speise deines Gottes dar. Als heilig soll er dir gelten; denn ich bin heilig, der Herr, der euch heiligt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Und wenn sich die Tochter eines Priesters durch Unzucht entweiht, so entweiht sie ihren Vater; man soll sie verbrennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Der aber, welcher Hoherpriester ist unter seinen Brüdern, auf dessen Haupt das Salböl gegossen worden ist und dem man die Hand gefüllt hat, dass er die (heiligen) Kleider anziehe, der soll sein Haupthaar nicht frei flattern lassen und seine Kleider nicht zerreissen. (1) vgl. Anm. zu 2Mo 28:41.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Er darf nicht zu irgendeiner Leiche hineingehen; auch an seinem Vater und an seiner Mutter darf er sich nicht verunreinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Aus dem Heiligtum soll er nicht herauskommen, damit er das Heiligtum seines Gottes nicht entweihe; denn die Weihe des Salböls seines Gottes ist auf ihm. Ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Er soll eine Jungfrau zum Weibe nehmen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Eine Witwe oder Verstossene oder Geschwächte oder Dirne, eine solche darf er sich nicht nehmen, sondern eine Jungfrau aus seinen Stammesgenossen soll er sich zum Weibe nehmen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'damit er sein Geschlecht nicht entweihe unter seinen Stammesgenossen; denn ich bin der Herr, der ihn heiligt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede mit Aaron und sprich: Wenn je einmal künftig einer aus deinem Geschlecht ein Gebrechen hat, so darf er nicht herzutreten, um die Speise seines Gottes darzubringen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'denn keiner, der ein Gebrechen hat, darf herzutreten: kein Blinder oder Lahmer; keiner, der im Gesicht verstümmelt oder an dem ein Glied zu lang ist;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'keiner, der einen gebrochenen Fuss oder eine gebrochene Hand hat;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'kein Buckliger oder Schwindsüchtiger; keiner, der einen Fleck im Auge hat oder mit Krätze oder Flechten behaftet ist, und kein Entmannter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Aus dem Geschlechte Aarons, des Priesters, darf keiner, der ein Gebrechen hat, herzutreten, um die Feueropfer des Herrn darzubringen. Er hat ein Gebrechen, darum darf er nicht herzutreten, um die Speise seines Gottes darzubringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Doch darf er von der Speise seines Gottes essen, von dem Hochheiligen wie von dem Heiligen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Nur zum Vorhange darf er nicht hineingehen, noch an den Altar treten, weil er ein Gebrechen hat, damit er meine Heiligtümer nicht entweihe; denn ich bin der Herr, der sie heiligt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Mose redete solches zu Aaron und zu seinen Söhnen und zu allen Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Sage Aaron und seinen Söhnen, dass sie in betreff der heiligen Gaben, die mir die Israeliten weihen, Zurückhaltung üben, damit sie meinen heiligen Namen nicht entweihen; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sage zu ihnen: Wenn je inskünftig irgendeiner aus euren Nachkommen den heiligen Gaben, welche die Israeliten dem Herrn weihen, sich naht, während er unrein ist, so soll seine Seele ausgerottet werden, hinweg von meinem Angesicht; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ein jeder vom Geschlechte Aarons, der aussätzig ist oder einen Fluss hat, der soll von den heiligen Gaben nicht mitessen, bis er wieder rein ist. Und wer irgend jemanden berührt, der sich an einem Toten verunreinigt hat, oder wer einen Samenerguss hat');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'oder wer irgendein Kriechtier berührt, durch das er unrein wird, oder einen Menschen, durch den er unrein wird infolge irgendwelcher Unreinheit, die an ihm haftet -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'wer so etwas berührt, der ist unrein bis zum Abend und soll nicht von den heiligen Gaben essen, sondern er soll zuvor seinen Leib in Wasser baden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'und wenn die Sonne untergegangen ist, so ist er wieder rein; dann mag er von den heiligen Gaben essen, denn das ist seine Speise.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Von einem verendeten oder zerrissenen Tier soll er nicht essen, weil er sich dadurch verunreinigen würde; ich bin der Herr. (a) 2Mo 22:31; 3Mo 7:24; 11:40; 17:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Sie sollen meine Vorschriften befolgen, damit sie nicht wegen des Geweihten Sünde auf sich laden und seinethalben sterben müssen, weil sie es entweihen; ich bin der Herr, der sie heiligt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein Fremder darf Geweihtes essen; der Hausgenosse und der Tagelöhner eines Priesters dürfen nicht Geweihtes essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber ein Priester einen Sklaven um Geld kauft, so darf dieser davon essen; auch die in seinem Hause gebornen (Sklaven) dürfen mit von seiner Speise essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Wenn die Tochter eines Priesters das Weib eines Fremden wird, so darf sie nicht mehr von der Hebe der heiligen Gaben essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Wenn aber eine Priesterstochter Witwe oder (von ihrem Mann) verstossen wird, und sie hat keine Kinder und kehrt wieder in das Haus ihres Vaters zurück (und wohnt da) wie in ihrer Jugend, so darf sie von der Speise ihres Vaters essen; irgendein Fremder aber darf nicht davon essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Doch wenn jemand aus Versehen Geweihtes isst, so soll er den fünften Teil (des Wertes) dazutun und es dem Priester samt dem Geweihten geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Und sie sollen die heiligen Gaben der Israeliten, das was sie für den Herrn abheben, nicht entweihen, (1) d.h. die Priester.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'und sie sollen nicht Schuld und Strafe über sie bringen, indem sie ihre heiligen Gaben essen; denn ich bin der Herr, der sie heiligt. (1) d.h. die Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Rede mit Aaron und seinen Söhnen und allen Israeliten und sprich zu ihnen: Ein jeder vom Hause Israel und von den Fremden in Israel, der seine Opfergabe darbringt - seien es nun gelobte oder freiwillige Gaben, die sie dem Herrn als Brandopfer darbringen wollen -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, '(soll so opfern,) dass es euch wohlgefällig macht: ein fehlloses männliches Tier von den Rindern oder Lämmern oder Ziegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nichts, was einen Fehler hat, sollt ihr opfern; denn es würde euch nicht wohlgefällig aufgenommen. (a) 5Mo 15:21; Mal 1:8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn jemand dem Herrn ein Heilsopfer von Rindern oder Schafen darbringen will, sei es um ein besonderes Gelübde zu erfüllen oder als freiwillige Gabe, so ist es nur wohlgefällig, wenn es fehllos ist; es soll keinen Fehler haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ist es blind oder hat es ein gebrochenes Glied, ist es verstümmelt oder hat es eiternde Geschwüre oder die Krätze oder Flechten - dergleichen Tiere sollt ihr dem Herrn nicht darbringen und als Feueropfer auf den Altar des Herrn legen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ein Rind oder ein Schaf, das ein zu langes oder ein zu kurzes Glied hat, darfst du als freiwillige Gabe darbringen, aber als gelobtes Opfer würde es nicht wohlgefällig aufgenommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ihr sollt dem Herrn kein Tier darbringen, dem die Hoden zerquetscht oder zerschlagen oder ausgerissen oder abgeschnitten sind. Weder sollt ihr in eurem Lande Tiere so verstümmeln');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'noch solche von einem Fremden kaufen, um sie eurem Gott als Speise darzubringen; denn sie haben einen Schaden, es ist ein Fehler an ihnen, sie würden euch nicht wohlgefällig aufgenommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Wenn ein Rind oder ein Lamm oder ein Zicklein geboren wird, so soll es sieben Tage lang bei seiner Mutter bleiben; erst vom achten Tage an wird es wohlgefällig aufgenommen, wenn man es dem Herrn als Feueropfer darbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ihr sollt nicht ein Rind oder Schaf am selben Tag mit seinem Jungen schlachten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Und wenn ihr dem Herrn ein Dankopfer darbringen wollt, so opfert es so, dass es euch wohlgefällig macht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Es soll noch am selben Tage gegessen werden, ihr dürft nichts übriglassen bis zum Morgen; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'So haltet denn meine Gebote und tut darnach; ich bin der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und ihr sollt meinen heiligen Namen nicht entweihen, damit ich heilig gehalten werde unter den Israeliten; ich bin der Herr, der euch heiligt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der euch aus dem Lande Ägypten herausgeführt hat, um euer Gott zu sein, ich, der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Rede mit den Israeliten und sprich zu ihnen: Dies sind meine Festzeiten, die Festzeiten des Herrn, für die ihr heilige Festversammlungen ausrufen sollt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage lang darf Arbeit getan werden, aber der siebente Tag ist hoher Feiertag, eine heilige Festversammlung; da sollt ihr keinerlei Arbeit tun in allen euren Wohnsitzen, es ist ein Ruhetag für den Herrn. (a) 2Mo 20:8-10; 23:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind die Festzeiten des Herrn, die heiligen Festversammlungen, die ihr zu ihrer festgesetzten Zeit ausrufen sollt:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Am vierzehnten Tage des ersten Monats, um die Abendzeit, ist Passafeier für den Herrn. (a) 2Mo 12:18; 4Mo 28:16; 5Mo 16:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Und am fünfzehnten Tage desselben Monats ist das Fest der ungesäuerten Brote für den Herrn; da sollt ihr sieben Tage lang ungesäuerte Brote essen. (a) 2Mo 13:6 7; 23:15; 34:18');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage sollt ihr eine heilige Festversammlung halten; da dürft ihr keinerlei Werktagsarbeit tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Und ihr sollt dem Herrn während sieben Tagen je ein Feueropfer darbringen. Am siebenten Tage ist heilige Festversammlung; da dürft ihr keinerlei Werktagsarbeit tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch geben will, und ihr dort Ernte haltet, so sollt ihr die Erstlingsgarbe von eurer Ernte zum Priester bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Der soll die Garbe vor dem Herrn schwingen, damit sie euch wohlgefällig mache; am Tage nach dem Sabbat soll sie der Priester schwingen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Und ihr sollt an dem Tage, da ihr die Garbe schwingt, dem Herrn ein fehlloses, einjähriges Lamm als Brandopfer darbringen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'samt dem dazugehörigen Speisopfer; zwei zehntel (Epha) Semmelmehl, mit Öl eingerührt, als lieblich duftendes Feueropfer für den Herrn; dazu als Trankopfer ein viertel Hin Wein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Brot aber und geröstete oder zerriebene Körner sollt ihr nicht essen bis zu ebendiesem Tage, bis ihr eurem Gott die Opfergabe dargebracht habt. Das ist ewiggültige Satzung für euch von Geschlecht zu Geschlecht, in allen euren Wohnsitzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Darnach sollt ihr von dem Tage nach dem Sabbat an zählen, von dem Tage an, da ihr die Webegarbe darbringt; sieben volle Wochen sollen es sein. (a) 5Mo 16:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Bis zum Tage nach dem siebenten Sabbat sollt ihr zählen, fünfzig Tage; dann sollt ihr dem Herrn ein Speisopfer vom neuen Korn darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Wohnsitzen sollt ihr zwei Webebrote bringen; zwei zehntel (Epha) Semmelmehl sollen es sein, und mit Sauerteig sollen sie gebacken werden, als Erstlinge für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und ausser den Broten sollt ihr sieben fehllose, einjährige Lämmer, einen jungen Stier und zwei Widder darbringen; sie sollen ein Brandopfer für den Herrn sein, samt dem dazugehörigen Speisopfer und den dazugehörigen Trankopfern, ein lieblich duftendes Feueropfer für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ausserdem sollt ihr einen Ziegenbock als Sündopfer und zwei einjährige Lämmer als Heilsopfer darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Und der Priester soll sie samt den Erstlingsbroten als Webeopfer vor dem Herrn schwingen, zugleich mit den zwei Lämmern; sie sollen dem Herrn geweiht sein und dem Priester gehören.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und ihr sollt an diesem Tag (das Fest) ausrufen - eine heilige Festversammlung sollt ihr halten, keinerlei Werktagsarbeit dürft ihr tun. Das ist ewiggültige Satzung für euch von Geschlecht zu Geschlecht, in allen euren Wohnsitzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Und wenn ihr die Ernte eures Landes schneidet, sollst du dein Feld nicht vollständig bis in die Ecken abernten und nach deiner Ernte nicht Nachlese halten; dem Armen und dem Fremdling sollst du es lassen. Ich bin der Herr, euer Gott. (a) 3Mo 19:9');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede mit den Israeliten und sprich: Am ersten Tage des siebenten Monats sollt ihr einen Feiertag halten mit Mahnung durch Lärmblasen, eine heilige Festversammlung. (a) 4Mo 29:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Da dürft ihr keinerlei Werktagsarbeit tun und sollt dem Herrn ein Feueropfer darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und der Herr redete mit Mose und sprach: (a) 3Mo 16:29; 4Mo 29:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Am zehnten Tage jedoch im selben siebenten Monat ist der Versöhnungstag; da sollt ihr eine heilige Festversammlung halten und fasten und dem Herrn ein Feueropfer darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'An ebendiesem Tage dürft ihr keinerlei Arbeit tun; denn es ist der Versöhnungstag, bestimmt, euch Sühne zu erwirken vor dem Herrn, eurem Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn ein jeder, der an ebendiesem Tage nicht fastet, dessen Seele soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Und einen jeden, der an diesem Tage irgendwelche Arbeit tut, den werde ich aus seinem Volk vertilgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ihr sollt keinerlei Arbeit tun. Das ist ewiggültige Satzung für euch von Geschlecht zu Geschlecht, in allen euren Wohnsitzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Es ist ein hoher Feiertag für euch, und ihr sollt fasten. Am Abend des neunten Tages im Monat, vom Abend bis wieder zum Abend, sollt ihr euren Feiertag halten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und der Herr redete mit Mose und sprach: (a) 4Mo 29:12; 5Mo 16:13');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede mit den Israeliten und sprich: Am fünfzehnten Tage desselben siebenten Monats ist das Laubhüttenfest, sieben Tage lang, für den Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage findet eine heilige Festversammlung statt; da dürft ihr keinerlei Werktagsarbeit tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Während sieben Tagen sollt ihr dem Herrn je ein Feueropfer darbringen; am achten Tage aber sollt ihr wieder eine heilige Festversammlung halten und dem Herrn ein Feueropfer darbringen. Es ist Festversammlung; da dürft ihr keinerlei Werktagsarbeit tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Das sind die Festzeiten des Herrn, für die ihr heilige Festversammlungen ausrufen sollt, um dem Herrn Feueropfer darzubringen: Brandopfer, Speisopfer, Schlachtopfer und Trankopfer, jeden Tag, was vorgeschrieben ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'abgesehen von den Sabbaten des Herrn und abgesehen von euren Gaben und all euren gelobten und freiwilligen Opfern, die ihr dem Herrn geben wollt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Am fünfzehnten Tage jedoch des siebenten Monats, wenn ihr den Ertrag eures Landes einsammelt, sollt ihr das Fest des Herrn feiern, sieben Tage lang. Am ersten Tag ist Feiertag, und am achten Tag ist Feiertag.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Und ihr sollt euch am ersten Tage Früchte von schönen Bäumen, Palmzweige und Äste von dichtbelaubten Bäumen und von Bachweiden holen und sieben Tage lang fröhlich sein vor dem Herrn, eurem Gott;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'jedes Jahr sollt ihr es sieben Tage lang feiern als ein Fest des Herrn. Das ist ewiggültige Satzung für euch von Geschlecht zu Geschlecht: im siebenten Monat sollt ihr es feiern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sieben Tage lang sollt ihr in Laubhütten wohnen, jeder, der einheimisch ist in Israel, soll in Laubhütten wohnen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'damit eure Nachkommen erfahren, dass ich die Israeliten in Hütten habe wohnen lassen, als ich sie aus dem Lande Ägypten herausführte, ich, der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose teilte den Israeliten die Festzeiten des Herrn mit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Gebiete den Israeliten, dass sie dir reines Öl aus zerstossenen Oliven für den Leuchter bringen, damit man eine immerbrennende Lampe aufstecken kann. (a) 2Mo 27:20');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Ausserhalb des Vorhangs, der vor (der Lade mit) dem Gesetz hängt, im heiligen Zelte, soll Aaron ihn herrichten, (dass er) beständig, vom Abend bis zum Morgen, vor dem Herrn (brenne). Das ist eine ewige, für alle Geschlechter gültige Verpflichtung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem Leuchter von reinem Gold soll er die Lampen herrichten, (damit sie) beständig vor dem Herrn (brennen).');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Dann sollst du Semmelmehl nehmen und daraus zwölf Kuchen backen; jeder Kuchen soll zwei zehntel (Epha) enthalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Und du sollst sie in zwei Reihen, je sechs in einer Reihe, auf den Tisch aus reinem Gold vor den Herrn hinlegen. (a) 2Mo 25:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Jeder Reihe aber sollst du reinen Weihrauch beigeben, damit er als Duftteil von den Broten ein Feueropfer für den Herrn werde.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Immer am Sabbat soll er sie vor dem Herrn herrichten; es ist für die Israeliten ewiggültige Bundesverpflichtung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und sie sollen Aaron und seinen Söhnen zufallen, und diese sollen sie an heiliger Stätte essen; denn als Hochheiliges kommt es ihm zu von den Feueropfern des Herrn, als immerwährende Gebühr. (a) 1Sa 21:6');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'EINST ging der Sohn einer Israelitin, der einen Ägypter zum Vater hatte, mitten unter die Israeliten, und der Sohn der Israelitin und ein Israelite bekamen miteinander im Lager Streit.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Da lästerte der Sohn der Israelitin den Namen (des Herrn) und fluchte; darum brachten sie ihn zu Mose. Seine Mutter aber hiess Selomith, die Tochter Dibris aus dem Stamme Dan.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Und sie legten ihn in Gewahrsam, bis ihnen Bescheid würde durch den Mund des Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Lass den Flucher vor das Lager hinausführen, und alle, die es gehört haben, sollen die Hände auf sein Haupt stützen, und dann soll ihn die ganze Gemeinde steinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Zu den Israeliten aber sollst du sagen: Ein jeder, der seinem Gotte flucht, lädt Sünde auf sich,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'und wer den Namen des Herrn lästert, der soll getötet werden; die ganze Gemeinde soll ihn steinigen. Sei er ein Fremdling oder ein Einheimischer, wenn er den Namen (des Herrn) lästert, soll er getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Wenn jemand irgendeinen Menschen erschlägt, soll er getötet werden; (a) 2Mo 20:13; 21:12');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'wer aber ein Stück Vieh erschlägt, der soll es ersetzen, Leben um Leben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Und wer seinem Nächsten einen Schaden zufügt, dem soll man tun, wie er getan hat:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn; denselben Schaden, den er dem andern zugefügt hat, soll man ihm zufügen. (a) 2Mo 21:24 25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Wer ein Stück Vieh erschlägt, der soll es ersetzen; wer aber einen Menschen erschlägt, der soll getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Einerlei Recht soll unter euch gelten, für den Fremdling wie für den Einheimischen; ich bin der Herr, euer Gott. (a) 2Mo 12:49');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Und Mose redete mit den Israeliten; da führten sie den Flucher vor das Lager hinaus und steinigten ihn. So taten die Israeliten, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'UND der Herr redete mit Mose auf dem Berge Sinai und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ihr in das Land kommt, das ich euch geben werde, so soll das Land dem Herrn einen Sabbat feiern. (a) 2Mo 23:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre darfst du dein Feld besäen und sechs Jahre deine Reben beschneiden und den Ertrag des Landes einsammeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber im siebenten Jahr soll das Land hohe Feierzeit halten, einen Sabbat für den Herrn; da darfst du dein Feld nicht besäen und deine Reben nicht beschneiden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Was von der Ernte (des sechsten Jahres) her von selbst wächst, das sollst du nicht ernten, und die Trauben deines unbeschnittenen Weinstocks sollst du nicht schneiden; es soll hohe Feierzeit sein für das Land.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Und was das Land während der Ruhezeit hervorbringt, soll euch als Nahrung dienen, dir und deinem Sklaven und deiner Sklavin, sowie dem Tagelöhner und dem Beisassen, die bei dir weilen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'auch deinem Vieh und dem Wild in deinem Lande soll der gesamte Ertrag zur Nahrung dienen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Und du sollst dir sieben Sabbatjahre abzählen, siebenmal sieben Jahre, sodass die Zeit der sieben Sabbatjahre 49 Jahre ausmacht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Dann sollst du die Lärmposaune erschallen lassen, am zehnten Tage des siebenten Monats; am Versöhnungstage sollt ihr in eurem ganzen Lande die Posaune erschallen lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'So sollt ihr das fünfzigste Jahr weihen und Befreiung ausrufen im Lande für alle, die darin wohnen; als Halljahr soll es euch gelten. Da sollt ihr ein jeder wieder zu seinem Besitz und ein jeder wieder zu seinem Geschlecht kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Als Halljahr soll es, das fünfzigste Jahr, euch gelten; da sollt ihr nicht säen, und auch nicht ernten, was von selbst wächst, noch Trauben schneiden von den unbeschnittenen Reben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Denn es ist ein Halljahr; als heilig soll es euch gelten. Vom Felde weg sollt ihr essen, was es hervorbringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In diesem Halljahr sollt ihr ein jeder wieder zu seinem Besitz kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Wenn du deinem Nächsten etwas verkaufst oder ihm etwas abkaufst, so soll keiner seinen Bruder übervorteilen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'nach der Zahl der Jahre, die seit dem Halljahr vergangen sind, soll sich dein Kaufpreis richten, und nach der Zahl der Erntejahre soll er es dir verkaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Je mehr Jahre es noch sind (bis zum nächsten Halljahr), um so grösser soll der Kaufpreis sein, und je weniger Jahre, um so kleiner der Kaufpreis; denn er verkauft dir eine (bestimmte) Anzahl von Jahreserträgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'So übervorteile denn keiner seinen Nächsten, sondern fürchte dich vor deinem Gott; denn ich bin der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Darum tut nach meinen Satzungen, und meine Vorschriften sollt ihr halten und darnach tun; so werdet ihr sicher im Lande wohnen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'und das Land wird seine Früchte geben, dass ihr genug zu essen habt und sicher darin wohnt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und wenn ihr denkt: Was sollen wir im siebenten Jahre essen? wir dürfen ja nicht säen und unsern Ertrag nicht einsammeln -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'so will ich euch im sechsten Jahre meinen Segen zuwenden, dass es den Ertrag für drei Jahre liefern soll.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Ihr werdet im achten Jahre säen und dabei noch Altes von dem Ertrag (des sechsten Jahres) essen; bis ins neunte Jahr, bis der Ertrag desselben eingeheimst wird, werdet ihr Altes essen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Grund und Boden darf nicht für immer verkauft werden, denn das Land ist mein, und ihr seid Fremdlinge und Beisassen bei mir.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Im ganzen Land, das ihr besitzt, sollt ihr für Grund und Boden Rückkauf gestatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Wenn dein Volksgenosse verarmt und etwas von seinem Grundbesitz verkauft, so soll sein nächster Verwandter als Löser hingehen und zurückkaufen dürfen, was sein Bruder verkauft hat. (a) Ru 4:4; Jer 32:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Wenn aber jemand keinen Löser hat und dann selbst so viel aufbringen kann, als zum Rückkauf nötig ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soll er die Jahre seit dem Verkauf in Rechnung bringen und den Rest (der Kaufsumme) demjenigen zurückerstatten, an den er verkauft hat, damit er wieder zu seinem Besitz kommt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Kann er jedoch nicht so viel aufbringen, als zur Rückerstattung nötig ist, so soll das, was er verkauft hat, in der Hand des Käufers bleiben bis zum Halljahr; im Halljahr wird es frei, und er kommt wieder zu seinem Besitz.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Wenn jemand ein Wohnhaus in einer ummauerten Stadt verkauft, so darf er es bis zum Schluss des Jahres, in dem er verkauft hat, zurückkaufen; die Rückkaufsfrist dauert nur eine Zeitlang.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wenn es nicht zurückgekauft wird, ehe ein volles Jahr vergangen ist, so verbleibt das Haus in der ummauerten Stadt für immer dem Käufer als Eigentum, auch für seine Nachkommen; es wird im Halljahr nicht frei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Die Häuser auf den Dörfern jedoch, die nicht von einer Mauer umgeben sind, sollen zum Feld des Landes gerechnet werden; ein solches Haus darf (jederzeit) zurückgekauft werden, und im Halljahr wird es frei.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Was aber die Städte der Leviten betrifft - die Häuser in den Städten, die ihnen gehören -, so steht den Leviten jederzeit der Rückkauf zu. (a) 4Mo 35:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Wenn jedoch einer der Leviten den Rückkauf nicht vornimmt, so wird ein von ihm verkauftes Haus, falls es in einer zu ihrem Besitz gehörigen Stadt steht, im Halljahr frei; denn die Häuser in den Städten der Leviten sind ihr Besitztum unter den Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Auch das Weideland, das zu ihren Städten gehört, darf nicht verkauft werden; denn es ist ihr Besitztum für alle Zeiten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Wenn dein Volksgenosse neben dir verarmt und sich nicht mehr zu halten vermag, so sollst du ihn aufrechthalten, dass er wie ein Fremdling oder Beisasse neben dir leben kann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du sollst keinen Zins und keine Zulage von ihm nehmen, sondern du sollst dich vor deinem Gott fürchten, sodass dein Volksgenosse neben dir leben kann. (a) 2Mo 22:25; Spr 28:8; Hes 18:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du sollst ihm dein Geld nicht auf Zins geben, noch deine Speise mit der Verpflichtung zu einer Zulage (bei der Rückerstattung).');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Denn ich bin der Herr, euer Gott, der euch aus dem Lande Ägypten herausgeführt hat, um euch das Land Kanaan zu geben und euer Gott zu sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Wenn dein Volksgenosse neben dir verarmt und sich dir verkauft, so sollst du ihn nicht Sklavendienst tun lassen; (a) 2Mo 21:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'wie ein Tagelöhner, wie ein Beisasse soll er bei dir sein. Bis zum Halljahr soll er bei dir dienen;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'alsdann soll er mitsamt seinen Kindern frei von dir ausgehen und soll zu seinem Geschlecht zurückkehren und wieder zum Besitze seiner Väter kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn meine Knechte sind sie, die ich aus dem Lande Ägypten herausgeführt habe; sie sollen nicht als Sklaven verkauft werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst ihm kein harter Herr sein, sondern du sollst dich vor deinem Gott fürchten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Was aber die Sklaven und Sklavinnen betrifft, die du halten darfst, so mögt ihr welche bei den Heiden kaufen, die um euch her wohnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Auch aus den Kindern der Beisassen, die unter euch weilen, mögt ihr welche kaufen, überhaupt aus ihrem Geschlecht, das unter euch wohnt und das in eurem Lande geboren ist; solche können euer Eigentum werden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und ihr dürft sie als bleibendes Eigentum auf eure Nachkommen vererben, für alle Zeit dürft ihr sie als Sklaven halten. Unter euch Brüdern aber, den Israeliten, soll keiner dem andern ein harter Herr sein. (a) 1Kön 9:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Wenn ein Fremdling oder Beisasse bei dir wohlhabend wird, dein Volksgenosse aber neben ihm verarmt und sich einem Fremdling oder Beisassen bei dir oder einem Abkömmling aus dem Geschlecht eines Fremdlings verkauft,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soll er, nachdem er sich verkauft hat, losgekauft werden können; einer von seinen Brüdern mag ihn loskaufen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'oder sein Oheim oder Vetter mag ihn loskaufen, oder sonst ein naher Blutsverwandter aus seinem Geschlecht mag ihn loskaufen; oder wenn er die Mittel dazu aufbringt, mag er sich selber loskaufen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Er soll aber mit seinem Käufer rechnen von dem Jahr an, da er sich verkauft, bis zum Halljahr, und der Verkaufspreis richtet sich nach der Zahl der Jahre; die Zeit, die er bei ihm ist, wird wie die eines Tagelöhners in Rechnung gebracht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Fehlen (beim Loskauf) noch viele Jahre (bis zum Halljahr), so soll er, um sich loszukaufen, einen entsprechenden Teil des Kaufpreises zurückerstatten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Fehlen aber nur noch wenige Jahre bis zum Halljahr, so soll er ebenfalls nachrechnen; nach Massgabe seiner Dienstjahre hat er sein Lösegeld zu entrichten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Wie ein Tagelöhner, der jahraus, jahrein arbeitet, soll er bei ihm sein, und er soll ihn vor deinen Augen nicht als harter Herr behandeln.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Wird er aber nicht in dieser Weise losgekauft, so soll er im Halljahr mitsamt seinen Kindern frei ausgehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn mein sind die Israeliten als Knechte, meine Knechte sind sie, die ich aus dem Lande Ägypten herausgeführt habe, ich, der Herr, euer Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'IHR sollt euch keine Götzen machen, und Gottesbilder und Malsteine sollt ihr euch nicht aufrichten, auch keine Steine mit Bildern hinstellen in eurem Lande, um euch davor niederzuwerfen; denn ich bin der Herr, euer Gott. (a) 2Mo 20:4; 5Mo 16:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Meine Ruhetage sollt ihr halten und euch vor meinem Heiligtum scheuen; ich bin der Herr. (a) 3Mo 19:30');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Wenn ihr in meinen Satzungen wandelt und meine Gebote haltet und darnach tut,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so werde ich euch Regen geben zu seiner Zeit, dass das Land seinen Ertrag gibt und die Bäume auf dem Felde ihre Früchte tragen. (a) 5Mo 11:14');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Dann wird bei euch die Dreschzeit bis zur Weinlese und die Weinlese bis zur Saatzeit reichen, und ihr werdet euch an eurem Brot satt essen und sicher wohnen in eurem Lande.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Ich will Frieden schaffen im Lande, und ihr werdet ruhig schlafen, ohne dass euch jemand aufschreckt. Die wilden Tiere im Lande will ich ausrotten, und kein Schwert soll durch euer Land gehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Ihr werdet eure Feinde vor euch her treiben, und sie werden vor euch dem Schwerte verfallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Euer fünf werden hundert vor sich her treiben, und euer hundert werden zehntausend vor sich her treiben, und eure Feinde werden vor euch dem Schwerte verfallen. (a) Jos 23:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und ich werde mich euch zuwenden und euch fruchtbar machen und euch mehren und meinen Bund mit euch aufrechterhalten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Und ihr werdet vom alten, vorjährigen (Korn) zu essen haben und das vorjährige wegen der Menge des neuen hinausschaffen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ich werde meinen Wohnsitz unter euch nehmen und keinen Widerwillen gegen euch hegen. (a) 2Mo 29:45');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ich werde mitten unter euch wandeln und will euer Gott sein, und ihr sollt mein Volk sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich bin der Herr, euer Gott, der euch aus dem Lande Ägypten herausgeführt hat, damit ihr dort nicht Sklaven wäret. Und ich zerbrach die Hölzer eures Jochs und liess euch aufrecht einhergehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Wenn ihr mir aber nicht gehorcht und nicht diese Gebote alle haltet,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'wenn ihr meine Satzungen missachtet und gegen meine Vorschriften Widerwillen hegt, sodass ihr nicht meine Gebote alle haltet und dadurch den Bund mit mir brecht,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so werde auch ich an euch ebenso handeln. Ich werde Schreckliches über euch bringen: die Schwindsucht und das Fieber, dass euch die Augen erlöschen und das Leben hinschwindet. Vergeblich werdet ihr säen; eure Feinde werden die Saat verzehren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Und ich werde mein Angesicht wider euch kehren, dass ihr von euren Feinden geschlagen werdet. Die euch hassen, werden euch unterwerfen, und ohne dass euch jemand verfolgt, werdet ihr fliehen. (a) Spr 28:1');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Und wenn ihr mir auch dann noch nicht gehorcht, so werde ich euch noch weiter züchtigen, siebenmal, um eurer Sünden willen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Ich werde euren Wohlstand zerbrechen, auf den ihr stolz seid: den Himmel über euch will ich (hart) wie Eisen machen und eure Erde wie Erz. (a) 5Mo 11:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Eure Mühe und Arbeit soll umsonst sein: euer Land wird seinen Ertrag nicht geben, und die Bäume auf dem Felde werden keine Früchte tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und wenn ihr mir widerstrebt und mir nicht gehorchen wollt, so werde ich euch weiter schlagen, siebenmal, nach euren Sünden:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'ich werde die wilden Tiere wider euch loslassen; die sollen euch eurer Kinder berauben und euer Vieh vertilgen und eure Zahl vermindern, sodass eure Strassen öde werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Und wenn ihr euch meiner Züchtigung auch dann nicht unterwerft, sondern mir widerstrebt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so will auch ich euch widerstreben und euch schlagen, siebenmal, um eurer Sünden willen:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'ich werde ein Schwert über euch kommen lassen, das meinen Bund rächen soll. Und wenn ihr euch dann in eure Städte flüchtet, werde ich die Pest unter euch senden, und ihr sollt in Feindeshand gegeben werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Wenn ich euch die Stütze des Brotes zerbreche, so werden zehn Frauen euer Brot in einem einzigen Ofen backen und euch das Brot abgewogen zurückbringen, und ihr werdet euch nicht satt essen können. (a) Hos 4:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Und wenn ihr mir auch dann noch nicht gehorcht, sondern mir widerstrebt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so will auch ich im Grimm euch widerstreben und euch züchtigen, siebenmal, um eurer Sünden willen:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'ihr werdet das Fleisch eurer Söhne und Töchter verzehren; (a) 2Kön 6:28; Jer 19:9; Kla 4:10');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'und ich werde eure Opferhöhen verwüsten und eure Sonnensäulen ausrotten und eure Leichen auf die Leichen eurer Götzen werfen, und ich werde euch verabscheuen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Ich werde eure Städte zu Schutthaufen machen und eure Heiligtümer verwüsten, und den lieblichen Duft eurer Opfer will ich nicht mehr riechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ja, ich selbst werde das Land verwüsten, dass eure Feinde, die dort Wohnsitz nehmen, sich darob entsetzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber will ich unter die Heiden zerstreuen, und das Schwert will ich hinter euch zücken, und euer Land soll zur Wüste und eure Städte zu Schutthaufen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alsdann wird das Land die ihm gebührenden Sabbatjahre ersetzt bekommen, während der ganzen Zeit, da es wüste liegt und ihr im Lande eurer Feinde seid; alsdann wird das Land ruhen und seine Sabbatjahre nachholen. (a) 2Ch 36:21');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Während der ganzen Zeit, da es wüste liegt, wird es Ruhe haben, die Ruhe, die ihm versagt war in den Ruhezeiten, die ihr hättet halten sollen, als ihr darin wohntet.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Und denen, die von euch übrigbleiben, will ich das Herz verzagt machen in den Ländern ihrer Feinde, dass das Rascheln eines verwehten Blattes sie jagen wird, und sie werden fliehen, wie man vor dem Schwerte flieht, und hinfallen, obschon sie niemand verfolgt. (a) Jes 30:17');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Und sie werden übereinander stürzen, wie auf der Flucht vor dem Schwerte, wo doch niemand verfolgt. Ihr werdet euren Feinden nicht standhalten können,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'und ihr werdet unter den Heiden umkommen, und das Land eurer Feinde wird euch verzehren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Die aber von euch übrigbleiben, sollen um ihrer Schuld willen vermodern in den Ländern eurer Feinde; auch um der Schuld ihrer Väter willen, die sie zu tragen haben, sollen sie vermodern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Wenn sie dann ihre und ihrer Väter Schuld bekennen, den Treubruch, den sie an mir begangen haben, und auch dass sie mir widerstrebt haben - (a) 5Mo 4:30; 30:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'weshalb auch ich ihnen widerstrebt und sie ins Land ihrer Feinde gebracht habe -, wenn sich alsdann ihr unbeschnittenes Herz demütigt und sie alsdann ihre Schuld abtragen: (a) Jer 9:26');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'so will ich meines Bundes mit Jakob gedenken, und auch meines Bundes mit Isaak und meines Bundes mit Abraham will ich gedenken, und des Landes will ich gedenken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Aber das Land muss (vorher) von ihnen verlassen werden und muss die ihm gebührenden Sabbatjahre ersetzt bekommen, während es wüste liegt und sie nicht mehr darin wohnen, und sie selbst müssen ihre Schuld abtragen, weil sie meine Vorschriften verworfen und gegen meine Satzungen Widerwillen gehegt haben. (1) V. 34');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Doch auch dann, wenn sie im Lande ihrer Feinde sind, verwerfe und verabscheue ich sie nicht so, dass ich sie ganz vertilgte, indem ich meinen Bund mit ihnen bräche; denn ich bin der Herr, ihr Gott.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ich will zu ihrem Heil meines Bundes mit den Vorfahren gedenken, die ich vor den Augen der Heiden aus dem Lande Ägypten herausgeführt habe, um ihr Gott zu sein, ich, der Herr.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Das sind die Satzungen und Vorschriften und Gesetze, die der Herr auf dem Berge Sinai durch Mose zwischen sich und den Israeliten aufgestellt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn jemand dem Herrn durch besonderes Gelübde Menschen weiht auf Grund deiner Schätzung,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'so sollst du den Mann zwischen dem zwanzigsten und sechzigsten Jahre auf fünfzig Lot Silber schätzen nach heiligem Gewicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ist es aber ein Weib, so soll deine Schätzung dreissig Lot Silber betragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Ist es eine Person zwischen dem fünften und dem zwanzigsten Jahre, so sollst du sie auf zwanzig Lot Silber schätzen, wenn sie männlich ist; wenn weiblich, auf zehn Lot Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ist es ein Kind zwischen einem Monat und fünf Jahren, so sollst du es auf fünf Lot Silber schätzen, wenn es ein Knabe ist; wenn ein Mädchen, auf drei Lot Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ist es ein Mann von sechzig Jahren oder darüber, so sollst du ihn auf fünfzehn Lot Silber schätzen; ist es ein Weib, auf zehn Lot Silber.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ist aber einer zu arm, um nach deiner Schätzung zu bezahlen, so stelle er ihn vor den Priester, und der Priester soll ihn schätzen; entsprechend dem, was der Gelobende vermag, soll ihn der Priester schätzen. (1) d.h. den geweihten Menschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Handelt es sich um Vieh, von dem man dem Herrn opfern darf, so soll jedes Stück, das einer dem Herrn gibt, dem Heiligtum verfallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Er soll es nicht auswechseln noch vertauschen, ein gutes für ein schlechtes, oder ein schlechtes für ein gutes. Sollte aber jemand doch ein Stück Vieh mit einem andern vertauschen, so sollen beide Tiere dem Heiligtum verfallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Handelt es sich dagegen um irgendein unreines Tier, das man dem Herrn nicht opfern darf, so stelle er es vor den Priester,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'und der Priester soll es schätzen, je nach seinen Vorzügen und Mängeln; und bei der Schätzung des Priesters soll es bleiben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will er es aber lösen, so soll er noch den fünften Teil des Schätzungswertes drauflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Wenn jemand sein Haus dem Herrn als heilige Gabe weiht, so soll der Priester es schätzen, je nach seinen Vorzügen und Mängeln; wie es der Priester schätzt, so hoch soll es zu stehen kommen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Wenn aber derjenige, der sein Haus geweiht hat, es lösen will, so soll er den fünften Teil des geschätzten Preises drauflegen; dann wird es wieder sein Eigentum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Wenn jemand dem Herrn ein Grundstück von seinem Erbgut weiht, so soll es von dir nach dem Mass der Aussaat geschätzt werden: wird ein Homer Gerste angesät, so soll es fünfzig Lot Silber gelten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Weiht er seinen Acker vom Halljahr an, so soll es bei deiner Schätzung bleiben. (a) 3Mo 25:8-16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Weiht er seinen Acker aber nach dem Halljahr, so berechne ihm der Priester den Preis nach den Jahren, die noch bleiben bis zum (nächsten) Halljahr, und es soll (ein entsprechender Betrag) an der Schätzung abgezogen werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will aber derjenige, der den Acker geweiht hat, diesen lösen, so soll er den fünften Teil des geschätzten Preises drauflegen; dann wird er wieder sein Eigentum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Löst er den Acker aber nicht und verkauft ihn dennoch einem andern, so kann er nicht mehr gelöst werden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'sondern der Acker verfällt, wenn er im Halljahr frei wird, als geweihtes Gut dem Herrn, wie ein dem Bann verfallenes Feld; er wird Eigentum des Priesters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Wenn jemand dem Herrn einen Acker weiht, den er gekauft hat, der also nicht zu seinem Erbgut gehört,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so soll ihm der Priester den Betrag der Schätzung bis zum Halljahr berechnen, und er soll am selben Tage diesen Betrag als dem Herrn geweihte Gabe bezahlen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Halljahr fällt der Acker an denjenigen zurück, von dem er ihn gekauft hat, dem also das Eigentumsrecht an dem Lande zusteht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Alle Schätzungen aber sollen nach heiligem Gewicht geschehen, das Lot Silber zu zwanzig Gera.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Doch darf niemand Erstlinge vom Vieh, die als Erstgeburt dem Herrn gehören, weihen; ob Rind, ob Schaf, es gehört dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Handelt es sich aber um ein unreines Haustier, so soll man es nach der Schätzung lösen und noch den fünften Teil drauflegen. Will man es nicht lösen, so verkaufe man es um den Schätzungspreis.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Gebanntes jedoch, das jemand dem Herrn durch einen Bannfluch weiht von allem, was ihm gehört, es seien Menschen, Haustiere oder Äcker seines Erbgutes, darf unter keinen Umständen verkauft oder gelöst werden; alles Gebannte ist hochheilig und gehört dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Wenn irgendein Mensch durch den Bannfluch geweiht wird, so darf man ihn nicht lösen, sondern er muss getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Alle Zehnten des Landes, sowohl vom Ertrag des Bodens als von den Früchten der Bäume, gehören dem Herrn, sind dem Herrn geweiht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Will aber jemand seinen Zehnten lösen, so soll er den fünften Teil des Wertes drauflegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Und der ganze Zehnte von Rindern und Schafen, je das zehnte Stück von allem, was unter dem Hirtenstabe hindurchgeht, soll dem Herrn geweiht sein.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soll nicht untersuchen, ob es gut oder schlecht sei, man soll es auch nicht vertauschen. Wenn es aber jemand doch vertauscht, so sollen beide Tiere dem Heiligtum verfallen und dürfen nicht gelöst werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Das sind die Gebote, die der Herr dem Mose auf dem Berge Sinai für die Israeliten gab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'UND der Herr redete mit Mose in der Wüste am Sinai im heiligen Zelte, am ersten Tage des zweiten Monats im zweiten Jahr nach ihrem Auszug aus dem Lande Ägypten, und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Stellt die Gesamtzahl der Gemeinde Israels fest, Geschlecht für Geschlecht, Familie für Familie, nach der Zahl der Namen alles, was männlich ist, Kopf für Kopf. (a) 4Mo 26:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Alle wehrfähigen Leute in Israel, von zwanzig Jahren an und darüber, sollt ihr mustern, Heerschar um Heerschar, du und Aaron.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und von jedem Stamm soll euch ein Mann dabei behilflich sein, der Obmann über die Familien des Stammes.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Dies sind die Namen der Männer, die euch zur Seite stehen sollen: von Ruben: Elizur, der Sohn Sedeurs,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'von Simeon: Selumiel, der Sohn Zurisaddais;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'von Juda: Nahason, der Sohn Amminadabs;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'von Issaschar: Nethaneel, der Sohn Zuars;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'von Sebulon: Eliab, der Sohn Helons;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'von den Söhnen Josephs, von Ephraim: Elisama, der Sohn Ammihuds, von Manasse: Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'von Benjamin: Abidan, der Sohn Gideonis;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'von Dan: Ahieser, der Sohn Ammisaddais;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'von Asser: Pagiel, der Sohn Ochrans;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'von Gad: Eljasaph, der Sohn Reguels;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'von Naphthali: Ahira, der Sohn Enans.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das sind die aus der Gemeinde Berufenen, die Fürsten der Stämme ihrer Väter, die Häupter der Tausende Israels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Und Mose und Aaron, zusammen mit diesen Männern, die mit Namen ausdrücklich bezeichnet worden waren,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'versammelten die ganze Gemeinde am ersten Tage des zweiten Monats, und die Leute liessen sich in die Verzeichnisse eintragen nach ihren Geschlechtern, Familie für Familie, nach der Zahl der Namen, von zwanzig Jahren an und darüber, Kopf für Kopf,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'wie der Herr dem Mose geboten hatte. So musterte er sie in der Wüste am Sinai.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Und die Söhne Rubens, des Erstgebornen Israels, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, Kopf für Kopf, alles, was männlich war, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'die Gemusterten vom Stamme Ruben zählten 46 500 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Die Söhne Simeons, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, Kopf für Kopf, alles, was männlich war, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'die Gemusterten vom Stamme Simeon zählten 59 300 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Die Söhne Gads, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'die Gemusterten vom Stamme Gad zählten 45 650 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Die Söhne Judas, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'die Gemusterten vom Stamme Juda zählten 74 600 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Die Söhne Issaschars, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'die Gemusterten vom Stamme Issaschar zählten 54 400 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Die Söhne Sebulons, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'die Gemusterten vom Stamme Sebulon zählten 57 400 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Die Söhne Josephs: die Söhne Ephraims, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'die Gemusterten vom Stamme Ephraim zählten 40 500 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Die Söhne Manasses, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'die Gemusterten vom Stamme Manasse zählten 32 200 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Die Söhne Benjamins, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'die Gemusterten vom Stamme Benjamin zählten 35 400 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Die Söhne Dans, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'die Gemusterten vom Stamme Dan zählten 62 700 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Die Söhne Assers, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'die Gemusterten vom Stamme Asser zählten 41 500 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Die Söhne Naphthalis, ihre Nachkommen nach ihren Geschlechtern und Familien, nach der Zahl der Namen, von zwanzig Jahren an und darüber, alle wehrfähigen Leute -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'die Gemusterten vom Stamme Naphthali zählten 53 400 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Das sind die Gemusterten, die von Mose und Aaron und den Fürsten Israels gemustert wurden - solcher Fürsten waren zwölf, je einer für jeden Stamm mit seinen Familien -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'alle, die unter den Israeliten nach ihren Familien gemustert wurden, von zwanzig Jahren an und darüber, alle wehrfähigen Leute in Israel -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'alle Gemusterten zählten 603 550 Mann. (a) 4Mo 2:32; 2Mo 38:26');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Die aber nach dem Stamm ihrer Väter Leviten waren, die wurden nicht mit den übrigen gemustert.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Nur die vom Stamme Levi sollst du nicht mustern und ihre Zahl nicht zu den (andern) Israeliten hinzurechnen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sondern du sollst die Leviten bestellen zum Dienst an der Wohnung des Gesetzes und an allen ihren Geräten und an allem, was zu ihr gehört. Ihnen kommt es zu, die Wohnung und alle ihre Geräte zu tragen, ihnen auch, derselben zu pflegen und sich rings um die Wohnung her zu lagern. (a) 4 Mo 3:6-8');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn die Wohnung weiterzieht, sollen die Leviten sie abbrechen, und wenn die Wohnung sich niederlässt, sollen die Leviten sie aufschlagen; wenn ein Unberufener sich daran macht, soll er getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Die (andern) Israeliten sollen sich nach ihren Heerscharen lagern, ein jeder in seinem Lager und bei seinem Panier,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'die Leviten aber sollen sich um die Wohnung des Gesetzes her lagern, damit nicht ein (Gottes-)Zorn über die Gemeinde Israels komme; so sollen die Leviten den Dienst an der Wohnung des Gesetzes versehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und die Israeliten taten genau, wie der Herr dem Mose geboten hatte; so taten sie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'UND der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Die Israeliten sollen sich so lagern, dass ein jeder unter seinem Panier bei den Feldzeichen der einzelnen Familien ist; rings um das heilige Zelt her, angesichts desselben, sollen sie sich lagern:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Vorn, gegen Osten, lagert sich Juda mit seinem Panier, Heerschar an Heerschar; der Fürst der Söhne Judas ist Nahason, der Sohn Amminadabs,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'und sein Heer zählt 74 600 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Neben ihm lagert sich der Stamm Issaschar; der Fürst der Söhne Issaschars ist Nethaneel, der Sohn Zuars,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'und sein Heer zählt 54 400 Gemusterte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'ferner der Stamm Sebulon; der Fürst der Söhne Sebulons ist Eliab, der Sohn Helons,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'und sein Heer zählt 57 400 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle Gemusterten im Heerlager Judas zählen 186 400 Mann, Heerschar an Heerschar; sie sollen zuerst aufbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Gegen Süden lagert sich Ruben mit seinem Panier, Heerschar an Heerschar; der Fürst der Söhne Rubens ist Elizur, der Sohn Sedeurs,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'und sein Heer zählt 46 500 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Neben ihm lagert sich der Stamm Simeon; der Fürst der Söhne Simeons ist Selumiel, der Sohn Zurisaddais,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'und sein Heer zählt 59 300 Gemusterte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'ferner der Stamm Gad; der Fürst der Söhne Gads ist Eljasaph, der Sohn Reguels,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'und sein Heer zählt 45 650 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle Gemusterten im Heerlager Rubens zählen 151 450 Mann, Heerschar an Heerschar; sie sollen an zweiter Stelle aufbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Dann soll das heilige Zelt aufbrechen, das Heerlager der Leviten, mitten zwischen den (andern) Lagern; wie sie lagern, so sollen sie auch aufbrechen, ein jeder an seinem Orte, Panier um Panier.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Gegen Westen lagert sich Ephraim mit seinem Panier, Heerschar an Heerschar; der Fürst der Söhne Ephraims ist Elisama, der Sohn Ammihuds,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'und sein Heer zählt 40 500 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Neben ihm lagert sich der Stamm Manasse; der Fürst der Söhne Manasses ist Gamliel, der Sohn Pedazurs,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'und sein Heer zählt 32 200 Gemusterte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'ferner der Stamm Benjamin; der Fürst der Söhne Benjamins ist Abidan, der Sohn Gideonis,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'und sein Heer zählt 35 400 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle Gemusterten im Heerlager Ephraims zählen 108 100 Mann, Heerschar an Heerschar; sie sollen an dritter Stelle aufbrechen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Gegen Norden lagert sich Dan mit seinem Panier, Heerschar an Heerschar; der Fürst der Söhne Dans ist Ahieser, der Sohn Ammisaddais,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'und sein Heer zählt 62 700 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Neben ihm lagert sich der Stamm Asser; der Fürst der Söhne Assers ist Pagiel, der Sohn Ochrans,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'und sein Heer zählt 41 500 Gemusterte;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'ferner der Stamm Naphthali; der Fürst der Söhne Naphthalis ist Ahira, der Sohn Enans,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'und sein Heer zählt 53 400 Gemusterte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle Gemusterten im Heerlager Dans zählen 157 600 Mann; sie sollen zuletzt aufbrechen von den (vier) Panieren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das sind die Gemusterten der Israeliten nach ihren Familien, alle Gemusterten der Heerlager nach ihren Heerscharen: 603 550 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Die Leviten aber wurden, wie es der Herr dem Mose geboten hatte, nicht mit den andern Israeliten gemustert. (a) 4Mo 1:49');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Israeliten taten genau, wie der Herr dem Mose geboten hatte: sie lagerten sich so nach ihren Panieren und brachen auch so auf, ein jeder nach seinem Geschlecht, bei seiner Familie.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'DIES sind die Nachkommen Aarons und Moses zu der Zeit, da der Herr mit Mose redete auf dem Berge Sinai,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'und dies sind die Namen der Söhne Aarons: Nadab, der Erstgeborne, und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Das sind die Namen der Söhne Aarons, der gesalbten Priester, denen man die Hand gefüllt hatte für den priesterlichen Dienst. (1) vgl. Anm. zu 2Mo 28:41.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab und Abihu aber starben vor dem Herrn, als sie in der Wüste am Sinai ein ungehöriges Feueropfer vor dem Herrn darbrachten, und sie hatten keine Söhne. So warteten denn Eleasar und Ithamar des Priesteramtes unter der Aufsicht ihres Vaters Aaron. (a) 3Mo 10:1 2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Lass den Stamm Levi herkommen und vor Aaron, den Priester, treten, damit sie ihn bedienen');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'und alles besorgen, was ihm und der ganzen Gemeinde vor dem heiligen Zelte zu besorgen obliegt, indem sie so des Dienstes an der Wohnung warten; (a) 4Mo 16:9; 18:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'und sie sollen alle Geräte des heiligen Zeltes besorgen nebst allem, was den Israeliten zu besorgen obliegt, indem sie so des Dienstes an der Wohnung warten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und du sollst die Leviten Aaron und seinen Söhnen übergeben; geschenkt sind sie ihm von seiten der Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron aber und seine Söhne sollst du dazu bestellen, ihres Priesteramtes zu warten. Wenn ein Unberufener sich daran macht, soll er getötet werden. (a) 4Mo 1:51; 16:40');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und der Herr redete mit Mose und sprach: (a) 4Mo 8:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Siehe, ich selbst habe die Leviten aus den Israeliten ausgesondert zum Ersatz für alle Erstgebornen unter den Israeliten, für das, was zuerst den Mutterschoss durchbrochen hat; mir sollen die Leviten gehören.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn mein ist alle Erstgeburt; an dem Tage, da ich alle Erstgeburten im Lande Ägypten schlug, habe ich mir alle Erstgeburten in Israel geweiht, von den Menschen sowohl als vom Vieh; mir sollen sie gehören, mir, dem Herrn. (a) 2Mo 13:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und der Herr redete mit Mose in der Wüste am Sinai und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Mustere die Söhne Levis nach ihren Familien und Geschlechtern; alles, was männlich ist, von einem Monat an und darüber, sollst du mustern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Da musterte sie Mose nach dem Gebot des Herrn, wie ihm befohlen war.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und dies waren die Söhne Levis mit ihren Namen: Gerson, Kahath und Merari. (a) 2Mo 6:16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Und dies sind die Namen der Söhne Gersons nach ihren Geschlechtern: Libni und Simei;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'und die Söhne Kahaths nach ihren Geschlechtern: Amram und Jizhar, Hebron und Ussiel;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'und die Söhne Meraris nach ihren Geschlechtern: Mahli und Musi. Das sind die Geschlechter Levis nach ihren Familien.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson stammt das Geschlecht der Libniter und das Geschlecht der Simeiter. Das sind die Geschlechter der Gersoniter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Bei ihrer Musterung belief sich die Zahl alles dessen, was männlich war, von einem Monat an und darüber, auf 7 500 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Geschlechter der Gersoniter lagerten jeweilen hinter der Wohnung, gegen Westen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'und das Familienhaupt der Gersoniter war Eljasaph, der Sohn Laels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Und die Gersoniter hatten am heiligen Zelte zu besorgen: die Wohnung und das Zelt(-Dach), seine Decke und den Vorhang am Eingang des heiligen Zeltes,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'ferner die Umhänge des Vorhofs und den Vorhang am Tor des Vorhofs, der die Wohnung und den Altar rings umschliesst, sowie die zugehörigen Stricke, nebst allem, was es damit zu tun gab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Von Kahath stammen die Geschlechter der Amramiter, der Jizhariter, der Hebroniter und der Ussieliter. Das sind die Geschlechter der Kahathiter.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Bei ihrer Musterung belief sich die Zahl alles dessen, was männlich war, von einem Monat an und darüber, auf 8 600 Mann; die versahen den Dienst am Heiligtum.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Geschlechter der Kahathiter lagerten jeweilen an der Längsseite der Wohnung gegen Süden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'und das Familienhaupt der Geschlechter der Kahathiter war Elizaphan, der Sohn Ussiels.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ihr Amt war die Besorgung der Lade, des Tisches, des Leuchters, der Altäre, der Geräte des Heiligtums, mit denen sie den Dienst versahen, und des Vorhangs (vor dem Allerheiligsten), nebst allem, was es damit zu tun gab.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Das oberste Haupt der Leviten aber war Eleasar, der Sohn Aarons, des Priesters; (er hatte) die Oberaufsicht über die, welche den Dienst am Heiligtum versahen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari stammt das Geschlecht der Mahliter und das Geschlecht der Musiter. Das sind die Geschlechter Meraris.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Bei ihrer Musterung belief sich die Zahl alles dessen, was männlich war, von einem Monat an und darüber, auf 6 200 Mann,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'und das Familienhaupt der Geschlechter Meraris war Zuriel, der Sohn Abihails. Sie lagerten jeweilen an der Längsseite der Wohnung gegen Norden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Die Merariter aber waren bestellt zur Besorgung der Bretter und Riegel, der Säulen und Füsse der Wohnung, sowie aller ihrer Geräte nebst allem, was es damit zu tun gab,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'ferner zur Besorgung der Säulen rings um den Vorhof mit ihren Füssen, Pflöcken und Stricken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Vor der Wohnung aber, gegen Osten, vor dem heiligen Zelte gegen Sonnenaufgang, lagerten Mose und Aaron mit seinen Söhnen, die den Dienst am Heiligtum versahen, alles, was den Israeliten oblag. Wenn ein Unberufener sich daran macht, soll er getötet werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle Gemusterten unter den Leviten, die Mose nach dem Gebot des Herrn Geschlecht für Geschlecht musterte - alles, was männlich war, von einem Monat an und darüber, zählte 22 000 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und der Herr sprach zu Mose: Mustere alle männlichen Erstgebornen unter den Israeliten, von einem Monat an und darüber, und stelle die Zahl ihrer Namen fest.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Und du sollst die Leviten für mich, den Herrn, bestimmen zum Ersatz für alle Erstgebornen unter den Israeliten, und das Vieh der Leviten zum Ersatz für alle Erstgeburten unter dem Vieh der Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose musterte, wie ihm der Herr geboten hatte, alle Erstgebornen unter den Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Und bei ihrer Musterung belief sich die Zahl der Namen aller männlichen Erstgebornen, von einem Monat an und darüber, auf 22 273.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten zum Ersatz für alle Erstgebornen unter den Israeliten, und das Vieh der Leviten zum Ersatz für ihr Vieh; die Leviten sollen mir gehören, mir, dem Herrn.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Und zur Lösung der 273 Erstgebornen unter den Israeliten, welche die (Zahl der) Leviten übersteigen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'sollst du auf jeden Kopf fünf Lot Silber erheben; nach heiligem Gewicht sollst du sie erheben, das Lot Silber zu zwanzig Gera.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Und du sollst das Geld für die Lösung der Überzähligen Aaron und seinen Söhnen geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Da erhob Mose das Lösegeld von denen, die in den durch die Leviten Gelösten nicht inbegriffen waren;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'von den Erstgebornen der Israeliten erhob Mose das Geld, 1 365 Lot Silber nach heiligem Gewicht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Mose gab das Lösegeld Aaron und seinen Söhnen nach dem Befehl des Herrn, wie der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'UND der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Stelle die Gesamtzahl der Kahathiter unter den Leviten fest, Geschlecht für Geschlecht, Familie für Familie,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre, aller, die dienstpflichtig sind -, damit sie Dienst tun am heiligen Zelte. (a) 4Mo 8:24 25');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies aber ist die Aufgabe der Kahathiter im heiligen Zelte: die Besorgung des Hochheiligen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Wenn das Lager aufbricht, sollen Aaron und seine Söhne hineingehen und den verhüllenden Vorhang herunternehmen und die Lade des Gesetzes damit bedecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Dann sollen sie eine Decke von Seehundsfell darauf legen und oben darüber ein Tuch breiten, ganz von blauem Purpur, und dann die Stangen durchstecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Auch über den Schaubrottisch sollen sie ein Tuch von blauem Purpur breiten und die Schüsseln, Schalen und Becher, sowie die Kannen für das Trankopfer darauf stellen; auch die Schaubrote sollen darauf liegen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Über all das sollen sie ein Tuch von Karmesin breiten und dieses mit einer Decke von Seehundsfell bedecken und dann die Stangen durchstecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Hierauf sollen sie ein Tuch von blauem Purpur nehmen und damit den Leuchter samt seinen Lampen, Lichtscheren und Pfannen bedecken, auch alle Ölgefässe, mit denen man ihn bedient.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Und sie sollen ihn samt allen seinen Geräten in eine Decke von Seehundsfell tun und so auf die Tragbahre legen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Auch über den goldenen Altar sollen sie ein Tuch von blauem Purpur breiten und ihn mit einer Decke von Seehundsfell bedecken und dann die Stangen durchstecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Hierauf sollen sie alle Dienstgeräte nehmen, mit denen man den Dienst im Heiligtum versieht, sie in ein Tuch von blauem Purpur tun und mit einer Decke von Seehundsfell bedecken und so auf die Tragbahre legen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Ferner sollen sie den (Brandopfer-)Altar von Asche reinigen, dann ein Tuch von rotem Purpur darüber breiten');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'und alle die Geräte darauf legen, mit denen man den Dienst auf ihm versieht: die Pfannen, Gabeln, Schaufeln und Sprengschalen, alle Geräte des Altars; darüber sollen sie eine Decke von Seehundsfell breiten und dann die Stangen durchstecken.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Wenn nun beim Aufbruch des Lagers Aaron und seine Söhne mit der Einhüllung der heiligen Gegenstände und aller heiligen Geräte fertig sind, dann sollen die Kahathiter kommen, um es wegzutragen; doch sollen sie das Heilige nicht berühren, sonst müssen sie sterben. Diese Teile des heiligen Zeltes haben die Kahathiter zu tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleasar aber, der Sohn Aarons, des Priesters, hat die Besorgung des Öls für den Leuchter, des wohlriechenden Räucherwerks, des täglichen Speisopfers und des Salböls, die Aufsicht über die ganze Wohnung und über alles, was darin ist an heiligen Gegenständen und Geräten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und der Herr redete mit Mose und Aaron und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Sorgt dafür, dass der Stamm der Geschlechter der Kahathiter nicht ausgerottet werde aus der Zahl der Leviten,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sondern das sollt ihr für sie tun, damit sie am Leben bleiben und nicht sterben, wenn sie sich dem Hochheiligen nahen: Aaron und seine Söhne sollen hineingehen und einem jeden seinen Dienst und seine Arbeit beim Tragen anweisen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Sie aber sollen nicht hineingehen, auch nur für einen Augenblick die heiligen Dinge zu sehen; sonst müssen sie sterben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Stelle auch die Gesamtzahl der Gersoniter fest, Familie für Familie, Geschlecht für Geschlecht;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre sollst du sie mustern, alle, die dienstpflichtig sind -, damit sie Dienst tun am heiligen Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Dies ist die Aufgabe der Geschlechter der Gersoniter, was sie zu tun und was sie zu tragen haben:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'sie sollen die Teppiche der Wohnung und das heilige Zelt tragen, seine Decke und die Decke von Seehundsfell, die oben darüber liegt, und den Vorhang am Eingang des heiligen Zeltes,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'ferner die Umhänge des Vorhofs und den Vorhang am Tor des Vorhofs, der die Wohnung und den Altar rings umschliesst, sowie die zugehörigen Stricke, samt allen Geräten, die sie zu besorgen haben; und alles, was es damit zu tun gibt, das sollen sie besorgen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Befehl Aarons und seiner Söhne soll der ganze Dienst der Gersoniter vor sich gehen, bei allem, was sie zu tragen, und bei allem, was sie zu besorgen haben. Und ihr sollt ihnen Weisung geben, indem ihr alles, was sie zu tragen haben, einzeln nennt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Das ist die Aufgabe der Geschlechter der Gersoniter am heiligen Zelte, und die Aufsicht über ihren Dienst steht bei Ithamar, dem Sohne Aarons, des Priesters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Auch die Merariter sollst du mustern, Geschlecht für Geschlecht, Familie für Familie;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre sollst du sie mustern, alle, die dienstpflichtig sind -, damit sie den Dienst am heiligen Zelte tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Dies ist ihre Aufgabe beim Tragen, das, was sie am heiligen Zelte zu besorgen haben: die Bretter und Riegel, die Säulen und Füsse der Wohnung,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'ferner die Säulen des Vorhofs ringsum samt ihren Füssen, Pflöcken und Stricken und allen ihren Geräten, nebst allem, was es damit zu tun gibt. Und ihr sollt alle Geräte, die zu tragen ihnen obliegt, einzeln nennen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Das ist die Aufgabe der Geschlechter der Merariter, alles, was sie am heiligen Zelte unter der Aufsicht Ithamars, des Sohnes Aarons, des Priesters, zu besorgen haben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose und Aaron samt den Fürsten der Gemeinde musterten die Kahathiter, Geschlecht für Geschlecht und Familie für Familie,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre, alle, die dienstpflichtig waren -, um Dienst zu tun am heiligen Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und die Zahl derer, die gemustert wurden, Geschlecht für Geschlecht, belief sich auf 2 750 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die Gemusterten aus den Geschlechtern der Kahathiter, alle, die am heiligen Zelte Dienst taten, die von Mose und Aaron gemustert wurden, wie der Herr durch Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Auch die Gersoniter wurden gemustert, Geschlecht für Geschlecht und Familie für Familie,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre, alle, die dienstpflichtig waren -, um Dienst zu tun am heiligen Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Und die Zahl derer, die gemustert wurden, Geschlecht für Geschlecht und Familie für Familie, belief sich auf 2 630 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das sind die Gemusterten aus den Geschlechtern der Gersoniter, alle, die am heiligen Zelte Dienst taten, die von Mose und Aaron gemustert wurden, wie der Herr geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Auch die Geschlechter der Merariter wurden gemustert, Geschlecht für Geschlecht und Familie für Familie,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre, alle, die dienstpflichtig waren -, um Dienst zu tun am heiligen Zelte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Und die Zahl derer, die gemustert wurden, Geschlecht für Geschlecht, belief sich auf 3 200 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die Gemusterten aus den Geschlechtern der Merariter, die von Mose und Aaron gemustert wurden, wie der Herr durch Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Alle Gemusterten aber unter den Leviten, die von Mose und Aaron und den Fürsten Israels, Geschlecht für Geschlecht und Familie für Familie, gemustert wurden,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'vom dreissigsten Jahre an und darüber bis zum fünfzigsten Jahre, alle, die hineingingen, um die Arbeit des Dienstes und die Arbeit des Tragens am heiligen Zelte zu verrichten -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'alle Gemusterten unter ihnen zählten 8 580 Mann.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach dem Befehl des Herrn durch Mose wies man einem jeden zu, was er zu tun und was er zu tragen hatte. So wurden sie angewiesen, wie es der Herr dem Mose geboten hatte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Gebiete den Israeliten, dass sie alle aus dem Lager wegweisen, die aussätzig sind oder an einem Fluss leiden oder sich an einem Toten verunreinigt haben. (a) 3Mo 13:46; 21:1; 4Mo 19:11-16');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Männer wie Frauen sollt ihr wegweisen, vor das Lager sollt ihr sie hinausweisen, damit sie euer Lager, wo ich mitten unter euch wohne, nicht verunreinigen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Israeliten taten so und wiesen sie vor das Lager hinaus; wie der Herr dem Mose geboten hatte, so taten die Israeliten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Sage den Israeliten: Wenn ein Mann oder ein Weib irgendeine Sünde begeht, wie die Menschen sie begehen, indem sie eine Untreue wider den Herrn verüben, und ein solcher Mensch lädt damit Schuld auf sich, (a) 3Mo 6:2');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so sollen sie die Sünde bekennen, die sie begangen haben, und sollen den vollen Wert des Veruntreuten zurückerstatten und noch den fünften Teil hinzufügen und es dem geben, an dem sie sich verschuldet haben. (a) 3Mo 5:5; 6:4 5');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Ist aber kein nächster Verwandter da, dem die Busse erstattet werden könnte, so fällt die Busse, die zu erstatten ist, an den Herrn zugunsten des Priesters, gerade wie der Sühnewidder, mit dem der Priester Sühne erwirkt. (a) 3Mo 5:15 16; 7:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Ebenso soll jede Hebe, von allen heiligen Gaben, welche die Israeliten zum Priester bringen, diesem zufallen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Auch was ein jeder an Gaben weiht, fällt ihm zu; was ein jeder dem Priester gibt, gehört diesem.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ein Eheweib auf Abwege gerät und ihrem Manne untreu wird');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'und ein andrer mit ihr Umgang hat, ohne dass ihr Mann es merkt, und sie bleibt unentdeckt, obschon sie sich verunreinigt hat, es ist auch kein Zeuge wider sie vorhanden, weil sie nicht ertappt worden ist,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'es kommt dann aber ein Geist der Eifersucht über ihn, sodass er auf sein Weib eifersüchtig wird, weil sie sich verunreinigt hat - oder es kommt ein Geist der Eifersucht über ihn, sodass er auf sein Weib eifersüchtig wird, obschon sie sich nicht verunreinigt hat -,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soll der Mann sein Weib zum Priester führen und das erforderliche Opfer für sie mitbringen: ein zehntel Epha Gerstenmehl; er soll kein Öl darauf giessen noch Weihrauch darauf tun; denn es ist ein Eifersuchtsopfer, ein Erinnerungsopfer, das Verschuldung (bei Gott) in Erinnerung bringt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Der Priester aber soll sie herzukommen und vor den Herrn treten lassen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Dann nehme der Priester heiliges Wasser in ein irdenes Gefäss; auch von der Erde am Boden der (heiligen) Wohnung soll er nehmen und sie in das Wasser tun.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Hierauf lasse der Priester das Weib vor den Herrn treten, löse ihr die Haupthaare und lege ihr das Erinnerungsopfer, das Eifersuchtsopfer, auf die Hände, während der Priester selbst das fluchwirkende Wasser des bittern Wehs in der Hand hält.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Dann soll der Priester das Weib schwören lassen und zu ihr sagen: Wenn kein Mann mit dir Umgang gehabt hat und du als deinem Manne untergebenes Weib dich nicht vergangen und verunreinigt hast, so sollst du von diesem fluchwirkenden Wasser des bittern Wehs unbeschädigt bleiben;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'wenn du aber als deinem Manne untergebenes Weib dich vergangen und verunreinigt hast und ein andrer ausser deinem Manne mit dir Umgang gehabt hat... -');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'der Priester also soll das Weib den Fluch schwören lassen, indem er zu ihr sagt: Der Herr mache deinen Namen zum Fluch und Schwurwort unter deinem Volke, indem er deine Hüfte schwinden und deinen Leib anschwellen lässt, (a) Jer 29:22');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'und dieses fluchwirkende Wasser dringe in deine Eingeweide, dass der Leib anschwelle und die Hüfte schwinde! Und das Weib soll sprechen: So geschehe es! So geschehe es!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Dann soll der Priester diese Flüche aufschreiben und die Schrift in das Wasser des bittern Wehs hinein abwaschen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Hernach gebe er dem Weibe das fluchwirkende Wasser des bittern Wehs zu trinken, damit das fluchwirkende Wasser in sie eindringe zu bitterm Weh.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Dann nehme der Priester das Eifersuchtsopfer aus der Hand des Weibes, schwinge das Speisopfer vor dem Herrn und bringe es auf den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Er soll eine Handvoll von dem Speisopfer nehmen, den als Duftopfer bestimmten Teil, und dies auf dem Altar verbrennen und darnach dem Weibe das Wasser zu trinken geben.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und wenn er ihr das Wasser zu trinken gegeben hat, so wird, falls sie sich verunreinigt hat und ihrem Manne untreu gewesen ist, das fluchwirkende Wasser zu bitterm Weh in sie eindringen, sodass ihr der Leib anschwillt und die Hüfte schwindet, und der Name des Weibes wird unter ihrem Volk ein Fluchwort werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Wenn aber das Weib sich nicht verunreinigt hat, sondern rein ist, so bleibt sie unbeschädigt und kann schwanger werden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Das ist das Eifersuchtsgesetz: wenn ein Eheweib auf Abwege gerät und sich verunreinigt,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder wenn ein Geist der Eifersucht über einen Mann kommt, sodass er auf sein Weib eifersüchtig wird, so soll er das Weib vor den Herrn treten lassen, und der Priester verfahre mit ihr genau nach diesem Gesetze.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Der Mann bleibt frei von Schuld, ein solches Weib aber lädt Schuld auf sich.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Rede mit den Israeliten und sprich zu ihnen: Wenn ein Mann oder ein Weib das besondere Gelübde eines Gottgeweihten auf sich nimmt, um dem Herrn zu Ehren Enthaltung zu üben,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'soll er sich des Weins und andern berauschenden Getränks enthalten; auch Essig von Wein oder anderm berauschendem Getränk darf er nicht trinken, überhaupt nichts, was aus Traubensaft gemacht ist; auch darf er weder frische noch getrocknete Trauben essen. (a) Ri 13:4; Jer 35:6; Lu 1:15');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Solange seine Enthaltung währt, soll er auch nichts essen, was, vom Weinstock herrührend, bereitet wird, weder unreife Trauben noch Rankenspitzen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Solange das Gelübde seiner Enthaltung währt, soll kein Schermesser auf sein Haupt kommen. Bis die Zeit um ist, während der er dem Herrn zu Ehren Enthaltung übt, soll er ein Geweihter sein; er soll das Haar auf seinem Haupte frei wachsen lassen. (a) Ri 13:5; 1Sa 1:11');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Die ganze Zeit, während der er dem Herrn zu Ehren Enthaltung übt, soll er zu keinem Toten hineingehen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Auch an seinem Vater, seiner Mutter, seinem Bruder oder seiner Schwester darf er sich nicht verunreinigen, wenn sie sterben; denn die Weihe seines Gottes ist auf seinem Haupte.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Während der ganzen Zeit seiner Enthaltung ist er dem Herrn geweiht.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Und wenn jemand neben ihm plötzlich und unversehens stirbt und er so sein geweihtes Haupt verunreinigt, so soll er sein Haupt scheren an dem Tage, da er wieder rein wird; am siebenten Tage soll er es scheren.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Und am achten Tage bringe er zwei Turteltauben oder zwei junge gewöhnliche Tauben zum Priester an den Eingang des heiligen Zeltes, (a) 3Mo 5:7');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'und der Priester soll die eine als Sündopfer und die andre als Brandopfer darbringen und ihm so Sühne erwirken dafür, dass er sich an dem Toten (verunreinigt und sich dadurch) versündigt hat. Dann soll er an demselben Tage sein Haupt wieder für geweiht erklären');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'und dem Herrn für dieselbe Zeit wie vorher Enthaltung geloben; auch soll er ein einjähriges Lamm zum Schuldopfer darbringen. Die frühere Zeit aber soll ungültig sein, weil er sein geweihtes Haupt verunreinigt hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Und dies ist das Gesetz über den Gottgeweihten: wenn die Zeit seiner Enthaltung um ist, soll man ihn an den Eingang des heiligen Zeltes führen,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'und er soll dem Herrn seine Opfergabe darbringen: ein fehlloses, einjähriges männliches Lamm als Brandopfer, ein fehlloses, einjähriges weibliches Lamm als Sündopfer und einen fehllosen Widder als Heilsopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'ferner einen Korb mit ungesäuerten Broten von Semmelmehl, Kuchen, mit Öl eingerührt, und ungesäuerte Fladen, mit Öl bestrichen, samt dem zugehörigen Speisopfer und den Trankopfern.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester bringe es vor den Herrn und verrichte das Sündopfer und das Brandopfer für ihn;');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'den Widder aber bringe er dem Herrn als Heilsopfer dar samt dem Korbe mit den ungesäuerten Broten. Auch das Speisopfer und das Trankopfer für ihn soll der Priester darbringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Der Gottgeweihte aber schere sein geweihtes Haupt am Eingang des heiligen Zeltes; dann nehme er sein geweihtes Haupthaar und werfe es auf das Feuer, das unter dem Heilsopfer brennt.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Darnach nehme der Priester die gekochte Vorderkeule des Widders, ferner einen ungesäuerten Kuchen aus dem Korbe und einen ungesäuerten Fladen und lege es dem Gottgeweihten auf die Hände, nachdem dieser sein geweihtes Haar geschoren hat.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Dies alles soll der Priester als Webeopfer vor dem Herrn schwingen; es fällt als geweihte Gabe dem Priester zu, samt der Webebrust und der Hebekeule. Darnach darf der Gottgeweihte wieder Wein trinken. (a) 2Mo 29:24 27; 3Mo 7:30 34');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz über den Gottgeweihten, der ein Gelübde auf sich nimmt - seine Opfergabe für den Herrn auf Grund seiner Weihung, ausser dem, was er (sonst noch) vermag; entsprechend dem Gelübde, das er auf sich nimmt, soll er tun, nach dem Gesetz über seine Weihung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'UND der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Rede mit Aaron und seinen Söhnen und sprich: So sollt ihr zu den Israeliten sprechen, wenn ihr sie segnet:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Der Herr segne dich und behüte dich! (a) Ps 67:2; 134:3');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Der Herr lasse sein Angesicht über dir leuchten und sei dir gnädig!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Der Herr erhebe sein Angesicht auf dich und gebe dir Frieden!');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Wenn sie so meinen Namen auf die Israeliten legen, will ich selbst sie segnen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'AN dem Tage nun, da Mose die Wohnung fertig aufgerichtet und sie samt allen ihren Geräten gesalbt und geweiht hatte, da er auch den Altar samt allen seinen Geräten gesalbt und geweiht hatte,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'brachten die Fürsten Israels, die Häupter ihrer Familien - das sind die Stammesfürsten, die Vorsteher der Gemusterten - Opfer dar,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'und zwar brachten sie als ihre Opfergabe vor den Herrn sechs bedeckte Wagen und zwölf Rinder, je einen Wagen von zwei Fürsten und je ein Rind von jedem; das brachten sie vor die Wohnung.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Und der Herr redete mit Mose und sprach:');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm sie von ihnen entgegen, um sie für den Dienst am heiligen Zelte zu verwenden, und übergib sie den Leviten, entsprechend dem Dienste eines jeden.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da nahm Mose die Wagen und Rinder entgegen und übergab sie den Leviten.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Die erforderlichen zwei Wagen und vier Rinder gab er den Gersonitern, entsprechend ihrem Dienste,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'und den Meraritern gab er die erforderlichen vier Wagen und acht Rinder, entsprechend ihrem Dienste unter der Leitung Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Den Kahathitern aber gab er nichts, weil ihnen der Dienst an den heiligen Geräten oblag; sie hatten dieselben auf den Schultern zu tragen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Dann brachten die Fürsten die (Gaben zur) Einweihung des Altars an dem Tage, da er gesalbt wurde; sie brachten ihre Opfergaben vor den Altar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Und der Herr sprach zu Mose: Jeden Tag soll nur je ein Fürst seine Opfergabe zur Einweihung des Altars bringen.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Derjenige nun, der am ersten Tage seine Opfergabe brachte, war Nahason, der Sohn Amminadabs, vom Stamme Juda.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Seine Opfergabe war eine silberne Schüssel, 130 Lot schwer, eine silberne Sprengschale, siebzig Lot schwer nach heiligem Gewicht, beide voll Semmelmehl, das mit Öl eingerührt war, zum Speisopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine goldene Schale, zehn Lot schwer, voll Räucherwerk,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Stier, ein Widder und ein einjähriges männliches Lamm zum Brandopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock zum Sündopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige männliche Lämmer. Das war die Opfergabe Nahasons, des Sohnes Amminadabs.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage opferte Nethaneel, der Sohn Zuars, der Fürst von Issaschar.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Er brachte als Opfergabe eine silberne Schüssel, 130 Lot schwer, eine silberne Sprengschale, siebzig Lot schwer nach heiligem Gewicht, beide voll Semmelmehl, das mit Öl eingerührt war, zum Speisopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'eine goldene Schale, zehn Lot schwer, voll Räucherwerk,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'einen jungen Stier, einen Widder und ein einjähriges männliches Lamm zum Brandopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock zum Sündopfer,');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'und zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige männliche Lämmer. Das war die Opfergabe Nethaneels, des Sohnes Zuars.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage opferte der Fürst der Söhne Sebulons, Eliab, der Sohn Helons.');
INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war eine silberne Schüssel, 130 Lot schwer, eine silberne Sprengschale, siebzig Lot schwer nach heiligem Gewicht, beide voll Semmelmehl, das mit Öl eingerührt war, zum Speisopfer,');
