INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage opferte der Fürst der Söhne Rubens, Elizur, der Sohn Sedeurs.');
