INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage opferte der Fürst der Söhne Simeons, Selumiel, der Sohn Zurisaddais.');
