INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage opferte der Fürst der Söhne Benjamins, Abidan, der Sohn Gideonis.');
