INSERT INTO `GerZurcher_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Am zehnten Tage opferte der Fürst der Söhne Dans, Ahieser, der Sohn Ammisaddais.');
